BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 326 of 1506 --

UBiLEX
El incumplimiento de la transacción no autoriza al perjudicado a solicitar la resolución de
ésta; la transacción judicial es un título de ejecución.
Si la transacción recae sobre algunas de las pretensiones propuestas o se relaciona con algu
nas de las personas, el proceso continuará respecto de las pretensiones o personas no com
prendidas en ella. En este últim o caso, se tendrá en cuenta lo normado sobre intervención de
terceros (Art. 337 C.PC.).
Todo acuerdo posterior a la sentencia firme, como la condonación, novación o prórroga del
plazo, no tiene la calidad de transacción ni produce los efectos de ésta (Art. 339 CPC).
Desistimiento: En general, el desistimiento es el apartamiento o una renuncia voluntaria y
expresa que pueden hacer las partes, sea de un acto procesal, del procesoy de la pretensión. El
desistimiento no se presume. El escrito que lo contiene debe precisar su contenido y alcance,
legalizando su firm a el proponente ante el secretario respectivo. El desistimiento es incondi
cional y sólo perjudica a quien lo hace.
Clases de desistimiento: Del proceso o de algún acto procesal y de la pretensión.
El desistimiento del proceso corresponde hacerlo al actor, caracterizándose porque no afecta a la
pretensión. Cuando se formule después de notificada la demanda, requiere la conformidad
del demandado. De haber oposición y se declarase fundada, el desistimiento carecerá de efi
cacia, debiendo continuar el proceso.
El desistimiento de un acto procesal corresponde a la parte que lo produjo, llámese la que inter
puso el medio impugnatorio, ofreció la prueba, etc. Esta renuncia sólo afecta al acto procesal
desistido. V. gr., si el desistimiento es de un recurso, su efecto es dejar firme la resolución im
pugnada, salvo que se hubiera interpuesto la adhesión.
El desistimiento de la pretensión es radical, porque el actor no podrá volver a demandar la misma
pretensión. La resolución que aprueba este desistimiento, produce los efectos de una deman
da infundada con la autoridad de la cosa juzgada (Art. 344 CPC). Si hubiera reconvención, el
proceso continuará.
Este desistimiento no requiere de la conformidad del demandado, debiendo el juez revisar
únicamente la capacidad de quien lo realiza y la naturaleza del derecho que sustenta la pre
tensión, teniendo en cuenta lo dispuesto sobre la improcedencia del allanamiento en lo que
corresponda.
Si el desistimiento no se refiere a todas las pretensiones o si sólo es deducido por uno de los
demandantes, el proceso continuará respecto de las pretensiones y personas no comprendidas
en él. En este últim o caso, debe tenerse presente lo dispuesto sobre el litisconsorcio necesario.
El titu lar de una pretensión no resuelta en primera instancia, puede desistirse de la misma
antes que el proceso sea decidido por el superior.
Abandono. Conocido también como perención; tiene como fundamento la inactividad del ac
tor respecto al proceso que inició. Sólo cabe el abandono en primera instancia.
El art. 346 del C.RC, señala que cuando el proceso permanezca en primera instancia durante
cuatro meses sin que se realice acto que lo impulse, el juez declarará su abandono de oficio o
a pedido de parte o de tercero legitimado.
326 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 327 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercia
Para el cómputo del plazo del abandono se entiende iniciado el proceso con la presentación
de la demanda.
Para el mismo cómputo, no se toma en cuenta el período durante el cual el proceso hubiera
estado paralizado por acuerdo de partes aprobado por el juez.
No se consideran actos de impulso procesal aquellos que no tienen por propósito activar el
proceso, tales como la designación de nuevo domicilio, pedido de copias, apersonamiento de
nuevo apoderado y otros análogos. No opera el abandono cuando la paralización del proceso
se debe a causas de fuerza mayory que los litigantes no hubieran podido superar con los me
dios procesales a su alcance.
Consentida o ejecutoriada la resolución que declara el abandono del proceso, quedan sin
efecto las medidas cautelares, y se archiva el expediente. Por otro lado, las pruebas actuadas
en un proceso concluido por abandono, son válidas para otro proceso, en donde pueden ser
ofrecidas como tales.
Declarado el abandono, la prescripción extintiva interrumpida por el emplazamiento sigue
transcurriendo, tal como si la interrupción no se hubiese producido.
No procede el abandono (Art. 350 CPC): En los procesos que se encuentren en ejecución de
sentencia; en los procesos no contenciosos; en los procesos que se contiendan pretensiones
imprescriptibles (como la filiación, la reivindicación, la petición de herencia, etc.); en los pro
cesos que se encuentren para sentencia, salvo que estuviera pendiente actuación cuya rea
lización dependiera de una parte, contándose en este caso el plazo desde que se notifica la
resolución que la dispuso; en los procesos que se encuentren pendientes de una resolución y
la demora en dictarla fuera imputable al juez, o la continuación del trám ite dependiera de una
actividad que la ley le impone a los auxiliares jurisdiccionales o al Ministerio Público o a otra
autoridad o funcionario público que deba cumplir un acto procesal requerido por el juez; y, en
los procesos que la ley señale.
El abandono pone fin al proceso sin afectar la pretensión. Sin embargo, su declaración impide
al demandante iniciar otro proceso con la misma pretensión durante un año, contado a partir
de la notificación del auto que lo declare. Asimismo, restituye las cosas al estado que tenían
antes de la demanda. Si por segunda vez, entre las mismas partes y en ejercicio de la misma
pretensión, se declara el abandono, se extingue el derecho pretendido y se ordena la cancela
ción de los títulos del demandante, si a ello hubiera lugar (artículo 351 CPC).
El auto que declara el abandono es apelable con efecto suspensivo. El recurso sólo puede estar
fundamentado en la existencia de un error de cómputo, o en causas de fuerza mayor. La reso
lución que desestima un pedido de abandono es apelable sin efecto suspensivo (artículo 353
CPC).
Conciliación. Es una de las modalidades de autocomposición, vale decir, que la solución de la
litis reside en la voluntad de las partes. La conciliación puede darse en dos ámbitos: extrajudi
cial o intraproceso.
En la conciliación intraproceso (o judicial) las partes pueden conciliar su conflicto de intereses
en cualquier estado del proceso, siempre que no se haya expedido sentencia en segunda ins-
