UBILEX
tancia, en donde las partes solucionan un conflicto de intereses, mediante acuerdo, convenio
o avenimiento, dando por terminada la litis.
Con la reciente modificatoria introducida por el Decreto Legislativo N °i070, se establece que
la conciliación se llevará a cabo ante un Centro de Conciliación elegido por las partes; y sola
mente si ambas lo solicitan el Juez facultativamente puede convocarla en cualquier etapa del
proceso, de esta manera se elimina la audiencia conciliatoria obligatoria dentro del proceso
(Art. 468 C.PC.). El Juez no es recusable por las manifestaciones que pudiera formular.
El Juez aprobará la conciliación que trate sobre derechos disponibles, siempre que el acuerdo
se adecúe a la naturaleza jurídica del derecho en litigio.
Si habiendo proceso abierto, las partes conciban fuera de éste, presentarán con un escrito el
Acta de Conciliación respectiva, expedida por un Centro de Conciliación Extrajudicial.
Presentada por las partes el acta de conciliación, el Juez la aprobará previa verificación del
requisito establecido en el artículo 325y, declarará concluido el proceso.
Si la conciliación presentada al Juez es parcial, y ella recae sobre alguna de las pretensiones o
se refiere a alguno o algunos de los litigantes, el proceso continuará respecto de las pretensio
nes o de las personas no afectadas. En este últim o caso, se tendrá en cuenta lo normado sobre
intervención de tercero.
Se encuentra regulada en los artículos 323 a 328 del Código adjetivo.
La conciliación surte el mismo efecto que la sentencia que tiene la autoridad de la cosa juz
gada.
13. Recursos: Reposición. Apelación. Casación. Queja
Recursos regulados en el Código Procesal Civil:
1. El recurso de la reposición. Recurso que se interpone contra un decreto, a fin que el mis
mo juez lo revoque.
El plazo de su interposición es de tres días, contado desde la notificación de la resolución.
Cabe el rechazo in limine de este recurso; igualmente, si el juez advierte que el vicio o error
es evidente lo puede resolver sin más trámite. De considerarlo necesario, el juez conferirá
traslado por tres días. Vencido el plazo, resolverá con su contestación o sin ella.
Si la resolución impugnada se expidiera en una audiencia, el recurso debe ser interpuesto
verbal mente y se resuelve de inmediato, previo traslado a la parte contraria o en su rebel
día. El auto que resuelve este recurso es inimpugnable (Art. 363 C.PC.).
2. El recurso de la apelación. El artículo 364 C.PC. prescribe: El recurso de apelación tiene
por objeto que el órgano jurisdiccional superior examine, a solicitud de parte o de tercero
legitimado, la resolución que les produzca agravio, con el propósito de que sea anulada
o revocada, total o parcialmente. La apelación se interpone contra los autos y las senten
cias.
Se discute en la doctrina si la apelación es un proceso, distinto al de primera instancia
(tesis renovadora) o si, por el contrario, se trata del mismo proceso dividido en distintos
grados (tesis revisora).
328 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 329 of 1506 --

Tema 1: Temas com unes a la especialidad: Civil, Familia y Comercial
La tesis renovadora confiere mayor am plitud a la apelación, admitiendo pruebas y el
ejercicio de distintas pretensiones en la segunda instancia; mientras que la tesis revisora
lim ita estas posibilidades partiendo de la ¡dea que en la alzada no se debe modificar la
sustancia que sirvió de base para la decisión primera.
Nuestro sistema jurídico sigue la tesis revisora, como casi toda la legislación comparada.
La apelación se interpone dentro del plazo legal ante el juez que expidió la resolución
impugnada, anexando el recibo de la tasa respectiva cuando ella fuera exigióle.
La apelación que no acompañe el recibo de la tasa, se interponga fuera del plazo, que no
tenga fundamento o no precise el agravio será de plano declarada inadmisible o im pro
cedente, según sea el caso.
El superiortam bién puede declarar inadmisible o improcedente la apelación, si advierte
que no se han cumplido los requisitos para su concesión. En este caso, además, declarará
nulo el concesorio (Art. 367 CPC).
Con fecha 06.10.2022 se publicó la Ley N° 31591, la misma que modifica los artículos 367,
370, 373 y 376 del Código Procesal Civil, eliminando la denominada “adhesión al recurso de
apelación", siendo uno de los tipos de impugnación que se emplea en aquellos casos en
los que una resolución judicial genera agravio a ambas partes del proceso; siendo que,
interpuesto el recurso por una de estas (concedido y corrido traslado del mismo), la otra
parte tiene la posibilidad de adherirse a este, solicitando que se modifique o revoque la
resolución recurrida en todo aquello que le resulte perjudicial.
Efectos del Recurso de Apelación: Con efecto suspensivoy sin efecto suspensivo. Dentro
de ésta se encuentra la apelación diferida.
En la apelación con efecto suspensivo la eficacia de la resolución recurrida queda suspen
dida hasta la notificación de la que ordena se cumpla lo dispuesto por el superior. Sin
perjuicio de la suspensión, el juez que expidió la resolución impugnada puede seguir co
nociendo las cuestiones que se tramitan en cuaderno aparte. Asimismo, puede, a pedido
de parte y en decisión debidamente motivada, disponer medidas cautelares que eviten
que la suspensión produzca agravio irreparable. Esta apelación se interpone contra las
sentencias y sólo contra los autos que pongan fin al proceso o impiden su continuación, y
en los demás previstos en la ley procesal (ejemplos: contra los autos que declaran funda
das las excepciones de incompetencia, cosa juzgada, caducidad, el abandono del proce
so, etc). El trám ite de la apelación de las sentencias está regulado en los artículos 373 a 375
CPC; el correspondiente a los autos con efecto suspensivo en el artículo 375.
En la apelación sin efecto suspensivo, la eficacia de la resolución impugnada se mantie
ne, incluso para el cumplimiento de ésta. En esta apelación se eleva un cuaderno con las
piezas procesales pertinentes. El trámite de esta apelación está previsto en el artículo 377
CPC.
La apelación d ife rid a , es una de las modalidades de la apelación sin efecto suspensivo. El
juez puede ordenar que se reserve el trámite de una apelación sin efecto suspensivo, a fin
de que sea resuelta por el superior conjuntamente con la sentencia u otra resolución que
