el juez señale. La falta de apelación de estas resoluciones determina la ineficacia de la
apelación diferida. La decisión es inimpugnable (Art. 369 CPC). Algunos supuestos de esta
modalidad lo encontramos en los artículos 4 9 4 ,7 5 7 y 691.
La re fo rm a tio in peius: Dentro de los límites que tiene el órgano jurisdiccional superior
está la prohibición de resolveren perjuicio de lo que ya obtuvo el apelante. Así el AQ uem
podrá confirmar la recurrida o mejorarla, pero no podrá empeorarla, salvo que la otra
parte también haya apelado o sea un menor de edad. Cuando la apelación es de un auto,
la competencia del superior sólo alcanza a éste y a su tramitación (Art. 370 CPC). Tiene
como sustento el principio dispositivo.
3. El recurso de casación: Es un recurso extraordinario, que se interpone cuando se cuestiona
objetivamente-entiéndase la legalidad- de una decisión de las Salas Superiores. La casa
ción civil se encuentra regulada en los artículos 384 a 399 del Código adjetivo.
En el Perú, ante la deficiencias en su regulación, entre ellas de las llamadas “causales”,
léase aplicación indebida, inaplicación e interpretación errónea, de una norma de dere
cho material o de la doctrina jurisprudencial, que traían como consecuencia que la Cor
te Suprema declaraba improcedente la mayoría de recursos de casación interpuestos, al
respecto surge la modificación al Código Procesal Civil a través de la Ley N° 29364 (Pub.
28.05.2009), con la finalidad de reorientar esta institución y la función de la Corte Su
prema de la República, en el marco de un Estado Constitucional de Derecho. Como se
desprende de la exposición de motivos del proyecto de ley que sustentó la Ley N° 29364, se
pretendía restringir el uso de la casación como un medio impugnatorio ordinario, el cual
era aplicado la mayor de las veces para dilatar procesos, haciendo de la Corte Suprema de
la República un simple órgano de revisión.
No obstante, introdujo entre sus modificaciones, una muy perjudicial, cual es la de privar
de competencia para revisar los requisitos de adm isibilidady el plazo a las salas superio
res que emitieron la resolución impugnada. Así, se dispuso inexplicablemente que reci
bido el recurso, en el día, estos órganos jurisdiccionales deberían elevar el expediente a
la Corte Suprema, siendo las salas superiores un especie de “mesa de partes", hecho que
motivo continuos reclamos de modificación.
En este contexto, el 26 de octubre de 2022 se promulga la Ley N°31951 que modifica diver
sos artículos del Código Procesal Civil, entre ellos los relacionados al recurso de casación.
Requisitos de procedencia (Artículo 386 CPC):
1. El recurso de casación procede contra las sentencias y autos expedidos por las salas
superiores que, como órganos de segundo grado, ponen fin al proceso.
2. Procede el recurso de casación, en los supuestos del numeral anterior, siempre que:
a. En la sentencia o auto se discuta una pretensión mayor a las 500 unidades de
referencia procesal o que la pretensión sea inestimable en dinero;
b. el pronunciamiento de segunda instancia revoque en todo o en parte la decisión
de primera instancia,y
c. el pronunciamiento de segunda instancia no sea anulatorio.
330 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 331 of 1506 --

Tema 1: Tem as co m unes a la especialidad: Civil, Fam ilia y Com ercial
Como se puede verificar, dentro de las modificatorias introducidas por la Ley N°
31951, se han agregado nuevos requisitos de procedencia del recurso de casación,
en el numeral z.a tenemos a la suma graviminis, el legislador ha establecido que la
pretensión que se discuta en la sentencia o auto sea mayor o superior a 500 URR O
cuando la pretensión sea inapreciable en dinero.
En el numeral 2 .b, el legislador ha implementado el “dobley conforme”; es decir, solo
se podrá interponer el recurso de casación contra sentencias de segunda instancia
que revoquen en parte o de manera total la decisión de primera instancia. En aque
llos casos en los que la Sala Superior confirme el pronunciamiento del juzgado, no
será posible recurrir a la Corte Suprema, esta modificatoria es un acierto, pues el re
curso de casación ya no procederá cuando haya dos resoluciones conformes.
Procedencia excepcional (Artículo 387 CPC):
Excepcionalmente, es procedente el recurso de casación en casos distintos a los previstos
en el artículo 386 cuando la Corte Suprema, discrecionalmente, lo considere necesario
para el desarrollo de la doctrina jurisprudencial.
Este artículo fue modificado por la Ley N°3i59i,cabe resaltar que la procedencia excep
cional ya se encontraba regulada en el Art. 392-A del C.PC. A través de esta reforma, se
le otorga la facultad a la Corte Suprema para que declare la procedencia del recurso de
casación en aquellos casos en los que, no obstante, no satisfacerse ninguno de los incisos
del artículo 386, lo considere necesario para el desarrollo de la doctrina jurisprudencial.
A decir del Magistrado Francisco Tavara10, esta innovación concuerda con el numeral 5
del artículo 391°, que establece “5 - Si se invoca el artículo 387o, sin perjuicio de señalarse
y justificarse la causal que corresponda conforme al artículo 388o, el recurrente deberá
consignar adicional y puntualmente las razones que justifican el desarrollo de la doctri
na jurisprudencial que pretende. En este supuesto, la sala superior, para la concesión del
recurso, sin perjuicio de lo dispuesto en los numerales 3 y 4 constatará la existencia de
la fundamentación específica exigida en estos casos”. Como vemos, el legislador está in
troduciendo sobre exigencias a la figura de la procedencia excepcional, haciendo más
complicado este medio impugnatorio,y le confiere a lasalasuperiorqueem itió la resolu
ción impugnada la facultad de calificar la “...existencia de la fundamentación específica...”
antes de la “concesión "del recurso.
Causales para interponer recurso de apelación (Artículo 388 CPC):
Las nuevas causales de procedencia del recurso de casación, conforme a la modificatoria
introducida por la Ley N°3i59i, son las siguientes:
1. Si la sentencia o auto ha sido expedido con inobservancia de algunas de las garantías
constitucionales de carácter procesal o material, o con una indebida o errónea apli
cación de dichas garantías.
