UBILEX
z. Si la sentencia o auto incurre o deriva de una inobservancia de las normas legales de
carácter procesal sancionadas con la nulidad.
3. Si la sentencia o auto importa una indebida aplicación, una errónea interpretación o
una falta de aplicación de la ley o de otras normas jurídicas necesarias para su aplica
ción.
4. Si la sentencia o auto ha sido expedido con falta de motivación o manifiesta ilogici-
dad de la motivación, cuando el vicio resulte de su propio tenor.
5. Si la sentencia o auto se aparta de las decisiones vinculantes del Tribunal Constitu
cional o de la Corte Suprema.
Improcedencia del recurso de casación (Artículo 393 CPC):
1. La Sala Civil de la Corte Suprema declarará la improcedencia del recurso de casación
cuando:
a. No se cumplen los requisitos y causales previstos en los artículos 391 y 388, res
pectivamente;
b. se refiere a resoluciones no impugnables en casación; o,
c. el recurrente hubiera consentido previamente la resolución adversa de primera
instancia, si esta fuere confirmada por la resolución objeto del recurso; o si invo
ca violaciones de la ley que no hayan sido deducidas en los fundamentos de su
recurso de apelación.
2. También declara la improcedencia del recurso cuando:
a. Carezca manifiestamente de fundamento; o,
b. se hubieren desestimado en el fondo otros recursos sustancialmente igualesy el
recurrente no presenta argumentos suficientes para que se modifique el criterio
o doctrina jurisprudencial ya establecida.
3. La improcedencia del recurso puede afectar a todas las causales invocadas o referirse
solamente a alguna de estas.
4. La resolución que se pronuncia sobre la procedencia del recurso de casación se expi
de dentro del plazo de veinte días, con el voto conforme de tres jueces supremos.
Trámite del recurso:
Interpuesto el recurso de casación ante la Sala Superior que emitió la resolución impug
nada (Art. 391.2 CPC), los órganos jurisdiccionales de segunda instancia deberán efectuar
una verificación, respecto de si el recurso de casación cumple con los requisitos previstos
en el artículo 386 CPC; así como, la correcta invocación de las causales de procedencia
señaladas en el artículo 388 del CPC.
Si no se cumple con lo previsto en el artículo 386, con los literales a o b del numeral 2 o
se invoquen causales distintas de las enumeradas en el CPC, la Sala Superior rechaza el
recurso e impondrá una multa no menor de 10 ni mayor de 50 URP en caso de que consi-
