Tema 1: Tem as co m unes a la especialidad: Civil, Familia y Com ercial
dere que su interposición tuvo como causa una conducta maliciosa o temeraria. (Art. 391.3
CPC)
En caso de superar los controles de procedencia, la Sala Superior admite el recurso y ele
vará el recurso de casación a la Corte Suprema para que esta proceda a analizar si las cau
sales planteadas merecen un pronunciamiento de fondo. (Art. 391-6).
4. El recurso de queja.-El recurso de queja tiene porobjetoel reexamen de la resolución que
declara inadmisible o improcedente el recurso de apelación o casación. También procede
contra la resolución que concede apelación en efecto distinto al solicitado. La interposi
ción del recurso no suspende la tramitación del principal, ni la eficacia de la resolución
denegatoria.
Excepcionalmente, a pedido de partey previa prestación de contracautela fijada pruden
cialmente, el juez de la demanda puede suspender el proceso principal, a través de reso
lución fundamentada e irrecurrible.
Normalmente se interpone ante el superior que denegó la apelación o la concedió en
efecto distinto al pedido, o ante la Corte Suprema en el caso respectivo. El plazo para in
terponerla es de tres días, contado desde el día siguiente a la notificación de la resolución
que deniega el recurso o de la que lo concede en efecto distinto al solicitado. Tratándose
de distritos judiciales distintos a los de Lima y Callao, el peticionante puede solicitar al
juez que denegó el recurso, dentro del plazo anteriormente señalado, que su escrito de
quejay anexos sea remitido por conducto oficial. El juez remitirá al superior el cuaderno
de queja dentro de segundo día hábil, bajo responsabilidad.
Al escrito que contiene el recurso se acompaña, además del recibo que acredita el pago
de la tasa correspondiente, copiasimple con el selloy lafirm ad el abogado del recurrente
en cada una, y bajo responsabilidad de su autenticidad, de los documentos que se preci
san en el artículo 402 del Código adjetivo.
Si se declara fundada la queja, el superior concede el recurso y precisa el efecto si se trata
de la apelación, comunicando al inferiorsu decisión para que envíe el expedienteo ejecu
te lo que corresponda.
Si se declara infundada, se comunicará al juez inferiory se notificará a las partes. Adicio
nal mente se condenará al recurrente a pago de las costas y costos del recurso y al pago de
una m ulta de 3 ni mayor de 5 URR
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓ N
Y N O M B R AM IEN TO DE JUECES Y FISCALES 3

-- 334 of 1506 --

1. Transmisión sucesoria
Se entiende la transmisión sucesoria como la transmisión patrimonial por causa de muerte.
En ese contexto podemos afirmar que la sucesión es la transmisión de los bienes, derechos
y obligaciones que constituyen la herencia de una persona muerta que deja a sus sucesores.
2. Petición de herencia
Según Planiol la petición hereditaria es la acción real de que goza un heredero y en virtud de
la cual puede exigir la entrega de los bienes de la sucesión que detente en todo en parte otra
persona que pretende tener derecho a ellos en calidad de heredero.
Las acciones reconocidas en nuestro Código Civil para recuperar los bienes hereditarios son:
2.1. La acción petitoria de herencia
Es la que el heredero dirige contra otro heredero para concurrir con él a la herencia o para
excluirlo si tiene mejor derecho. (Art. 664o C.C.)
La ejerce el heredero que no se encuentra en posesión de los bienes de la herencia que consi
dera que le pertenecen, para reclamarlos en todo o en parte de quien o de quienes los deten
tan invocando también derechos hereditarios, con el objeto de concurrir con ellos o excluirlos.
2.2. La acción reivindicatoría
Es aquella que se ejercita contra el tercero adquirente o simplemente contra el poseedor sin
título. (Art. 665o C.C.)
La ejerce el heredero contra el tercero que sin buena fe se encuentra en posesión de los bie
nes de la herencia, por haberlos adquirido en virtud de contratos traslativos de dom inio del
heredero aparente o si es que los que posee sin título alguno que se justifique esa posesión.
3. Representación sucesoria
Existen dos modos de suceder:
1. Por Derecho Propio: Que poseen vocación sucesoral directa, referido a sucesión por cabe
zas, como es el caso de los hijos que heredan a sus padres.
2. Por Derecho de Representación: Que poseen vocación sucesoral indirecta, que es la suce
sión por estirpes, en este caso los representantes forman una sola cabeza.
334 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓ N
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 335 of 1506 --

Tema 2: Temas de derecho civil
Elementos de la representación
El Causante: Es la persona que con su fallecimiento deja una masa hereditaria.
El Representado: Es la persona a quien corresponde ser heredero del causante y que
no recibió la herencia de éste, por que murió, renunció o lo perdió por indignidad o
desheredación.
El Representante: Es aquel aquien corresponde la parte de la herencia que le habría
tocado a su representado.
Presupuestos en los que opera la representación
Son cuatro los presupuestos: La premoriencia, la renuncia, la indignidad y la deshe
redación.
Premoriencia: Es decir cuando el representado ha fallecido prematuramente antes
de la apertura de la sucesión.
Renuncia: En principio nadie puede ser obligado a aceptar una herencia contra su
voluntad, por lo que la ley otorga la posibilidad de renunciar, en dicho caso los hijos
y descendientes del renunciante ocuparían su lugar por que poseen vocación suce
soria con respecto a él, podemos afirmar entonces que el derecho de representación
proviene de la ley y no de la voluntad del representado.
Indignidad y desheredación: Otra de las excepciones es el de la representación de
los descendientes del indigno y del desheredado quienes no pueden quedar exclui
dos por la culpa de su padre o ascendiente; siendo la indignidady la desheredación
una consecuencia de la culpa, las sanciones que son personalísimas no pueden ex
tender sus efectos a la prole inocente.
La representación sucesoria en línea recta descendente
Se da a favor de los hijos y demás descendientes de cualquier grado que sea, es decir
por su extensión esta representación es ilim itada (Art. 682o C.C.)
En los casos en que todos los representantes tengan el mismo grado de parentesco
frente al causante y que lo hagan solos tales como los nietos llamados a la herencia
del abuelo por impedimento de sus ascendientes, se aplica la regla de la sucesión
por representación o por estirpes. (Art. 684o C.C.)
La representación sucesoria en la línea colateral
Está contemplado en el Art. 683o C.C. y se aplica al único caso de la herencia entre
hermanos de tal modo que al fallecer uno de ellos concurran a la herencia los her
manos sobrevivientes que heredan por derecho propio con los hijos del hermano
premuerto que son sobrinos del causante quienes heredan por representación dis
tribuyéndose la cuota respectiva por estirpe.
4 . La sucesión testamentaria
Es conocida también como sucesión testada o voluntaria, es aquella en que la transmisión
patrimonial por causa de muerte se produce por disposición del causante expresada en el tes
tamento, con los requisitos formales y dentro de los límites establecidos por la ley.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 336 of 1506 --

UBILEX
No existe incompatibilidad absoluta entre las sucesiones testamentaria y la intestada, la su
cesión testamentaria puede darse respecto a parte de los bienes, pudiendo coexistir con la
intestada que tendría que regular la transmisión de los bienes no dispuestos por el testador,
dándose el caso de sucesiones mixtas, en parte testada y en parte intestada. La sucesión tie
ne como fundamento la voluntad del causante y la ley, la primera se expresa en la sucesión
testamentaria que se encuentra en el derecho de la propiedad privada y en el principio de la
autonomía de la voluntad.
5. El testam ento
El testamento es el acto jurídico personalísimo, unilateral, revocable y solemne por el que una
persona dispone, para después de su muerte, de todos sus bienes y una parte de ellos, así
como de otros asuntos no patrimoniales que le conciernen. (Art. 686° C.C.).
Es A c t o J u r íd ic o : Por cuanto se trata de una declaración eminentemente voluntaria, lícita y des
tinada a producir efectos jurídicos en lo relativo a la transmisión de todo o en parte del patri
monio deí causante y otras cuestiones no patrimoniales que se involucran bajo el térm ino de
intereses. (Art. 140o C.C.).
Es P e r s o n a lís im o : En cuanto a su otorgante que es testador debe expresar por sí mismo su vo
luntad, nadie más que el propio testador puede otorgarlo, no se admite delegación alguna,
no se puede dar poder a otro para que lo otorgue en su representación. La ley exige que el
testamento sea otorgado por el mismo causante (Art. 690o C.C.).
Es U n ila t e r a l: El testamento contiene una voluntad única, la expresión plural de voluntades es
característica particular de los contratos. El testamento se perfecciona sólo con la voluntad del
testador, no se exige para su perfeccionamiento de una voluntad recepticia.
No pueden intervenir varias personas ni como otorgantes ni uno de ellos como aceptante, la
ley declara que es nulo el testamento otorgado en común por dos o más personas. (Art. 814o
C.C.).
Es R e v o c a b le : El testador puede en cualquier momento revocar cualquier clase de testamento
que haya otorgado por cualquiera de las formas prevista en nuestra legislación, el testador
puede sustituir un testamento, modificarlo parcial o totalmente o dejarlo sin efecto. (Art. 798o
C.C.) La ley faculta expresamente a reconocer hijos extramatrimoniales mediante testamento
(Art. 390o C.C.) y según lo expresado por LANATTA, la excepción a la revocabilidad del testa
mento es precisamente la cláusula de reconocimiento de filiación. (Art. 395o C.C.).
Es S o le m n e : El testamento es un acto a d s o le m n it a t e m , su validez como acto jurídico está supe
ditado al cumplim iento de ciertos requisitos deforma. (Art. 219o C.C.)
Es testamento produce sus efectos sólo a la muerte del testador, por eso se dice que el testa
mento es un acto de disposición m o r t is c a u s a , mientras se encuentra con vida el testador.
No confiere a los instituidos ningún derecho actual.
Formalidades generales de los testamentos
De acuerdo al Art. 695o C.C. entre las formalidades tenemos: forma escrita, la fecha de
otorgamiento, el nombre del testadory la firma.
336 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 337 of 1506 --

Tema 2: Tem as de derecho civil
Clases de Testamentos
Tenemos los siguientes:
1. Testamentos Ordinarios: Testamento en Escritura Pública. Testamento Cerrado, Testa
mento Ológrafo.
2. Testamentos Especiales: Testamento Militar, Testamento Marítimo, Testamento otorga
do en el extranjero.
TESTAMENTO POR ESCRITURA PÚBLICA: Conocido también testamento público,
abierto o auténtico, es el que otorga personalmente el testador en presencia de dos testi
gos, ante un notario que lo escribe en su registro.
Formalidades (Art. 6 9 6 ° C.C.)
Manifestación de Voluntad: El testamento es un acto personalísimo e indelegable, el
testador debe expresar por sí mismo su voluntad o, tratándose de una persona con dis
capacidad, con el otorgamiento de ajustes razonables o apoyos para la manifestación de
su voluntad, en caso lo requiera. Si así lo requiere, dictando su testamento al notario o
dándole personalmente por escrito las disposiciones que debe contener.
Redacción Manuscrita del Notario: El notario deberá escribir el testamento de su puño
y letra o a través de medios de tecnología informática u otros de naturaleza similar, en su
registro de escrituras públicas, pudiendo insertar, de ser el caso, las disposiciones escritas
que le sean entregadas por el testador.
Lectura del Testamento: Una vez redactado el testamento, deberá darse lectura, clara y
distintamente, por el Notario, el testador o el testigo testamentario que éste elija.
Durante la lectura, al fin de cada cláusula, se verifique si el contenido corresponde a la ex
presión de su voluntad. Si el testadorfuera una persona con discapacidad, podrá expresar
su asentimiento u observaciones directamente o través de ajustes razonables o apoyos en
caso lo requiera.
El notario deberá dejar constancia de las indicaciones que, luego de la lectura, pueda ha
cer el testador, y salve cualquier error en que se hubiera incurrido.
La Firma: Después de la lectura del testamento y estando conforme se procederá a la
firm a en el mismo acto, por el testador, los testigos y el Notario, no sólo al final de la escri
tura sino tam bién en cada unadesus páginas, pues lafirm aes la prueba de su aprobación
por el testador, de haber sido elementos presenciales en el caso de los testigos y de haber
autorizado el acto con arreglo a derecho por el Notario.
Si el testador es analfabeto, deberá leérsele el testamento dos veces, una por el notario y
otra por el testigo testamentario que el testador designe. Si el testador no sabe o no pue
de firmar, lo hará a través del uso de la huella dactilar, de todo lo cual se mencionará en el
testamento. En caso no tenga huella dactilar, el notario debe hacer uso de cualquier otro
medio de verificación que permita acreditar la identidad del testador.
Unidad del Acto: Todas las formalidades antes mencionadas deben cumplirse en un solo
acto, en el cual estén reunidos desde el principio hasta el fin, el Notario, el testadory los 2
testigos hábiles. El notario está obligado a verificar la identidad del testadory los testigos
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 338 of 1506 --

UBILEX
a través del documento de identidad y los medios de identificación biométrica estable
cidos por el RENIEC. Cualquiera de los testigos puede actuar como testigo a ruego del
testador o testigo de identidad.
El apoyo de la persona con discapacidad puede ser beneficiario: En caso en que el apo
yo de la persona con discapacidad sea un beneficiario del testamento, señala el inciso 9
incorporado por el Decreto Legislativo 1384, se requiere el consentimiento del juez, apa
rentemente el mecanismo sería a través de un proceso no contencioso.
TESTAMENTO CERRADO: Conocido también como testamento secreto o místico es
aquel otorgado por el testador y que es entregado en forma personal al Notario dentro
de un sobre cerrado o con la cubierta clausurada en presencia de dos testigos hábiles,
indicando que contiene su últim a voluntad sobre el cual el Notario extiende el acta de su
otorgamiento, que la transcribe a su Registro asumiendo la custodia del testamento.
Formalidades (Art. 699oC.C) .
La Redacción del Testamento: Nuestra legislación no admite form alidad alguna, el tes
tador puede redactarlo en cualquier papel, puede ser hecha a máquina o en forma ma
nuscrita, como desee, cuando quiera o donde quiera.
Tratándose de un testamento otorgado por una persona con discapacidad por deficiencia
visual, podrá ser otorgado en un sistema braile o utilizando algún otro medio o formato
alternativo de comunicación, debiendo contar cada folio con la impresión de su huella
dactilary su firma.
El otorgamiento ante el Notario y los Testigos: Cuando el testador considere que ha
concluido de redactar su últim a voluntad, el testador debe colocar el testamento dentro
de un sobre, cerrar la cubierta o sellarla de tal modo que el testamento no pueda extraído
sin que se produzca la rotura o alteración de la cubierta.
El testador personalmente debe entregar al Notario ante dos testigos hábiles el sobre
cerrado expresando que su voluntad testamentaria se halla contenida en el pliego inte
rior que va dentro del sobre. A continuación el Notario extenderá el acta respectiva de su
otorgamiento, en la que se debe consignar la identificación del testador, la capacidad con
que procede, el haberse cumplido con las formalidades legales, el lugar, día, mesy año de
su otorgamiento y la firm a por el testador, el Notario y los testigos.
La conservación del testamento: Una vez extendida el acta de su otorgamiento en la cu
bierta del sobre el testamento queda depositado en poder y custodia del Notario. (Art.
700o C.C.)
TESTAMENTO OLOGRAFO: Son formalidades esenciales del testamento ológrafo, que
sea totalmente escrito, fechado y firmado por el propio testador.
Este testamento es otorgado en privado, sin la presencia de Notario o la intervención de
testigos, pero no obstante su privacidad no deja de ser un acto jurídico solemne en cuan
to la validez de este testamento está supeditado al cumplim iento de formalidades, cuya
observancia puede traer consigo la nulidad del acto, y ellos son que el texto, la fecha y la
firm a del testamento hayan sido escritas por el propio testador.
38 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 339 of 1506 --

Tema 2: Te m as de derecho civil
Si lo otorgara una persona con discapacidad por deficiencia visual, podrá ser otorgado en
sistema braile o utilizando algún otro medio o formato alternativo de comunicación.
Desde el inicio de la redacción del testamento es un documento privado, pero después de
la comprobación judicial y posterior protocolización notarial, en un plazo máximo de un
año contado desde la muerte del testador, se confiere al testamento ológrafo la condición
de instrumento público.
Apertura judicial: Presentado el testamento ológrafo con la copia certificada de la parti
da de defunción del testador o declaración judicial de muerte presunta, el juez, con cita
ción a los presuntos herederos, procederá a la apertura si estuviera cerrado, pondrá su fir
ma enteray el sello del juzgado en cada una de sus páginasy dispondrá lo necesario para
la comprobación de la autenticidad de la letray firm a del testador mediante el cotejo, de
conformidad con las disposiciones del Código Procesal Civil que fueran aplicables. Solo
en caso de faltar elementos para el cotejo, el juez puede disponer que la comprobación
sea hecha por tres testigos que conozcan la letray firm a del testador.
En caso de un testamento otorgado en sistema braille uotro medio o formato alternativo
de comunicación, la comprobación se hará sobre la firm a y huella digital del testador.
TESTAMENTO MILITAR: Solamente puede usarse esta forma testamentaria en tiempo
de guerra dentro o fuera del país, tal como lo precisa el Art. 712o C.C., quienes pueden
otorgarlo son los miembros de las fuerzas armadas y fuerzas policiales, que estén dentro
o fuera del país acuartelados o participando de operaciones bélicas; las personas que sir
van o sigan a esas fuerzas, tales como los profesionales de la salud, los guías voluntarios,
los rehenesy los prisioneros de guerra que estén en poder de las mismas.
Formalidades
El testamento m ilitar puede ser otorgado ante un oficial, Jefe de Destacamento, Puesto
o Comando al que pertenezca el testador, no es necesario que dicho Jefe tenga la clase
de oficial ni que ostente determinado cargo; si el testador está enfermo o herido puede
hacerlo también ante el capellán o médico que lo asista. El Art. 713o C.C exige que el tes
tamento sea por escrito, nuestro ordenamiento no admite testamento oral. Se exige la
presencia de z testigos hábiles.
El Art. 714o C.C. ordena que el testamento sea haga llegar a la mayor brevedad posible por
conducto regularal Cuartel General, luego al Ministerio de Defensa que lo remitirá al juez
del últim o dom icilio del causante.
El testamento m ilitar sólo se justifica en las circunstancias en que fue otorgado, por loque
caduca dentro del plazo de 3 meses de que el testador deje de estar en campaña y llegue a
un lugar del territorio nacional y pueda otorgar testamento en forma ordinaria. (Art. 715o
C.C.)
TESTAMENTO MARÍTIMO: Conocido como testamento de los navegantes, según el Art.
716o C.C., es aquel que pueden otorgar durante el período de navegación acuática todos
cuantos se encuentren a bordo de un buque de guerra peruano o de un barco mercante
de bandera nacional.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R A M IE N TO DE JUECES Y FISCALES

-- 340 of 1506 --

UBILEX
El fundamento de esta forma especial de testar radica en la situación de riesgo que su
pone el viaje por m ary la imposibilidad que tienen de acudir a un Notario quienes por
estar embarcados y navegando no pueden usar las formas ordinarias del testamento por
escritura pública o el testamento cerrado.
Pueden usar esta forma testamentaria los jefes, oficiales, tripulantes, pasajeros que se
encuentren a bordo de una nave de travesía que es la navegación de altura o por alta mar
o en la de cabotaje que es a través de Puertos de un mismos litoral, en los barcos de la ar
mada, o dedicados al transporte de carga, a fines industriales como los de pesca de altura,
o a fines políticos.
Formalidades: De acuerdo a lo establecido por el Art. 717o C.C., el testamento debe cons
tar por escrito, sin que se establezca ninguna especificación en cuanto a que sea manus
crito por el testador u otra persona, por lo que incluso podría admitirse la validez de tes
tamentos marítimos redactados por medios mecánicos o informáticos.
Debe otorgarse ante quien tenga el mando de la nave, el Comandante en el caso de un
buque de la armada o ante el Capitán en el caso de un barco mercante, o ante alguno
de los oficiales a quienes éstos deleguen esta función, otorgamiento que se efectuará en
presencia de 2 testigos quienes firmarán conjuntamente con el testadory la persona ante
quien se otorga el testamento.
El testamento m arítimo debe otorgarse por duplicado con las firmas que el original, a fin
de uno de esos ejemplares pueda entregarlo el Comandante o Capitán de la Nave, bajo
cargo, al agente Consular del Perú si lo hubiere en el primer puerto al que arribe el barco,
el que a su vez remitirá al Ministerio de Defensa o Dirección General de Capitanías según
corresponda.
El testamento debe ser anotado en el diario de bitácora, que es un libro o registro obli
gatorio que toda nave debe llevar para que se anoten las incidencias importantes que
ocurran en la nave.
El Art. 720o C.C. señala que el testamento marítimo caduca a los 3 meses de haberse des
embarcado definitivamente el testador.
- TESTAMENTO OTORGADO EN PAÍS EXTRANJERO: Se le conocía con el nombre de
testamento consular y puede otorgarse por escritura pública o en la forma cerrada, y no
en forma ológrafa pues esta forma privada no requiere la intervención notarial o consular
y puede otorgarse en cualquier lugar del país o del extranjero, siendo por ende válido el
testamento ológrafo otorgado en el extranjero cuya eficacia empero será relativa tratán
dose de un peruano residente en el extranjero, si es que la legislación de dicho país no
reconociera la validez del testamento ológrafo por regir en materia de sucesiones la ley
del domicilio del causante. (Art. 2100o C.C.).
En el testamento consular se requerirá adicionalmente a los requisitos establecidos, que
la firm a del Agente Consular en la escritura pública o en la cubierta del testamento cerra
do se legalice por el Ministerio de Relaciones Exteriores del Perú.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 341 of 1506 --

Tema 2: Temas de derecho civil
El Art. 722o C.C. admite la validez de ese testamento para lo cual deberá el Cónsul del país
legalizar la firm a del Notario Extranjero y a su vez el ministerio de Relaciones Exteriores
certificar la del Cónsul.
CAPACIDAD PARA TESTAR:
P o d e m o s a f ir m a r q u e t ie n e n c a p a c id a d p a r a t e s ta r to d a s la s p e r s o n a s q u e n o se e n c u e n
tr a n e x p r e s a m e n t e a fe c t a d a s p o r la s c a u s a le s d e in c a p a c id a d t a x a t iv a m e n t e e n u m e r a d a s
e n el A rt. 6 8 7 o C .C .
El testamento es un acto jurídico, que requiere para su validez que sea otorgado por agen
te capaz. (A r ti4 0 ° inc. 1 C.C.). con la nueva redacción del inc. 1 del art. 140, modificado por
el Decreto Legislativo 1384, los testamentos deberán ser otorgados por personas en plena
capacidad de ejercicio.
El m a e s tro R ó m u lo L a n a tta a se v e ra q u e la c a p a c id a d d e l te s ta d o r o d e te s ta r es u n a m o d a li
