INCAPACIDAD PARA TESTAR:
Lo determina el Art. 687o C.C:
i. Los menores de edad: Tienen plena capacidad de ejercicio de sus derechos civiles las
personas que hayan cumplido los 18 años de edad, esto incluye a todas las personas
con discapacidad, en igualdad de condiciones con las demás y en todos los aspectos
de la vida, independientemente de si usan o requieren de ajustes razonables o apo
yos para la manifestación de su voluntad, según lo establecido por el Art. 42o C.C.,
por lo tanto están impedidos de otorgar testamento los menores de edad.
La excepción se da para los mayores de 16 años que hayan obtenido título oficial que
lo autorice para ejercer una profesión u oficio.
Cesa la incapacidad, a partir del nacimiento del hijo o la hija sólo para inscribir el
nacimiento y reconocer a sus hijos, reclamar o demandar por gastos de embarazo y
parto, para demandar y ser parte en los procesos de tenencia, alimentos y régimen
de visitas a favor de sus hijos e hijas, Demandary ser parte en los procesos de filia
ción extramatrimonial de sus hijos e hijas, Celebrar conciliaciones extrajudiciales a
favor de sus hijos e hijas, sol icitar su inscripción en el Registro Único de Identificación
de Personas Naturales, tram itar la expedición y obtener su DNI e impugnar judicial
mente la paternidad.
ii. Los ebrios habituales: El e b r io h a b it u a l es la p e r s o n a a d ic t a a la s b e b id a s a lc o h ó li
cas. La e b r ie d a d c o n s u e t u d in a r ia c o n d u c e a la d e g r a d a c ió n y a u t o d e s t r u c c ió n d e la
p e r s o n a c o n g ra v e d e te r io r o y h a s t a p é r d id a d e la c a p a c id a d d e d is c e r n im ie n t o .
iii. Los toxicómanos: Conocido también como drogadicto a la persona que debido al
consumo de sustancias estupefacientes ha desarrollado fármaco-dependencia se
vera que no le permite vivir sin consumirdrogas.
