e n c u e n t r a n p r iv a d o s d e la f a c u lt a d d e d is p o n e r d e s u s b ie n e s p o r te s ta m e n t o .
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 341

-- 342 of 1506 --

UBILEX
¡v. Las personas que se encuentren en estado de coma, quien, por evidentes razones,
no podrá otorgar testamento, ni siquiera con apoyos o guardas porque el testamento
es un acto personalísimo e indelegable conforme se manda en el artículo 690o del
C.C.
6. Lim itaciones del notario y de los testigos
De acuerdo a lo dispuesto por el Art. 704o C.C. el testador está impedido de intervenir en el
otorgamiento de un testamento por escritura pública o de autorizar un testamento cerrado, si
el testador es su pariente dentro del cuarto grado de consanguinidad o segundo de afinidad,
en cuyo caso el testamento será nulo de pleno derecho por haber infringido la formalidad
exigida por nuestro código, tal como lo dispone el Art. 811o C.C.
Nuestro ordenamiento jurídico exige la presencia de testigos en el otorgamiento de todos los
testamentos a excepción del testamento ológrafo, pero en contraparte nos señala taxativa
mente quienes no pueden ser testigos testamentarios en el Art. 705o C.C. (Los que son incapa
ces de otorgar testamento; los analfabetos; los herederos y los legatarios en el testamento en
que son instituidos y sus cónyuges, ascendientes, descendientes y hermanos; los que tienen
con el testador los vínculos de relación fam iliar indicados en el inciso anterior; los acreedores
del testador, cuando no pueden justificar su crédito sino con la declaración testamentaria; el
cónyuge y los parientes del notario, dentro del cuarto grado de consanguinidad o segundo
de afinidad, y los dependientes del notario o de otros notarios; y los cónyuges en un mismo
testamento).
Pero aquellos testigos llamados por el testador y cuyos impedimentos no sean notorios, no
debe conllevar su participación a anular el testamento, ya que el error en su designación de
parte del testador que actuó de buena fe no debe ser perjudicado, dicha circunstancia ha sido
previstay solucionada por nuestros legisladores en el Art. 706o C.C.
7. Condiciones para heredar
La sucesión es la transmisión patrimonial y de otros derechos por causa de muerte, para que
se verifique la transmisión se deben darse dos presupuestos: la existenciay el mejor derecho.
La Existencia: El Art. i° de nuestro Código Civil nos dice que la persona humana es sujeto de
derecho desde su nacimiento, por lo tanto la capacidad para suceder se refiere a la existencia.
Por excepción, la capacidad comprende al nasátums, persona concebida al momento del falleci
miento del causante, que nace viva, su derecho se suspende mientras el nacimiento no se efectúe.
El segundo párrafo expresa que el concebido es sujeto derecho para todo cuanto lefavorezcay
que la atribución de derechos patrimoniales está condicionada a que nazca vivo.
Las personas jurídicas también pueden heredar, pero sólo pueden hacerlo a través de la su
cesión testamentaria, el supuesto es que deben existir para suceder, de acuerdo al Art. 77o
C.C. las personas jurídicas de derecho privado existen a partir de su inscripción en el registro
respectivo.
El Mejor Derecho: El m e jo r d e r e c h o e s tá re fe rid o a la c o n d ic ió n d e su c e so r, s ig n if ic a no e s ta r
p r e c e d id o p o r u n s u c e s o r p r e fe rib le .
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 343 of 1506 --

Tema 2: Temas de derecho civil
Existe un orden para suceder, y está establecido por el Art. 816o C.C. se determina quienes de
ben recibir la herencia excluyéndose unos a otros. Los parientes de la línea recta descendente
excluyen a los de la ascendente, y los parientes más próximos en grado excluyen a los más
remotos, salvo el derecho de representación como lo ordena el Art. 817o C.C. El (la) cónyuge o,
en su caso, el integrante sobreviviente de la unión de hecho son los únicos que concurren con
los dos primeros órdenes.
8. Premoriencia y conm oriencia
Respecto al fallecimiento de varias personas ocurridas como consecuencia de un mismo acon
tecimiento, como puede ser un accidente, un terremoto, un naufragio o una guerra, se plantea
el problema de determinar el orden en que se produjeron las muertes para poder determinar
si hubo entre las personas transmisión de derechos hereditarios.
Para este tipo de acontecimientos se han elaborado dos teorías: la premoriencia y la conmo
riencia.
Teoría de la premoriencia: En este caso, por circunstancias de hecho, edad y sexo, debe pre
sumirse que unas personas fallecieron con anterioridad a otrasy que, en consecuencia, habría
entre ellas transmisión sucesoria.
Teoría de la conmoriencia: Sostiene que no puede presumirse que una persona falleció antes
que otra sino, mas bien, que todas fallecieron al mismo tiempo, en consecuencia, no puede
existir entre ellas transmisión sucesoria.
Nuestro ordenamiento jurídico ha optado por esta teoría y la plasma en el Art. 62o C.C., que
preceptúa que si no se puede probar cuál de dos o más personas murió primero, se le reputa
muertas al mismo tie m p oy entreellas no habría transmisión de derechos hereditarios, la pre
sunción esjuris tantum .
9. La legítim a
Concepto. El Art. 723o C.C. define legítima como parte de la herencia de la que no puede dis
poner libremente el testador cuando tiene herederos forzosos.
La legítima o reserva hereditaria es una restricción o limitación a la voluntad del testador, la
ley obliga a dejar a ciertos herederos llamados forzosos o legitimarios una porción considera
ble de la herencia instituyéndolos como sus beneficiarios aún contra su voluntad, de modo
que no existe en nuestro ordenamiento libertad absoluta o irrestricta de testar.
Fijación de La Legítima: Nuestro Código Civil determina la extensión de la legítima partiendo
de la cuota de libre disposición, la misma que es variable de acuerdo a la existencia o inexis
tencia de herederos forzosos que de acuerdo al Art. 724o C.C. son: a) Los hijos y demás des
cendientes, b) Los padres y demás ascendientes, y c) El cónyuge o, en su caso, el integrante
sobreviviente de la unión de hecho. Pudiendo ser de dos tercios (2/3), si hay descendientes,
cónyuge, o integrante sobreviviente se la unión de hecho y un medio (1/2) si solamente hay
padres u otros ascendientes.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 344 of 1506 --

UBILEX
a) Hijos ti otros descendientes o cónyuge o integrante sobreviviente de la unión de hecho (Art.
725o C.C.)
2/3 Legítima 1/3 Cuota de Libre Disposición.
b) Sólo padres u otros ascendientes (Art. 726o C.C.)
1/2 Legítima 1/2 Cuota de Libre Disposición.
Legítima de los Hijos y demás descendientes: Dentro de los hijos y demás descendientes se
incluye a los hijos matrimoniales, extramatrimoniales reconocidos voluntariamente o decla
rados por sentencia judicial y los hijos adoptivos y sus descendientes.
Notiene en cambio calidad de legitimario el llamado hijo alimentista pues en rigor no llegará
a tener establecida su filiación con el causante, pero si el testador estuviese obligado el pago
de una pensión alimenticia, la porción disponible quedará gravada hasta donde fuera necesa
rio para cumplirla, según el Art. 728o C.C.
Cuando hay hijosy descendientes de cualquier grado que fuesen, la legitimase extiende a 2/3
de la herencia, incluidas las donaciones si se hubiesen otorgado, tal como se ha precisado en
la cuestión relativa al modo de calcular la legítima. Esta extensión se deduce de la porción de
libre disponibilidad fijada por el Art. 725o C.C. La Legítima debe distribuirse en partes iguales
entre los hijos, según el Art. 818o C.C., que atribuye a los hijos igual derecho sucesorio sin dis
tinción del origen de la filiación.
Legítima de los Ascendientes: Se considera entre los legitimarios a los padres y demás as
cendientes; entre los padres únicamente a aquellos que hayan reconocido voluntariamente
al causante, negándose el carácter de legitimarios a quienes hubiesen sido forzados a asumir
su paternidad por sentencia judicial, quienes se encuentran excluidos de vocación sucesoria
según el Art. 412o C.C.
El Art. 398 del C.C. establece que el reconocimiento de un hijo mayor de edad no confiere al
que lo hace derechos sucesorios salvo que haya existido entre ellos posesión constante de
estado o el hijo haya consentido en el reconocimiento.
Los ascendientes son llamados a heredar en calidad de legitimarios únicamente en caso de
que no existan descendientes, bastará entonces que exista uno solo para que todos los ascen
dientes sean excluidos, y en cambio sí hay cónyuge no habrá exclusión sino más bien concu
rrencia. (Art. 726o C.C.).
Legítima del cónyuge: La e x te n s ió n d e la le g ít im a c u a n d o el de cujus d e ja c ó n y u g e s o b r e v i
v ie n t e es d e la s 2 /3 p a rte s d e la h e r e n c ia c o n s id e r á n d o s e d e n t r o d e e lla , p a ra e fe c to s d e l c á lc u
lo, el v a lo r d e la s lib e r a lid a d e s o t o r g a d a s en v id a d e l c a u s a n t e , d if e r e n c ia q u e se d e d u c e d e la
c u o t a d e lib r e d is p o s ic ió n d e q u e g o z a el t e s t a d o r c u a n d o t ie n e n c ó n y u g e q u e es d e 1/3 s e g ú n
el A rt. 7 2 5 o C .C . c u y a c u o t a d e n t r o d e la p o rc ió n le g it im a r ia es ig u a l a la d e u n h ijo o a la d e un
a s c e n d ie n t e c o n q u ie n o q u ie n e s le t o q u e c o n c u rrir.
En los casos de concurrencia es adecuado que se haya dispuesto que la cuota del cónyuge es
igual “a la de un hijo” como lo establece el Art. 822o C.C., pero no ocurre lo mismo cuando se
trata de la concurrencia con ascendientes, pues no se iguala la cuota del cónyuge a la de un
padre sino a la de uno de los ascendientes como lo establece el Art. 824o C.C.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 345 of 1506 --

Tema 2: Temas de derecho civil
Legítima del integrante sobreviviente de la unión de hecho: Con respecto al conviviente
sobreviviente de una unión de hecho, denominado integrante sobreviviente de unión de he
cho, según la Ley N° 30007 (Pub. 17.04.2013), éste tendrá tal calidad siempre y cuando reúna
las condiciones previstas en el artículo 326 del C.C., así tendrá derechos sucesorios sobre el
patrimonio de su fallecido conviviente, no solo tendrá el derecho a recibir bienes y derechos
patrimoniales, sino también deberá asumir las obligaciones transmisibles por herencia que
hubiera dejado el fallecido conviviente.
Asi, los convivientes pueden heredarse entre ellos y participar de la herencia como herederos
forzosos con una porción igual a la que le correspondería en caso de ser casados o cónyuges,
es decir, las 2/3 partes de la herencia.
Con el reconocimiento de la calidad de heredero forzoso al conviviente sobreviviente se le
puede instituir como heredero en el testamento con derecho a la legítima. Y en sucesión in
testada, la calidad de heredero del conviviente es preferencial y concurrente con los parientes
del prim ery segundo orden sucesorio.
Intangibilidad de la Legítima: El Art. 733° C.C. establece que el "testador no puede privar de
la legítima a sus herederos forzosos” salvo en los casos expresamente determinados por la ley.
Las modalidades más frecuentes de afectar la legítima son:
1. El menoscabo o disminución de la legítima: Que se produce cuando el testador se ex
cede de sus facultades de libre disposición, de modo que no deja bienes suficientes para
satisfacer el pago de las legítimas.
Para remediar esta situación, la ley franquea en el Art. 807o C.C. la acción de reducción,
llamada también de complemento o suplemento de la legítima.
2. La preterición: Que viene a ser la omisión o exclusión de un heredero forzoso en el testa
mento del causante que teniendo la obligación de instituirlo, guarda silencio respecto de
su designación causándole con ello un despojo, una privación a su derecho legitimario.
El heredero preterido puede pedir la caducidad de la cláusula testamentaria, según el Art.
806o C.C.
3. La imposición de cargas o gravámenes: El testador impone modalidades a la legítima,
estableciéndose condiciones, cargas o gravámenes a favor de terceros; en este caso la so
lución es más sencilla, no se requiere el ejercicio de una acción, la sanción opera de pleno
derecho según el Art. 736o C.C., las modalidades que se imponga el testador a los herede
ros forzosos se tendrán por no puestas.
10. Institución y sustitución de herederos y legatarios
La institución de herederos exige dos requisitos: debe recaer en persona cierta y debe ser he
cha sólo por testamento (Art. 734° C.C.)
El testamento, que es el acto jurídico por el cual una persona ordena su propia sucesión y el
destino de su patrimonio para después de su fallecimiento, puede tener disposiciones de ca
rácter patrimonial y también disposiciones no patrimoniales, e incluso puede solamente con
tener este tipo de disposiciones no patrimoniales.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 346 of 1506 --

UBILEX
Una de las disposiciones de contenido típico, relativos al destino del patrimonio del causante
lo constituye la denominada cláusula de institución de herederos y legatarios, que viene a ser
la disposición por el cual el testador nombra, designa o instituye a sus sucesores que pueden
ser herederos o legatarios que deberán suceder al testador en la titularidad de sus bienes,
derechosy obligaciones.
Caracteres de la institución de herederos y legatarios
Podemos distinguir:
Debe ser hecha por el testador.
La institución o designación de herederos y legatarios debe ser hecha personalmente por
el testador.
La institución debe hacerse en forma inequívoca.
La in s t it u c ió n d e h e r e d e r o s y le g a t a r io s d e b e r e c a e r s o b re p e r s o n a c ie r ta s e g ú n el A rt.
734° C.C.
La institución de persona cierta puede recaer en personas físicas incluso en los concebi
dos o a favor de personas jurídicas.
La institución de herederos es a título universal.
Así lo señala el Art. 735o C.C., esa calidad le confiere el derecho sobre la totalidad de los
bienes, derechosy obligaciones que constituye la herencia o sobre una parte alícuota de
ellas.
La institución de legatario es a título particular.
El testador con cargo a cuota de libre disposición puede instituir legatarios, quienes por lo
general suceden a título particular o singular, es decir el derecho del legatario se circuns
cribe a los bienes específicos o determinados que han sido materia de la liberalidad.
Distinción entre heredero y legatario
S i el d e r e c h o d e l s u c e s o r p r o v ie n e d e l p a re n t e s c o c o n s a n g u ín e o o d e l v ín c u lo d e l m a t r im o n io ,
s u c a lid a d s e r á la d e h e re d e ro .
Si el beneficio se otorga más por liberalidad que por derecho o adicionalmente a éste, la cali
dad del sucesor será la de legatario, pudiendo el sucesor detentar esa doble calidad pues no
resultan excluyentes los derechos que emergen de ambas calidades de sucesores en la misma
persona.
11. La sustitución
El testador puede designar sustituto de los herederos voluntarios y de los legatarios para el
caso en que el instituido muera antes del testador, o que renuncie a la herencia o al legado o
que los pierda por indignidad (Art. 740o C.C.).
Esta institución es subsidiaria o defectiva para el caso de que el o los primeros instituidos no
llegaran a recibir la herencia.
La sustitución sólo puede disponerse para el caso de los herederos voluntarios o legatarios, no
así para los herederos forzosos o legitimarios, a los cuales no se les puede nombrar sustitutos,
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 347 of 1506 --

Tema 2: Temas de derecho civil
así los establece el Art. 7 4 6 ° C.C. que contempla esta figura únicamente para el caso de la ins
titución de herederos voluntarios y los legatarios, y el Art. 733° C.C. que prohíbe imponer sus
titución a los herederos forzosos o legitimarios, a quienes no se les puede perm itir sustitutos,
por el carácter intangible de la legítima de la cual el testador no puede disponer libremente.
Nuestro Código Civil acepta únicamente la sustitución vulgar u ordinaria que está regulada
por el Art. 740° C.C., por ser inconveniente que el orden sucesorio voluntario regido por el tes
tamento se superponga al orden legal hasta desvirtuarlo.
12. Los albaceas
Los albaceas son los ejecutores testamentarios a quienes el testador nombra para que cum
plan sus disposiciones de últim a voluntad.
El maestro Jorge Eugenio Castañeda decía que el albacea es un mandatario del testador, que
tiene la función de vigilar y actuar para que se ejecute la últim a voluntad de dicho testador,
esta función constituye la llamada ejecución testamentaria.
Requisitos: Todas las personas mayores de edad pueden ser albaceas con excepción de las
personas que están incursas en los artículos 667o (causales de indignidad), 7 4 4 ° (causales de
desheredación de descendientes), 745° (causales de desheredación de ascendientes) y 746o
(causales de desheredación del cónyuge).
El profesor Luis Echecopar García refiere que si una persona no puede adquirir bienes por he
rencia, no sería justificado que asumiera la representación y la administración de un patrim o
nio ajeno.
Clases: Atendiendo al origen de su nombramiento:
Testamentarios: Son los designados por el causante en su testamento. (Art. 779° C.C.)
Legales: A falta de albacea testamentario, sus funciones y atribuciones serán ejercidas por
los herederos con la condición de albaceas legales o legítimos según el Art. 792o C.C.
Dativos: Son los nombrados por el juez, a falta de nombramiento por el causante cuando
los herederos no se ponen de acuerdo. (Art. 792. C.C.)
Por la extensión de sus facultades:
Universales: Son los nombrados para ejercer las facultades del cargo sin limitaciones.
Particulares: Son los que han sido encomendados sólo para cumplir determinadas funcio
nes.
Por el número:
Singulares: Es el caso del encargo dado a una sola persona.
Plurales: Es el caso del encargo dado a varias personas, que pueden ser ejercidos sim ultá
neamente o de manera sucesiva.
Caracteres
Es voluntario: La designación no obliga a la persona en la cual recae el nombramiento, esta
puede aceptar o renunciar a él (Art. 785o C.C.) o sea se perfecciona el albaceazgo con la
aceptación del designado.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 348 of 1506 --

Es personalísimo: La designación de albacea se inspira en un sentido de confianza que el
testador deposita en el designado, por lo que considera un cargo in tu ito personae.
Sólo quien ha sido designado por el testador puede desempeñar el cargo de albacea tes
tamentario, pero sólo en casos excepcionales podrá hacerse representar por mandatarios
que obren a sus órdenes o bajo su responsabilidad (Art. 789o C.C.).
Es remunerado-. Por regla general el cargo de albacea es remunerado, salvo que el testador
haya dispuesto su gratuidad.
La remuneración puede ser fijada por testamento o por decisión judicial.
Si el testador no ha fijado remuneración alguna al designado puede señalarla el Juez a
solicitud del albacea, observándose que no exceda el 4% de la masa líquida según el Art.
793° C.C.
Es temporal: El plazo para ejercer el cargo del albaceazgo es de 2 años de acuerdo a lo de
terminado por el Art. 796° inc. 1) el encargo es temporal, circunstancial y necesariamente
pasajero.
El plazo puede ser mucho mayor si así lo ha dispuesto el testador, el mismo puede ser
prorrogado por el Juez con acuerdo de los herederos.
Atribuciones del albacea. Según el Art. 787o C.C. son las siguientes:
1. Atender la inhumación o la incineración del cadáver si éste así lo ha dispuesto. Esta función será
ejercida siempre que el testador no tenga parientes directos. Quien primero determina la
forma de los funerales es el propio testador, de no hacerlo se deberá proceder de acuerdo,
al Art. 13o C.C.
2. Ejercitar acciones para la seguridad de los bienes hereditarios. La ley y el testador confieren am
plias facultades conservativas para cautelar la indemnidad de los bienes de la herencia,
adoptando todo tipo de providencia en oren a ese cometido.
3. Hacer inventario. Dentro de las facultades conservativas el albacea debe hacer un inventa
rio de los bienes que le pertenecen al causante a su fallecimiento, el que debe ser judicial
con la citación de los herederos y demás interesados en la sucesión.
4. A dm inistrar los bienes de la herencia. El albacea es el administrador de los bienes del tes
tador, debe velar por su conservación, arrendarlos cuando sea necesario, atender a los
gastos de su mantenimiento, el pago de los impuestos, etc.
5. Pagar deudasy cargas. Los herederos responden de las deudas y cargas de la herencia hasta
donde alcance los bienes de ésta según establece el Art. 661o C.C.
6 . Pagar o entregar legados. Después de satisfechos los pasivos que el causante haya dejado
y que estén debidamente acreditados recién pueden pagarse los legados hasta donde lo
permita la porción de libre disposición del testador, y hacerlo con conocimiento de los
herederos.
7. Venderlos bienes hereditarios. El albacea podrá efectuar la venta de bienes siempre que se
encuentre autorizado porel testador, los herederos o el Juez, en los casos que es indispen
sable para pagar deudas, cumplir los legados o facilitar la partición.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 349 of 1506 --

Tema 2: Temas de derecho civil
8 . Cum plir los encargos especiales del testador. C a s o s en q u e el al b a c e a a c t ú a c o m o m a n d a t a r io
postm ortem d e l te s ta d o r.
9. Sostener la validez del testamento. El al b a c e a es p a rte le g it im a d a p a ra in t e r v e n ir en to d o s
lo s p r o c e s o s e n lo s q u e se d e m a n d a la in v a lid e z , im p u g n a c ió n o c a d u c id a d to ta l o p a r c ia l
d e u n t e s ta m e n t o , p o r lo q u e d e b e e m p la z a r s e n o s ó lo a lo s h e re d e ro s s in o t a m b ié n al
a lb a c e a .
Extinción del Albaceazgo
Las causas de la extinción del albaceazgo, están previstas en el Art. 796o C.C.:
1. Por haber transcurrido más de 2 años desde su aceptación, salvo mayor plazo que señale
el testador, o conceda el juez con acuerdo de la mayoría de los herederos.
El plazo se fija con el propósito de evitar dilaciones a que son proclives los albaceas que
tienden a prolongar su actuación limitando los derechos de los herederos.
2. Por haber concluido sus funciones.
Es la forma normal de terminar el albaceazgo; si se llega a cumplir la voluntad del testa
dor finaliza la ejecución del testamento.
3. Por renuncia con aprobación judicial.
El albacea puede excusarse de aceptar el cargo sin necesidad de explicar motivos por tra
tarse de una gestión de desempeño voluntario, pero una vez aceptado no puede renun
ciara él, si no es por causa justa.
4. Por incapacidad legal o física.
El albacea puede resultar afectado poruña incapacidad sobrevin ¡ente, que puede ser físi
ca o mental como una enfermedad, accidente o la privación del discernimiento o puede
sertambién jurídica, como una condena a una pena privativa de la libertad.
5. Por remoción judicial a petición de parte debidamente fundamentada.
La remoción es equiparable a una destitución por un incumplimiento en el desempeño
de sus funciones. El Art. 795o C.C. establece que da lugar a la remoción, el que el albacea
no haya hecho facción de inventario dentro de los 90 días contados a partir de la muerte
del testador, de protocolizado el testamento o de su nombramiento judicial.
6 . P o r s u m u e rt e , d e s a p a r ic ió n o d e c la r a c ió n d e a u s e n c ia .
Como el albaceazgo es un cargo de confianza, no se transmite a los herederos.
13. Ineficacia de disposiciones testam entarias
Revocación: La revocación es el acto porel cuaí una persona deja sin efecto o anula volun
tariamente, en todo o en parte, un testamento anterior.
La revocabilidad constituye una característica esencial de los testamentos y es un derecho
irrenunciable, toda declaración que se haga en contrario carece de valor. (Art. 798o C.C.).
