Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 351 of 1506 --

Tema 2: Temas de derecho civil
Asimismo se produce la caducidad o extinción de los derechos sucesorios prove
nientes del vínculo del matrimonio, si se hubiera declarado la separación ju d i
cial por culpa del cónyuge sobreviviente o en el caso del divorcio. La disposición
punitiva contra el culpable está contenida en el Art. 343° C.C.
U n o d e lo s e fe c to s d e l d iv o r c io es la p é r d id a d e lo s d e r e c h o s h e r e d it a r io s , a s í lo
e s t a b le c e el A r t 3 53° C .C .
2 .3 . P o r d e c la r a c ió n d e in d ig n id a d o d e s h e r e d a c ió n .
El heredero instituido pierde la herencia o caduca su designación si ha sido ex
cluido de la herencia por indignidad o desheredación, pero si los herederos de
jan descendientes estos pasan a recibir la herencia por representación.
El Art. 8 o 6° C.C. hace referencia a la caducidad de la cláusula de institución de
herederos, en el caso de la preterición, que es la omisión o exclusión de un here
dero forzoso en el testamento.
14. Nulidad de testam ento
El testamento es nulo cuando se han om itido los requisitos necesarios para su validez por al
guna causa existente al tiempo de su otorgamiento.
No es lo mismo testamento nulo que testamento revocado, en el primero la ineficacia se deri
va de un vicio que existe en el testamento desde su origen, mientras que el testamento revo
cado supone la existencia de un testamento válido antes de que su ineficacia sea determinada
por una nueva disposición del testador.
No es lo mismo testamento nulo y testamento caduco, este últim o pierde su eficacia no por
un vicio inmerso en el propio acto testamentario sino por un hecho sobrevinientey ajeno a la
voluntad del testador.
Siendo el testamento un acto jurídico son de aplicación para su validez los requisitos que enu
mera el Art. 140o C.C.*1
Es n u lo el t e s t a m e n t o o t o r g a d o p o r d o s o m á s p e r s o n a s (A rt. 8 1 4 o C .C .)
Los testamentos especiales son nulos de pleno derecho cuando falta la forma escrita, la firm a
del testador o de la persona autorizada para recibirlos (Art. 8i 3°C.C.)
15. Desheredación
La desheredación es el acto jurídico por el cual el causante priva de la herencia a su heredero
forzoso mediante expresa disposición testamentaria y fundado en alguna de las causales de
desheredación predeterminadas por la ley.
1 A r t íc u lo 14 0 . - El acto jurídico es la manifestación de voluntad destinada a crear, regular, modificar o extinguir
relaciones jurídicas. Para su validez se requiere:
1. - Plena capacidad de ejercicio, salvo las restricciones contempladas en la ley.
2. - Objeto físicay jurídicamente posible.
3. - Fin lícito.
4. - Observancia de la forma prescrita bajo sanción de nulidad.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 352 of 1506 --

UBILEX
Presupuestos: Para que opere la desheredación se requiere de:
1. Que exista causal (Art. 742° C.C)
2. Que esa causal esté basada en una de las razones establecidas por los Artículos 744°,
745° y 746oC.C.
3. Que el testador manifieste su voluntad indubitable de practicar desheredación, y
4. Que se trate de herederos forzosos.
Causales de Desheredación: La desheredación sólo puede efectuarse por alguna de las
causales taxativamente enumeradas por la ley (Arts. 744°, 745°, 746°y 74 7° C.C.), sin que
pueda aplicarse una interpretación extensiva a otros hechos no previstos, así se trate de
hechos muchos más graves.
Respecto de los Descendientes. Las causales del Art. 747° C.C. son:
1. Haber maltratado o injuriado grave y reiteradamente al ascendiente o a su cónyuge si
éste es también ascendiente del ofensor.
Se refiere al maltrato a la agresión o violencia contra la integridad física del testador o de
su cónyuge, no es necesario que se configure sevicia o trato excesivamente cruel.
La injuria, que es el maltrato moral o agravio a los sentimientos o dignidad del ascendien
te o de su cónyuge, se exige en cambio que sea grave y reiterada.
2. Haberle negado sin motivo justificado alimentos o haber abandonado al ascendiente en
contrándose éste gravemente enfermo o sin poder valerse por sí mismo.
Se admite en doctrina, que no es preciso que es negativa deba sustentarse con actuados
judiciales sobre alimentos, laque podrá acreditarse por otros medios de prueba.
3. Haberle privado de su libertad injustificadamente.
No habiéndose hecho referencia al delito tipificado por el Art. 152o C.R, para no supeditar
la aplicación de esta causal a una sentencia penal condenatoria, para permitirle al testa
dor a aplicar la sanción civil sin que necesariamente se le obligue adenunciar penalmente
a su heredero forzoso por el delito cometido en su agravio.
4. Llevar el descendiente una vida deshonrosa o inmoral.
Respecto de los Ascendientes. El Art. 745o C.C. prescribe:
1. Haber negado injustificadamente alimentos a sus descendientes.
Como la obligación alimentaria es recíproca, la hipótesis que se contempla es que el as
cendiente que se encontraba en posibilidad económica negó asistencia a su descendien
te que se encontraba en estado de necesidad.
2. Haber incurrido el ascendiente en alguna de las causas por la que se pierde la patria po
testad o haber sido privado de ella.
Las causales de pérdida o privación de la patria potestad que son por condena derivada de
delito cometido en agravio del menor, por abandono del hijo, por dar órdenes, consejos o
ejemplos corruptores, por dedicarlos a la mendicidad, por tratarlos con dureza excesiva,
52 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 353 of 1506 --

Tema2: lem as de derecho civil
etc. Están contemplados como causales de suspensión de la patria potestad en el Art. 83o
del Código de los Niñosy los Adolescentes.
Respecto del Cónyuge-. De acuerdo al Art. 746o C.C. las causales de desheredación son las mismas
causales de separación de cuerposy divorcio previstos en los seis primeros incisos del Art. 333o
C.C., a los que se hace remisión y que son el adulterio, la violencia física o psicológica, el aten
tado contra la vida del cónyuge, la injuria grave, el abandono injustificado de la casa conyugal
por más de 2 añosy la conducta deshonrosa que haga insoportable la vida en común.
Efectos
Los efectos de la desheredación se refieren a la legítima y no se extienden a las donacio-
nesy legados otorgados al heredero, que el causante puede revocar, ni a los alimentos de
bidos por ley, ni a otros derechos que correspondan al heredero con motivo de la muerte
del testador.
De acuerdo a lo establecido por el Art. 755° C.C. los descendientes del desheredado here
dan por representación la legítima que le correspondería a éste si no hubiera sido exclui
do.
16. Indignidad
Concepto: Consiste en lasanción civil que se impone al heredero o legatario cuando incu
rre con respecto al causante, sus ascendientes, descendientes, o cónyuge, en actos delic
tuosos o reprobables previstos por la ley como causales de indignación, por cuyo motivo
ese sucesor puede ser excluido de la herencia o el legado a instancia de los llamados a
sucederle a falta o en concurrencia con el indigno, siempre que la acción sea amparada
por sentencia judicial firme.
Presupuestos: Para que opere la exclusióny la pérdida del derecho hereditario se requie
re las siguientes condiciones:
1. Que el sucesor haya incurrido en algunas de las causales de indignidad.
2. Que se ejercite la acción respectiva de exclusión de un sucesor por indignidad antes
que venza el plazo prescriptorio que es relativamente breve.
3. Que el o los accionantes prueben dentro del proceso los hechos constitutivos de la
indignidad, salvo que se trate de causas de puro derecho.
4. Que la demanda sea amparada o se declare la indignidad por sentencia consentida
o ejecutoriada.
Causales: Pueden afectara los herederos y en la sucesión testamentaria.ya los herederos
legales en la sucesión intestada, las causales de indignidad se encuentran enumerados
en el Art. 667o del C.C.
1. Homicidio doloso o su tentativa: Esta causal de indignidad no desaparece por el in
dulto ni por la prescripción de la pena.
En esta causal no se requiere que se haya perpetrado el delito con la intención de
recoger la herencia del causante, es indiferente el móvil que lo haya impulsado a
cometer el delito.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 354 of 1506 --

UBILEX
La indignidad por la causal de homicidio o su tentativa no pueden ser impuestas sin
que medie una condena penal dictada en el proceso respectivo.
2. Condena por delito doloso: Esta causal no se refiere al delito de homicidio previsto en
la causal anterior, sino a otros delitos de carácter doloso que sanciona el Código Penal
siempre que el agraviado a consecuencia de los actos punibles del sucesorsean el cau
sante, sus descendientes, ascendientes o cónyuge que son herederos forzosos.
3. Denuncia calumniosa: Se priva del derecho hereditario aquel heredero que acusó al
causante en vida, da haber cometido un delito que por su gravedad la ley sanciona
con pena privativa de la libertad.
La imputación hecha contra el causante debe atribuirle la comisión de un ilícito pe
nal, y debe haber sido promovida ante la autoridad competente.
La denuncia basta por sí sola, no es preciso que se haya instaurado un proceso penal
o se haya obtenido una condena en base a ella.
La denuncia debe ser calumniosa, es decir, formulada a sabiendas de su falsedad y
que se presenta con el propósito de perjudicar o mortificar al causante.
4 . Dolo o violencia ejercidas contra el causante: Se busca proteger la voluntad testa
mentaria, lo que se pretende es que la declaración sea otorgada en forma libre y es
pontánea.
Como todo acto jurídico, el testamento debe ser producto de una voluntad libre y
espontánea, y será anulable según los Arts. 2 io °y 214° del C.C., si es que se prueba
que en su otorgamiento hubo vicios de la voluntad o falta de libre consentimiento,
de modo que es posible que puedan generarse 2 efectos jurídicos: la invalidación de
un testamento o su revocación y la exclusión del sucesor que haya empleado el dolo
o la violencia por indignidadsucesoria.
5. Destrucción de la voluntad testamentaria: La destrucción, el ocultamiento están
referidas al testamento ológrafo ya que un testamento por escritura pública o uno
cerrado, no se podrían destruir pues se encuentran bajo custodia notarial.
6 . Violencia familiar contra el causante: Son indignos de suceder los que hubieran
sido sancionados con sentencia firme en un proceso de violencia fam iliar en agravio
del causante.
7. Es indigno de suceder al hijo, el progenitor que no lo hubiera reconocido voluntaria
mente durante la minoría de edad o que no le haya prestado alimentos y asistencia
conforme a sus posibilidades económicas, aun cuando haya alcanzado la mayoría de
edad, si estuviera imposibilitado de procurarse sus propios recursos económicos.
8 . - Es indigno de suceder al causante el pariente con vocación hereditaria o el cónyuge
que no le haya prestado asistencia y alimentos cuando por ley estuviera obligado a
hacerloy se hubiera planteado como tal en la vía judicial.
La exclusión por indignidad del heredero o legatario debe ser declarada por sentencia, en
juicio que pueden promover contra el indigno los llamados a suceder a falta o en concu
rrencia con él.
354 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 355 of 1506 --

Tema2: lem as de derecho civil
La acción prescribe al año de haber entrado el indigno en posesión de la herencia o del
legado.
17. Indignidad y desheredación
Semejanzas: La indignidad y la desheredación tienen por objeto pues privar de la herencia al
sucesor que no merece recibirla; ambas figuras se basan en que la vocación hereditaria que
surge del parentesco, del matrimonio o de una declaración de voluntad del testador, supone
un vínculo de afecto, consideración y solidaridad que obliga a los posibles sucesores a obser
var una conducta acorde para mantener sus expectativas hereditarias.
Diferencias:
1. Por su extensión: La indignidad es más amplia funciona en la sucesión testada como in
testada, la desheredación es propia de la sucesión testamentaria.
2. Por el ámbito de los posibles afectados: La exclusión por indignidad es aplicable a todos
los sucesores, la desheredación sólo tiene sentido respecto de cierta clase de herederos
forzosos o legitimarios.
3. Por la calidad de heredero: La desheredación implica la privación de la vocación here
ditaria desde la apertura de la sucesión, lo que no ocurre con el indigno que conserva la
calidad de sucesor hasta la sentencia firme que lo declare como tal.
Efectos: Amparada la acción judicial interpuesta por los herederos llamados a heredar a falta
o en concurrencia del indigno, el sucesor culpable pierde todo derecho de heredar al causante.
El indigno no pierde el derecho de intervenir por representación de su causante en otra he
rencia, ya que como lo prescribe el Art. 68i° C.C. existe representación a los descendientes en
la herencia de su ascendiente cuando éste la hubiera renunciado o perdido por indignidad o
por desheredación.
18. Masa hereditaria
Zarate del Pino, señala que la masa hereditaria es un concepto de contenido patrimonial que
comprende a las relaciones jurídicas de las que el causante era titular, consideradas como una
universalidad; no se trata de la sucesión en el dominio de cada bien o especie que perteneció
al causante, sino como un derecho al todo, al conjunto, a la universitas, que comprende todo
el activo y pasivo q ue pertenecía al causante.
Debemos distinguir entre la masa hereditaria bruta de la masa hereditaria neta, la primera
comprende todos los bienes, derechosy obligaciones que pertenecían al causante; la segunda
llamada también herencia líquida es el patrimonio que resulta después de deducir de la masa
hereditaria bruta, las cargas y deudas de la herencia, luego los gananciales que corresponden
al cónyuge supérstite, al cual deben añadirse el valor de los bienes dados en calidad de dona
ción o anticipo de legítima a favor de los herederos forzosos si no fueron dispensados de la
obligación de colacionar.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 355

-- 356 of 1506 --

] y Colaaén
Es la operación mediante la cual un heredero forzoso, llamado a la sucesión en concurrencia
con otros, restituye a la masa hereditaria los bienes o valores recibidos del difunto a título
gratuito.
La figura de la colación permite establecer una igualdad entre los herederos forzosos, ya que
el causante ha podido real izar transferencias a título gratuito.
Las liberalidades realizadas por el causante en vida no son imputables a la cuota de libre dis
posición sino a la legítim ay se considera como un anticipo de aquella.
Presupuestos:
i. Deben concurrir varios herederos forzosos.
z. Que algunos de los herederos forzosos hayan sido favorecidos en vida del causante con una
donación o algún acto de liberalidad que pueda reputarse como un anticipo de legítima.
3. Que el heredero favorecido con la liberalidad no haya sido dispensado de la obligación de
colacionar.
20. Anticipo de legítima
Es el adelanto que una persona puede hacer a alguno de sus herederos forzosos, de una parte
igual o menor de los bienes que les correspondería recibir por concepto de cuota hereditaria a
la muerte de quien hace el anticipo.
Existen 2 clases de anticipo:
1. Anticipo simple: Cuando es sin dispensa de la obligación de colacionar, es deducible de la
porción de la herencia (Legítima) que le correspondería recibir al heredero beneficiado.
2. Anticipo no colacionable: Cuando quien lo otorga lo hace dispensando al heredero de
la obligación de colacionar, la que debe ser establecida mediante testamento o escritura
pública (Art. 832o C.C.), dispensa que tiene efecto dentro de limites.de la porción disponi
ble del causante.
Obligados a colacionar: Están obligados a colacionartodos los herederos forzosos que hubie
sen recibido donaciones en vida del causante.
Dispensa de colacionar: La regla general de la colación es que ésta procede siempre que el
causante hubiera dispuesto de bienes a título gratuito a favor de sus herederos forzosos. (Art.
832o C.C.)
La excepción a esta regla es que la colación no se lleva a cabo si existe dispensa por parte del
causante.
La dispensa significa la declaración del causante de que los bienes que dona no sean colacio
nados, y puede otorgarse dentro de la cuota de libre disposición.
Formas de colacionar:
Colación de bienes: Según el artículo 833 del C.C: La colación de los bienes se hace a elec
ción de quien colaciona, devolviendo el bien a la masa hereditaria o reintegrando a ésta
su valor. Si el bien hubiese sido enajenado o hipotecado, la colación se hará también por
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 357 of 1506 --

Tema 2: Temas de derecho civil
su valor. En ambos casos, el valor del bien es el que tenga en el momento de la apertura
de la sucesión.
Colación en especie: Señala el artículo 834 del C.C.: El que colaciona en especie deducirá
en su favor el valor de las mejoras que hubiere hecho, y resarcirá a la masa hereditaria el
valor de los deterioros que el bien haya sufrido por culpa suya.
Colación de dinero, crédito o títulos valores: Según el artículo 835 del C.C.: si la liberali
dad consistió en dinero, créditos, o títulos valores, se hará un equitativo reajuste, según
las circunstancias del caso, para determinar el valor colacionable al tiempo de la apertura
de la sucesión. En caso de discrepancia entre los herederos, el valor será determinado, en
la vía incidental, por el juez a quien corresponde conocer de la sucesión.
No son colacionares:
1. Los bienes perecidos o siniestrados antes de la apertura de la sucesión por causas que no
sean imputables al heredero (Art. 836o C.C.).
2. Lo gastado en alimentos, en darle una profesión arte u oficio al heredero (Art. 837o C.C.).
3. El importe de los seguros de vida contratado a favor del heredero ni las primas pagadas
por ese seguro (Art. 838o C.C.).
4. Las utilidades obtenidas por el heredero, las que según el Art. 839o C.C. son consecuencias
de contratados celebrados con el causante, se entiende que ellos son a título oneroso ta
les como el contrato de sociedad o el contrato de asociación en participación.
21. Indivisión
Concepto: Cuando varias personas son llamadas a heredar surge entre ellos un estado de in
división, en la que todos los herederos son propietarios en común de los bienes de la herencia
en proporción a la cuota que tengan derecho de heredar.
Clases.- Están clasificadas en:
1. Forzosa: Es aquella que existe por mandato de la ley, como los bienes comunes que cons
tituyen la sociedad de gananciales o los bienes el patrimonio fam iliar o por la naturaleza
de las cosas que son indivisibles como las áreas comunes o las paredes medianeras, etc.
2. Voluntaria: Es aquelladispuesta por voluntad del testador o convenida por los herederos.
2.1. Por el testador: De acuerdo al Art. 846o C.C. se puede establecer la indivisión de cual
quier empresa comprendida en la herencia, hasta por un plazo de cuatro años sin
perjuicio de que los herederos se distribuyan normalmente los herederos, a excep
ción de las explotaciones agrícolas y ganaderas que se rigen por la ley de la materia.
2.2. Por los herederos: Los herederos de acuerdo al Art. 8 4 7 ° C.C. están facultados para
pactar la indivisión total o parcial de la herencia hasta por un plazo de cuatro años,
pudiendo ser renovado en forma indefinida.
22. Partición
La partición sucesoria es el acto jurídico mediante el cual se pone fin a la copropiedad de la
herencia, adjudicándosele a cada sucesor lo que corresponde.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 358 of 1506 --

UBILEX
Derecho a Pas- lición
Pueden practicarla o solicitarla las siguientes personas:
1. Cuando el causante ha dejado hecha la partición de sus bienes en su testamento.
(Art. 852o C.C.).
2. Los herederos en su condición de copropietarios están obligados a hacer partición
cuando uno de ellos o el acreedor de cualquiera lo pida, salvo los casos de indivisión
forzosa, de acto jurídico o de ley que fije plazo para la partición. (Art. 984o C.C.).
3. Los acreedores de la sucesión o de cualquiera de los herederos, tal como lo prescribe
el Art. 854o C.C. inc. zy el Art. 984o C.C.
Momento de la Partición: De acuerdo al tiempo de su realización se puede clasificaren:
1. Partición inmediata: La partición procede cualquier momento tal como lo dispone el Art.
984o C.C., salvo que el testador haya establecido la indivisión (Art. 846o C.C.) o la hayan
convenido los herederos (Art. 8 4 7° C.C.) o se trate de indivisión forzosa.
Sin embargo, puede ordenar a petición de cualquiera de los herederos, la partición en
cualquier momento, cuando sobrevienen circunstancias graves que lo justifiquen, tal
como prevé el Art. 850o C.C.
2. Partición mediata: Se da este caso, cuando debe esperarse el plazo fijado por el testador
o los herederos y no sobrevengan circunstancias graves, o cuando se trate de indivisión
forzosa.
3. Partición sujeta a suspensión: Nuestro ordenamiento tiene tres figuras:
a) La partición que comprende los derechos de un heredero concebido será suspen
dida hasta su nacimiento. En el intervalo la madre disfruta de la correspondiente
herencia en cuenta tenga necesidad de alimentos (Art. 856o C.C.).
b) La partición que se difiere o suspende, respecto de todos los bienes o de parte de
ellos, por acuerdo de todos los herederos o por resolución judicial y por un plazo
no mayor de dos años, cuando la ejecución inmediata pueda ocasionar notable per
juicio al patrimonio hereditario, o si es preciso para asegurar el pago de deudas o
legados (Art. 857o C.C.).
c) La partición se difiere o suspende por acuerdo unánime (Art. 991° C.C.).
Clases: Existen las siguientes.-
a) Realizada por el causante: Es aquella que permite el Art. 852o C.C. al testador para
dejarla hecha en el testamento, señalando la norma que en este caso puede pedirse
sólo la reducción en la parte que excede lo permitido por la ley.
b) Efectuada por los herederos: Esta partición es conocida también como convencio
nal, amigable o extrajudicial.
Para que opere la presente partición se requiere que todos los herederos estén de
acuerdo en hacer la partición, que pueden hacerla mediante escritura pública o ante
el juez, por acta que se protocolizará. (Art. 853o).
358 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISGALES

-- 359 of 1506 --

Tema 2: Temas de derecho civil
c) Efectuada judicialmente: Se da cuando no hay acuerdo entre los herederos, y a so
licitud de uno de ellos o de cualquier acreedor de la sucesión o de cualquiera de los
herederos. La partición judicial, se realiza de acuerdo al trámite establecido por los
Arts. 486o al 4 9 4 ° CPC., que corresponden al Proceso Abreviado conforme a la Cuarta
Disposición Final.
23. Deudas y cargas de la herencia
Se denominan deudas a las obligaciones de carácter pasivo que deja pendientes el causante
a su muerte y cargas las obligaciones que gravan la herencia con motivo del fallecimiento del
causante o de las operaciones originadas por la liquidación de la sucesión.
Cargas: De acuerdo al Art. 8 6 9 ° C.C. las cargas de la herencia son:
1. Los gastos del funeral y, en su caso los de incineración, que se pagan preferentemente-.
Todos los gastos del funeral son pasivos de primer orden y deben ser cancelados en forma
prioritaria con cargo a la masa hereditaria.
2. Los gastos provenientes de la últim a enfermedad del causante:
Dicha carga igualmente debe ser cubierta por la masa hereditaria.
3 . Los gastos de administración:
Se refiere a los gastos realizados en el trámite judicial o notarial de la sucesión.
4. Los gastos de vivienda y alimentación de las personas que hayan vivido en casa del cau
sante:
Las personas que hayan dependido económicamente del causante pueden solicitar a los
herederos o al albacea siga cubriendo dichas obligaciones hasta por tres meses.
Derechos de los Acreedores: Los acreedores de la herencia pueden ejercitar las siguientes
acciones:
1. El cobro (Arts. 1218oy 1219°C.C.)
2 . Solicitar la declaratoria de herederos del causante sino existe testamento (Art. 830o CPC)
3. Impedir la partición (Arts. 875oy 876o)
4. Ejercitar la acción subrogatoria, cuando los herederos son negligentes y no defienden los
derechos de la herencia (Art. 1219° inc. 4 C.C.)
5. Ejercitar la acción pauliana, cuando los actos de los herederos conduzcan a la dism inu
ción injustificada del patrimonio hereditario (Arts. I 95°y 200o C.C.)
Acreedor-Heredero: Cuando el acreedor es a su vez heredero, conserva los derechos deriva
dos de su crédito (Art. 880o C.C.), su doble condición determina que como coheredero debe
responder por las deudas de la sucesión y como acreedor de la sucesión debe cobrar su deuda,
pero existe la posibilidad de consolidary de extinguir parcialmente el crédito de hasta donde
alcance su obligación.
Acreedores de un Heredero: El acreedor de un heredero puede embargar y rematar los de
rechos indivisos del deudor sobre la masa hereditaria; pero no puede rematar un bien deter-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 360 of 1506 --

UBILEX
minado sí aún no se le ha adjudicado a su deudor. El acreedor goza de la facultad de pedir la
partición de la herencia.
24 La sucesión iníesiacfe
La transmisión del patrimonio de una persona que fallece se rige por voluntad del causante
expresada en el testamento, y a falta o por defecto de éste por las disposiciones de la ley.
La sucesión intestada se caracteriza por ser una sucesión universal, pues en ella sólo existen
herederos legales que reciben todo o una parte alícuota de la herencia, no hay en esta clase de
sucesión legatarios o sucesores a título particular.
¿Cuándo opera?
De acuerdo al Art. 815o C.C., la herencia corresponde a los herederos legales o intestados en
los casos siguientes:
1. Cuando el causante muere sin dejar testamento o el que otorgó fue declarado nulo.
Es el caso más frecuente, porque la mayoría de la población no dispone mediante testa
mento sus bienes, fallecen sin haber declarado su últim a voluntad o cuando habiéndolo
hecho el testamento es declarado nulo judicialmente.
z. Cuando el testamento no contiene institución de herederos, o se ha declarado la caduci
dad o invalidez de la disposición que los instituye.
Supone la existencia de testamento pero, éste no contiene designación de herederos, que
puede darse ya que son válidos los testamentos que solamente contienen disposiciones
no patrimoniales.
3. Cuando el heredero forzoso muere antes que el testador, renuncia a la herencia o la pier
de por indignidad o desheredación y no tiene descendientes.
4. Cuando el testador voluntario o legatario muere antes que el testador, o por no haberse
cumplido la condición puesta por éste, por renuncia o por haberse declarado indignos a es
tos sucesores sin que se hubiera previsto la designación de sustitutos que tengan a su favor
un llamamiento subsidiario o defectivo.
5. Cuando el testador no tiene herederos forzosos o voluntarios instituidos en testamento,
no ha dispuesto de todos sus bienes en legados en cuyo caso la sucesión legal sólo funcio
nará con respecto a los bienes que no dispuso, dándose así como el caso de una sucesión
mixta, en parte testada en lo relativo a los legados y en parte intestada en lo relativo a los
bienes no dispuestos por el testador.
25. Orden sucesorio
Los órdenes sucesorios constituyen la preferencia que existen entre los herederos, según sus
derechos, sobre los bienes o la masa hereditaria dejada por el causante, y que su vocación he
reditaria se establece de acuerdo a la relación que han tenido con el causante, la que se deriva
del parentesco consanguíneo, del parentesco civil o del vínculo del matrimonio, a quienes se
agrupa por líneas, la línea recta en las ramas descendentes y ascendentes, y la línea colateral,
360 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 361 of 1506 --

Tema 2: Temas de derecho civil
determinándose el llamamiento dentro de cada línea por la regla de la proximidad en el grado
de parentesco.
P r im e r o rd e n : Los hijosy demás descendientes
En primer lugar o la primera preferencia en el orden de los llamamientos está otorgado a los
hijos y demás descendientes, sin distinción alguna, por lo que heredan al padre los hijos ma
trimoniales, extramatrimoniales reconocidos voluntariamente o mediante sentencia judicial
y los adoptivos. (Art. 818o C.C.).
Si sólo concurren hijos, adquieren la herencia en la sucesión intestada en partes iguales pues
si heredan por derecho propio la distribución debe efectuarse por cabeza como lo señala el
Art. 8i9°C.C.,y lo harán por estirpe aquellos descendientes de hijos premuertos, renunciantes
o excluidos de la sucesión por indignidad que sean llamados a heredar por derecho de repre
sentación sucesoria.
Segundo orden: Los padres y demás ascendientes
Los parientes de la línea recta ascendente ocupan el segundo lugar o preferencia en el orden
de llamamientos en la sucesión intestada, Están comprendidos dentro de este orden los pa
dres y demás ascendientes sin distinción de su paternidad m atrimonial, extramatrimonial o
adoptiva, excepto la paternidad que tuvo que ser declarada judicialmente, en este caso no se
confiere el derecho sucesorio según el Art. 412o C.C.
En el caso de concurrencia de ascendientes se aplica el principio general recogido por el Art.
817o C.C. respecto de los parientes más próximos en grado excluyen a los más remotos, divi
diéndose en partes iguales los ascendientes del mismo grado.
Tercer orden:
a) El cónyuge sobreviviente.
El cónyuge sobreviviente es un heredero preferencial y ocupa aparentemente el tercer lu
gar en el orden general de los llamamientos a continuación de la línea recta descendente
y de la ascendente y antes que los órdenes sucesorios de la línea colateral, pero no es así
pues el cónyuge puede concurrir con los descendientes o los ascendientes del causante
que no logran desplazarlo, pues tiene un derecho equivalente al de ellos.
Los descendientes que desplazan a otros sucesores concurren con el cónyuge supérstite
cuya parte o porción es igual a la de un hijo, es decir se considera al viudo o viuda en la
herencia como uno o más de los hijos según el Art. 822° C.C., obsérvese que la cuota del
cónyuge no es igual a la de uno de los descendientes con quienes le toque concurrir sino
igual a la parte de un hijo.
Cuando concurre el cónyuge con los ascendientes no se le da un tratam iento similar, así
el Art. 824o del C.C. no establece que la parte del cónyuge a uno de los padres, sino igual
a la parte de uno de los ascendientes, de tal modo si concurre con los abuelos la cuota del
cónyuge disminuye, de un tercio que le correspondería en caso de concurrencia con los
padres del causante hasta un quinto.
El Art. 826o C.C. establece que la sucesión que corresponde al viudo a o la viuda no llega
a ser adquirida cuando hallándose enfermo de los cónyuges al celebrarse el matrimonio,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 362 of 1506 --

UBILEX
muriese de esa enfermedad dentro de los 30 días siguientes, salvo que el m atrimonio
hubiera sido celebrado para regularizar una situación de hecho.
El Art. 343o C.C. establece una sanción para el cónyuge culpable consistente en la pérdida
de su derecho hereditario, conservando en cambio el cónyuge inocente la vocación suce
soria que le corresponde.
El Art. 353o C.C. establece la pérdida de la vocación sucesoria en el caso del divorcio vincu
lar, sin establecer la culpabilidad o inocencia,
b) El integrante sobreviviente de la unión de hecho
Con la Ley N° 30007, publicada el 17 de abril de 2013, se ha reconocido la vocación here
ditaria del integrante sobreviviente de unión de hecho. Cabe aquí puntualizar que debe
tratarse de la unión de hecho acorde con los requisitos establecidos en el Art. 326 del C.C.,
pues voluntariamente deben haber unido sus vidas un varón y una mujer, que deben en
contrarse libres de impedimento matrimonial, para alcanzar finalidades y cumplir debe
res semejantes a los del matrimonio, unión que debe haber durado cuando menos dos
años continuos. A través de la mencionada ley se incorpora al integrante sobreviviente de
unión de hecho en el tercer orden sucesorio, y con derecho concurrente a heredar con los
parientes de los dos primeros órdenes sucesorios, esto es, los hijos y demás descendien
tes, y los padres y demás ascendientes.
Debe considerarse que el conviviente tendrá derecho a heredar de modo preferente,
siendo posible que herede únicamente o en concurrencia con alguno de los parientes del
primer o segundo orden sucesorio. De existir parientes de dichos dos órdenes, la apli
cación de la regla de exclusión sucesoria del artículo 817 del Código Civil permitirá de
terminar cuál o cuáles de los parientes tienen derecho a heredar, en concurrencia con el
conviviente, en función a que los parientes de línea recta descendente excluyen a los de la
ascendente, y los parientes más próximos en grado excluyen a los más remotos, salvo el
derecho de representación sucesoria.
El derecho sucesorio del conviviente se encontrará mejor cautelado si a la fecha del fa
llecimiento del conviviente estaba inscrita la unión de hecho en Registros Públicos, pues
podrá pedir que se ejecute la voluntad testamentaria, si hubo testamento, sino tendrá el
derecho de iniciar el proceso de sucesión intestada para obtener el título de heredero, ya
sea en vía notarial o judicial. Incluso, si hubo testamento pero no se le comprendió en su
calidad de heredero forzoso, podrá impugnar el testamento.
En caso de que no se hubiera inscrito la unión de hecho, el conviviente sobreviviente de
berá solicitar la declaración judicial de unión de hecho, a la cual podrá acumular la de
manda de petición de herencia para que se le declare heredero o, si fuera el caso, para
concurrir o excluir a las personas que se hubieren hecho declarar herederos del fallecido
conviviente.
Así, el conviviente sobreviviente tiene un derecho reconocido a heredar al causante falle
cido, esto es, tiene vocación sucesoria. La condición de heredero se establece en el título
sucesorio; será heredero si fue instituido voluntariamente por el causante en su testa
mento; si no dejó testamento válido y vigente, será heredero por declaración judicial o
notarial.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 363 of 1506 --

Tema 2: Temas de derecho civil
Cuarto orden: Los H e r m a n o s
De no haber herederos de los 3 órdenes anteriores, es decir, descendientes, ascendientes, ni
cónyuge, ni concubino sobreviviente, son llamados a heredar los parientes consanguíneos en
la línea colateral como lo señala el Art. 828o C.C. Entre éstos, son llamados en primer término
los parientes en 2° grado de la línea colateral por consanguinidad que son los hermanos.
Si d e la c o n c u r r e n c ia d e h e r m a n o s d e p a d r e y m a d r e c o n m e d io s h e r m a n o s , lo s p r im e r o s r e c i
b ir á n el d o b le d e lo r e c ib ir á n lo s ú lt im o s . (A rt. 8 2 9 o C .C .)
Quinto orden: Los T ío s y S o b r in o s
A continuación de los hermanos, de no existir herederos de los órdenes sucesorios que le pre
ceden, son llamados a heredar los parientes colaterales en tercer grado por consanguinidad,
que corresponden a los tíos y sobrinos del causante, quienes reciben en partes iguales por
tratarse de parientes de un mismo grado.
Sexto orden: Los P r im o s H e r m a n o s
