c o la t e r a l p o r c o n s a n g u in id a d , es d e c ir lo s p r im o s h e r m a n o s , q u e ig u a lm e n t e s o n lla m a d o s a
r e c ib ir la h e r e n c ia a f a lt a d e h e re d e ro s d e lo s ó r d e n e s s u c e s o r io s a n t e r io r e s .
El parentesco por consanguinidad no es ¡limitado en la línea colateral, éste se extiende hasta
el 4o grado que corresponde a los primos hermanos, más allá el parentesco ya no surte efectos
legales. (Art. 236o C.C.).
26. Sucesión del estado y de las beneficencias públicas
En nuestro Código Civil ya no hay necesidad de que se declare vacante la herencia, pues en es
tos casos según lo dispone el Art. 830o C.C. a falta de sucesores testamentarios o legales el Juez
que conoce el trám ite de sucesión intestada adjudicará los bienes a la Sociedad de Beneficen
cias o falta de esta, a la Junta de Participación Social del lugar del últim o dom icilio que tuvo
el causante en el país o a la Sociedad de Beneficencia de Lima Metropolitana si el causante
estuvo domiciliado en el extranjero.
