BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 364 of 1506 --

UBILEX
Según Manuel Albaladejo: El Derecho Real es un poder directo e inmediato sobre una cosa,
que concede a su titu lar un señorío, bien pleno (propiedad), o bien parcial (derecho real en
cosa ajena) sobre aquélla, de forma que en el ámbito de poder concedido (que varía según el
derecho real de que se trate), tiene la cosa sometida a su dominación.
1. Principios generales
Para nuestra legislación, los Derechos Reales constituyen númerus clausus, pues están lim ita
dos a los regulados por el Código Civil y por leyes especiales, es decir, sólo son Derechos Reales
los que se encuentran reconocidos normativamente (Art. 881o C.C.). Sin embargo, en doctrina
se debate porque los Derechos Reales sean numeras apertus que representaría la facultad que
las personas puedan establecer los derechos reales que consideren pertinentes, es decir, De
rechos Reales atípicos.
La libertad de circulación de bienes, representa uno de los principios de los Derechos Reales,
pues no se puede establecer contractualmente la prohibición de enajenar o gravar un bien,
salvo que la ley lo permita (Art. 882 C.C.)
2. Los bienes
Concepto: Se considera bien a todo aquel elemento exterior de las personas, que de una ma
nera directa o indirecta sirven para satisfacer sus diferentes necesidades y tienen como deno
minador común o nota esencial, un valor, representando en consecuencia, una riqueza (Arias
Shreiber).
La palabra bien tiene un significado muy preciso para el Derecho Civil. Únicamente la cosa
(todo aquello susceptible de apropiación por el hombre) que está dentro del patrimonio de
un sujeto de derechos, y que además tiene características pecuniarias o económicas merece el
calificativo del bien (Velásquezjaramillo).
Clasificación
i. Corporales e incorporales.
a) Es corporal cuando es perceptible por los sentidos. Estos se subclasifican en:
- consumibles (se agotan con su consumo) y no consumibles (no se agotan con su
consumo).
- fungibles (son susceptibles de ser reemplazados por otra de su misma especie)
y no fungibles (son los que representan una individualidad que los hace extraño
a cualquier sustitución).
- divisibles (pueden ser separados por fracciones, sin que pierdan su valor) y no
divisibles (los que al fraccionarse pierden susustanciay por tanto pierden su va
lor).
b) Es incorporal cuando no puede ser materialmente tocado ni percibido sensorial-
mente, sino sólo a través de la inteligencia.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 365 of 1506 --

13í m 2: l emas de derecho civil
2. Inmuebles y muebles. Son inmuebles los que se encuentran arraigados al suelo y están
inmovilizados, no pudiendo trasladarse de uno a otro lugarsin producir su menoscabo o
destrucción (Art. 885 C.C.), estos se encuentran subclasificados en:
a) Por su naturaleza, se encuentran arraigados al suelo (el suelo propiamente dicho).
b) Por determinación de la ley,ya sea por el destino que tiene un mueble o por la impor
tancia del mismo, por una ficción de la ley les otorga la calidad de inmueble.
Se consideran como bienes muebles, a aquellos que carecen de asiento fijo o esta
ble, pudiendo ser fácilmente trasladado de un lugar a otro sin daño alguno (Art. 88 6
C.C.), estos se encuentran sub clasificados en:
Porsu naturaleza: Son aquellos susceptibles de moverse sin perjuicio alguno, sea por
dinámica propia o por propulsión de una fuerza extraña.
Por determinación de la ley, así se tiene las acciones o cuotas de las sociedades y
compañías, etc.
3. Principales y accesorios. Lo principal es lo que puede subsistir por sí mismo. Es accesorio
lo que necesita de un bien principal para poder subsistir.
Partes integrantes y accesorias
Son partes integrantes las que no pueden ser separadas sin destruir, deteriorar o alterar el
bien, por lo que no pueden ser objeto de derechos singulares (Art. 887 C.C.)
Son accesorios aquellos que sin perder su individualidad, están permanentemente afectados
a un fin económico u ornamental con respecto a otro bien, pudiendo ser materia de derechos
singulares (Art. 888 C.C.).
Las partes integrantes de un bien y sus accesorios siguen la condición de éste, salvo que la ley
o el contrato permita su diferenciación o separación (Art. 889 C.C.).
Frutos y productos
Son frutos los provechos renovables que produce un bien, sin que se altere ni disminuya su
sustancia (Art. 890 C.C). Los frutos pueden ser (Art. 891 C.C.)
- Naturales: los que provienen del bien, sin intervención humana.
- Industriales: los que produce el bien, por la intervención humana.
- Civiles: los que el bien produce como consecuencia de una relación jurídica.
Son productos los provechos no renovables que se extraen de un bien (Art. 894 C.C.).
3. La posesión
Concepto: La posesión es el ejercicio de hecho de uno o más poderes inherentes a la propie
dad (Art. 896 C.C). Se conceptúa el ejercicio de hecho como una dirección y un contacto even
tual del sujeto sobre el bien, de manera más o menos estable, dentro de los cuales el sujeto
puede hacer empleo de alguno o algunos de los atributos propios del dominio, como son el
uso, el disfruteyaún la disposición del objeto poseído (Arias Schreiber).
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 366 of 1506 --

UBILEX
Clases de posesión:
Posesión mediata e inmediata: El a r t íc u lo 9 0 5 o d e l C ó d ig o C iv il r e g u la lo c o n c e r n ie n t e
a la p o s e s ió n m e d ia t a e in m e d ia t a , s e ñ a la n d o q u e es p o s e e d o r in m e d ia t o el p o s e e d o r
t e m p o r a l e n v ir t u d d e u n t ít u lo , m ie n t r a s q u e le c o r r e s p o n d e r á la p o s e s ió n m e d ia t a a
q u ie n c o n f ir ió el tít u lo .
El poseedor mediato no posee por sí solo, requiere el concurso (no para compartir, sino para
superponerse) de un mediador posesorio, que es el poseedor inmediato.
Posesión legítima e ilegítima: De lo regulado por los artículos 906o a 910o del Código
Civil, emerge que la posesión es legítima cuando existe correspondencia entre el poder
ejercido y el derecho alegado, será ¡legitima cuando deja de existir esa correspondencia.
Se ha llegado a sostener que la posesión es legítima cuando el ejercicio de dicho derecho
sea de acuerdo a las disposiciones del ordenamiento civil, en tanto que será Ilegítima
cuando se tenga sin título o por un título nulo o que ha sido adquirido por un modo insu
ficiente para adquirir los derechos reales, o cuando se adquiere del que no tenía derecho
a poseer la cosa o no lo tenía para transmitirla.
Es posesión legítima en cuanto no se declare la nulidad del título que la produce si se ha
adquirido el bien de quien no es su dueño.
Posesión precaria (Art. 911 C.C.): Una persona tendrá la condición de precaria cuando
ocupe un inmueble ajeno, sin pago de renta y sin título para ello, o cuando dicho título
no genere ningún efecto de protección para quien lo ostente, frente al reclamante, por
haberse extinguido el mismo.
Cuando se hace alusión a la carencia de título o al fenecimiento del mismo, no se está re
firiendo al documento que haga alusión exclusiva al título de propiedad, sino a cualquier
acto jurídico que le autorice a la parte demandada a ejercer la posesión del bien, puesto
que el derecho en disputa no será la propiedad sino el derecho a poseer. (IV Pleno Casa-
torio Civil)
Presunciones posesorias
1. El poseedores reputado propietario mientras no se pruebe lo contrario (Art. 912 C.C.).
2. La p o s e s ió n d e u n b ie n h a c e p r e s u m ir la p o s e s ió n d e s ú s a c c e s o r io s (A rt. 9 13 C .C ).
3. La p o s e s ió n d e u n in m u e b le h a c e p r e s u m ir la d e lo s b ie n e s m u e b le s q u e se h a lle n en él
(A rt. 913 C .C .).
4. Se p r e s u m e la b u e n a fe d e l p o s e e d o r, s a lv o p r u e b a en c o n t r a r io (Art. 9 14 C .C .) .
5. Se presume que el poseedor actual ha poseído anteriormente, salvo prueba en contrario
(Art. 915 C.C.).
Modos de adquisición de la posesión
1. Originaria: Se puede adquirir originariamente como ocurre con la ocupación (Art. 900
C.C.).
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 367 of 1506 --

Tema 2: Temas de derecho civil
2. Derivada: Se adquiere en forma derivativa, cuando implica la expresión de lavoluntad del
anterior poseedor en el sentido de colocar al nuevo adquirente en dicha condición, como
es la tradición (entrega del bien) (Art. 901 C.C.).
Derechos del poseedor
- Hacer suyo los frutos, sólo si se trata de poseedorde buena fe. (Art. 908 C.C.).
- Ejercer la defensa de su posesión,ya sea por los medios establecidos por leyó por los que
ejerza por la fuerza.
Suma de plazos posesorios.- El poseedor puede adicionar a su plazo posesorio el de aquel
que le trasm itió válidamente el bien (Art. 898 C.C.).
Defensa posesoria (clasesy régimen jurídico)
1. Defensa posesoria extrajudicial, es aquel mecanismo de tutela brindado a todo posee
dor (legitimo, ilegítimo o precario) para que: 1. pueda repeler por la fuerza cualquier in
tromisión al bien en el que se encuentre o 2. recupere el bien del que fuese desposeído (le
gítima defensa) siemprey cuando su accionar ocurra de manera inmediata y proporcional al
intento de desposesión o desposesión consumado (Art. 920 C.C.). Para su configuración
se requiere:
Un acto de violencia contra el poseedor del bien mueble o inmueble.
Que el poseedor responda ante este acto de violencia de forma inmediata.
Que la autoridad no pueda intervenir oportunamente.
Que el poseedor responda ante el acto de violencia de manera proporcional.
2. Defensa posesoria judicial, procede para los muebles inscritos y para los inmuebles, pu-
diendo el poseedor utilizar las acciones posesorias y los interdictos. Si su posesión es de
más de un año puede rechazar los interdictos que se promuevan contra él (Art. 921 C.C.).
La defensa posesoria judicial se ejerce mediante los interdictos de recobrary retener (Se
tram itan por la vía del proceso establecido por los arts. 5 9 7 y ss. del C.PC.).
a) Interdicto de Recobrar: Procede cuando el poseedor es despojado de su posesión,
siempre que no haya mediado proceso previo (Art. 603 C.PC.).
b) Interdicto de Retener: Procede cuando el poseedor es perturbado en su posesión
(Art. 606 C.PC.).
Las mejoras
Concepto: Las mejoras constituyen una alteración material producida en el bien sujeto a po
sesión, y buscan repararla, aumentar su valor o proporcionar mayores comodidades y hasta
lujos (Arias Schreiber).
Clases: (Art. 916 C.C.)
1. Necesarias, cuando tienen por objeto impedir la destrucción o el deterioro del bien.
2. Útiles, las que sin pertenecer a la categoría de las necesarias aumentan el valory la renta
del bien.
3. Recreo, cuando sin ser necesarias ni útiles, sirven para ornato, lucimiento o mayorcomodidad.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 368 of 1506 --

Derechos del poseedor: El p o s e e d o r t ie n e d e r e c h o al v a lo r a c t u a l d e la s m e jo r a s n e c e s a r ia s y
ú t ile s q u e e x is t a n al t ie m p o d e la r e s t it u c ió n y a r e t ir a r la s d e re c re o q u e p u e d a n s e p a r a r s e sin
d a ñ o , s a lv o q u e el d u e ñ o o p te por pagarsuvaloractual. E sta re g la n o es a p lic a b le a la s m e jo r a s
h e c h a s d e s p u é s d e la c it a c ió n ju d ic ia l s in o c u a n d o se t r a t a d e la s n e c e s a r ia s (A rt. 9 17 C .C .)
Extinción de la posesión:
La posesión se extingue por (Art. 922 C.C.):
1. Tradición,
z. Abandono.
3. Ejecución de resolución judicial.
4. Destrucción total o pérdida del bien.
4. La propiedad
Concepto: La propiedad es el poder jurídico que permite usar, disfrutar, disponer y reivindicar
un bien. Se ejerce en armonía con el interés social y dentro de los límites de la ley (Art. 923 C.C.).
Atributos: 1. Uso. 2.Coce. 3- Disposición.
Caracteres
1 . Es absoluta, e s ta c a r a c t e r ís t ic a h a s id o d is m in u id a , e s t a b le c ie n d o n u e s t r a le g is la c ió n q u e
p r o p ie d a d se e je rc e e n a r m o n ía c o n el In te ré s s o c ia l (Art. 9 2 3 C .C ).
2. La elasticidad, permite que recaiga sobre ella gravámenes o limitaciones pero en forma
temporal, pues ésta siempre debe ser repuesta.
3. La exclusividad, permite que el propietario sea el único facultado para ejercitar sobre el
bien los atributos correspondientes al uso, gocey disposición.
4. La plenitud, está referido al goce completo del bien, en su totalidad.
5. La existencia autónoma o independiente, significa que una vez surgido el derecho de pro-
piedadsu existencia no depende de ningún otro derecho del cual derive, a diferencia de los
demás derechos reales que presuponen la previa situación de dominio en otra persona.
6. La perpetuidad, en el entendido que el derecho de dom inio es indefinido en el tiempo y
que subsiste al margen de su ejercicio por parte del propietario.
4.1. Formas de adquisición
1. Por Apropiación, cuando un bien no pertenece a nadie, cuando se cazan los animales en
predios que les sean permitidos realizar esta actividad.
2. Por especificación y mezcla, a la especificación en doctrina se le conoce como accesión
de muebles con muebles. La especificación presupone la pérdida de la individualidad del
bien y se presenta como un modo de adquirir el dom inio que se produce cuando alguien,
por su trabajo, hace un objeto nuevo con la materia de otro y con intención de apropiár
selo (Cabanellas). En cuanto a la mezcla es la incorporación, unión, mixtura o reunión de
varias sustancias o bienes en un conjunto más o menos homogéneo, distinguiéndole y
siendo separables (Cabanellas).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 369 of 1506 --

Tema 2: Temas de derecho civil
3. Por accesión, es lo que se une o adhiere materialmente a un bien, pasando su propie
tario a adquirir lo que se ha adherido. La accesión puede ser por aluvión o avulsión. Se
entiende por aluvión a las uniones de tierra y los incrementos que se forman sucesiva e
imperceptiblemente en los fundos situados a lo largo de los ríos o torrentes, pertenecen
al propietario del fundo (Art. 939 C.C.)y por Avulsión, cuando la fuerza del río arranca una
porción considerabley reconocible en un campo ribereñoy lo lleva al de otro propietario
ribereño. (Art. 940 C.C.).
4. Por trasmisión de la Propiedad, se realiza por medio de un acto jurídico. Para los bienes
muebles opera por la tradición, para los inmuebles con la sola obligación de enajenar el
bien de parte del propietario.
5. Por prescripción adquisitiva, se adquiere por posesión continua, pacífica y publica como
propietario duranteio años. Si hubiera justo títu lo y buena fe se adquiere a los 5 años (Art.
950C.C.).
