BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 369

-- 370 of 1506 --

Precedente judicial vinculante:
La Corte Suprema de Justicia de la República, con los fundamentos que brevemente se comentan a conti
nuación, declara, por unanimidad, infundado el recurso de casación y establece como doctrina jurisprudencial
vinculante lo siguiente:
"La correcta interpretación del artículo 950 del Código Civil debe hacerse en el sentido de que nada obsta
para que dos o más coposeedores homogéneos puedan usucapir, puesto que de ser amparada su pretensión
devendrían en copropietarios, figura jurídica que está prevista en nuestra legislación".
2do S u puesto.- IV Pleno Casatorio C ivil. Cas. N° 2 1 § 5 - 2 0 1 1 -Ucayali. (Pub. El Peruano 2 2 .08.2009 )
Resumen del caso.- Luis Arturo Corre Linares apoderado de Luis Miguel Correo Panduro; Jorge
Enrique Correo Panduro y Cesar Arturo Correa Panduro interpone demanda ei desalojo por:
ocupación precaria del Inmueble sito en Jr. Tarata 663 y 665 contra Mima Lisbeth Panduro
Abarca y Euclides Vaca Turco.
El accionante manifiesta que sus poderdantes son propietarios del inmueble materia de re
clamo, cuya titularidad tienen inscrita en los RR.PP. de la ciudad de Pucailpa y que los demandados tienen la
condición de precarios.
Mediante sentencia del 15.09.2010 se declaró fundada la demanda, ordenándose el lanzamiento de los de
mandados, sentencia que fue apelada por ambos demandados.
La Sala Superior especializada en lo Civil y afines de Ucayaíi, medíante sentencia deí 08.04.2011, confirma
ia alzada en todos sus extremos, precisando que la demanda debe ampararse conforme a lo resuelto por el
A quo, acotando que los demandantes han acreditado haber obtenido la titularidad sobre el bien materia de
reclamo, al haberlo recibido en anticipo de legitima de parte de la señores Nancy Panduro Abarca, y que en
lo concerniente a la posesión a título de propietarios por usucapión que alegan los demandados, se observa
que los documentos que se adjuntan, varios de ellos aparecen a nombre de terceros, por lo que no habiéndose
desvirtuado la precariedad de la posesión resulta viable el desalojo.
Interpone casación sólo doña Mima Panduro, alegando que la demanda de desalojo se ha planteado invo-,
cando normas referidas a la conclusión del arrendamiento y que el A quo, lejos de corregir ello, ha aplicado,
además, el artículo 1697 del C.C., referido a las causales de resolución del arrendamiento. Siendo que el Ad
quem, también incurrió en el mismo error al no haber resuelto sobre este punto que fue materia de apelación..
Precedente judicial vinculante: La Corte Suprema de Justicia de la República, con los fundamentos que breve
mente se comentan a continuación, declara, por unanimidad, infundado el recurso de casación y establece
como doctrina jurisprudencial vinculante lo siguiente:
“3. No procede alegarse ni discutirse en el proceso de desalojo por ocupación precaria el mejor derecho de
propiedad, la resolución de un contrato, la prescripción adquisitiva de dominio, la accesión industrial el despo
jo violento o clandestino u otros supuestos análogos, toda vez que el proceso de desalojo es uno de carácter
sumaríslmo donde se requiere la tutela urgente y tiene limitaciones en la actividad y debate probatorio, por
lo que tales hipótesis deben hacerse valer en la vía procesal que correspondiera; aún más si en el caso del
despojo violento o clandestino nuestro sistema jurídico prevé tutela a través del interdicto de recobrar, Puya
vía procesal también es sumarísima, además de las medidas cautelares más eficaces que nuestro sistema
procesal regula.1'' '' .
Así, en un proceso de desalojo por ocupación precaria, pese a que el demandado alegue que ha adquirido el bien •
por prescripción, el juez deberá resolver ei fondo del asunto y declarar el mejor derecho a poseer, tomando en
cuenta los medios probatorios aportados; sin perjuicio que. el demandado vencido pueda posteriormente en un
proceso sobre prescripción adquisitiva solicitarla inejecución de la sentencia de desalojo o la restitución del bien.
Extinción de la propiedad:
1. Adquisición del bien por otra persona.
2. Destrucción o pérdida total o consumo del bien.
3 . Expropiación.
4. Abandono del bien durante veinte años, en cuyo caso pasa el predio al dom inio del Esta
do.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 371 of 1506 --

Tema 2: Temas de derecho civil
5. Régimen jurídico. Propiedad exclusiva y propiedad común (Propiedad horizontal)
Nociones Generales y Régimen Legal aplicable. Adquisición. Derecho o Atribuciones.
La propiedad es exclusiva cuando un solo sujeto ejerce el derecho real de propiedad.
La propiedad es común, cuando el derecho de propiedad se ejerce por varios sujetos.
La propiedad horizontal es una propiedad especial o suigeneris, ya que concurren en ella la pro
piedad unitaria (o exclusiva) y la indivisa o comunitaria. El propietario ejerce su derecho en
forma plena sobre su apartamento o local y tiene una cuota ideal o indivisa sobre los bienes
comunes, como son el suelo, el techo, las escaleras, la portería, etc. Se denomina horizontal,ya
que su estructura física se basa en pisos superpuestos, de manera que cada piso es suelo de un
apartamento y techo de otro. Cuentan con bienes comunes, los necesarios para la existencia,
seguridady conservación del edificio y los que permitan atodosy cada uno de los propietarios
el uso y goce de su piso o departamento, tales como el terreno, los cimientos, los muros, esca
leras, accesorios, etc.
La Ley N° 27157, Ley de Regularización de Edificaciones, del Procedimiento para la Declaratoria
de Fábrica y del Régimen de Unidades Inmobiliarias de Propiedad Exclusiva y de Propiedad
Común, establece que los propietarios de las edificaciones de departamentos, quintas, casas
en copropiedad, centros y galerías comerciales o campos feriales, y otras unidades inm obilia
rias con bienes en común pertenezcan a propietarios distintos, pueden elegir entre regímenes
de propiedad exclusiva y propiedad común o independización y copropiedad. Esta opción
debe constar en el Formulario Único Oficial y debe inscribirse en el Registro correspondiente.
Asimismo, su Reglamento, dispone que el régimen de Independización y Copropiedad supo
ne la existencia de unidades inmobiliarias de propiedad exclusiva susceptibles de ser inde
pendizadas y bienes de uso común sujetas al régimen de copropiedad regulado en el Código
Civil. Las unidades inmobiliarias de propiedad exclusiva comprenden necesariamente el te
rreno que ocupa cada una.
Conforme a lo señalado el régimen de independización y copropiedad era demasiado com
plejo al igual que el de propiedad exclusiva y propiedad común, determinándose que en la
práctica no tenía aplicación.
Al día de hoy, el régimen de independización y copropiedad regulado por la Ley N° 27157 ha
sido derogado a través del Decreto Legislativo N°15 68 - Decreto Legislativo del Régimen de la
Propiedad Horizontal, publicado el 28 de mayo de 2023, disponiendo que las unidades inmo
biliarias sujetas a ella se adecúan al régimen de propiedad horizontal en la oportunidad que
se presente al Registro de Predios la solicitud de inscripción de algún acto que modifique el
Reglamento Interno primigenio.
5.1. Copropiedad
5.1.1. Noción: En doctrina existe una polémica sobre la construcción jurídica de la copropie
dad. Según unos hay división intelectual del bien, que se considera fraccionada en tantas cuo
tas como copropietarios son. De forma que cada uno tiene un derecho de propiedad pleno y
exclusivo, cuyo objeto no es el bien entero sino una parte ideal de éste.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 372 of 1506 --

UBILEX
Según otros, sobre el bien íntegro recae un único derecho de propiedad, pero este derecho se
halla dividido por cuotas ideales entre los condueños. Finalmente, otros creen que ni el bien ni
el derecho se dividen intelectualmente en cuotas, sino que cada condueño tiene un derecho
íntegro de propiedad sobre la totalidad del bien (Albadalejo).
El Art. 969 del C.C. lo define cuando un bien pertenece por cuotas ideales a dos o más perso-
ñas.
5.1.2. Caracteres
1. El copropietario no tiene derecho exclusivoy total sobre el bien, es solo dueño exclusivo o
individual de la cuota parte que le corresponde en la comunidad (una tercera, una quinta,
etc.); su señorío es parcial. Solo tiene derecho a una parte de los frutos; si venden, cada
uno tiene derecho al valor de su cuota.
2. La cuota que tiene el copropietario es una cuota ideal no representable materialmente
mientras exista la indivisión.
3. En la copropiedad existen tantos derechos de dom inio cuantos propietarios hubiere so
bre el objeto, y todos unidos forman la propiedad plena. Por ello cada condueño puede
enajenar o hipotecar su cuota ideal sin consultar a sus demás compañeros.
4. Fuera del derecho individual de cada copropietario a una cuota parte ideal, existe un de
recho colectivo sobre el bien que únicamente puede ejercerse con el acuerdo de todos.
5.1.3. Clases
1. Casas en copropiedad: Unidades inmobiliarias de propiedad exclusiva que conforman
un conjunto de viviendas unifamiliares que incluyen bienes de propiedad común, como
áreas recreativas o de otra índole y servicios comunes.
2. Casas en quinta: Unidades inmobiliarias de propiedad exclusiva que conforman un con
junto continuo de viviendas unifamiliares construido sobre un terreno urbanizado, que
cuenta, por lo menos, con un pasaje de acceso desde la vía pública en calidad de bien
común.
3. Departamentos en edificio: Unidades inmobiliarias de propiedad exclusiva para uso resi
dencial, comercial, industrial o mixto, ubicadas en una edificación de más de un piso que
cuenta con bienes y servicios comunes.
5.1.4. Derechos y obligaciones
Derechos
1. Cada copropietario tiene derecho a servirse del bien común, siempre que no altere su
destino ni perjudique el interés de los demás (Art. 974 C.C.).
2. A disfrutar del bien (Art. 976 C.C.).
3. Cada copropietario puede disponer de su cuota ideal y de los respectivos frutos, así como
gravarlos (Art. 977 C.C.).
4. Cualquier copropietario puede reivindicar el bien común. Asimismo, puede promoverlas
acciones posesorias, los interdictos, las acciones de desahucio, aviso de despedida y las
demás que determine la ley. (Art. 978 C.C.).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 373 of 1506 --

Tema 2: Temas de derecho civil
5. A las mejoras necesarias y útiles (Art. 980 C.C.).
Obligaciones
1. Indemnizara los demás copropietarios cuando usa el bien parcial o totalmente con exclu
sión de ellos, salvo el caso del cónyuge sobreviviente sobre el que fuera el hogarconyugal
(Art. 975 C.C.).
2. A reembolsar proporcionalmente los provechos obtenidos del bien (Art. 976 C.C.).
3. Responder proporcionalmente por los gastos que ocasionen las mejoras necesariasy úti
les (Art. 980 C.C.).
4. A concurrir en proporción a su parte, a los gastos de conservación y al pago de los tributos,
cargas y gravámenes que afecten al bien común (Art. 981 C.C.).
5. Al saneamiento en caso de evicción, en proporción a la parte de cada uno (Art. 982 C.C.).
5.1.5. Partición.- Por la partición permutan los copropietarios, cediendo cada uno el derecho
que tiene sobre los bienes que no se le adjudiquen, a cambio del derecho que le ceden en
los que se le adjudica (Art. 983 C.C). Los copropietarios están obligados a hacer la partición
cuando uno de ellos o el acreedor de cualquiera lo pida, salvo los casos de indivisión forzosa,
de acto jurídico o de ley que fije plazo para la partición (Art. 984 C.C).
La acción de partición es imprescriptibley ninguno de los copropietarios ni sus sucesores pue
den adquirir por prescripción los bienes comunes (Art. 985 C.C.). Los copropietarios pueden
hacer partición por convenio unánime (986 C.C.). Los bienes comunes que no son susceptibles
de división material pueden ser adjudicados, en común, a dos o más copropietarios que con
vengan en ello, o se venderán por acuerdo de todos el los y se dividirá el precio. Si los copropie
tarios no estuviesen de acuerdo con la venta contractual o la adjudicación en común se vende
rá en pública subasta, teniendo preferencia los copropietarios para adquirir la propiedad del
bien, pagando el precio de latasación en las partes que correspondan a los demás copartícipes
(Art. 989 C.C).
5.1.6. Extinción de la copropiedad (Art. 992 C.C.)
1. División y Partición del bien común.
2. Reunión de todas las cuotas partes en un solo propietario.
3. Destrucción total o pérdida del bien.
4. Enajenación del bien a un tercero.
5. Pérdida del derecho de propiedad de los copropietarios.
5.1.7. Pacto de indivisión - Los copropietarios pueden celebrar pacto de indivisión por un pla
zo no mayor de cuatro años y renovarlo todas las veces que lo juzguen conveniente, cuando
el pacto no consigne plazo se presume que es por cuatro años. No obstante, si se presentan
circunstancias graves el juez puede ordenar la partición antes del vencimiento del plazo.
Para que produzca efecto contra terceros, el pacto de indivisión debe inscribirse en el registro
correspondiente (Art. 993 C.C.)
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 374 of 1506 --

UBILEX
5.1.8. Medianería." La medianería constituye una modalidad o matiz de la propiedad comuni
taria o copropiedad, que se materializa sobre los elementos que la componen (paredes, cerco,
zanjas o similares) de modo que cada propietario del predio contiguo tiene un derecho de uso
común, dentro de un permanente estado de indivisión forzosa (Arias Schreiber). En tal sentido
se presumen comunes las paredes, cercos o zanjas situados entre dos predios (Art. 994 C.C.). Asi
mismo, todo colindante puede colocar ti rantesy vigas en la pared medianeray servirse de ésta sin
deteriorarla, pero no puede abrir en el la ventana o claraboyas (Art. 996C.C.), loque genera que los
colindantes contribuyan a prorrata para la conservación, reparación o reconstrucción de la pared
medianera, a no ser que renuncien a la medianería, hagan o no uso de ella (Art. 998 C.C.).
De otra parte, cualquier colindante puede levantar la pared medianera, siendo de su cargo
los gastos de la reparación y cualesquiera otros que exigiera la mayor altura (Art. 997 C.C.);
asimismo, si la pared que separa los predios se ha levantado en terreno de uno de ellos, el
vecino puede obtener la medianería pagando la mitad del valor actual de la obray del suelo
ocupado (Art. 995 C.C.).
6. Expropiación
Concepto: Es el acto mediante el cual en aras de un interés superior se impone a los particu
lares la enajenación forzosa de sus bienes a favor del Estado o de alguna repartición pública, y
en casos de excepción en beneficio de empresas privadas o concesionarios públicos, a cambio
de una justiciera indemnización equivalente a su valor (Arias Schreiber).
El numeral 4-5 del TUO del Decreto Legislativo N °ii92, Decreto Legislativo que aprueba la Ley
Marco de adquisición y expropiación de inmuebles, transferencia de inmuebles de propiedad
del estado, liberación de interferencias y dicta otras medidas para la ejecución de obras de in
fraestructura- D.S. N° 015-2020-VIVIENDA publicado el 26 de octubre de 2020, vigente a la fe
cha, define a la expropiación como la transferencia forzosa del derecho de propiedad privada
sustentada en causa de seguridad nacional o necesidad pública, autorizada únicamente por
ley expresa del Congreso de la República a favor del Estado, a iniciativa del Gobierno Nacional,
Gobiernos Regionales o Gobiernos Locales y previo pago en efectivo de la indemnización jus
tipreciada que incluya compensación por el eventual perjuicio al sujeto pasivo. En el mismo
numeral el TUO del D.Leg. N° 1192, define el proceso de Adquisición como la transferencia
voluntaria de la propiedad del inmueble necesario para la ejecución de la Obra de Infraestruc
tura, del Sujeto Pasivo a favor del Beneficiario como resultado del trato directo.
Sujetos
a) Sujeto expropiante o activo: Es el Ministerio competente del sector, el Gobierno Regional
y el Gobierno Local responsable de la tramitación de los procesos de Adquisición o Expro
piación.
b) Sujeto expropiado o pasivo: Es el propietario o poseedor del inmueble sujeto a Adquisi
ción o Expropiación. La identificación del Sujeto Pasivo será realizada por el Sujeto Activo.
Bienes objeto de adquisición y expropiación: Todos los Bienes inmuebles de dom inio priva
do.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 375 of 1506 --

Tema 2: Temas de derecho civil
Indemnización justipreciada: Comprende el valor de tasación comercial debidamente ac
tualizado del bien que se expropiay la compensación que el sujeto activo de la expropiación
debe abonar en caso de acreditarse fehacientemente daños y perjuicios para el sujeto pasivo
originados inmediata, di recta y excl usivamente por la naturaleza forzosa de la transferencia.
Procedimiento: En la ley que se expida en cada caso debe señalarse la razón de necesidad
pública o seguridad nacional que justifica la Expropiación.
El Decreto Legislativo N ° ii9 Z crea un procedimiento de expropiación que tiene como paso
previo la “identificación de los inmuebles materia de adquisición” mediante la figura de la
adquisición y de ser el caso de la expropiación con fines de “necesidad publica” y “seguridad
nacional".
Este procedimiento consiste en la comunicación al sujeto pasivo (que en este caso sería el pro
pietario o poseedor del inmueble), cuya comunicación; la identificación de la partida registral
y una orden de anotación preventiva emitida por la administración serían documentos sufi
cientes para que el Registro de Propiedad Inmueble realice la anotación en la partida regis
tral correspondiente, obligando al registrador a inscribir dicha a anotación en la partida del
inmueble correspondiente sin calificar la validez del acto. Asimismo, este decreto establece
que en caso la expropiación se realice por una Asociación Pública Privada-APP y tratándose
de una obra de infraestructura la administración podría iniciar la obra sin que la expropiación
allá sido declarada mediante Ley tal y como lo establece la constitución.
Dentro de los 10 días hábiles siguientes al rechazo o al vencimiento del plazo a la oferta de
adquisición, el Sujeto Activo expide la norma que apruebe la ejecución de Expropiación del
bien inm uebleyel valorde laTasación. La norma que apruebe laejecución de la Expropiación
será a través de la resolución ministerial; acuerdo de consejo regional en el caso de Gobiernos
Regionales; o mediante acuerdo de concejo en caso de los Gobiernos Locales.
Dentro de los 05 días hábiles siguientes de emitida la norma que apruebe la ejecución de la
Expropiación y notificado la consignación al Sujeto Pasivo, la entidad pública correspondiente
remite al Registro de Predios de la Sunarp, copia de la norma que aprueba la ejecución de Ex
propiación del bien inmueble, copia fedateada del documento que acredite la consignación
del monto del valorde laTasación a favor del Sujeto Pasivo, así como la siguiente información:
a. Si el bien inmueble está inscrito, se indica el número de la partida electrónica, b. Si el bien
inmueble no está inscrito, se debe adjuntar los planos correspondientes suscritos por verifi
cador catastral del Registro de Predios, c. Si el bien inmueble forma parte de uno de mayor
extensión inscrito, se indica el número de partida registral y adjuntarse los planos correspon
dientes para su independización suscrito por verificador catastral del Registro de Predios, d.
Para todos los casos, se identificará el Sujeto Activo, Sujeto Pasivo y el Beneficiario de la Expro
piación, pudiendo incorporar derechos superficiales y cualquier otro derecho real que ostente
el Sujeto Pasivo sobre el bien inmueble materia de Expropiación.
El registrador dentro de los 07 días hábiles de recibida la orden de inscripción con la informa
ción indicada en el presente artículo, inscribe la Expropiación a nombre del Beneficiario al cual
pertenece el proyecto, bajo responsabilidady sanción de destitución.
Caducidad: El derecho de Expropiación del Sujeto Activo caduca en los siguientes casos:
