UBILEX
a. Cuando no se haya iniciado el procedimiento expropiatorio en un plazo de 6 o meses con
tados a partir de la vigencia de la Ley autoritativa. La caducidad se produce de pleno dere
cho. La autoridad jurisdiccional encargada de la causa la declara a petición de parte.
b. En los casos que sea necesario expropiar más de un inmueble para una Obra de Infraes
tructura, el plazo de caducidad que se refiere el literal anterior, comienza a computarse
desde que se autorice o inicie la últim a Expropiación.
En casos que como consecuencia del vencimiento del plazo establecido en el numeral ante
rior, el Congreso puede autorizar mediante la expedición de una ley autoritativa una nueva
expropiación sobre los mismos bienesy por la misma causa.
Causales de cuestionamiento en vía arbitral o judicial: Son causales de cuestionamiento en
vía arbitral o judicial, únicamente:
a. Revisión del valor de Tasación del bien inmueble objeto de Expropiación.
b. La solicitud de Expropiación total del inmueble, en los casos que el Sujeto Activo realice
una Expropiación parcial, solo cuando el remanente del bien inmueble que no es afecta
do por el acto expropiatorio sufre una real desvalorización o resultare inútil para los fines
a que estaba destinado con anterioridad a la Expropiación parcial.
c. Las duplicidades de partidas a que se refiere el artículo 29 de este Decreto, siempre que la
controversia no se relacione con la impugnación de actos administrativos.
Los arbitrajes iniciados bajo esta causal se tramitarán entre las partes involucradas en la du
plicidad de partidasy sólo serán de conocimiento del Sujeto Activo en su etapa inicial, a fin de
verificar el cumplim iento de la regla de procedencia prevista en el últim o párrafo del artículo
35 de este Decreto Legislativo.
Vía arbitral: En caso el Sujeto Pasivo decida ejercer su derecho en vía arbitral, son de aplica
ción las reglas del arbitraje en el presente Título, siendo de aplicación supletoria el Decreto
Legislativo N ° i0 7 i, Decreto Legislativo que norma el Arbitraje.
El Sujeto Activo puede oponerse a acudir al arbitraje dentro del plazo máximo de 10 días hábiles
de recibida la comunicación del Sujeto Pasivo. En caso de no manifestar expresamente su negativa,
dentro del plazo señalado, se entiende que el Sujeto Activo ha aceptado someterse al arbitraje.
Los árbitros, Tribunal Arbitral y/o los peritos que designe o contrate, se sujetarán a lo dispues
to en el presente Decreto Legislativoy normas complementarias.
El Sujeto Activo y el Sujeto Pasivo pueden acordar someterse al arbitraje siempre que el Sujeto
Pasivo efectúe la entrega anticipada de la posesión del inmueble.
Del procedimiento de ejecución coactiva: Vencidos los plazos establecidos en el literal f) del
numeral 20.4 y literal e) del numeral 28.1 del Decreto Legislativo 1192, y en caso el Sujeto Pasi
vo no cumpla con entregar el bien materia de Adquisición o Expropiación, el Sujeto Activo, a
través de su ejecutor coactivo, debe iniciar el procedimiento de ejecución coactiva.
7. Usufructo
Concepto: Es el derecho real que otorga las facultades de usary disfrutartem poralm ente de
un bien ajeno. (Art. 999 C.C.).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 377 of 1506 --

Tema 2: Temas de derecho civil
Formas da co osiitod én : (Art. 1000 C.C.)
1. Por Ley.
z. Contrato o acto jurídico unilateral.
Además, la doctrina considera: por testamento (está comprendido en nuestro Código, en el
acto jurídico unilateral) y prescripción adquisitiva.
Características
1. Es un derecho temporal (Art. 1001 C.C.).
- Generalmente en persona natural es vitalicio.
- Para personas jurídicas no excede de 30 años.
- Para inmuebles de valor monumental de propiedad del Estado que sean materia de
restauración con fondos de persona natural o jurídica es de 99 años.
2. Concede al usufructuario el derecho de uso y disfrute del bien ajeno (Art. 999 C.C.).
3. Dejaasalvo lasustanciade las cosas, poresosedaen bienes noconsumibles (a excepción
del cuasi usufructo que nuestra legislación ha regulado).
Derechos del usufructuario: Derecho a percibir los frutos que produce el bien, así le pertene
cen los frutos naturales y mixtos pendientes al comenzar el usufructo (Art. 1016 C.C).
Deberes del usufructuario
1. Realizar un inventario y tasación de los bienes muebles, salvo que haya sido expresamen
te eximido de esa obligación por el propietario que no tenga heredero forzoso (Art. 1006
C.C.).
2. Prestar la garantía señalada en el título constitutivo de su derecho a la que ordene el juez,
cuando éste encuentre que puede peligrar el derecho del propietario (Art. 1007 C.C.).
3. Explotar el bien en la forma normal y acostumbrada (Art. 1008 C.C.).
4. No realizar modificaciones sustanciales del bien o de su uso (Art. 1009 C.C.).
5. Pagar los tributos, las rentas vitaliciasy las pensiones de alimentos que graven los bienes.
6 . Devolver el bien a nudo propietario, al finalizar el usufructo.
Derechos del nudo propietario
1. Derechos de disposición sobre el bien.
2. A obtener los frutos pendientes al momento de la restitución del bien (Art. 1016 C.C.).
3. A ser indemnizado si el bien ha sufrido alteración sustancial.
4. Derecho al tesoro (no lo tenemos regulado en nuestro Código Civil, pero podría aplicarse
el Art. 934 C.C.).
Deberes del nudo propietario: No perturbar el ejercicio de sus derechos del usufructuario.
Extinción y modificación: (Art. 1021 C.C.)
1. Cumplimiento de los plazos máximos que prevé el Art. 1001 C.C. o del establecido en el
acto constitutivo. Para la doctrina, una causal de extinción el cumplim iento de la condi
ción.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 378 of 1506 --

UBILEX
2. Prescripción extintiva, por el no uso del derecho durante 5 años.
3. Por consolidación del usufructo con la propiedad.
4. Por muerte o renuncia del usufructuario.
5. Destrucción o pérdida total del bien.
6. Por sentencia judicial, motivada en el abuso que el usufructuario haga de su derecho,
enajenando o deteriorando los bienes o dejándolos perecer por falta de reparaciones or
dinarias.
8. Cuasiusufructo
Concepto: Denominado también como usufructo imperfecto o impropio, a diferencia del
usufructo propiamente dicho, éste recae sobre un bien consumible. Nuestra legislación sólo
aplica el usufructo al dinero y al crédito, que para un sector de la doctrina constituiría en un
comodato. (Art. 1018 C.C.)
9. Uso
Es el derecho real que faculta a usar o servirse de un bien no consumible (Art. 1026 C.C.).
1 0 . Habitación
Cuando este derecho de uso recae sobre una casa o parte de ella para que sirva de morada
(Art. 1027 C.C.).
11. Superficie
Es la facultad con que cuenta el superficiario de gozar temporalmente una construcción en
propiedad separada sobre o bajo la superficie del suelo, siempre que no exceda de 99 años.
Al finalizar el derecho de superficie, el propietario del suelo adquiere la propiedad de lo cons
truido reembolsando su valor, salvo que se pacte lo contrario (Art. 1030 C.C.).
12. Servidumbres
Cuenta con dos definiciones, una es objetiva y la otra subjetiva.
Objetiva: Es un derecho real que permite que el propietario de un predio se beneficie de otro
predio que no es suyo.
Subjetiva: Es el gravamen que se le impone a un predio en beneficio de otro predio (Art. 1035 C.C.).
Formas de constitución
1. Por ley.
2. Por contrato.
3. Por testamento.
4. Por prescripción adquisitiva de las servidumbres aparentes, mediante la posesión conti
nua durante 5 años con justo título y buena fe o durante 10 años sin estos requisitos (Art.
1040).
378 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 379 of 1506 --

Tema 2: Temas de derecho civil
Clases de servidumbres
1. Aparentes e Inaparentes: Las primeras son aquellas que se encuentran continuamente
a la vista, como la de tránsito cuando se hace por una senda o por una puerta especial
mente destinada a él (Art.1040). Las Inaparentes, son aquellas que no se conocen poruña
señal exterior, como la misma de tránsito por un sendero oculto, la de acueducto a través
de un canal que no es visible a la superficie.
2. Continuas y Discontinuas: Las primeras son aquellas que para su ejercicio no requieren
de un hecho actual del hombre. Un acueducto no requiere de la presencia diaria del pro
pietario beneficiado con él. Funciona sin intervención de nadie. Las Discontinuas, son las
que suponen un hecho actual del hombre y se ejercen durante intervalos más o menos
largos de tiempo. La servidumbre de tránsito, el sacar agua de un pozo a través de un pre
dio, son discontinuas porque necesitan de un hecho actual del hombre.
3. Positivas y Negativas: La primera impone al dueño del predio sirviente la obligación de
dejar hacer algo al dueño del predio dominante, como las servidumbres de acueducto,
de tránsito, etc. La Negativa, impone al propietario del predio sirviente una carga de no
hacer, que si no fuera por la existencia de la servidumbre le sería lícito hacerlo. La servi
dumbre de luz, la de vista, la de no edificar hasta cierta altura.
Características
1. Son inseparables de ambos predios.
2. Se transmiten con los predios.
3. Subsisten cualquiera sea su propietario.
4. Son perpetuas salvo disposición legal o pacto en contrario.
5. Son indivisibles.
Extinción
1. Por el no uso durante 5 años (Art. 1050 C.C.).
2. Por destrucción total, voluntaria o involuntaria, de cualquiera de los edificios, dominante
o sirviente, sin mengua de las relativas al suelo.
En Doctrina: i) Al vencimiento del plazo o al cumplim iento de la condición; ii) Nulidad,
resolución o rescisión del acto jurídico que lo constituía; iii) Pérdida de utilidad del predio.
13. Derechos reales de garantía
La garantía real permite al deudor responder frente al acreedor con bienes personales y tan
gibles.
Los derechos reales de garantía (garantía mobiliaria, hipoteca, anticresis, warrant) aseguran
el cumplim iento de obligaciones contraídas en favor del acreedor titu lar del derecho real de
garantía. El beneficio que extrae el titu lar del derecho real de garantía está relacionado con
la seguridad que brinda al cumplimiento de la obligación principal y no con el uso y goce del
bien, excepto la anticresis en laque el titu lartien e un derecho de goce del bien.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 380 of 1506 --

13.1. Garantías n o b ilia ria s
En cuanto a garantía mobiI¡aria se refiere, ha tenido que pasar por una cierta “evolución” le
gislativa. En principio, nuestro país regulaba las garantías mobiliarias en nuestro Código Civil,
como prendas civiles; y en otras legislaciones, como prendas especiales o prendas sin des
plazamiento, haciendo engorrosa su aplicación. Entonces, había la necesidad de regular las
garantías mobiliarias en una sola ley. Es por ese motivo, que se crea la Ley N° 28677, la dación
de esta últim a norma significó una reconfiguración del sistema de garantías en el Perú, pues
significó la derogación de la prenda, la permisión del pacto comisorio, la posibilidad de ga
rantizar con bienes futuros y aún ajenos. La finalidad era única: hacer más eficaz el sistema
crediticio.
Continuando con el proceso de reforma buscando mayor simplicidad en el proceso, fue dero
gada la Ley N° 28677, con fecha 10 de septiembre del 2018 se publicó en el diario oficial El Pe
ruano, el Decreto Legislativo N °i400- Decreto Legislativo que aprueba el Régimen de Garantía
Mobiliaria-, que tiene por objeto regular el Régimen de Garantía Mobiliaria (GM) y el Sistema
Informativo de Garantías Mobiliarias (SIGM).
Concepto: LaGM es la afectación de un bien mueble mediante un negocio jurídico, destinada
a asegurar el cumplimiento de una obligación. Mediante dicha figura, se busca darle valor a
los bienes muebles desde un plano dinámico, por lo que puede darse con o sin desposesión
del bien mueble.
La GM puede darse con posesión o sin posesión del bien en garantía. Así tenemos:
GM con posesión o posesoria, cuando se entrega la posesión del bien al acreedor garantiza
do o a un tercero depositario. Se constituye al momento en que el deudor garante entrega
la posesión de los bienes en garantía al acreedor garantizado o a un tercero depositario
designado por éste. Dicha constitución debe constar por cualquier medio escrito que deje
constancia de la voluntad de las partes bajo sanción de nulidad, el cual debe formalizarse
mediante escritura pública, firmas legalizadas, firmas digitales o firmas manuscritas, se
gún lo determinen las partes.
GM sin posesión, cuando el bien en garantía permanece en posesión del deudor garante
o de un tercero. Se constituye mediante acto jurídico constitutivo, por cualquier medio
escrito que deje constancia de la voluntad de las partes bajo sanción de nulidad, debien
do formalizarse mediante escritura pública, firmas legalizadas, firmas digitales o firmas
manuscritas, según lo determinen las partes.
Bienes objeto de garantías mobiliarias
De manera enunciativa, pero no limitativa, pueden ser objeto de GM los bienes muebles es
pecíficos, categorías genéricas de bienes muebles, derechos sobre bienes muebles, bienes
muebles determinados o determinables, bienes muebles tangibles o intangibles, bienes
muebles presentes o futuros, bienes muebles registrados o no registrados o sobre la totalidad
de los bienes muebles del deudor garante, entre otros como: 1. Los vehículos. 2. Los inven
tarios. 3. El saldo de cuentas de depósitos en ESF, los certificados de depósito a plazo o los
certificados bancarios en ESF. 4. Conocimientos de embarque o títulos de análoga naturale
za. 5. Las acciones o participaciones en sociedades o por contratos asociativos, aunque éstas
