Temq 2: Te m as de derecho civi
sean propietarias de bienes inmuebles, con excepción de lo contemplado en el numeral 4 del
artículo 5 del presente Decreto Legislativo. 6 . Los derechos patrimoniales de autor, derechos
de patente, nombres comerciales, marcas y otros derechos de propiedad intelectual. 7. Los
créditos o las carteras de créditos en ESF. 8 . Los derechos de crédito para exigir una prestación.
En caso el derecho de crédito se incorpore en un título valor o valor representado mediante
anotación en cuenta en una ICLV, el acreedor garantizado debe registrar la garantía en la ICLV
de conformidad con la normativa aplicable. 9. Las indemnizaciones provenientes de las pó
lizas de seguro. 10. El derecho de obtener frutos o productos de cualquier bien. 11. Todo tipo
de maquinaria o equipo que conserve su carácter mobiliario, iz. Los derechos a dividendos
o a utilidades de sociedades o que se deriven de contratos asociativos. 13. Todo bien mueble
dado en arrendamiento financiero o arrendado. 14. Las concesiones privadas, sus flujos de
cajay otros derechos accesorios a la concesión. 15. Las locomotoras, vagonesy demás material
rodante afecto al servicio de ferrocarriles. 16. Los cultivos agroforestalesy la cosecha presente
o futura. 17. Los productos derivados de la explotación agropecuaria u otros emprendimientos
de las comunidades campesinas que puedan ser afectados por sus comuneros, de acuerdo
con la ley de la materia. 18. Los bienes muebles destinados a la actividad m ineray los minera
les extraídos. 19. Los flujos de bienes presentesy/o futuros, zo. Cualquier otro bien que no esté
excluido en el art. 5 del D.Leg. 1400.
Bienes excluidos del régimen de garantías mobiliarias
Se encuentran excluidos de ser afectados con GM regulada por el D.Leg. 1400, los siguientes
bienes:
1. Los bienes muebles inembargables. 2. Los intangibles excluidos expresamente por ley. 3. Las
naves y embarcaciones establecidas en las leyes y convenciones internacionales aplicables. 4.
Los títulos valores o valores representados mediante anotaciones en cuenta en una ICLV. 5. Los
warrantsy los certificados de depósito con warrants emitidos por los almacenes generales de
depósito y depósitos aduaneros autorizados así como los bienes representados por aquéllos.
6. Las remuneracionesy el fondo de compensación por tiempo de servicios, salvo las excepcio
nes establecidas en las leyes especiales de la materia. 7. Los recursos que constituyen el encaje
bancario de conformidad con el artículo 163 de la Ley N° 26702, Ley General del Sistema Finan
ciero y del Sistema de Seguros y Orgánica de la Superintendencia de Banca y Seguros. 8 . Los
bienes que integran los Fondos de Aportes Obligatorios, el Encaje Legal, el Fondo de Longevi
dad, el Fondo Complementario y los demás señalados en el artículo 20 del Decreto Supremo
N° 054-97-EF, TUO de la Ley del Sistema Privado de Administración de Fondos de Pensiones.
9. Los bienes muebles que forman parte de una hipoteca y que no puedan separarse del bien
inmueble sin perjudicar su integridad, de acuerdo con lo establecido por el Código Civil. 10.
Otros bienes que se excluyan por ley expresa.
Caracteres.- La GM comprende, salvo pacto distinto, la deuda principal, los intereses, las co
misiones, los gastos, las primas de seguros pagadas por el acreedor garantizado, las costas
y los costos procesales, los eventuales gastos de custodia y conservación, las penalidades, la
indemnización pordañosy perjuicios y cualquierotro concepto acordado porlas partes hasta
el monto del gravamen establecido en el acto jurídico constitutivo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES ■3L

