UBILEX
El pago derivado de la ejecución de la garantía mobiliaria se imputará al capital, los intereses
que devengue, las primas del seguro pagadas por el acreedor, las costas y costos procesales,
las penalidades, la indemnización por daños y perjuicios, los gastos y las comisiones, en ese
orden, salvo pacto en contrario.
Prelación y oponibilidad ante terceros.- La prelación y oponibilidad ante terceros respecto
de los derechos conferidos por la GM surte efectos desde el momento en que aquella se pu-
blicita.
La prelación de los acreedores garantizados cuyas GM adquieren publicidad al ingresar un
aviso electrónico en el SIGM, se rige por el criterio de prioridad en el tiempo.
Cuando se constituye más de una GM sobre un mismo bien o bienes, la prelación de dichas
garantías, incluyendo sus bienes atribuí bles y derivados, se determina por el momento de su
publicidad conforme al párrafo 36.1.
La prelación de los mandatos y/o resoluciones judiciales, arbitrales o administrativas, se de
terminan porel momento de su publicidad conforme al párrafo 36.1.
Publicidad y prelación de GM sobre bienes en posesión o con contrato de control del acree
dor garantizado:
1. La garantía mobiliaria con posesión por parte del acreedor o un depositario designado
por éste adquiere publicidad al momento que el acreedor o el depositario adquiere pose
sión sobre los bienes en garantía, lo que determina la prelación.
2. El acreedor garantizado de una garantía mobil ¡aria con posesión por parte de dicho acree
dor, tiene prelación sobre cualquier otro acreedor, salvo que exista un aviso electrónico
ingresado en el SIGM con fecha previa al momento en que comenzó a ejercer la posesión.
3. La garantía mobiliaria sobre saldos en cuentas de depósitos referidas en el numeral 3 del
artículo 4 y en el artículo 14 del D. Leg. 1400, se determina por el momento en que se
otorgue el control al acreedor garantizado.
Prelación con respecto a los bienes muebles colocados en un bien inmueble por su incorpo
ración o destino: La GM sobre bien mueble colocado en un inmueble por su incorporación o
destino sobre el cual se constituye hipoteca tiene prelación si antes de la constitución de dicha
garantía real existe un aviso electrónico de la constitución de la garantía mobiliaria en el SIGM.
Prelación de la garantía mobiliaria preinscrita o sujeta a condición: Surte efectos ante terceros
desde la fecha de su publicidad, aunque dicha publicidad sea anterior al acto jurídico consti
tutivo, anteriora la adquisición de los bienes o anterior al cumplim iento de la condición a que
se sujetó la obligación.
Constitución y Registro de la GM: La GM se constituye mediante acto jurídico expresado en
cualquier medio escrito que deje constancia de la voluntad de las partes, debiendo form ali
zarse mediante escritura pública, firmas legalizadas, firmas digitales o firmas manuscritas,
según lo determinen las partes.
En el caso particular de la GM con posesión o posesoria, la constitución ocurre en el momento
en que el deudor entrega la posesión del bien en GM al acreedor garantizado o a un tercero
depositario. El registro de laGM otorga seguridad jurídica a las partes, puesto que en un doble
