Tema 2: Temas de derecho civil
filtro (notario y registrador) se verifica la identidad de las partes, así como el propietario del
bien. Adicionalmente, el registro sirve para fines de determinar el rango de prioridad o pre
lación sobre la CM, así como para dar publicidad de la GM. De considerarlo conveniente las
partes, la GM es registrada en el Registro de Bienes Muebles, a cargo de la Superintendencia
Nacional de Registros Públicos (SUNARP) y que comprende, entre otros, el registro de pro
piedad vehicular y el registro mobiliario de contratos. Cabe agregar que la SUNARP asume
responsabilidad por el contenido de la partida registral.
El nuevo Régimen deGM crea el SIGM, que es una plataforma únicay de alcance nacional para
el registro voluntario de avisos electrónicos de GM. El ingreso y consulta de los avisos electró
nicos se realizará por vía directa y remota a través del portal que se diseñe para tal efecto. La
responsabilidad del contenido del aviso recaerá sobre la persona que ingrese la información,
dado que no hay ninguna instancia que verifique la veracidady exactitud de la información in
gresada. Cabe agregar que el SIGM es un sistema independiente del Registro de Bienes Mue
bles de la SUNARPy, a diferencia de este último, no otorga derechos de propiedad, por ser un
registro sin calificación registral. Asimismo, a diferencia de los sistemas de registro, el SIGM no
convalida actos jurídicos o contratos, su existencia, eficacia o validez.
Proceso de Ejecución de las GM (PEGM).- En caso de incumplimiento del deudor, el proceso
de ejecución puede darse a través de:
i) La venta extrajudicial: El acreedor garantizado, a través del representante, puede iniciar
y llevar a cabo el procedimiento de venta aún si no cuenta con la posesión del bien en
garantía. De realizarse la venta, corresponde al deudor entregar la GM al nuevo adqui-
rente. Respecto a este últim o punto, es suficiente que el acreedor acredite la existencia
de la GM, el requerimiento del pago cursado al deudory la exigibilidad de la obligación
de entrega para que el Juez, sin mayor trámite, ordene la toma de posesión del bien en
GM mediante su entrega inmediata con auxilio de la fuerza pública. Las partes pueden
establecer que las GM se vendan a través de una venta privada o venta en subasta pública.
El valor del bien se puede determinar mediante el mecanismo que acuerden las partes,
incluyendo la referencia a una cotización del bien en una bolsa o mercado determinado,
una fórm ula de cálculo, la intervención de un tasador o cualquier otro mecanismo.
ii) La adjudicación del bien por el acreedor: Producido el incumplimiento, el acreedor que
desee adjudicarse el bien en GM deberá comunicar notarialmente al deudory al repre
sentante el monto detallado de la obligación garantizada no pagada y el valor del bien
mueble afecto en GM acordado por las partes.
iii) La venta judicial: Se rige porel Código Procesal Civil y, en tal sentido, el proceso de ejecu
ción de laGM no difiere del que corresponde a la garantía inmobiliaria.
En los dos primeros casos, el acreedor debe otorgar poder específico e irrevocable a un
tercero (el representante) para que éste realicey formalice la transferencia de laGM.
13.2. La anticresis
Por la anticresis se entrega un inmueble en garantía de una deuda, concediendo al acreedor el
derecho de explotarloy percibirsus frutos.
