S e r r a n o G ó m e z , 2005, p. 301).
Las hipotecas legales. Son aquellas cuya constitución puede ser exigida por la persona a
cuyo favor una ley la establece en garantía de determinados derechos. Nace del solo mi
nisterio de la ley; es la propia ley laque da por constituida a la hipoteca, sin que las partes
involucradas en el contrato hayan manifestado su voluntad. La ley de forma directa actúa
ante el silencio de la voluntad de las partes. "Existe hipoteca legal cuando la hipoteca se
constituye de pleno derechoy se inscriben de oficio, bajo responsabilidad del registrador,
simultáneamente con los contratos de los cuales emanan” (Art. 1119 C.C.).
