Tema 2: Temas de derecho civil
1. La del inmueble enajenando sin que su precio haya sido pagado totalmente o haya sido
con el dinero de tercero.
2. La del inmueble para cuya fabricación o reparación se haya proporcionado trabajo o ma
teriales por el contratistay por el monto que el comitente se haya obligado a pagarle.
3. La de los inmuebles adquiridos en una participación con laobligación de hacer amortiza
ciones en dinero a otros de los copropietarios”.
Formalidad
La hipoteca se constituye por escritura pública, salvo disposición diferente de la ley (Art. 1098
C.C). La forma es consustancial al acto jurídico de hipoteca, pues es el único modo de pro
bar su existencia y contenido, no solo cumple una función probatoria (ad probationem) sino
es la única prueba de su existencia (ad solemnitatem) ya que no admite prueba supletoria2. La
hipoteca es un derecho real que se perfecciona con la observancia de la forma prescrita, en
este caso escritura pública y subsiguiente inscripción en el Registro. Así, a la solemnidad se
la conceden dos elementos: i) El documento, la escritura pública (Art. 1098). ii) El registro, la
inscripción en el registro de propiedad inmueble (Art. 1099, inc. 3).
Según nuestra jurisprudencia:
(T) para que un acto jurídico pueda ser admitido como válido es menester que cumpla con
1 1 los requisitos de validez previstos para tal efecto, que ei caso específico submatería, tratándose::
■ de hipoteca,el artículo 1098 del Código Civil.ha establecido como formalidadpara sucohstitucipní
■ B H B que sea otorgada por escritura pública, salvo disposición diferente de la ley." Cas. N° 217-2003-Lima.
; '' (2) Sin embargo, “sí bien el artículo 1098 de la norma sustantiva establece una formalidad para
la constitución de la hipoteca, lo cierto es que, no sanciona con nulidad su inobservancia, por lo
que conforme al artículo 144 del Código Civil, el documento que se extienda tiene el carácter de
ad probationem. Dicho acto no es nulo ni inexistente, pues constituye un medio de prueba de la existencia del
acto", Cas. N° 3787-2015-Junín.
Caracteres
1. La hipoteca debe recaer sobre inmuebles específicamente determinados (Art. 1100 C.C.). El
art. 1100 del Código Civil recoge el principio de especialidad de la hipoteca, según el cual
debe individualizarse en el acto constitutivo de la hipoteca el bien o bienes hipotecados.
Según nuestra jurisprudencia:
"se entiende que el bien debe estar individualizado con la fijación del área, linderos y medidas peri-
métricas que deben coincidir con aquellas señaladas en la ficha registra! del Registrode Propiedad
Inmueble". Cas. N° 2402-2012-Lambayeque.
2. Tiene naturaleza temporal, debido a que necesariamente se resuelve en el tiempo, sea
por la cancelación de laobligación que garantiza o por la realización del bien o cualquiera
de las formas de extinción del gravamen. El plazo de la hipoteca puede ser inicial o sus-
2 Cas. N° 217-2003-Lima.
