UBILEX
pensivo, final o resolutorio, así como cierto e incierto. De esta manera, podrá pactarse
que la hipoteca produzca sus efectos desde y hasta determinada fecha. Pasado el plazo,
final o resolutorio, no podrá ejecutarse el bien gravado con la hipoteca (Beaumont, 2011,
p. 613). (Art. 1005 C.C.)
3. Se constituye por convención entre las partes (hipoteca convencional) o por disposición
de la ley (hipoteca legal).
4. Es necesariamente onerosa, como limitación del dominio.
5. La hipoteca es indivisible y subsiste por entero sobre todos los bienes hipotecados (Art.
1102 C.C.). Cada una de las cosas hipotecadas y cada parte de ellas son obligadas al pago
de toda la deuda.
Según nuestra jurisprudencia:
(Ü "Un carácter jurídico de la hipoteca es su indivisibilidad, de tal manera que recae sobre el
todo y cada una de las partes, y si el bien hipotecado se divide, todas y cada una de las partes
continúan gravadas en garantía del cumplimiento o pago". Cas. N° 306-97-Aísgmpa.
Í2J "La hipoteca es un derecho real, accesorio e indivisible, pues el acreedor tiene el derecho de
persecución y venta del bien, se constituye en garantía de un crédito u obligación y se extiende a
todas las partes del bien hipotecado". Cas. N° 723-98- Arequipa.
No obstante la indivisibilidad, el deudortiene derecho a la reducción del gravamen y ade
cuarlo al monto real de la obligación (Art. 1115 C.C.)
El deudor hipotecario puede solicitar al juez la reducción del monto de la hipoteca, si ha
disminuido el importe de la obligación. La petición se tramita como incidente. (Art. n i 6 C.C.)
6. Es un derecho accesorio, o sea que depende de una obligación principal cuyo cumpli
miento garantiza. (Arias Schreiber). La accesoriedad significa que depende del principal;
por tanto, carece de vida propia e independiente pues no se concibe hipoteca por la hipo
teca misma, y siempre acompaña a un crédito al cual accede. El artículo 1097 del C.C. le
asigna esta característica.
Según nuestra jurisprudencia:
"La hipoteca es un derecho real, accesorio e indivisible, pues el acreedor tiene el derecho de perse
cución y venta del bien, se constituye en garantía de un crédito u obligación y se extiende a todas las
partes del bien hipotecado". Cas. N° 723-98- Arequipa.
Requisitos
1. Que afecte el bien el propietario o quien esté autorizado para ese efecto conforme a ley.
2. Que asegure el cumplimiento de una obligación determinada o determinable.
3. Que el gravamen sea de cantidad determinada o determ inabley se inscriba en el registro
de la propiedad inmueble.
La inscripción de la hipoteca en el registro tiene carácter constitutivo, es decir, que la no ins
cripción ocasiona la ineficacia absoluta frente a terceros y entre las partes (Vásquez Ríos, 2011,
>1®
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 387 of 1506 --

Tema 2: Temas de derecho civil
p. 84).“La hipotecase constituye por la inscripción en el registro de la propiedad. El momento
de la inscripción determina el rango hipotecario” (Álvarez Caperochipi,i987, p. 145).
De acuerdo con el numeral 3 del artículo 1099 del C.C., uno de los requisitos para la validez
de la hipoteca es que el gravamen se inscriba en el Registro de la Propiedad Inmueble. Según
Cuadros Villena (1996) “la inscripción constituye la expresión de la publicidad de la hipoteca.
La inscripción es, pues, no solamente la solemnidad de la hipoteca, sino-fundam entalm en
te -la garantía y seguridad de los terceros” (p. 319).
Según la Sentencia del VI Pleno Casatorio Civil: “En la hipoteca no existe la entrega del inmueble
al acreedor o al depositario designado por ambas partes, sustituye la falta de entrega con la inscripción
del gravamen en el Registro de Propiedad Inmueble como acto constitutivo para el nacimiento de este
derecho”.
Extensión.- La hipoteca se extiende a todas las partes integrantes del bien hipotecado, a sus
accesorios, y al importe de las indemnizaciones de los seguros y de la expropiación, salvo pac
to distinto (Art. 1101 C.C.)
Rango.- Las hipotecas tendrán preferencia por razón de su antigüedad conforme a la fecha del
registro, salvo cuando se ceda su rango.
No se puede renunciara la facultad de gravar el bien con segunda y ulteriores hipotecas.
El acreedor preferente puede ceder su rango a otro acreedor hipotecario. Para que la cesión
produzca efecto contra el deudor se requiere que éste acepte que le sea comunicada fehacien
temente.
Extinción
1. Extinción de la obligación que garantiza,
z. Renuncia escrita del acreedor.
3. Anulación, rescisión o resolución de dicha obligación.
4 . Destrucción total del inmueble.
5. Consolidación.
Ejecución extrajudicial de hipotecas (D. Leg. N°495)
El Decreto Legislativo N° 4 9 5 creó la hipoteca populary reguló la ejecución extrajudicial y ju
dicial de la hipoteca prevista en el Código Civil y de la hipoteca popular. La ejecución extra
judicial consiste en términos generales en lo siguiente: al constituirse la hipoteca, el deudor,
con asentimiento del acreedor, puede otorgar poder especial e irrevocable a un mandatario,
que no puede ser el acreedor hipotecario, para que venda el bien en caso de incumplimiento.
Producido el incumplimiento, el acreedor dirige una carta notarial al deudory al mandatario
dejando constancia del incumplimiento y este últim o procede a la venta directa del bien. La
venta no puede realizarse en precio menor a las dos terceras partes del valor del bien esta
blecido en el contrato de hipoteca, actualizado a la fecha de la venta, según los índices del
Instituto Nacional de Estadística.
La ejecución judicial, por su lado, procedía a falta de pacto de venta extrajudicial, o si, en caso
de pacto, hubieran transcurrido 30 días desde que el acreedor envió la carta notarial dejando
constancia del incumplimiento y no se hubiera vendido el bien hipotecado. En cuanto al trá-
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 388 of 1506 --

mite judicial, erasim ilaral procedimiento de ejecución regulado por el Decreto Legislativo N°
215, actualmente los artículos referidos a la ejecución judicial se encuentran derogados.
13.4. El derecho de retención
La retención es un derecho real de garantía que está consagrado en el artículo 1123 del Código
Civil en los siguientes términos: "Por el derecho de retención un acreedor retiene en su poder
el bien de su deudor si su crédito no está suficientemente garantizado. Este derecho procede
en los casos que establece la ley o cuando haya conexión entre el crédito y el bien que se re
tiene”.
El profesor Martin Mejorada3 indica que deben concurrir ciertos elementos de hecho para que
se cumpla el supuesto de la retención, a saber:
(i) Debe existir una obligación no garantizada suficientemente: La obligación que justifica
la retención es cualquiera que tenga contenido patrimonial. A diferencia de lo que ocurre
con las otras garantías (prenda e hipoteca), la obligación garantizada no tiene que ser
dineraria. Esto es así porque la retención no conduce a la ejecución o venta del bien. En las
demás garantías la obligación garantizada siempre es dineraria porque el resultado de la
venta (que es dinero) debe pagar la obligación.
(ii) Debe existir un bien del deudor en poder del acreedor: Los bienes deben ser del deu
dor. El supuesto más simple es que los bienes pertenezcan al deudor (propiedad), pero se
pueden presentar situaciones en que los bienes corresponden al deudor a título distinto,
como es el caso del usufructo, la superficie, el uso, la habitación, etcétera. En estos casos,
los bienes retenidos son los derechos desmembrados (que también son bienes confor
me a lo dispuesto por los artículos 885 inciso 10 y 8 8 6 inciso 11 del Código Civil), siempre
que los títulos que explican la desmembración estén vigentes frente al propietario, o que
de ellos no se desprenda un poder de reivindicación anticipado del dueño, precisamente
ante el hecho de la retención. Si el dueño de los bienes resolviera la relación en acuer
do con el deudor, luego de producida la retención, estaríamos ante una concurrencia de
acreedores que tiene por pretendientes al acreedor (retenedor) y al propietario, lo cual se
resolverá por las reglas de los artículos 1135 y 1136 del Código Civil según que el bien sea
mueble o inmueble. No se aplica en estos casos la prohibición del artículo 1124, pues ella
solo se refiere a los bienes que al tiempo de recibirse ya estaban destinados a otra perso
na, lo cual no ocurre cuando el título de la desmembración está plenamente vigente.
(iii) La ley debe disponer que procede la retención o debe existir conexión entre el crédito
y el bien: En todos los supuestos donde la ley ha establecido la retención como derecho
especial del acreedor, siempre existe conexión entre el bien y el crédito, de manera que
hubiera bastado la definición general de este derecho para comprender a todos los su
puestos de retención que nuestro ordenamiento parece admitir.
3 MEJORADA CHAU CA, Martin. Retención civil: apremio legítimo contra el deudor, lus Et Veritas N ° 30. pp. 145-150.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 389 of 1506 --

Tema 2: Temas de derecho civil
Oponibilidad de la retención
Respecto de la oponibilidad el profesor Martin Mejorada manifiesta que ''‘según el artículo
1128 del Código Civil, para que la retención surta efectos frente a terceros debe inscribirse en
el Registro. La norma no lo dice, pero obviamente esta es una inscripción que no requiere la
participación del titu la r del bien, pues la retención es en sí misma un acto unilateral. La nor
ma ratifica en parte la regla que se sigue para todos los derechos reales sobre inmuebles. Los
derechos solo son oponiblessi se han inscrito. Si el derecho no está registrado debe ceder ante
quienes sí tienen derechos inscritos. Ahora bien, el artículo 1128 solo parece ocuparse de la
oponibilidad de la retención frente al adquirente a título oneroso del bien. Mas aun, la norma
se refiere concretamente al adquirente de la propiedad, empero, como sabemos los conflictos
entre el retenedory los terceros no se agotan en la presencia de un adquirente a título oneroso
de la propiedad. ¿Qué pasa cuando el retenedor se enfrenta a otros titulares (usufructuarios,
superficiarios, etcétera) o cuando dichos adquirentes no son a título oneroso? Considero que
en tales supuestos se deben aplicar las normas sobre concurrencia de acreedores. Artículo 1135
para inmueblesy artículo 1136 para muebles. Es decir, el retenedor de inmuebles solo será ven
cido por los adquirentes que hayan inscrito su adquisición de buena fey si nadie ha registrado
por el adquirente que cuente con título cierto más antiguo que el suyo. Si el bien retenido es
mueble, el retenedor ganará siempre que tenga buena fe al ejercer la retención. Su buena fe
significa que al tiempo de retener debe ignorar si el bien se había comprometido a favor de
un tercero. De otro lado, el artículo 1129 del Código Civil señala que la retención no impide el
embargo y remate del bien, pero el adquirente no puede retirarlo del poder del retenedor si no
pagando la obligación garantizada, salvo la preferencia hipotecaria. En realidades una norma
imprecisa, que bajo la apariencia de ocuparse integralmente de un tema term ina describien
do solo un supuesto muy concreto de oponibilidad en la retención”.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 390 of 1506 --

UBILEX
1. La relación obligatoria: Concepto y clasificaciones. Concurso de acreedores en bie
nes muebles e inmuebles. La teoría del riesgo: Consecuencias. Cesión de créditos:
Concepto. Limitaciones.
La relación obligatoria: La relación obligatoria, denominada también relación obligacional,
es aquella en la que concurren solamente dos posiciones: la del acreedor o acreedores y la
del deudor o deudores, no interesando para el caso sean éstas personas naturales o jurídicas.
De ahí que las circunstancias vicisitudes, exigencias, emplazamientos, satisfacciones, tendrán
lugar solamente entre estas dos categorías.
La relación obligacional es un vínculo ideal, intersubjetivos, que va de sujeto a sujeto entre
los que se ha establecido un nexo, es decir un lazo o vínculo jurídico a partir de la prestación
a cumplirse que puede ser de dar, hacer o no hacer y que sólo surtirá efectos jurídicos entre
ellos, no alcanzando a los terceros ajenos a la relación obligatoria. Esta característica imposi
bilita constituir una obligación por otro o para otro de manera directa; sin embargo, esto no es
obstáculo para que la relatividad de la relación obligatoria haga surtir efectos frente a terceros
(contrato a favor de terceros) y que obligan al deudor a actuar en benéfico de ese tercero con
pleno interés del acreedor. Art. 1457 del C.C
Concepto de obligación: Para Manuel Camarra Pereda es “La relación jurídica que se crea en
tre dos o más personas, en virtud de la cual uno de los sujetos, tiene la facultad de exigir al otro
una prestación determinada”4
Colin y Capitant, consideran a la obligación como “una necesidad jurídica por efecto de la cual
una persona está sujeta respecto de otra a una prestación positiva o negativa, es decir a un
hecho o a una abstención”5.
Según Ciorgi, “la mejor definición que puede ofrecerse es denominarla vínculo jurídico entre
dos o más personas determinadas, en virtud de la cual, una o varias de ellas (deudor o deudo
res) a hacer o no hacer alguna cosa”6.
De todo esto podemos colegir que la obligación es el vínculo que se crea entre dos o más per
sonas y por la cual una o unas pueden exigir a la otra u otras una determinada prestación
positiva o negativa.
Elementos de la obligación: Son los factores indispensables que se requieren para el naci
miento de una obligación válida. Los elementos de la obligación son de dos clases: intrínsecos
y extrínsecos.
4 GAM ARRA PEREDA, Manuel. El Derecho de Obligaciones en el Código Civil Peruano. Editorial Boiivariana. Trujitlo-
Perú.1969. p. 11.
5 COLIN, Ambroise y CAPITANT, Henri. Curso Elemental de Derecho Civil. Instituto Editorial Reus. Madrid 1955.
6 CIORGI, Giorgio. Teoría de la Obligaciones en el Derecho Moderno. Volumen I. Imprenta de la Revista de la
Legislación. Madrid. 1909. p. 11.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 391 of 1506 --

Tema 2: Temas de derecho civil
I.- Elementos intrínsecos: Son aquellos elementos esenciales o de fondo que no pueden fal
taren la obligación, tales como: los sujetos, el objetoy el vínculo jurídico, de modo tal que
si alguno de estos faltare, la obligación resultaría nula.
a. - Los sujetos.- Son las personas que intervienen en la obligación. Están constituidos
por el sujeto o sujetos activos de la obligación denominados también acreedor o
acreedores que son los titulares de la obligación los que tienen derecho a exigir la
prestación y el sujeto o sujetos pasivos de la obligación denominado también deu
dor o deudores que son la persona o personas sobre la cual o las cuales recaer la
prestación y por tanto el deber de cumplir.
Al sujeto activo de la obligación, también se le denomina accipiens, credendi, sujeto
creditoriy al sujeto pasivo de la obligación solvens, sujeto debitori o reas debendi.
Ahora bien, los sujetos de la obligación pueden ser personas naturales o jurídicas.
Estas últimas a su vez pueden estar constituidas por personas jurídicas de derecho
público o personas jurídicas de derecho privado.
El único requisito para que las personas tanto naturales como jurídicas puedan o bli
garse es el que gocen de capacidad.
b. - El objeto de la obligación.- Está constituido por la prestación en sí. Es todo acto hu
mano que puede consistir en entregar un bien, hacer o dejar de hacer algo. A decir
de Gustavo Palacios Pimentel en su obra citada “la prestación es el contenido de la
obligación. En sí es una actividad del deudor en provecho del acreedor o de terceros
que por lo general se traduce en una ventaja de económica’7.
La prestación puede revestir las formas de dar (daré), un hacer (facere) o un no hacer
(nom facer).
Como se puede apreciar la prestación, es la conducta, el comportamiento positivo
o negativo que habrá de observar el deudor, frente al acreedor hasta satisfacer, su
crédito o lo debido.
En cuanto al objeto de la obligación éste debe reunir los siguientes requisitos de
acuerdo a ley, afín deque la obligación sea válida. Estos son:
a) Debe ser física y jurídicamente posible.- Es decir, ser una realidad de lo contra
rio estaríamos frente a una Imposibilim nulla obligatio est. La imposibilidad debe
ser anterior a la prestación, de lo contrario se estaría frente a un riesgo de la pres
tación.
b) Debe ser lícita.- Esto es no atentar contra la moral, las buenas costumbres
c) Debe ser determinado o determinable.- En virtud de los cual, la cosa es concre
ta, definida e individualizada.
d) Debe ser útil.- Es decir, que la prestación debe tener un contenido patrimonial
que debe valorarse en dinero (ya que la obligación se ubica en la esfera de los
derechos patrimoniales).
7 PALACIOS PIMENTEL, Gustavo. Elementos de Derecho Civil Peruano. Tipografía SESATOR. Lima-Perú. Año 1985. p.
350.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 392 of 1506 --

UBILEX
c - Ei vínculo jurídico,- Denominado también relación jurídica o iuris vinculum como lo
denominaban los romanos, novieneasersino la ligazón que se crea entre los sujetos
de la obligación,y que determina la situación jurídica en que se encuentra cada cual,
el uno frente al otro, o en condición de acreedor o en condición de deudor.
11- Elementos extrínsecos.- Son la forma y la prueba. Y cuyo estudio no corresponde al Dere
cho de Obligaciones.
2. Clasificación de las obligaciones
1. - Por su origen: Las obligaciones según la fuente de donde emanan se clasifican en:
1.1. Obligaciones convencionales.- Son aquellas que nacen de la voluntad de las partes
y tienen su origen en la voluntad de las partes. Resultan de la concurrencia de volun
tades de los celebrantes de un acto jurídico.
1.2. Obligaciones legales.- Tienen suorigen en la ley y escapan de la voluntad de las partes.
Han sido creadas por mandato de la ley. Por ejemplo la obligación de indemnizar por
los dañosy perjuicios irrogados, en caso de responsabilidad extracontractual derivada
de un accidente de tránsito o la de pagar tri butos.
2. - Por el número de sujetos:
2.1. Obligaciones únicas o singulares.- Son aquellas en las que intervienen un solo
acreedor frente a un solo deudor, no interesando para el caso que se trate de perso
nas naturales o personas jurídicas, o que éstas sean de derecho público o de derecho
privado.
2.2. Obligaciones múltiples o plurales.- Son aquellas en las que concurren una plura
lidad de acreedores o de deudores. Esto es “varios deudores frente a un acreedor o
varios acreedores frente a un deudor o varios acreedores frente a varios deudores”8.
Estas obligaciones pueden revestir como se puede apreciar tres modalidades: una
pluralidad pasiva en el primer caso descrito, pluralidad activa en el segundoy plura
lidad plena o mixta en el tercer caso.
De acuerdo con pluralidad o m ultiplicidad de los sujetos ¡ntervinientes en la obli
gación o relación obligacional, las obligaciones se clasifican en: Mancomunadas, y
solidarias.
2.2.1. Obligaciones mancomunadas.- Son obligaciones en las cuales la prestación
puede ser cumplida o satisfecha en forma parcial por cada uno de los deudoresy
exigida por cada uno de los acreedores en lo que se refiere únicamente a su parte
en la obligación, de forma tal que si un deudor paga lo suyo se libera él; pero no
libera a sus demás a codeudores y de igual modo si un coacreedor mancomu
nado cobra la parte que le corresponde en el crédito la obligación del deudor de
quien obtuvo el pago se extingue para con él; pero no se extingue para con sus
demás coacreedores con quienes sigue obligado si la mancomunidad es activa.
8 VILLAR ÑAÑEZ, Hugo. Manual de Obligaciones Civiles. Ediciones Instituto de Derecho Civil “José León
Barandiarán” Lima-Perú. 2000. p. 29.
