c) Pluralidad de vínculos jurídicos.- En c u a n t o h a y u n a s o la o b lig a c ió n , pero
u n a re la c ió n c o n t o d o s lo s d e u d o r e s .
Una misma obligación puede estará constituida con modalidades distinta con
respecto a los coacreedores o codeudores, pero ello no afecta a la solidaridad. El
Art. 1184 del C.C. prescribe que la solidaridad no se excluye por la circunstancia
de que cada uno de los deudores esté obligado con modalidades diferentes ante
el acreedor, o de que el deudor común se encuentre obligado con modalidades
distintas con los acreedores, sin embargo, tratándose de condiciones o plazos
suspensivos no podrá exigirse el cumplim iento de la obligación afectada por
ellas, hasta que se cumpla la condición o venza el plazo.
