A c e rc a d e la m o ra en los caso s d e s o lid a r id a d p a siv a, c u a n d o p o r c u lp a d e u n o d e los
c o d e u d o re s s o lid a rio s , los d e m á s se ve n im p e d id o s d e c u m p lir con la p re sta c ió n , las
le g is la c io n e s e x tra n je ra s h an re su e lto la c u e s tió n d e a c u e rd o a tres crite rio s:
a) Teoría francesa -T e n ie n d o e n c u e n t a el v a lo r d e la c o s a d e b id a y los d a ñ o s
y p e r ju ic io s s e ñ a la n q u e el d e u d o r c u lp a b le r e s p o n d e d e e ste ú lt im o y los
o tro s c o d e u d o r e s s ó lo d e l v a lo r d e la c o s a d e b id a .
b) Teoría italiana.- R e s p o n s a b iliz a p o r la c u lp a d e u n o d e los d e u d o r e s a los
d e m á s , q u e re s p o n d e n p o r el v a lo r d e la c o s a y p o r lo s d a ñ o s y p e r ju ic io s .
c) Teoría alemana.- R e s p o n s a b iliz a p o r el v a lo r d e la c o s a y lo s d a ñ o s y p e r
ju ic io s a l d e u d o r c u lp a b le d e la m o r a , q u e d a n d o lo s d e m á s lib r e s d e t o d a
r e s p o n s a b ilid a d .
En c u a n t o se re fie re a lo s e fe c to s d e la s o b lig a c io n e s s o lid a r ia s , es p re c is o e s t a
b le c e r lo s ig u ie n t e :
a) El p a g o r e a liz a d o p o r u n o d e lo s c o d e u d o r e s s o lid a r io s , e x t in g u e la o b li
g a c ió n d e lo s d e m á s c o d e u d o r e s p a r a c o n el a c r e e d o r, p e ro e n t r e e s to s se
c re a n r e la c io n e s in t e r n a s .
b) El in c u m p lim ie n t o d e la o b lig a c ió n s o lid a r ia p o r c a u s a d e u n o d e los d e u d o
res o v a r io s d e é sto s, no lib e r a a lo s d e m á s d e la o b lig a c ió n d e p a g a r el v a lo r
d e la p r e s t a c ió n d e b id a ( in - s o l id u m ) , p e ro lo s d a ñ o s y p e r ju ic io s s ó lo so n
r e s p o n s a b ilid a d d e l d e u d o r o d e u d o r e s r e s p o n s a b le s d e l in c u m p lim ie n t o
t e o r ía f r a n c e s a (A rt. 11 9 5 C .C .).
c) En las obligaciones solidarias los actos mediante los cuales el acreedor in
terrumpe la prescripción contra uno de los deudores solidarios o uno de los
acreedores solidarios interrumpe la prescripción contra el deudor común,
interrumpe también para los demás. (Art. 1196 C.C.).
d) La s u s p e n s ió n o p e r a d a re s p e c to d e u n o d e lo s c o d e u d o r e s o a c r e e d o r e s
s o lid a r io s , s ó lo le a fe c ta a a q u e l m a s n o a s í a lo s d e m á s (A rt. 1 1 9 7 C .C ) .P o r
e je m p lo q u e u n o d e lo s c o d e u d o r e s d e v e n g a e n in c a p a z .
e) De igual manera la renuncia a la prescripción de los codeudores solidarios,
no afecta a los demás, no pudiendo por tanto aquel repetir contra los de
más codeudores y así mismo la renuncia a favor de uno de los acreedores
solidarios, favorece a los demás acreedores (Art. 1198 C.C.)
f) El r e c o n o c im ie n t o d e la d e u d a r e a liz a d o p o r p a rte d e u n o d e lo s c o d e u d o
res s o lid a r io s n o a fe c ta a lo s d e m á s c o d e u d o r e s , p e ro s í lo p r a c t ic a re s p e c to
a lo s a c r e e d o r e s s o lid a r io s , fa v o re c e a lo s d e m á s (Art. 1 1 9 9 C .C .)
