-- 396 of 1506 --

g) Si u n a c r e e d o r r e n u n c ia a la s o lid a r id a d c o n re s p e c to a la s o lid a r id a d a fa v o r
d e u n o d e lo s d e u d o r e s , es d e c ir le d a p o r c a n c e la d a la p a rte q u e le c o rre s
p o n d e d e t o d a s m a n e r a s c o n s e r v a la s o lid a r id a d c o n re s p e c to a lo s d e m á s
c o d e u d o r e s (A rt. i z o i C .C .).
h) La novación, compensación, condonación, y la transacción entre el deudory
uno de los acreedores solidarios sobre la totalidad de la obligación. En estos
casos las relaciones que se dan entre el deudor que practicó tales actos y sus
codeudores, se rige por las siguientes reglas:
• En la Novación.- Los codeudores responden a su elección, por su parte
en la obligación primitiva o por la proporción que les habría correspon
dido en la nueva obligación.
• En la Compensación.- Los codeudores responden por su parte.
• En la Condonación.- S e e x t in g u e la o b lig a c ió n p a ra t o d o s lo s d e m á s c o
d e u d o r e s .
• En la Transacción.- Los c o d e u d o r e s r e s p o n d e n a s u e le c c ió n p o r s u p a r
t e e n la o b lig a c ió n o r ig in a l o p o r a q u e lla q u e les h u b ie r a c o r r e s p o n d id o
en la n u e v a o b lig a c ió n .
i) La c o n s o lid a c ió n p r o d u c id a e n u n o d e lo s c o d e u d o r e s o c o a c r e e d o r e s , s ó lo
s u rte e fe c to c o n re s p e c to a l c o d e u d o r o c o a c r e e d o r p a r a q u ie n se d a m a s no
p a ra lo s d e m á s , p o r t r a ta r s e d e u n a s it u a c ió n p e r s o n a l y p o r t a n t o la s o lid a
r id a d se d a s ó lo e n lo q u e c o n c ie r n e a s u p a rte , m a s n o e n lo q u e re s p e c ta
a lo s d e m á s c o d e u d o r e s o c o a c r e e d o r e s , é s ta t ie n e u n c a r á c t e r s u b je t iv o y
s ó lo se p u e d e h a c e r v a le r c o m o u n a e x c e p c ió n p e r s o n a l (A rt. 11 9 1 C .C .).
j) La o b lig a c ió n s o lid a r ia se d iv id e in t e r n a m e n t e e n tre lo s d iv e r s o s d e u d o r e s
y a c r e e d o re s , s a lv o q u e h a y a s id o c o n t r a íd a e n in te ré s e x c lu s iv o d e a lg ú n d e
e llo s . La p r o p o r c ió n d e c a d a u n o d e lo s d e u d o r e s , o e n s u c a s o d e lo s a c r e e
d o r e s se p r e s u m e n ig u a le s , s a lv o q u e lo c o n t r a r io re s u lte d e la ley, el t ít u lo
d e la o b lig a c ió n o la s c ir c u n s t a n c ia s d e l c a so . (A rt. 11 9 3 C .C .).
k) Si alguno de los codeudores es insolvente su porción se distribuye en por
ciones iguales entre los demás de acuerdo con sus intereses en la obliga
ción. (Art. 1204 C.C).
3. Por el objeto: De acuerdo con el objeto las obligaciones se clasifican:
3 .1 . Por la forma de su ejecución.- En positivas y negativas.
3.1.1. Obligaciones positivas.-Son aquellas en las que el deudor se obliga a realizar
una determinada actividad de dar o hacer en beneficio del acreedor. Según el
Dr. Romero Zavala “Las obligaciones positivas que consisten en una acción del
deudor. La acción del deudor radica en una de dar o de hacer.”9
9 ROMERO ZAVALA, Luis. El Derecho de las Obligaciones en el Perú. Editora Fecati999- Lima-Perú. p. 49.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 397 of 1506 --

Tema2: lem as de derecho civil
3.1.2, Obligaciones negativas.- Son aquellas que imponen al deudor una absten
ción e impiden una actividad y por tanto el deudor se obliga a dejar de hacer, a
abstenerse de dar o hacer algo siempre para beneficio del deudor. Son las o bli
gaciones de omisión. Ejemplo. Abstenerse de poner el mismo negocio que otro,
realizar el mismo programa televisivo para otro canal de la competencia.
3.2. Por la naturaleza de la prestación.- Las o b lig a c io n e s p u e d e n s e r d e dar, d e h a c e r y d e
n o h acer.
3.2.1. Obligaciones de dar.- Son obligaciones positivas, en virtud de las cuales el deu
dor se obliga se obliga a transferir a favor del acreedor la propiedad, el uso, la
tenencia, o posesión de algún bien, o la restitución de alguna cosa.
Las o b lig a c io n e s d e d a r t ie n e n u n g ra n c a m p o d e a c c ió n , a b a r c a t o d a c la s e d e
o b je t o s o c o s a s y to d a s la s m o d a lid a d e s d e d e r e c h o s s o b re e lla s .
Las o b lig a c io n e s d e d a r re q u ie r e n :
a) Q u e la c o s a o b ie n p e r te n e z c a a l d e u d o r ., p u e s es r e g la g e n e r a l q u e q u ie n
t ie n e la p r o p ie d a d d e u n a c o s a , p u e d e t r a n s f e r ir la a o t r a p e r s o n a .
b) Que la cosa materia de la obligación sea determinada o determinable, es
decir que esté señalada por sus caracteres individuales.
c) Q u e se t r a n s f ie r a la p r o p ie d a d d e l b ie n , c u a n d o la o b lig a c ió n se re fie re al
d e r e c h o d e d o m in io s o b re el o b je to .
Las obligaciones de dar a su vez se subdividen en: obligaciones de dar bien
ciertoy obligaciones de dar bien incierto.
3-2.1.1. Obi igaciones de dar bien cierto.- Denominadas en Roma obligatiospeciei, son
aquellas en virtud de las cuales el deudor se obligaatransferir un bien determ i
nado por sus caracteres particulares que lo singularizan, que lo determinan, de
tal manera que resulta inconfundible (Art. 1132C.C)
El o b lig a d o a d a r u n b ie n c ie r to t ie n e lo s s ig u ie n t e s d e b e r e s s e g ú n ley.
a) Entregar el bien y no otro en el lugar, modo y tiempo oportuno (Art. 1132
C .C ).
b) Conservar el bien hasta su entrega (Art. 1134 C.C).
c) Entregar el bien con todos sus accesorios, salvo que lo contrario resulte de la
ley, del título de la obligación o de las circunstancias del caso (Art. 1134 del
C.C.).
d) Informar sobre el estado del bien cuando lo solicite el acreedor quien tiene
legítimo derecho de conocer el estado en que se encuentra la prestación,
hasta el día en que el deudor cumpla con la obligación (Art. 1133 del C.C.).
3.2.1.2. Obligaciones de dar bienes inciertos.- Son las denominadas obligaciones ge
néricas u Obllgatiogenens como las denominaron los romanosy que se dan cuando
el objeto de la obligación que debe cumplir el deudor está señalado por sus carac
teres generales de especie y cantidad (Art. 1142 C.C.). Ejemplo. Cuando alguien se
obliga a entregar un carro, sólo por su especie sabemos que se trata de un carro y
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 398 of 1506 --

no de mueble y por su cantidad que es uno y no dos, pero desconocemos porque
no se ha especificado en la obligación si se trata de un automóvil o de una camio
neta, de qué marca, año de fabricación, número de motor, color, etc. que en todo
caso de ser asíya estaríamos frente a una obligación de dar bien cierto.
De acuerdo con el Art. 1143 del C.C. vigente la elección del bien corresponde al
deudor en las obligaciones genéricas, salvo que lo contrario resulte de la ley, el
título de la obligación o de las circunstancias del caso.
Cabe señalar sin embargo, que si bien es cierto que el deudor en esta clase de
obligaciones tiene más libertad para escoger el objeto con el que se libere del
acreedor, también es verdad que le afecta la extinción del bien con el principio
delgenus nuncuam perit (el género nunca perece).
Este mismo artículo en comentario prevé en la elección del bien las siguientes
reglas:
a) .- Cuando la elección corresponde al deudor, éste debe escoger bienes de ca
lidad no inferiora la media.
b) .- Cuando la elección corresponde al acreedor, éste de escoger bienes de cali
dad no superior a la media.
c) .- Si la elección corresponde a un tercero, éste debe escoger bienes de calidad
media.
Todo lo cual quiere decir que sea cual fuere el sujeto llamado a elegir, deberá
hacerlo ciñéndose a la buena fey a la equidad, unoy otro deberán pronunciarse
por una cosa de calidad media.
En cuanto al plazo para la elección se entiende que la elección del bien debe rea
lizarse dentro del plazo o término señalado para el cumplim iento de la obliga
ción, sin embargo, puede ocurrir que no se haya señalado plazo para la elección,
en tal caso corresponde al juez fijarlo. De igual manera si el deudor omite efec
tuar la elección dentro del plazo establecido o fijado por el juez, ésta le corres
ponde al acreedor. Dicha regla se aplica al acreedor cuando a éste le corresponde
practicar la elección. Si la elección se confía a un tercero y éste no la efectúa debe
hacerla el juez, sin perjuicio del derecho que les asiste a las partes de exigir el
pago a dicho tercero de una indemnización por su incumplimiento.
Realizada la elección del bien, ésta surte los siguientes efectos:
1. La elección es irrevocable una vez ejecutada la prestación (Art. 1145 C.C.)
2. La elección practicada por un tercero o por el juez, una vez comunicada a
una o a ambas partes surte el mismo efecto.
3. Antes de la individualización, es decir de la elección no puede el deudor
eximirse de la entrega, invocando la pérdida sin culpa. (Art. 1146 C.C.).
4. Cuando la elección debe efectuarse sobre varios bienes determinados, de la
misma especiey todos ellos se pierden sin culpa del deudor, no se aplica la
regla anterior, es decir se exime al deudor de su entrega. (Art. 1146 C.C.).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 399 of 1506 --

Tema 2: Temas de derecho civil
5 . Una vez practicada la elección de bienes inciertos, se aplica las reglas esta
blecidas sobre obligaciones de dar bienes ciertos.
3.2.2.-Obligaciones de hacer.-Son obligaciones positivas y en virtud de las cuales el
deudor se obliga a hacer una obra, prestar un servicio. Ejemplo: Hacer un juego
de confortables, tejer un mantel, pintar una casa, defender como abogado una
causa.
Son características de las obligaciones de hacer: el plazoy el modo convenidos, así
lo prescribe nuestro Código Civil.
a) El Modo.- No viene a ser sino la forma cómo debe cumplirse la obligación.
En efecto el modo como se realiza la obligación de hacer es fundamental
en este tipo de obligaciones. Ejemplo: Si se mando a construir un puente
de fierro, no se tendrá por hecho si lo hacen de madera y de forma distinta
a la convenida, se tendrá por no hechoy por tanto no podrá exigir la contra
prestación o podrá destruirse lo que fue mal ejecutado.
b) El Plazo.- Es el tiempo o término en que debe realizarse la prestación pro
metida. El plazo a su vez puede ser de varias clases:
• Plazo Convencional.- Es el fijado por las partes de común acuerdo.
• Plazo Legal.- Es el señalado por la ley.
• Plazo Judicial.-Cuando el juez lo fija teniendo en cuenta la naturaleza
de la prestación, o las circunstancias del caso, a falta de plazo fijado por
las partes. (Art. 1148 C.C.).
De otro lado también, si el hecho convenido padece de defectos de otra índole,
se impondrá al deudorel pago de dañosy perjuicios o una disminución pruden
cial del precio estipulado y los gastos que el acreedor efectúe en la destrucción
de la cosa o prestación mal ejecutada serán de cuenta del deudor.
En la ejecución de las obligaciones de hacer debemos tener en cuenta que éstas
pueden ser ejecutadas:
a) Por el mismo deudor, dadas sus cualidades in tu ito personae, cuando se trata
de obligaciones personalísimas.
b) Por persona distinta al deudor, es decir por un tercero.
El incumplimiento de las obligaciones de hacer puede ser total o parcial, y pue
de darse por culpa del deudor, por culpa del acreedory sin culpa de las partes.
Veamos:
1.- Incumplimiento total de las obligaciones de hacen por culpa del deudor (Art. 1750
del C.C.).- En caso de incumplimiento de este tipo de obligaciones por culpa
del deudor se deberán tener en cuenta las siguientes medidas:
a) Exigir la ejecución forzada del hecho prometido, a no ser que sea nece
sario para ello recurrirá la violencia contra la persona del deudor. Claro
estáqueen estos casos hayque teneren cuenta que cuando hablamos
de violencia sobre la persona del deudor no nos estamos refiriendo
