5 . - Prestación imposible por culpa del acreedor-En estos casos de conformidad con
el Art. 1155 del C.C.
a) La obligación queda resuelta.
b) El acreedor conserva el derecho a la contraprestación si la hubiere.
Ig u a l re g la se a p lic a d ic e la n o r m a c u a n d o e l c u m p lim ie n t o d e la o b lig a c ió n
