6 . - Imposibilidad de la prestación sin culpa de las partes (Art. 1156 C .C.).-Se t e n d r á n
en cuenta las siguientes medidas:
a) Laobligación queda resuelta.
b) El deudor deberá devolver al acreedor lo que hubiere recibido, corres
pondiéndole los derechos y obligaciones que hubieren quedado rela
tivas a la obligación no cumplida.
3.2.3. Obligaciones de no hacer.- Las obligaciones de no hacer pueden revestir dos
modalidades: una simple abstención u omisión de hacery la otra un tolerar que
el acreedor haga algo sin oponerse ni poner obstáculos al hacer del acreedor.
En cuanto se refiere a las obligaciones de no hacer su inejecución faculta al
acreedor a tom ar las siguientes medidas, de conformidad con el Art. 1158 del
C.C.,yaseaqueel deudor u obligado obre con culpa o dolo. Estas son:
1 - Exigir la ejecución forzada de la obligación a no ser que sea necesario em
plear la violencia sobre la persona del deudor.
2.- Exigir la ejecución de lo ejecutado o destruirlo por cuenta del deudor. Ejem
plo: Mandar destruir la pared que se comprometió a no levantar.
3 - Dejar sin efecto la obligación.
En todos estos casos le cabe al acreedor el derecho de exigir el pago de la corres
pondiente indemnización por los dañosy perjuicios irrogados (Art. 1159 del C.C)
De igual manera el artículo 1160 del C.C. prevé que son aplicables a las obliga
ciones de no hacer las disposiciones de artículo 1154 del C.C (primer parágrafo, es
decir, si resulta imposible de cum plir por el deudor la obligación, ésta se resuelve
y el acreedor deja de estar obligado a la contraprestación si la hubiere), sin per
juicio de exigir el derecho al pago de la indemnización que corresponda.
Así mismo los artículos 1155 C.C (cuando la imposibilidad es por culpa del acree
dor) y el 1156 C.C.(cuando la imposibilidad es sin culpa de las partes) y cuando
como consecuencia de la inejecución por culpa del deudor éste obtiene una in
demnización o derecho contra un tercero.
