3 3 - Por la índole de su contenido: Las obligaciones pueden ser de dos clases:
33.1. Obligaciones de medios. Son aquellas que permiten o facilitan el cumplim ien
to de una prestación, expresadas fundamentalmente en acciones u omisiones.
33 2. Obligaciones de resultados Son aquellas cuya prestación constituyen en sí el
producto final que se manifiesta generalmente en bienes o cosas.
3.4. Por el número de prestaciones:
3.4.1. Obligaciones simples. Son aquellas en las cuales el objeto de la obligación re
cae sobre una sola prestación expresada en un solo bien, acción u omisión.
3.4.2. Obligaciones compuestas. Son aquellas en las cuales el objeto de la obliga
ción recae sobre varias prestaciones. Estas a su vez se subdividen en obligaciones
conjuntivas y disyuntivas.
3.4 - 2.1. Obligaciones conjuntivas. Denominadas también conjuntas, son aquellas
en las cuales el objeto de la obligación recae sobre varias prestaciones que el
deudor está obligado a cumplir. "En las obligaciones conjuntas todas las presta
ciones son debidas y tienen que ser ejecutadas o cumplidas la nulidad o impo
sibilidad de cualquiera de el las no lo libera al deudordecum plircon las demás”.
3.4- 2.2. Obligaciones disyuntivas. Son aquellas en las cuales el objeto de la obliga
ción recae sobre varias prestaciones, pero el deudor solo está obligado a realizar
una de ellas para satisfacer su crédito u obligación.
Las o b lig a c io n e s d is y u n t iv a s a s u v e z se c la s if ic a n e n a lt e r n a t iv a s y f a c u lt a t iv a s .
3.4.2.2.1 Obligaciones alternativas. Son aquellas en las que el deudor se obliga a
cumplir una de las dos o más prestaciones sobre las cuales recae el objeto de
la obligación. Es decir, son aquellas que tienen dos o más prestaciones ¡n obliga-
tione; pero solo una se entrega o se cumple insolutione. Ejemplo: Luis promete a
Jaime un carro o departamento para saldar la deuda que le tiene, si entrega uno
solo de los objetos citados se tendrá por cumplida la obligación.
En las obligaciones alternativas prima el criterio romano dua vessm t in obligatio-
nessed una in solutione.
La alternatividad puede recaer sobre diversas modalidades de una misma pres
tación. Así sucederá si se conviene en que el deudor A entregará el automóvil To
yota Yarls en la ciudad de Lima en el concesionario de la Av. Canadá (La Victoria)
o Av. República de Panamá (Surquillo) o que dicho carro se entregará en 2023 ó
2024. Se trata en estos casos de circunstancias de lugar, tiempo y modo.
En cuanto a la naturaleza de las obligaciones alternativas el estudio de esta clase
de obligaciones a dado lugar a discusiones serias y profundas entre los juristas
así para unos doctrinarios en la obligación alternativa existe un solo vínculo ju
rídico o sea una sola relación jurídica con objeto m últiple y para otros que en las
obligaciones alternativas hay una pluralidad de obligaciones, hay tantas obli
gaciones como prestaciones existan, solo que las demás quedan supeditadas a
la elección de una sola de ellas. De ahí que mucho se discute si se deben llamar
