En este tipo de obligaciones la elección siempre le corresponde al deudor.
En las obligaciones facultativas la obligación principal está in obligatione, y la
accesoria in facúltatesolutione. Ejemplo: El caso de la obligación de entregar un
fundo con la facultad acordada al deudor de liberarse de la obligación mediante
el pago de $ 100,000 dólares americanos.
La obligación facultativa se extingue cuando la prestación principal resulta nula
o imposibledecumplir. De igual manera laobligación facultativa se convierte en
simple cuando la prestación accesoria resulta nula e imposible de cumplir (Art.
1170 del C.C).
D if e r e n c ia s e n t r e la s o b lig a c io n e s a lt e r n a t iv a s c o m o f a c u lt a t iv a s :
OBLIGACIONES ALTERNATIVAS
Pluralidad de objetos y una sola obligación.
Hay derecho de elección por parte del deudor,
acreedor y un tercero.
Si desaparece un objeto de la prestación que
dan los oíros.
La indeterminación es mayor.
Los objetos de la prestación que se hacen impo
sible por caso fortuito no extinguen la obligación.
Solo hay un objeto.
Solo hay elección por parte del deudor.
Se debe un solo objeto de la prestación que es
principal, pudiendo el deudor sólo sustituirlo
por otro accesorio en el momento del pago.
La indeterminación es mínima.
Si se produce la pérdida de la prestación princi
pal por caso fortuito se extingue la obligación.
Cuando hay duda si la obligación es alternativa o facultativa, se debe tener por facultativa, de acuerdo
con el Art. 1171 del C.C., por ser la menos gravosa para el deudor. Esta posición adoptada por nuestro
país difiere de la adoptada por otras legislaciones como la Argentina, Chilena, Colombiana y Urugua
ya, para quienes la obligación se considera alternativa.
3.5 Por el tiempo de su cumplimiento:
3.5.1. Obligaciones de ejecución inmediata o instantánea.- Cuando las obligaciones
se ejecutan inmediatamente de ser contraídas. Son exigibles desde el momento
mismo en que la obligación queda válidamente estableciday no admite poster
gación alguna.
3.5.2. Obligaciones de ejecución diferida.- Son aquellas que no se ejecutan luego de
adquirida la obligación, sino que su ejecución queda sujeta a cumplirse poste
riormente después de un determinado plazo o período de tiempo.
3.5 3. Obligaciones de ejecución permanente.- Son aquellas en las cuales la pres
tación convenida tiene que cumplirse en un lapso prolongado de tiempo y que
puede darse en forma continuada sin interrupción ni intervalos de tiempo, pero
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 406 of 1506 --

UBILEX
también en forma periódica. Por tanto, estas clases de obligaciones a su vez pue
den subdividirse en: Obligaciones continuadas y periódicas.
3.5 3 .1. Obligaciones continuadas.- Denominadas también de tracto sucesivo son
aquellas que se tienen que cum plirsin intervalos de tiempo. Ejemplo: La obliga
ción que tiene una Compañía Eléctrica de proporcionar energía a un hospital de
emergencia.
3.53 2. Obligaciones periódicas. Son aquellas que deben ejecutarse en intervalos
regulares de tiempo. Ejemplo: Dictar clase de 8 a.m a 12 p.m en un colegio.
3.6. Por la naturaleza de la prestación:
3.6.1. Obligaciones divisibles. Son aquellas en las que concurren una pluralidad de
acreedores o de deudores frente a una misma obligación cuyo objeto es suscep
tible de dividirse en igual naturalezay calidad, sin que se altere su valor.
Para que se produzca esta clase de obligaciones como se puede apreciar, es me
nester que existan una pluralidad de acreedores o de deudores o de ambos, es
decir, para que haya divisibilidad se precisan que sean dos o más los acreedores
o los deudores, esto es, que hay dos clases de divisibilidad: activa y pasiva e inclu
so m ixta cuando existe una pluralidad de deudores y acreedores a la vez.
La pluralidad de los sujetos en la obligación debe estar relacionada o vinculada
con la naturaleza del objeto de la obligación, si se relaciona con la voluntad de los
contratantes aparecerá otra modalidad: obligaciones mancomunadas y solidarias.
El artículoii72 C.C. prevé que cuando son varios los acreedores o los deudores de una
prestación divisible y la obligación no es solidaria cada uno de los acreedores sólo
puede pedir la satisfacción de la parte del crédito que le corresponda mientras que
cada uno de los deudores únicamente está obligado a su parte en la deuda.
Por otro lado en las obligaciones divisibles el crédito o la deuda se presumen
divididos en tantas partes iguales como acreedores o deudores existan respe
tándose créditos o derechos distintos e independientes unos de otros, salvo que
resulte lo contrario del título de la obligación o de las circunstancias del caso
(Art. 1173 del C.C).
Acorde con el artículo 1174 del C.C la divisibilidad no puede ser opuesta, es decir,
interpuesta:
• Por el heredero del deudor encargado de cumplir con la prestación.
• Por quien se encuentra en posesión de la cosa debida.
• Por quien adquiere el bien que garantiza la obligación.
3.6.2. Obligaciones indivisibles.- Son aquellas en las que concurren una plura
lidad de acreedores o deudores frente a una misma prestación que dada su
naturaleza es imposible de dividirse o fraccionarse en partes, es decir, de cum
plirse parcialmente, ya sea por mandato expreso de la ley, por la naturaleza
de la prestación o por el modo en que fue considerada al constituirse dicha
obligación.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 407 of 1506 --

Tema 2: Temas de derecho civil
Para el doctor Felipe Osterling Parodi “la obligación es indivisible cuando la pres
tación no puede cumplirse en forma parcial porque así lo deciden su naturaleza,
el pacto o la ley”10.
Ejemplo: A-B-C reciben una vaca en herenciay la venden a X por 500 dólares
americanos. En este caso X puede reclamar a cualquiera de los tres deudores
que cumpla con entregarle la vaca, no pretenderán entregársela por partes, pues
la naturaleza misma del bien sobre el cual recae la prestación no lo permite.
En las obligaciones indivisibles cualesquiera de los acreedores pueden exigirá
cualquiera de los deudores la ejecución de la obligación indivisible, dada la cir
cunstancia de que el acreedor no puede demandar partes de lo que es natural
e intrínsecamente indivisible. El deudor queda liberado si paga conjuntamente
a todos los acreedores o a alguno de ellos el íntegro de la obligación, siemprey
cuando dicho acreedor garantice a los demás el reembolso de dicha obligación.
Para Pothier refiriéndose a las obligaciones indivisibles se dice “Pues no se puede
pagar por partes lo que no es susceptible de partes”11. Lo cual en buena cuenta
quiere decir que el acreedor no puede demandar partes de lo que es natural e
Intrínsecamente indivisible.
La indivisibilidad opera de acuerdo con el artículo 1177 del C.C en los siguientes
casos:
• Respecto a los herederos del acreedor que por el título de tales pueden co
brar el crédito existente a favor de su causante.
• Respecto a los herederos del deudor, que tampoco pueden pretender que la
obligación se dividida para hacer cumplida por el número de herederos que
existan.
En las obligaciones solidarias de acuerdo con el a rtic u ló la s del C.C la consolida
ción entre el acreedory uno de los deudores no extingue la obligación respecto a
los demás codeudores, el acreedor sin embargo sólo puede exigir la prestación
reembolsando a los codeudores el valor de la parte que les correspondió en la
obligación o garantizando el reembolso.
En las en las obligaciones indivisibles debe tenerse en cuenta que producida la
novación entre el deudory uno de los acreedores, no extingue la obligación res
pecto de los demás coacreedores (se entiende con los cuales no ha novado). Sin
embargo, dichos acreedores no pueden exigir la prestación indivisible, sino es
reembolsando al deudor el valor de la parte de la prestación original correspon
diente al acreedor que novó o garantizando el reembolso.
En las en las obligaciones indivisibles debe tenerse en cuenta que producida la
novación entre el deudory uno de los acreedores, no extingue la obligación res
pecto de los demás coacreedores (se entiende con los cuales no ha novado). Sin
10 OSTERLING PARODI, Felipe. Las Obligaciones. Fondo Editorial de la PUCP. Lima-Perú. 1987.
11 POTHIER, R.J. Tratado de las Obligaciones. Editorial Bibliográfica Argentina. Buenos Aires-Argentina. 1971. p.176.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 408 of 1506 --

UBILEX
embargo, dichos acreedores no pueden exigir la prestación indivisible, sino es
reembolsando al deudor el valor de la parte de la prestación original correspon
diente al acreedor que novó o garantizando el reembolso.
Esta misma regla es de aplicación en los casos de compensación, condonación,
consolidación y transacción.
La obligación indivisible se resuelve en la indemnizar los daños y perjuicios. De
acuerdo con el artículo 1180 del C.C cada uno de los deudores queda obligado
porel íntegro de la indemnización salvo aquellos deudores que hubiesen estado
dispuestos a cumplir, quienes sólo contribuirán a la indemnización con la por
ción del valor de la prestación que les corresponda.
Entre las obligaciones solidarias e indivisibles existen notables diferencias, aun
cuando en ambas cada uno de los codeudores esté obligado a cumplir con el
íntegro y los coacreedores facultados para exigir la totalidad de la prestación
convenida. Estas son:
• La indivisibilidad depende de la naturaleza de la prestación, de la imposibi
lidad material de cumplir parcialmente; en cambio, la solidaridad se funda
en el título de la prestación.
• La indivisibilidad tiene carácter Subjetivo-objetivo, puesto que, si bien es
cierto recae sobre las personas, depende o resulta su indivisibilidad de la
prestación que no se puede dividir; en cambio la solidaridad recae sobre las
personas como causa de la obligación, es decir, la solidaridad es eminente
mente subjetiva.
• La indivisibilidad se transmite a los herederos del acreedor y deudor; la so
lidaridad no se transmite a los herederos del deudor que fallece, se divide
entre los herederos en las proporciones respectivas.
• En las obligaciones indivisibles ningún acreedores dueño único del crédito
y es más bien la ley la que lo autoriza a recibirlo en su integridad, por la
naturaleza de la prestación; en las solidarias cada acreedor es dueño del ín
tegro del crédito.
4. Por el vínculo jurídico
4.1. Obligaciones naturales o impropias.- Son aquellas que carecen de naturaleza jurídica,
están desprovistas de acción, no existen mecanismos legales capaces de hacerlas valer. Se fun
damentan en consideraciones de orden moral religioso o de las buenas costumbres. Ejemplo:
El deber de un católico de ir a misa todos los domingos y fiestas de guardar. Para el católico
esto supone una obligación; pero cuyo incumplimiento no puede ser sancionado legalmente.
Dicha persona solo se podrá sentir mal moralmente, será una falta a sus obligaciones religio
sas porque de acuerdo a su fe sabe que constituye pecado.
4.2. Obligaciones civiles o propias.- Son aquellas que están provistas de acción, es decir, de
una ACTIO, de un medio procesal reconocido por la ley para que puedan hacerse efectivas,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 409 of 1506 --

Tema 2: Temas de derecho civil
facultando al acreedor para que pueda exigir al deudorel cumplim iento de la obligación. Pue
den clasificarse en:
4.2.1. Obligaciones unilaterales.- Son aquellas en las cuales uno de los sujetos (personas na
turales o jurídicas, singularo plural) solo es acreedor, mientras que el otro u otros, únicamente
es deudor. Tienen este carácter por ejemplo las obligaciones que surgen de los contratos de
mutuo, comodato o depósito, así como aquellas que nacen de la comisión de un acto ilícito.
Las obligaciones unilaterales se dan cuando se trata de que es solo la persona del acreedor a
quien le corresponde el derecho de exigir la prestación y al deudorel de cumplirla.
4.2.2. Obligaciones bilaterales.- Se dan cuando ambos, acreedor y deudor a la vez tienen
que cumplir una determinada prestación. Ejemplo. En un contrato de locación-conducción o
arrendamiento de bien inmueble (casa), tanto el arrendador como el arrendatario adquieren
deberes y derechos entre sí. Así luego de suscrito el contrato el arrendador tiene el deber de
poner al arrendatario en posesión del bien para que lo use y a su vez el arrendatario tiene con
respecto al arrendador el deber de pagar mensual mente la merced conductiva pactada. Por su
parte el arrendador tiene el derecho de exigir al arrendatario el pago de la merced conductiva
mensual, en caso contrario podrá iniciarle una acción de desalojo por falta de pago y a su vez
el arrendatario en caso de que luego de suscrito el contrato el arrendador se negara a ponerle
en posesión del bien tiene el derecho de exigir la entrega de la llavey de pretender el arrenda-
dor desalojarlo del bien sin que se cumpla el plazo tiene también el derecho el arrendatario de
exigirse respete el plazo estipulado.
4.2.3. Obligaciones puras.- Son aquellas que no están sujetas a ninguna condición.
4.2.4. Obligaciones condicionadas.- Son aquellas que están sujetas a condición. Estas a su vez
pueden ser condicionadas resolutorias o condicionadas suspensivas.
5. C o ncurso de acreedo res en b ienes m u e b le s e in m u e b le s
1.- Concurrencia de acreedores en las obligaciones de dar bien cierto inmueble.- El artí
culo 1135 del C.C prescribe que cuando el bien a entregar es inmueble y concurren varios
acreedores, a quienes el mismo deudorse ha obligado a entregar un mismo bien. Se debe
tener en cuenta el siguiente orden de preferencia:
i° Se debe preferir al acreedor de buena fe cuyo título ha sido primeramente inscrito,
aparte de disponer de una escritura públicay un contrato de compraventa.
2o Se prefiere al acreedor que cuenta con una escritura públicay su respectivo contrato.
3o Se prefiere al acreedor que solamente tiene el documento privado, con fecha cierta
más antigua.
Ante la concurrencia de acreedores, en aras del principio de buena fe registral y la publicidad def dere
cho, la preferencia es al acreedor inscrito primero en Registros Públicos. ■
2.- Concurrencia de varios acreedores en las obligaciones de dar cosa cierta mueble.-
Acorde con el Art. 1136 del C.C si el bien que debe entregarse es mueble y lo reclaman
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 410 of 1506 --

diversos acreedores, a quien el mismo deudor se ha obligado, se tendrá en cuenta lo si-
guíente:
I o Será preferido el acreedor de buena fe, a quien el deudor hizo la tradición o entrega
de la cosa, aunque su título sea de fecha posterior a otros acreedores. Ejemplo: Si
Juan, propietario del bien, le vendió a Pedro una escultura, sin realizar la entrega o
tradición de la misma y, posteriormente, le vendió a Mateo la misma obra de arte
y realizó la tradición o entrega sin que él sepa de su anterior acuerdo con Pedro, la
escultura pasa a ser propiedad de Mateo, pese a que Pedro tenga un título de fecha
anterior. En razón a ello, en el presente supuesto prevalece la tradición.
2o Si el deudor no hizo la tradición del bien, será preferido el acreedor cuyo título sea
de fecha anterior prevaleciendo es este últim o caso, el título que conste de docu
mento de fecha cierta antigua. Ejemplo. Si Sandro le vendió a Héctor el derecho de
propiedad intelectual de su compañía de discos, sin haberle hecho la tradición del
mismo, él aún no es propietario por faltar la tradición. Asimismo, si Sandro le vende
el mismo derecho a Juana, teniendo esta un título con fecha posterior, el propietario
vendría a ser Héctor. Por ello, Zeus deviene en la obligación de otorgarle este bien
mueble a Hércules, quien posee título con fecha anterior. En consecuencia, en este
supuesto prevalece el título con fecha anterior.
Cabe acotar que cuando hablamos de fecha cierta, nos referimos a aquellos instru
mentos públicos y privados en los que consta la fecha de su expedición, inscripción o
de su reconocimiento.
La transferencia de bienes muebles se ampara en la circulación de bienesy la defen
sa posesoria.
La teoría del riesgo: consecuencias
1. La teoría del riesgo
Señala Osterlingy Castillo Freyre12 que “esta teoría adquiere relevancia, cuando para la ejecu
ción de la prestación deba mediar un lapso— apreciable en el tiempo— desde el momento en
que se celebró el contrato o, en general, desde el momento en que tuvo nacimiento la obliga
ción, hasta el momento en que ésta deba ejecutarse. Resulta claro que en este caso, en el inter
valo podría ocurrir una pérdida o un deterioro del bien objeto de la prestación. Concordamos
con los términos del Doctor Jorge Eugenio Castañeda, cuando señala que la teoría del riesgo
aparece en el momento en que pueda haberse perdido, o sufrido deterioros que disminuyan
su valor, la cosa debida, en el intervalo transcurrido desde que la obligación es contraída hasta
que ella debe ser cumplida, o sea hasta que la cosa debe ser entregada”.
Para Romero Zavala "Los riesgos no solamente tienen im portanciajurídicaen las obligaciones,
sino también en los contratos, como no puede ser de otra manera, porque los contratos están
íntimamente vinculados a las obligaciones; no por gusto el código peruano de 1984 denomina
12 “La pérdida en las obligaciones de dar bienes ciertos y la teoría del riesgo” en http://www.osterlingfirm.com/
Documentos/art¡culos/la_perdida_en_las_obligac¡ones_de_dar_b¡enes.pdf.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 411 of 1506 --

Tema 2: Temas de derecho civil
a los contratos, fuentes de las obligaciones. Claro está, en la doctrina contractual, la doctrina
se complica, desde que ya no se trata de cualquier riesgo, sino de un tipo especial: el riesgo
imprevisible, estudiado por la Teoría de la Imprevisión".
El artículo 1138 del C.C. contiene las reglas que establecen cuál de las partes de la relación obli-
gacional debe sufrir o correr con el riesgo de la pérdida de la contraprestación, ante la im po
sibilidad de ejecución de la propia prestación o su deterioro. El ámbito de aplicación general
del artículo 1138, al igual que del resto de normas de obligaciones de dar, corresponde a la
generalidad de las mismas y no sólo a las obligaciones de dar que impliquen transferir la pro
piedad de un bien.
En conclusión, el artículo 1138 del C.C. trata sobre la teoría del riesgo, destinada a verificar cuál
de las dos partes en la relación jurídica (el acreedor o el deudor) es quien tiene que sufrir el
riesgo por la pérdida de la contraprestación, si la hubiere, y eventualmente indemnizar por
daños y perjuicios.
2. Consecuencias de la teoría del riesgo. Reglas
La teoría del riesgo contemplada por el artículo 1138 del Código Civil, sólo es de aplicación para
el supuesto de las obligaciones de dar bienes ciertos.
Casos de pérdida o deterioro
1. Pérdida o deterioro del bien cierto a dar por culpa del deudor.
Si el bien cierto a dar se pierde por culpa del deudor (Inc. 1 A rt 1138 C.C.)
a) La obligación queda resuelta, deduciéndose esto del hecho de que resultará imposi
ble ya ejecutar la prestación.
b) El acreedor dejará de estar obligado a ejecutar su contraprestación, en el caso de
tratarse de un contrato con prestaciones recíprocas.
Ejemplo i: Pedro se obliga frente a Juan a entregarle un automóvil. La noche anterior
a su entrega, Pedro decide dar una vuelta al barrio conduciendo dicho vehículo, y al
hacerlo, sufre un accidente, causado por él mismo, ya que se produjo al haber cru
zado una calle sin observar la luz roja del semáforo. Si como consecuencia de dicho
accidente el auto se destruye totalmente (perece) o sufre tales daños que lo hagan
inútil para Juan (lo que también constituye un supuesto de perecimiento), se habrá
producido la pérdida del bien, y por lo tanto, serán de aplicación las consecuencias
previstas por el inciso 1 art. 1138 C.C.
c) El deudor queda obligado al pago de la correspondiente indemnización.
d) Si a raíz de esta pérdida el deudor obtiene alguna indemnización o adquiere un de
recho contra tercero en sustitución de la prestación debida, el acreedor puede exigir
la entrega de dicha indemnización o sustituirse en la titulación del derecho contra
ese tercero, reduciéndose en estos casos la indemnización de daños y perjuicios en
los montos correspondientes.
Ejemplo 2: Si Juan se había comprometido a entregar a Pedro como precio por el
automóvil la suma de s/16,000.00 soles, y Juan hubiese sufrido daños y perjuicios
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 412 of 1506 --

UBILEX
generados por concepto de la falta de entrega del bien por parte de Pedro, por un
monto de s/5,000 solesjuan tendría la oportunidad de hacerse cobro de esta últim a
suma del monto que la Compañía de Seguros deba pagar a Juan. En tal sentido, el
deudor solamente recibiría por concepto del siniestro la cantidad de s/11,000 soles.
Los otros s/5,000 soles corresponderían al acreedor. Serán de aplicación las conse
cuencias previstas en el zdo párrafo del inciso 1 art. 1138 C.C.
Si el bien cierto a dar se deteriora por culpa del deudor-,
a) SI el bien se deteriora por culpa del deudor, el acreedor puede optar por resolver la
obligación, o por recibir el bien en el estado en que se encuentre y exigir la reducción
de la contraprestación, si la hubiere, y el pago de la correspondiente indemnización
de dañosy perjuicios. (Inc. 2 primer párrafo Art. 1138 C.C.)
b) Si el deterioro es de escasa importancia la norma ha previsto que el acreedor puede
exigir la reducción de la contraprestación. (Inc. 2 segundo párrafo Art. 1138 C.C.)
2. Pérdida o deterioro del bien cierto a dar por culpa del acreedor.
Si el bien cierto a dar se pierde por culpa del acreedor: (Inc. 30Art. 1138 C.C)
a) La obligación queda resuelta para el deudor, pero éste conserva el derecho a la contra
prestación, si la hubiere.
b) Si como consecuencia de la resolución de la obligación, el deudor obtiene algún benefi
cio, el valor de dicho beneficio reduce la contraprestación a cargo del acreedor.
Ejemplo: El acreedor del automóvil estaba obl ¡gado a pagar la cantidad de s/ 24,000.00 so
les por el vehículo. Si por efectos de la destrucción del bien por culpa del acreedor, el deu
dor recibiese una indemnización de la Compañía de Seguros equivalente a s/ 24,000.00
soles que debía haber pagado el acreedor, de acuerdo con lo señalado por la últim a parte
del inciso tercero, el acreedorya no deberá pagar nada al deudor, pues la indemnización
de la Compañía de Seguros cubre el íntegro del valor de la prestación que aquél tenía que
ejecutar en su favor. La ley considera que si el acreedor siguiese obligado a pagar dicha
cantidad de dinero, el deudor estaría resultando doblemente (por lo tanto injustamente)
beneficiado. Lo propio ocurriría respecto del monto de una hipotética indemnización de
dañosy perjuicios que el acreedor tuviera que pagar en favor del deudor. Si el monto de
lo pagado por concepto del seguro cubre también dicho monto, no tendría que pagar
suma alguna. Pero la Compañía de Seguros — y mucho dependerá esto de las cláusulas
generales de contratación pactadas en el contrato— cobrará al acreedor. Está claro que la
aseguradora no soportará finalmente dicho egreso ocasionado por la pérdida.
Si el bien cierto a darse deteriora por culpa del acreedor:(Inc. 4 °A rt.ii3 8 C.C)
a) El acreedortiene laobligación de recibirel bien en el estado en que se halle,sin reducción
alguna de la contraprestación, si la hubiere.
3. Pérdida o deterioro del bien sin culpa de las partes
Cuando el bien cierto a darse pierde por caso fortuito o fuerza mayor, se aplican las siguientes
reglas (lnc.50Art. 1138):
La obligación queda resuelta, con pérdida del derecho a la contraprestación, si la hubiere.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 413 of 1506 --

Tema 2: Temas de derecho civil
Corresponden al deudor los derechosy acciones relativas al bien.
Cuando el bien cierto a dar se deteriora por caso fortuito o fuerza mayor, se aplican las siguien
tes reglas (lnc.6°Art. 1138):
En caso de deterioro, el deudor sufre las consecuencias, efectuándose una reducción pro
porcional de la contraprestación.
Corresponden al deudor los derechosy acciones que pueda originar el deterioro del bien.
Cesión de créditos. Concepto, limitaciones y requisitos
Concepto. La cesión de créditos o de derechos consiste en la renuncia o transmisión gratuita u
onerosa, que se hace de un crédito acción o derechos a favor de otras personas.
Realmente es un negocio jurídico entre el cedente y el cesionario. Debe hacerse por escrito,
bajo sanción de nulidad. Según ANIBAL ALTERINI es formal, es decir que “debe ser hecha de
forma escrita, cualquiera que sea el valor del crédito cedido y aunque él no conste de instru
mento público o privado”13.
Los sujetos de la cesión de crédito son tres:
a) EL CEDENTE - Es el que transmite el derecho.
b) EL CESIONARIO.- Es la persona a quien se le transmite el derecho.
c) EL CEDI DO.-Es el deudor.
La cesión es una forma de transm itir los créditos, así como la tm á itio lo es para transm itir los
derechos reales.
La cesión debe basarse en una causa que la justifique.
El artículo 1206 del C.C prescribe que la cesión puede hacerse aún sin el consentimiento del
deudor.
La cesión debe constar por escrito bajo sanción de nulidad, puesto que el documento o título
de la transferencia sirve de constancia de la cesión (Art. 1207).
Limitaciones.- Los Derechos que no se pueden ceder, acorde con el Art. 1210 del C.C son:
Cuando se oponen a la ley, por ejemplo: no se puede ceder una herencia futura (Art. 1405
del C.C).
Cuando se opone a la naturaleza de la obligación, por ejemplo: derecho a pedir alim en
tos, derecho a reconocer un hijo.
Cuando se opone al pacto con el deudor. En este últim o caso el pacto que prohíbe o res
tringe la sección se puede oponer al cesionario de buena fe, si consta del Instrumento por
el que constituyo la obligación, o se prueba que el cesionario lo conocía al momento de
efectuar la cesión. Por tanto, la cesión practicada contra una prohibición será nula, esta
nulidad afecta al acreedor, al deudory también al cesionario que obró de mala fe.
