Requisitos.
a) Que exista una obligación.
b) Que sea por escrito.
c) Que se transmita el derecho a un tercero (cesionario).
d) Que no se oponga a la ley.
e) Que sea comunicada al deudor (cedido).
f) Que no exista un pacto non cedendo (que no haya un acuerdo convencional entre el ceden-
te y el cedido que lo prohíba).
8. El pago: noción, principios y efectos. Intereses: concepto, clases. Anatocism o
y capitalización de los intereses. Formas de pago: pago por consignación. Pago
con subrogación: concepto y efectos. Tipos de subrogación: casos. Im putación de
pago. Dación de pago. Pago indebido.
8.1. Noción de pago
El pago es la forma más común y usual de cum plir con las obligaciones. Es el acto de cum pli
miento de la prestación por el deudor, constituido por un dar, un hacer o un no hacer.
Para Josserrand"pago es el medio de extinción por excelencia; constituye el desenlace normal
de las obligaciones"
A decir de Manuel Borja Soriano "Es más natural ocuparse del pago a propósito del cum pli
miento de las obligaciones, pues la extinción de las obligaciones no es sino el efecto del pago.
Es más natural ocuparse del pago a propósito del cumplim iento de las obligaciones, pues la
extinción de las obligaciones no es sino el efecto del pago”14. En este sentido el autor hace bien
en aclarar que el pago es el cumplimiento de la obligación; mientras que la extinción es tan
solo consecuencia de aquel.
Planiol Marcelyjorge Ripert, en suTratado Práctico de Derecho Civil Francés nos definen el pago
como “es el modo normal de extinción de las obligaciones, ya que consiste en el hecho de cum-
plircon laprestación prometida”15. Para Ferrero Costa “cuando nuestro Código Civil trata del pago
se está refiriendo a la ejecución de la prestación debida y no únicamente a la movilización del
dinero. Debemos entenderlo como cualquier forma de ejecutar la prestación debida"16.
Para nosotros es mejor referirnos al cumplimiento o pago en sentido estricto) como un hecho
cancelatorio que implica ampliamente la realización de ¡a prestación debida (solutio), por me
dio del cual la obligación se extingue. De esta manera vemos que el pago es su cumplimiento
y la extinción su consecuencia.
