Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 415 of 1506 --

Tema 2: Temas de derecho civil
El Art. 1220 del C.C. prescribe: “Se entiende efectuado el pago sólo cuando se ha ejecutado
íntegramente la prestación”17.
8 . 2 . P r i n c i p i o s d e l p a g o y e f e c t o s
Por naturaleza el pago es un acto jurídico bilateral, es voluntario y lícito cuyo efecto es crear
un efecto jurídico ¿Cuál es? La extinción de la obligación. Es la opinión generalizada de los
tratadistas.
Los principios del pago son los siguientes:
Principio de identidad.- Es aquel en virtud del cual el objeto del pago de laobligación debe ser
el mismo al que se obligó el deudor. El objeto del pago no puede serdistinto al de la prestación
convenida o prometida, lo cual supone que al pagar hay que entregar esa cosa y no otra, aún
cuando la cosa que se desea entregar sea de mayor valor, entendiéndose ejecutado el pago
sólo cuando se ha ejecutado.
Este principio es considerado en lo preceptuado en el Art. 1132 de nuestro Código Civil “El
acreedor de bien cierto no puede ser obligado a recibir otro, aunque éste sea de mayor valor”.
El principio de identidad tiene las siguientes aplicaciones:
Rige para toda clase de obligaciones, sea cual fuere la fuente de la cual emanen y cual
quiera que fuere su objeto: dar, hacer o no hacer
Es invocable tanto por el acreedor como por el deudor, ni uno, ni otro pueden unilateral
mente apartarse del principio.
A su vez este principio produce los siguientes efectos:
i°- El acreedor no puede ser obligado a recibir una cosa por otra, aunque ésta sea de igual o
mayor valor que la convenida, ni compelido a aceptar la ejecución de otro hecho que no
sea el de laobligación.
2o- Al deudor no le está permitido sustituir el objeto específico que debe con una indem ni
zación dineraria que compense la inejecución de aquel objeto. Al contrario siempre que
el cumplim iento específico sea posible y útil al acreedor, éste tiene derecho a ese cum
plimiento, sólo cuando se presente una situación de incumplimiento absoluto, es decir,
cuando ha desaparecido por una causa imputable al deudor (dolo, culpa), la posibilidad
de conceder el objeto específico, puede el deudor desobligarse mediante el pago de una
indemnización sustitutoria.
Sin embargo, cabe anotar que este principio de identidad tiene ciertas excepciones como:
a) En las obligaciones facultativas cuando el deudor ejerce la facultad de sustituir el objeto
del pago (la prestación principal) por una accesoria, cuando la prestación resulta nula o
imposible de cum plir (Art. 1169 C.C.).
b) Cuando se trata de obligaciones contraídas en moneda extranjeras y que pueden ser can
celadas en moneda nacional al valor de cambio de venta del día y lugar de vencimiento
de la obligación (Art. 1237 CC).
17 TORRES VÁSQUEZ, Aníbal. Derecho Civil. 3a. Edic. Impresión Gráfica Bellido S.R.L. L¡m a-Perúi996. p. 44-
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 416 of 1506 --

UBILEX
Principio de integridad - Según el cual el pago debe ser completo, es decir, el objeto de pago
debe ser cuantitativamente igual al objeto del crédito.
Se debe tener en cuenta que mientras porel principio de identidad se resuelve el problema de
calidad o esencia, con el de integridad se resuelve el de cantidad o magnitud. De ahí que así
como el acreedor no puede ser obligado a recibir una cosa distinta (identidad), tampoco se le
puede exigir que acepte una cantidad menor o fraccionada (integridad).
Este principio se haya contenido en diversas disposiciones de nuestro Código Civil (Arts. 1220,
1574 del CC).
El principio de integridad impide que el deudor pueda efectuar pagos parciales cuando no
está autorizado, la idea de indivisibilidad está comprendida en él.
Este principio se fundamenta en varias ideas. Entre ellas:
Para algunos se basa en el principio de la autonomía de la voluntad, según esta tesis si las par
tes convienen en que el pago será íntegro, ni el acreedor, ni el deudor pueden apartarse luego
de lo pactado.
Para otros inspirados en Pothier el principio de integridad se basa en el respeto al interés
del acreedor.
Para otros la integridad del pago reposa en la intangibilidad de la relación obligacional
después de que ésta ha sido constituida, a partir de cualquiera de las fuentes admitidas,
sus elementos no pueden ser alterados, salvo los casos previstos por la ley. Ni el acreedor,
ni el deudor pueden unilateralmente modificar o alterar el objeto del pago.
La vigencia de este principio trae consigo los siguientes efectos o consecuencias:
10.- El acreedor no puede ser obligado a recibir pagos parciales.
20.- Si se debe una suma de dinero con intereses, el pago no será íntegro si no se pagan los
intereses con el capital. Si se ha iniciado un juicio por cobro de dinero, el pago no será ín
tegro si no se pagan los intereses con el capital, además de las costasy costos del proceso
que están a cargo del deudor.
3o- El deudor tampoco puede ser obligado a entregar pagos parciales. Tiene derecho a libe
rarse mediante el pago total.
El principio de integridad es aplicable en los siguientes casos:
i° Tanto en las obligaciones de dar, hacer y no hacer. Ejemplo: el caso de la modelo que se
obliga posar 4 horas diarias, no puede pretender desobligarse posando únicamente 2,
pues su prestación dejaría de ser íntegra.
2o Tanto en las obligaciones singulares como en las plurales.
3o Se da tanto en las obligaciones de ejecución instantánea como continuada.
Las excepciones al principio de continuidad sin embargo pueden darse como:
A) Acuerdo de voluntades.-Es decir por acuerdo entre el acreedory el deudor que pueden pac
tar la disminución del pago a su fraccionamiento haciendo uso de su libertad. Ejemplo:
la venta de un inmueble en $100, 000.00 dólares americanos estipulándose que dicho
precio será pagado en cuotas periódicas por el plazo de 10 años.
m6 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 417 of 1506 --

Tama 2: Temas de derecho civil
B) Por autorización legal.-Cuando es la propia ley la que autoriza un apartamiento del princi
pio de autoridad, como cuando por ejemplo si una deuda tiene una parte líquida e ilíqui
da, el acreedor puede exigir el pago de la primera parte (líquida), sin que el deudor pueda
oponerse invocando la liquidez de una porción de la deuda (Art. 1221 del C.C.).
C) Por autorización ju dicial.-Se deja de lado la integridad en virtud de la potestad judicial, el
juez puede establecer la forma de pago concediéndoles al deudor el beneficio de pagar
en cuotas periódicas (Art. 1983 C.C.).
8 . 3 . I n t e r e s e s
Concepto.- Los intereses constituyen los frutos civiles que pueden producir cualquier bien o
prestación, sea o no una suma de dinero, por lo que se aplican a toda clase de deudas. Los
intereses son accesorios al capital, no pueden generarse si no existe una deuda principal, de
ahí que aquellos tienen el carácter de prestación accesoria.
Clases de intereses.- Existen varias clases de intereses:
a) Intereses compensatorios.- Son aquellos que producen una contraprestación por el uso
del dinero o cualquier otro bien, su fin es mantener el equilibrio patrimonial, evitando
que una de las partes se enriquezca a costa del otro constituyendo un enriquecimiento
indebido al no pagar el importe del rendimiento del bien (Primer párrafo del Art. 1242
C.C.).
b) Intereses moratorios.-Tienen por finalidad indemnizar la mora, es decir la demora en el
■pago sancionando así el retraso doloso o culposo en el que incurra el deudor en el cum
plimiento de su obligación. (Segundo párrafo del Art. 1242 C.C.).
c) Intereses convencionales.- Son aquellos acordados libremente por las partes, de acuerdo
a la economía contractual y no tienen más limitación que las normas de orden público
que provienen de la ley. Los intereses convencionales no se devengan sino se pactan; sin
embargo si se pagan sin estar pactados no podrá reclamarse su devolución.
d) Intereses legales.- Son aquellas que se aplican a falta de pacto, por disposición de la ley,
cuando se incurre en mora (Art. 1244 C.C). Este interés es fijado por el Banco Central de
Reserva del Perú, teniendo en cuenta una serie de factores que influyen en el índice infla
cionario.
8.3.1.A natocism o o capitalización de intereses
La capitalización de intereses, se denomina anatocismo, no es otra cosa que la generación de
interés sobre interés.
Existen dos formas de anatocismo: a) Anatocismo conjunto: El interés se sumaal capital con
virtiéndose en un nuevo capital que a su vez devengará nuevos intereses, b) Anatocismo sepa
rado. Implica la formación de un capital (paralelo al capital original; no se confunde con éste)
con los intereses devengados para hacerlos producir nuevos intereses.
El artículo 1249 del Código Civil consagra el principio de prohibición de la capitalización de
intereses al momento de contraerse la obligación; pero admite la capitalización por excepción
en el caso de las cuentas mercantiles, bancarias, financieras o similares. La capitalización de
