Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 418 of 1506 --

UBILEX
intereses requiere el acuerdo de las partes. Cuando la norma habla de cuentas similares a las
bancarias, se entiende que se está refiriendo a entidades similares a los bancos y/o a las em
presas del sistema financiero (bancos, compañías de seguros, mutuales, etc.)
8.4. Formas de pago
PAGO POR CONSIGNACIÓN.- Es el acto mediante el cual el deudor deposita la prestación
debida ante el tercero para que sea entregada al acreedor. Es un medio de liberar al deudor.
Requisitos o presupuestos legales para que proceda la consignación.- De acuerdo con el Art.
1251 del C.C. para que proceda el pago por consignación se requiere:
i° - Que haya un ofrecimiento de pago.
2o- Que el deudor haya puesto a su disposición el pago en la forma pactada en el título de la
obligación.
3o- Que el acreedor se haya negado injustificadamente a recibir el pago o que no haya prac
ticado los actos necesarios para que se pueda ejecutar la obligación como puede ser que
haya respuestas evasivas, inconcurrencia en el lugar pactado en el díay hora para el cum
plimiento o cuando se rehúse a entregar el recibo o conductas análogas.
Caracteres del pago por consignación.- El pago por consignación tiene las siguientes caracte
rísticas:
a) Es judicial. En los casos que así se hubiera pactado y además: cuando no estuviera estable
cida contractual o legalmente la forma de hacer el pago, cuando por causa que no le sea
imputable el deudor estuviera impedido de cumplir la prestación de la manera prevista,
cuando el acreedor no realiza los actos de colaboración necesarios para que el deudor pue
da cumplir la que le compete, cuando el acreedor no sea conocido o fuese incierto, cuando
se ignore su domicilio, cuando se encuentre ausente o fuera una persona contemplada en el
artículo 43 o 44 del Código Civil sin tener representante, curador o apoyo designado, cuando
el crédito fuera litigioso o lo reclamaran varios acreedores y en situaciones análogas que
impidan al deudor ofrecer o efectuar directamente un pago válido.
El ofrecimiento extrajudicial debe efectuarse de la manera que estuviera pactada la obli
gación y, en su defecto, mediante carta notarial cursada al acreedor.
b) Es facultativa.- El deudor puede recurrir a ella cuando lo estime conveniente para cuyo
efecto tendrá que solicitar su ofrecimiento judicial y en su caso que se le autorice a con
signárselo con propósito de pago; pero cuando se trate de un proceso contencioso en que
se discute la relación material que lo originó o que esté conectada a la obligación debida,
el ofrecimiento y eventual consignación deberá efectuarse en el mismo proceso, siguién
dose el trám ite que le corresponde al mismo (Art. 802 del C.RC.)
c) Es excepcional.- P e r m ite a l d e u d o r e n t r e g a r lo d e b id o p o r m e d io d e u n te rc e ro q u e es el
ju e z , c u a n d o lo n o r m a l es q u e se p a g u e lo d e b id o d ir e c t a m e n t e al a c re e d o r.
Importancia del pago por consignación.- Tiene las siguientes ventajas:
a) Evita que el deudor se constituya en mora.
b) Evita el pago de los intereses aparte de la mora.
c) El deudorse libera de la obligación.
