e) D e s a p a r e c e n la s g a r a n t ía s re a le s o p e r s o n a le s .
f) Los rie s g o s y p e lig r o s d e la c o s a c ie r t a a d a r p a s a n a l a c re e d o r.
PAGO CON SUBROGACIÓN.- Es el p a g o r e a liz a d o p o r u n te rc e ro in t e r e s a d o o n o en el c u m
p lim ie n t o d e la o b lig a c ió n y q u e lo p u e d e h a c e r c o n el c o n s e n t im ie n t o d e l d e u d o r, s in s u c o n -
s e n t im ie n t o y a ú n c o n t r a s u v o lu n t a d .
El q u e p a g a p o r el d e u d o r se s u s t it u y e en t o d o s s u s d e r e c h o s a la p e r s o n a d e l a c re e d o r, a e fe c
to s d e e x ig ir a l d e u d o r u n a p r e s t a c ió n ig u a l a la s a t is f e c h a , g o z a n d o d e la s m is m a s g a r a n t ía s
e s t a b le c id a s p a r a el a c r e e d o r d e l c ré d it o ( a c r e e d o r p r im it iv o ) .
La subrogación supone para algunos autores una ficción legal ya que el crédito se extingue
respecto del acreedor que recibió el pago; pero subsiste íntegramente respecto al tercero que
pagó, con todos sus accesorios, privilegios, prendas e hipotecas que aseguraban el crédito del
acreedora quien se pagó (Art. 1262 del C.C.).
