Casos en la subrogación convencional
a) C u a n d o el a c r e e d o r re c ib e el p a g o d e u n te rc e ro y lo s u s t it u y e en t o d o s su s d e r e c h o s . La
s u b r o g a c ió n o p e r a p o r a c u e r d o e n tre el a c r e e d o r y el te rc e ro , s u s t it u y é n d o s e é ste e n t o
d o s lo s d e r e c h o s d e a q u e l.
