d o y a p r o b a c ió n d e l d e u d o r.
c) C u a n d o el d e u d o r p a g a c o n u n a p r e s t a c ió n q u e h a r e c ib id o e n m u t u o y s u b r o g a al m u
t u a n t e e n lo s d e r e c h o s d e l a c re e d o r, s ie m p r e q u e el c o n t r a t o d e m u t u o se h a y a c e le b r a d o
p o r d o c u m e n t o y se h a y a h e c h o c o n s t a r ta l p ro p ó s ito , e x p r e s a n d o s u p r o c e d e n c ia al m o
m e n t o d e e f e c tu a r s e el p a g o . Este es u n c a s o m u y e s p e c ia l d e s u b r o g a c ió n , d a d o a q u e no
e x is te el p a g o d e l te rc e ro al a c r e e d o r; s in o q u e el te rc e ro le p r e s ta d in e r o al d e u d o r p a r a
q u e é ste p a g u e a l a c re e d o r.
