8.5. La imputación al pago
Consiste en la expresa determinación por quien tiene derecho para ello de la deuda, a la cual
se aplica el pago que efectúa cuando existen obligaciones de igual naturaleza.
La imputación al pago, sólo cabe cuando entre acreedor y deudor existe una pluralidad de
deudas, porque efectuando el pago no se sabría a cuál de éstas aplicar, salvo que el monto del
pago sea equivalente al total de deudas vencidas, en cuyo caso no cabría imputación al pago,
ya que todos los créditos quedarían satisfechos.
La imputación al pago se practica de acuerdo a un orden de prelación, en primer lugar por el
deudor, en su defecto por el acreedory en defecto de ambos por la misma ley.
1. - Requisitos de la imputación al pago. Para que se dé la imputación al pago se requiere:
a) Pluralidad de deuda.
b) Sim ilituden la naturaleza de la prestación.
c) Plazo vencido,
d) Que el acreedor sea el mismo.
e) Que todas las prestaciones sean a su vez fungiblesy homogéneas.
2. - Reglas de la imputación al pago.
Quien tiene varias obligaciones de la misma naturaleza constituidas por prestacio
nes fungiblesy homogéneas, en favor de un solo acreedor, puede indicar al tiempo
de hacer el pago, o, en todo caso, antes de aceptar el recibo em itido por el acreedor, a
cual de ellas se aplica éste. Sin el asentimiento del acreedor, no se imputará el pago
parcialmente o a una deuda ilíquida o no vencida. (Art. 1256 C.C.).
El que debe capital, gastos e intereses, no puede sin la aceptación del acreedor apli
car el pago al capital antes que a otros gastos, ni aplicar los gastos antes que a los
intereses. (Art. 12 5 7 C.C.)
Cuando el deudor no ha indicado a cuál de las deudas debe imputarse el pago, pero acep
ta el recibo del acreedor aplicando a cualquiera de ellas, no puede aplicar contra éste la
imputación, salvo que exista alguna causa que impida practicarla. (Art. 1258 C.C.)
C u a n d o no se e x p r e s a a q u é d e u d a d e h a c e rs e la im p u t a c ió n , se a p lic a el p a g o a la
m e n o s g a r a n t iz a d a , e n tre v a r ia s d e u d a s ig u a lm e n t e g a r a n t iz a d a s a la m á s o n e r o s a
p a ra el d e u d o r y e n tre v a r ia s d e u d a s g a r a n t iz a d a s y o n e r o s a s a la s m á s a n t ig u a . Si
e sta s re g la s n o se p u e d e n a p lic a r la im p u t a c ió n al p a g o se h a r á p r o p o r c io n a lm e n t e .
(Art. 1 2 5 9 C .C .)
8.6. La dación en pago
Denominada en Roma la datio insolutum . Consiste en una sustitución que hace el deudor con
el consentimiento del acreedor de la cosa debida, por otra o por otro servicio para extinguir la
obligación. Esta excluye de modo expreso el dinero. Así los prescribe el Art. 1265 del C.C.
EL Art. 1266 del C.C. estipula que las relaciones del acreedor con el deudor si se determ ina la
cantidad por la cual el acreedor recibe del deudor el bien en pago, su relación con el deudor
