8.7. El pago indebido
Se p r o d u c e c u a n d o el d e u d o r p a g a p o r e r r o r d e h e c h o o d e d e r e c h o u n a d e u d a , al c o n s id e r a r s e
o b lig a d o a e llo (A rt. 1 2 6 7 d e l C .C .).
Cualquiera que haya sido la forma de pago, se considera no válido por carecer de fundamento
jurídico, y por tanto quien lo ha efectuado tiene el derecho de repetir contra quien lo haya
recibido de buena o mala fe.
Requisitos:
a. E n tre g a d e u n b ie n e n c a l id a d d e p a g o .
b. El propósito de cancelar la deuda.
c. La falta de causa en razón de que el bien no era el debido (in debitum ex re) o si existiendo
la deuda ésta no sea de cargo de quien paga, ni a favor de quien recibe (in debitum ex per
sonóte).
Supuestos del pago indebido en nuestra legislación.- El pago indebido puede darse en los
siguientes supuestos:
a) El doble pago.-C uando por error se paga una deuda que ya estaba cancelada.
b) El pago en dem asía- C u a n d o e q u iv o c a d a m e n t e se p a g a m á s d e lo d e b id o , d e m o d o ta l q u e
e sto p u e d e d a r lu g a r a s o lic it a r la r e s t it u c ió n d e l e x c e d e n te .
c) El pago de una deuda sujeta a una condición aun pendiente- Quien contrae una deuda bajo
condición y pago sin que aquella se dé también incurre en pago indebido.
d) El pago de una deuda a plazo suspensivo.- S e g ú n E u g e n io P etit, q u ie n h a p r o m e t id o a p la z o
n o es m e n o s d e u d o r q u e a q u e l q u e p a g a a n t e s d e l v e n c im ie n t o , p o r q u e p a g a lo q u e es
d e b id o y n o p u e d e e n c o n s e c u e n c ia r e p e t ir lo q u e p a g ó .
Todo pago hecho indebidamente da lugar a repetición por parte de quien pago, acción que la
dirige contra quien pago y recibió de buena fe, como contra aquel a quien pago y recibió de
mala fe, no teniendo en el primercaso derecho a cobrar indemnización por dañosy perjuicios
yen el segundo caso sí.
9. La transacción.- Concepto. Requisitos y contenido. Diferencias y similitudes con
otras figuras: renuncia, mediación o buenos oficios, conciliación y arbitraje. Tipos
de transacción. Restricciones a la facultad de transigir.
9.1. La transacción. Concepto
Es una categoría jurídica en virtud de la cual dos o más personas extinguen obligaciones origi
narias, mediante un acuerdo en el que se hacen concesiones recíprocas, solucionando conflic
tos creados entre las personas (Art. 1302 del C.C.).
En D o c t r in a a lg u n o s c o n s id e r a n la t r a n s a c c ió n c o m o el m o d o d e e x t in g u ir la s o b lig a c io n e s
p o r s e r u n a c to m e r a m e n t e d e c la r a t iv o , o tro s e n c a m b io d ic e n q u e es u n c o n t r a t o p o r el c u a l
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 421

-- 422 of 1506 --

UBILEX
las partes regulan y crean derecho al hacerse concesiones recíprocas. Así Salvat nos dice "El
carácter contractual de la transacción resulta incontestable, por cuanto ésta produce efectos
jurídicos similares a cualquier otro contrato de obligaciones reciprocas, por cuanto no sólo se
encarga de extinguir obligaciones, lo que muchas veces no ocurre, sino que produce en los
contratantes la obligación de cumplir con lo transado”.
9.2. Requisitos de la transacción
Para que se dé la transacción tienen que tenerse en cuenta los siguientes requisitos-.
a) Acuerdo de voluntades.
b) Concesiones recíprocas.
c) Debe contener la renuncia de las partes (Art. 1303 C.C).
d) Debe versar sobre derechos patrimoniales.
e) Debe hacerse por escrito bajo sanción de nulidad (Art. 1304 C.C).
f) Es onerosa.
9.3. Contenido de la transacción
Sólo se puede transar sobre derechos patrimoniales y sólo sobre ellos se pueden hacer conce
siones recíprocas. Hay bienes patrimoniales que no pueden ser objeto de transacción como:
los bienes de uso público, los derechos de uso y habitación, la obligación de prestar alimentos,
sobre la herencia futura, etc.
Por otro lado, cabe anotar que no se puede transigir sobre la acción penal que provenga de
delito; perosísobre la responsabilidad civil que derive de aquello (Art. 1306), porque la respon
sabilidad penal es de orden público, pero independiente de la civil.
9.4. Características de la transacción
Son rasgos distintivos de la transacción:
a) Es un acto jurídico bilateral, es decir hay un acuerdo de voluntades que consecuentemen
te pone a ambas partes en la obligación de hacerse concesiones recíprocas.
b) D e b e s e r a t ít u lo o n e ro s o , es c o n s e n s u a l.
d) Es un acto indivisible, pues la nulidad o anulabilidad de algunas de sus estipulaciones
acarrean la nulidad del acto de la transacción, salvo pacto en contrario entre las partes.
9.5. Diferencias de la transacción y similitudes con otras figuras, renuncia, mediación o
buenos oficios, conciliación y arbitraje
Con la renuncia. Se d if e r e n c ia en que-,
a) Mientras la transacción es bilateral, la renuncia es unilateral.
b) La t r a n s a c c ió n s o lo p e sa s o b re d e r e c h o s p a t r im o n ia le s , m ie n t r a s q u e la r e n u n c ia s e re fie
re a t o d o s lo s d e r e c h o s r e n u n c ia b le s y n o s o la m e n t e a lo s c r e d it ic io s .
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 423 of 1506 --

Tema 2: Temas de derecho civil
c) En la renuncia la persona abdica, abandona sus derechos, mientras que en la transacción
sólo parcialmente.
d) Mientras la transacción necesita de la acepción de la otra parte, la renuncia no.
e) Se puede renunciar expresa o tácitamente, en cambio sólo se puede transigir por escrito
bajo sanción de nulidad.
f) Solo se transa sobre derechos versar sobre derechos controvertidos o no controvertidos.
Se asemejan la transacción con la renuncia en que ambas suponen actos voluntarios.
Con la mediación.-Se diferencia en que:
a) La mediación es una figura jurídica de Derecho Internacional Público, mientras que la
transacción es una figura jurídica de Derecho Privado.
b) La mediación supone un arreglo pacífico de disputas internacionales, mientras que la
transacción lo es también pero de discrepancias o disputas privadas.
c) La mediación es una forma de lograr zanjar conflictos entre los Estados, en cambio la
transacción lo es entre las personas de derecho privado.
d) En la mediación siempre interviene un tercero tratando de apaciguar los sentimientos
de agravio que pudieran haber surgido entre los Estados desavenidos, en cambio en la
transacción sólo intervienen las partes en las obligaciones.
Con los buenos oficios.- Se diferencia en que:
a) En los buenos oficios hay una participación amistosa de terceros para procurar solucionar
pacíficamente una desavenencia entre Estados; pero implica la menor participación po
sible del oficiante; en cambio la transacción sólo se da entre las partes que son siempre
personas naturales o jurídicas del Derecho Privado.
b) En los buenos oficios es el tercero el que pretende coadyuvara las partes a que logren una
solución pacífica; en cambio en la transacción son las propias partes, las que con su propia
iniciativa deciden llegara un buen arreglo.
c) Es una figura jurídica que corresponde al Derecho Internacional Público y por el cual un
tercer Estado se ofrece a mediar en un conflicto para lograr una solución pacífica al pro
blema entre Estados, en cambio la transacción es una figura jurídica, pero de Derecho
Privado, que la celebran las propias partes a iniciativa de ellas mismas.
Se asemejan ambas figuras porque tratan de dar solución pacífica a hechos controverti
dos.
Con el arbitraje.- La transacción se diferencia del arbitraje en que:
a) El arbitraje consiste en el fallo dictado por un tercero que pone fin a la contienda, en cam
bio la transacción diríamos que ambas partes lo deciden, es consensual.
b) El arbitraje es una forma de administrar justicia, en cambio la transacción se da judicial o
extrajudicialmente.
c) En el arbitraje interviene un tercero, que es el árbitro; en cambio en la transacción sólo las
partes.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 424 of 1506 --

UBILEX
d) El arbitraje es una figura jurídica de Derecho Internacional Público y Privado; en cambio
la transacción sólo es de Derecho Privado.
Ambas figuras jurídicas se asemejan en que ambas para ser ejecutables tienen que ser apro
badas por el juez.
Tipos de transacción: (Art. 1312C.C.)
a. Transacción judicial.- Es la que se da dentro de un proceso judicial (Art. 335 del C.RC).
La transacción judicial se ejercita de la misma forma que la sentencia, es decir surte los
mismos efectos que ésta, puesto que es aprobada mediante auto judicial.
b. Transacción extrajudicial.- Se da fuera del proceso judicial, se hace valer en la vía ejecutiva.
Restricciones a la facultad de transigir: Tanto en el C.C como en el C.RC encontramos algunas
restricciones a la facultad de transigir. Estas son:
a) A los representantes de ausentes e incapaces.- De acuerdo con el Art. 1307 del C.C los
representantes pueden transigircon autorización del juez.
b) Transacción del estado y otras personas de derecho público.- Art. 336 del C.RC. Según el
cual el Poder Ejecutivo, Legislativo y Judicial, el Ministerio Público, los Órganos Constitu
cionales Autónomos, los Gobiernos Regionales y Locales y las Universidad, sólo pueden
transigir previa aprobación expresa de la autoridad o funcionario competente.
Esta exigenciaesaplicabletambién a la conciliación al desistimiento de la pretensióny al pro
ceso.
1 0 . La mora. Concepto y clases. Mora del deudor y mora del acreedor. Concepto,
requisitos y efectos en cada caso. La clausula penal: concepto y utilidad de esta
figura. Diferencia con las obligaciones alternativas y las facultativas. Posibilidad
de la reducción de la clausula penal, asi como de la indemnización del daño ulterior.
10.1. La mora
Concepto: Es el retardo en el cumplimiento de la obligación. Según J. Arias Ramos es el in
cumplimiento justifica de la obligación por parte del deudor o la negativa injustificada del
acreedora recibir la prestación ofrecida por el deudor en tiempo oportuno.
Clases de mora: Existen dos clases de mora:
Mora solvendi o debitoris.-Cuando es el deudor el que incurre en ella.
Mora credendi o creditoris-Cuando incurre en el la el acreedor.
Requisitos de la mora.- Son:
La obligación debe ser váliday exigióle.
Debe versar sobre una obligación civil.
Que retardo en el cumplimiento de la obligación.
Debe referirse a obligación o interpelación. Sin embargo, para nuestra ley civil no es nece
sario la intimación para que la mora exista.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 425 of 1506 --

Tema 2: Temas de derecho civil
La mora del deudor.- El deudor incurre en mora desde que el acreedor le exige judicial o ex-
trajudidalm ente el cumplimiento de la obligación (Art. 1333 C.C). Sin embargo, de acuerdo
con la norma suscrita no es necesaria la intimación para que la mora exista:
i° Cuando la ley o el pacto lo declaran expresamente.
2o Cuando de la naturaleza o circunstancia de la obligación resultare que la designación del
tiempo en que había de entregarse el bien o practicarse el servicio, hubiese sido motivo
determinante para contraería. Ejemplo: La entrega de un telescopio a un astrónomo para
la observación para la observación de un eclipse solar en una determinada fecha, si no se
cumple en esa fecha, carecería de utilidad para el acreedor que se lo entreguen después.
3o Cuando el deudor manifiesta por escrito su negativa a cumplir con la obligación.
4 o Cuando la intimación no fuese por causa imputable al deudor.
Efectos de la mora del deudor.- Los efectos son:
El deudor responde los daños y perjuicios que irrogue el retraso en el cumplim iento de
la obligación y por imposibilidad sobreviniente aún cuando resulte imposible el cum pli
miento de la misma por causa no imputable a aquel.
Cuando a raíz de la mora del deudor la obligación resulte sin utilidad para el acreedor,
éste puede revisar su ejecución y exigir el pago de la indemnización de daños y perjuicios
(Art. 1337 C.C).
Efectos de la mora del acreedor.- De acuerdo con el Art. 1338 del C.C el acreedor incurre en
mora, cuando sin motivo legitimóse niega a aceptar la prestación ofrecida por el deudor o no
cumple con facilitar los actos necesarios para que se puede practicar la prestación, quedando
obligado a indemnizar los daños ocasionados por su retraso.
De igual manera el acreedor en mora asume los riesgos de la imposibilidad del cum plim iento
de la obligación, salvo que obedezca a dolo o culpa inexcusable del deudor (Art. 1340 C.C).
10.2. La cláusula penal
Se da cuando las partes para asegurar el cumplimiento exacto y oportuno de la obligación,
de antemano señalan voluntariamente una pena a cargo del deudory a favor del acreedory
que se hará efectiva en caso de retardo o irregularidad en el cumplim iento o ejecución de la
obligación.
Caracteres de la obligación con cláusula penal.- Las obligaciones con cláusula penal tienen
las siguientes características:
a) Son condicionales.- Su funcionamiento depende del incumplimiento o del retardo en el
cumplim iento de la obligación.
b) Son accesorias.- Porque se añade a la prestación principal, a cuyo cumplim iento contri
buye.
c) Son subsidiarias.- Sustituye a la prestación principal. Solo puede exigirse en defecto del
incumplimiento o el no regular cumplimiento de la obligación, porque está destinada a
asegurar el cumplim iento de la obligación.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 426 of 1506 --

UBILEX
d) Son inmutables.- Porque ni el acreedor, ni el deudor pueden cambiar.
e) Son definitivas.- Porque una vez que surge el hecho condicionante es de exigibilidad, por
parte del acreedor, no pudiendo negara cum plirel deudor.
f) Son de interpretación estricta.- Este c a r á c t e r e s a d o p t a d o p o r L la m b ía s q u e c o n s id e r a
q u e s u p o n e u n d e r e c h o e x c e p c io n a l. D ic e q u e p a c t a d a u n a c lá u s u la p e n a l p a ra el c u m p li
m ie n to , no p u e d e d a r s e p a ra la s im p le m o r a .
Utilidad de esta figura.
a) Permite preverde antemano una penalidad pecuniaria en caso de incumplimiento de la
obligación, evitando tener que discutir posteriormente a cuánto ascienden los daños y
perjuicios que irrogue aquel.
b) Es p e r s u a s iv a , p o r c u a n t o la s p a rte s s a b e n c o n c e rte z a a lo q u e se a t ie n e n en c a s o d e in
c u m p lim ie n t o .
Diferencias de la cláusula penal con las obligaciones alternativas.
a) La c lá u s u la p e n a l se d if e r e n c ia d e la s o b lig a c io n e s a lt e r n a t iv a s , p o r q u e é s ta s so n o b lig a
c io n e s p r in c ip a le s , t o d a s la s p r e s t a c io n e s e s tá n e n o b lig a c ió n y s ó lo u n a se d a en s o lu c ió n ;
en c a m b io e n la c lá u s u la p e n a l, é s ta es u n a o b lig a c ió n a c c e s o r ia .
b) La cláusula penal es inmutable porque el acreedor ni el deudor la pueden cambiar, en
cambio en las obligaciones alternativas el acreedor o el deudor al momento de elegir,
pueden cumplir la obligación con cualquiera de las prestaciones.
c) La c lá u s u la p e n a l e s tá s u je t a a q u e no se c u m p la c o n la o b lig a c ió n p r in c ip a l, en c a m b io las
o b lig a c io n e s a lt e r n a t iv a s d e t o d a s m a n e r a s t ie n e n q u e c u m p lir s e .
Posibilidad de la reducción de la cláusula penal así como de la indemnización de los daños
y perjuicios ulteriores.
La cláusula penal puede ser reducida por el juez, cuando ésta fuese excesiva o la obligación
hubiere sido irregularmente cumplida. Ejem. El deudor tiene que pagar si los muebles que le
fueron enviados a hacer no salen exactamente al modelo que le fue encomendado, estable
ciéndose como penalidad que pague el mismo valor doblado (Art. 1346 C.C.).
P a ra e x ig ir la p e n a no es n e c e s a r io q u e se p r u e b e n lo s d a ñ o s y p e r ju ic io s p o r el a c r e e d o r. S in
e m b a r g o , s ó lo p u e d e e x ig ir s e c u a n d o el in c u m p lim ie n t o o b e d e c e a c a u s a im p u t a b le a l d e u
d or, s a lv o p a c to en c o n t r a r io (A rt. 13 4 3 C .C .).
