El contrato privado! Concepto, importancia y fuerza vinculatoria
Concepto.- El contrato es definido por nuestro Código Civil como el acuerdo de dos o más
partes para crear, regular, modificar o extinguir una relación jurídica patrimonial (Art. 1351
C.C.). Tal consistiría en una definición legislativa. Pero el contrato podemos concebirlo como
negocio jurídico (acto jurídico), como documento, como relación jurídica o como proceso. En
el primer caso, el contrato viene a ser el negocio jurídico patrimonial de carácter bilateral o
p!urilateral, es decir, la resultante negodal unitaria de declaraciones provenientes de dos o
más partes, que inciden sobre relaciones jurídicas de naturaleza patrimonial, creándolas, mo
dificándolas, regulándolas o extinguiéndolas. Constituye así el instrumento para la autodisci
plina de los intereses particulares; es decir, el consenso que dentro de los límites establecidos
por el ordenamiento se presta a la realización de las más disímiles finalidades de las partes,
diferenciándose de los negocios jurídicos de naturaleza fam iliar carentes de patrimonialidad.
Como documento el contrato es un simple medio de prueba, o la materialización de un ele
mento constitutivo, cuando se trate de contrato solemne. Como relación jurídica se denomina
contrato a la situación que sigue a la celebración del contrato, vale decir a la relación jurídica
obligatoria (relación contractual) que nace, se regula, se modifica o se extingue como efecto
de aquel. Finalmente, visto desde la dinámica del mismo, el contrato es un proceso que se
inicia con los contactos sociales, tratativas, ofertas, consentimiento, ejecución, deberes pos
contractuales, todo en una secuela sin separar en etapas.
Importancia.- Cualquiera que sea su figura concreta el contrato tiene una función y contenido
constante, cual es el de ser el instrumento con el cual se realizan los más diversos fines de la
vida económica, mediante la composición de intereses opuestos. Como tal, el mismo llena de
sí la vida jurídica, además de la vida económica, extendiendo su círculo de acción, también, a
