Tema 2: Temas de derecho civil
legal del tipo, en cuanto a normas dispositivas o supletorias; e) libertad de concluir contratos atí
pleos o innominados; f) libertad de forma, salvo en los casos de contratos solemnes; y g) libertad de
determinar el contenido del contrato, dentro de los límites establecidos por las normas legales
imperativas. De estas consecuencias de la libertad o autonomía contractual, las que tienen
mayor relevancia son la propiamente llamada libertad de conclusión, denominada también
libertad de contratar o de contratación, y la libertad de contenido, denominada propiamente
libertad de configuración interna del contrato.
El Art. 1354 del C.C. reconoce el principio de la autonomía de la voluntad al establecer que: “Las
partes pueden determinar libremente el contenido del contrato, siempre que no sea contrario
a la ley”. La libertad contractual es la regla general y su limitación opera como excepción.
El contrato forzoso.- La más fuerte injerencia imaginable a la libertad contractual se produce
cuando alguien viene obligado a la conclusión de un contrato. Aparece así el contrato forzoso
como aquel en el que se impone el deber de celebrar. Se le llama forzoso por contraposición a
los libresque, en teoría, nada constriñeaconcluir. Sin embargo, esta compulsión no se circuns
cribe necesariamente a la libertad de contratación, sino que afecta también a la libertad para
la determinación del contenido del contrato, vale decir, la libertad de configuración interna
del contrato. La definición clásica de la contratación obligada se refiere, por eso, a la libertad
de conclusión y de contenido, cuando se indica que contratación forzosa es la que con funda
mento en una norma del ordenamiento jurídico a un sujeto de derecho sin actuación de su
voluntad, en interés de un beneficiario le impone la obligación de concluir un determinado
contrato o con contenido fijado por parte imparcial. Un ejemplo lo tenemos en el seguro obli
gatorio de automóviles.
La idea de contrato forzoso aparece contradictoria en sí misma. No lo es en la medida que las
partes se someten voluntariamente a ellos y celebran el contrato debido, en cuyo caso hay
siempre contrato como acuerdo. El contrato celebrado en cumplim iento de la obligación le
gal, de un fallo judicial o de una orden de la Administración pública, no es menos contrato
que cualquier otro. Distinta resulta la imposición sin contrato de la relación jurídica, es decir,
la admisión de una relación obligacional legal, que inmediatamente se ordena a la presta
ción. Ante la negativa del particular a otorgar el contrato, el ordenamiento o la autoridad re
accionan imponiéndole, sin su voluntad, el establecimiento de la relación jurídica de que se
trate. No obstante, para tal caso de contratación forzosa se da el tratam iento que reciben los
contratantes en el tráfico jurídico usual, es decir, se comprende que incluso en la contratación
forzosa se regule la relación entre los interesados mediante contrato y no por ley.
Reglas y limitaciones al contenido del contrato.- Siendo la libertad de configuración interna
una manifestación de la autonomía privada y, por ello, un poder reconocido por el ordena
miento jurídico, tal libertad sólo puede ejercitarse dentro de los límites que el propio orde
namiento le impone. La libertad de contenido no puede, obviamente, ser omnímodo. Según
nuestro Código Civil, la libertad contractual está limitada, de manera expresa e inmediata,
por su conformidad a las normas legales de carácter imperativo, tal como lo señala el artículo
1354 de dicho Código. También está limitada, de manera mediata, por el artículo V del Títu
lo Preliminar del Código, que establece que es nulo el acto jurídico contrario a las leyes que
interesan al orden público o a las buenas costumbres. La noción de libertad y autonomía no
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 430 of 1506 --

puede asimilarse a la de mero arbitrio, por lo cual, siempre presupone límites, ante todo aquel
básico respeto por los intereses ajenos. La actividad de los particulares, permaneciendo libre,
ha de someterse a la disciplina dictada por el ordenamiento que le impone una serie de reglas
y límites, a los cuales han de sujetarse si es que quieren alcanzar sus propias finalidades dentro
del derecho. En orden a ello, el Código Civil establece en su artículo 1355 que la ley, por consi
deraciones de interés social, público o ético puede imponer reglas o establecer limitaciones
al contenido de los contratos. La razón del artículo es regular el intervencionismo del Estado
en la contratación, el cual se manifiesta a través de reglas y limitaciones impuestas, que se
incorporan al contrato, formando parte de él, aun en sustitución de las cláusulas que en con
trario hubieran sido puestas por las partes. Se trata de proteger el interés público y social, que
aparecen vinculados a los principios del orden público; así como el interés ético relacionado,
más bien, con las buenas costumbres, respondiendo a criterios de moralidad.
3. Elementos y caracteres del contrato
Elementos.- La tradición nos ha trasm itido la distinción entre elementos esenciales, elemen
tos naturales y elementos accidentales del contrato. Los primeros son los requisitos generales
del contrato o los elementos de identificación de los singulares tipos contractuales, a falta de
los cuales el contrato no es calificable como perteneciente a un determinado tipo o es nulo.
Los elementos esenciales serán el consentimiento o acuerdo de las partes, la causa, el objeto y la
forma en tanto ésta constituya requisito de validez del contrato.
Consentimiento, es la concordancia de las dos o más voluntades declaradas de las partes
que celebran el contrato. El consentimiento supone la manifestación de la voluntad de las
partes, ya sea de forma expresa o de forma tácita. Al respecto el Código Civil señala:
“No hay contrato mientras las partes no estén conformes sobre todas sus estipulaciones,
aunque la discrepancia sea secundaria.” Artículo 1359 del C.C.
“El contrato queda perfeccionado en el m om entoy lugaren que la aceptación es conocida
por el oferente.” Artículo 1373 del C.C.
La causa, es la función económica social del acto de autonomía contractual.
El objeto, es la creación, regulación, modificación o extinción de relaciones jurídicas patri
moniales, aunque en forma mediata o indirecta el objeto viene referido al propósito del
contrato, es decir, la obligación que se crea. Según nuestro Código Civil “El objeto del con
trato consiste en crear, regular, modificar o extinguir obligaciones”. Art. 1402 C.C. Además,
como se indica en el artículo 1403 C.C.: “La obligación que es objeto del contrato debe ser
lícita. La prestación en que consiste la obligación y el bien que es objeto de ella deben ser
posibles”.
La forma, en principio es un elemento natural de todo contrato en tanto que es el vehículo
de exteriorización del acuerdo de voluntades; sin embargo, en sentido técnico y preciso
la forma constituye un requisito de validez cuando la ley o las partes hacen depender
de ella el perfeccionamiento y la eficacia del contrato. "Se presume que la forma que las
partes convienen adoptar anticipadamente y por escrito es requisito indispensable para
la validez del acto, bajo sanción de nulidad.” Art. 1411 del C. C.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 431 of 1506 --

Tema 2: Temas de derecho civil
Los elementos naturales se identifican con parte del contenido legal de los singulares tipos con
tractuales que se introducen al contenido del contrato por normas derogables por voluntad
de las partes, es decir, normas dispositivas supletorias (Ejemplo: Saneamiento porevicción).
Finalmente, los elementos accidentales son aquellos meramente eventuales del contrato, como
el término y la condición, que en el contrato se incluyen por voluntad de las partes y que afec
tan no a la validez, sino a la eficacia del contrato.
Caracteres:
a) Carácter temporal, lo que surte efecto es la relación jurídica obligacional. El contrato crea
esta relación y luego ya no interesa porque se agota cuando se cumple el consentimiento.
b) Su función económicay social es la que hace al contrato que sea protegida por el derecho,
es decir, que tiene la tutela jurídica.
c) Existe una distribución efectiva de riqueza, para cum plir esta función es necesaria la in
tervención del Estado, pero no con límites (señalados en el Art. 2 de la Constitución).
d) Carácter patrimonial, porque es susceptible de valoración económica.
Contenido patrimonial.- Para precisar el ámbito del contrato el artículo 1351odel Código Civil
señala que la relación jurídica creada por éste debe ser patrimonial. La relación jurídica es
patrimonial cuando versa sobre bienes o intereses que posean una naturaleza económica, es
decir, cuando son susceptibles de valoración económica. Esta valoración debe medirse de una
manera objetiva, es decir, con independencia de cuál sea la postura o actitud del sujeto con
respecto a los bienes en cuestión. Así, por ejemplo, aun cuando el interés del sujeto respecto
del bien sea puramente sentimental o de afección, la relación jurídica será patrimonial siem
pre que el bien sobre el que recaiga, objetivamente considerado, posea valor económico.
Conclusión del contrato.- Co n el us ió n del contrato es la concurrencia de las declaraciones de
voluntad para formar una declaración conjunta de una voluntad común, o sea el consenti
miento. Desde el momento en que la aceptación recoge la declaración contenida en la ofer
ta, haciéndola suya, y es conocida por el oferente, el contrato queda concluido. La conclusión
del contrato vendría a ser el evento final del procedimiento deformación del contrato, dando
lugar al perfeccionamiento del mismo. Normalmente, la conclusión del contrato consensual
lleva consigo el perfeccionamiento del mismo, porque no se necesita algo más para que el
contrato produzca efectos. Sin embargo, puede ocurrir que el contrato esté sometido a una
condición suspensiva o a la determinación de su contenido por un tercero. En estos casos se
dice por un sector de la doctrina, que el contrato estará concluido (celebrado), pues las partes
han llegado a un consenso definitivo, siendo innecesario un nuevo acuerdo de voluntades,
no obstante, lo cual no es perfecto (completo) pues no ha dado lugar a la producción de sus
efectos. De acuerdo a ello debería entenderse entonces que el contrato queda concluido por el
consentimiento. La formación del contrato en sentido estricto comienza y termina con el en
cuentro de los dos actos constitutivos del acuerdo, y que se definen como oferta y aceptación,
teniendo en cuenta su contenidoy la función que cumplen.
Clases de contratos.- Se han propuesto numerosos criterios de clasificación, los cuales se con
jugan entre sí, llegándose a proponer el siguiente:
Por la prestación: Se clasifican en unilateralesy bilaterales.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 432 of 1506 --

UBILEX
Por la valoración: Onerosos y gratuitos.
Por el riesgo: Conmutativos y aleatorios.
Por la estructura: Simplesy complejos.
Por el área: Civiles, comerciales y especiales.
Por la autonomía: Principales, accesorios y derivados.
Por la formación: Consensúales, formales y reales.
Por la regulación: Típicos y atípicos.
Por la función: Constitutivos, reguladores, m odificativosy extintivos.
Por el tiempo: De ejecución inmediata, diferida e instantáneay de duración.
Por los sujetos obligados: Individuales y colectivos.
Por la posibilidad de negociación: De negociación previa y contratos de adhesión.
Por el rol económico: Contratos de cambio, de colaboración, de prevención, de custodia
o conservación, de crédito, de garantía, de goce, de liquidación, de disposición, y de resti
tución.
4. Objeto y forma del contrato
Objeto.- La doctrina está dividida en cuanto a la determinación del objeto del contrato. Para
unos es la prestación o prestaciones que emanan de la celebración del contrato; para otros
un bien, servicio, o abstención; otros sostienen que el contrato no tiene objeto sino sólo efec
tos, en tanto que el objeto constituiría propiamente un elemento de la obligación o relación
jurídica consecuencia del contrato; finalmente, otros afirman que el objeto del contrato es la
creación, modificación o extinción de una obligación. Esta últim a posición es la recogida por
nuestro Código Civil en su artículo 1402. De lo dicho se observa que el objeto del contrato está
considerado como un propósito, esto es, la creación, regulación, modificación o extinción de
una obligación, y que, una vez lograda esa intención, el contrato ha cumplido básicamente
su cometido y lo que sigue es la relación jurídica obligacional. Luego, objeto de la obligación
es la prestación, sea de dar, hacer o no hacer; mientras que el objeto de la prestación estaría
conformado por los bienes, servicios o abstenciones. Conforme al artículo 1403 del Código Ci
vil, la obligación que es objeto del contrato debe ser lícita; en tanto que la prestación en qué
consiste la obligación y el bien que es objeto de ella, deben ser posibles, entendiéndose que
se refiere a una posibilidad físicay jurídica.
Forma.- En sentido amplio la forma es el medio por el cual se exterioriza la declaración de vo
luntad, y en el caso del contrato el acuerdo de voluntades. La voluntad tiene que manifestar
se de alguna forma para que aparezca y tenga trascendencia en el mundo del Derecho. En
tal sentido, todo contrato tendría implícita una forma determinada, utilizada por las partes
como vehículo para exteriorizar su voluntad. Así, las partes podrán servirse de cualquier me
dio, siendo las más frecuentes la forma oral o la escrita.
En sentido estricto la forma se impone como un medio concreto y determinado para la exteriori-
zación de la voluntad contractual. Aparecen así los contratos solemnes o formales en oposición a
los no formales, constituyendo la forma así entendida como un requisito esencial para la validez
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 433 of 1506 --

Tema 2: Temas de derecho civil
del contrato, bajo sanción de nulidad, a la que se denomina form alidad“adsolemnitatem”. Se di
ferencia de la formalidad "ad probatíomm", en que la exigencia de la forma en estos casos es una
facultad que queda librada a las partes, sin que esto afecte la validez del contrato.
La formalidad "ad solemnitatem" puede ser legal o convencional, en la medida en que sea la ley o el
convenio entre las partes el que lo imponga. El artículo 1352odel Código Civil consagra laformalidad
"ad solemnitatem” que nace de la ley, mientras que el artículo 1411 se refiere a la que emana de la
voluntad de las partes. Por su parte, el artículo 1412 viene referido a la formalidad "ad probationem”.
5. El consentimiento
El consentimiento consiste en la concordancia de las dos o más voluntades declaradas de las
partes que celebran el contrato. Se da por la exte rio rizad ó n de las declaraciones y su integra
ción en la oferta y aceptación. Estas declaraciones presuponen una voluntad interior que no
interesa en el contrato, solo tiene que declararse la intención de contratar o de propuesta con
tractual. Cuando se habla de consentimiento contractual hay que mantener separados los si
guientes fenómenos: a) La voluntad interna e individual de cada contratante, en el que puede
valorarse el simple querery el propósito que la guía; b) La declaración que el contratante emite
y a través de la cual su voluntad es conocida por el otro contratante; y c) lo que puede llamarse
la voluntad o intención común, es decir, aquella zona en que las dos declaraciones coinciden,
de lo contrario habría disenso o desacuerdo, pero no contrato.
Concordancia de las declaraciones: El acuerdo de las partes consiste en el encuentro de sus
respectivas manifestaciones o declaraciones de voluntad: el contrato se concluye o se perfec
ciona sólo si, o sólo cuando, se alcance plena y total coincidencia entre las declaraciones de
voluntad provenientes de los contratantes. Un acuerdo parcial, que las partes hayan alcanzado
en el curso de los tratos preliminares, no tiene efecto vinculante, sin perjuicio de la eventual
responsabilidad precontractual o violación del principio de buena fe, no se puede distinguir
entre puntos esenciales y puntos accesorios. La aceptación tiene valor de tal sólo si está total
mente conforme con la oferta, de lo contrario equivale a una nueva oferta que requeriría de la
aceptación del oferente originario.
Contenido del consentimiento: El consentimiento es un fenómeno que resulta no sólo del
concurso de las voluntades, sino de su combinación. Cada declaración debe ser emitida y, ade
más, comunicada a la contraparte. Las dos declaraciones y las correspondientes voluntades
se combinan, en el sentido de que se integran recíprocamente y son así, complementarias.
La formación del contrato en sentido estricto comienzay term ina con el encuentro de los dos
actos constitutivos del acuerdo y que se suelen definir como propuesta u oferta y aceptación,
teniendo en cuenta su contenido y la función que cumplen.
Disentimiento: El disenso o disentimiento viene a ser el fenómeno de falta de encuentro de
las voluntades de los contratantes. Existe falta de coincidencia, en otras palabras hay discre
pancia en las declaraciones de las partes que quieren celebrar un contrato, pero finalmente no
llegan a hacerlo por existir error en la declaración de una de ellas, sobre el sentido de la decla
ración de la otra. Esta falta de coincidencia debe ser involuntaria, esto es que las partesdeseen
celebrar el contrato y, en tal sentido sus declaraciones de voluntad están dirigidas a ello, pero,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 434 of 1506 --

por algo que escapa a su deseo no se produce la coincidencia de estas declaraciones, o sea la
declaración conjunta de la voluntad común. Este algo es generalmente el error.
El contrato es anulable o no existe por haber error en la declaración porque las partes no cele
bran el contrato aun cuando en realidad quieran hacerlo.
Hay dos tipos de disentimiento:
Manifiesto o Aparente: Cuando las partes obran sabedoras de la falta de encuentro de la
oferta y la aceptación, caso en el cual no se pone en duda que jamás podrá considerarse
concluido el contrato.
Oculto o Malentendido: Se reduce al desacuerdo no advertido por las partes acerca del
sentido en que cada cual entiende el contenido contractual. Es este desacuerdo el que
depende del error en que incurre un contratante sobre el sentido de la declaración del
otro, del que además, no se ha percatado.
Teoría del conocimiento y contratación entre ausentes: Se entiende por ausencia el hecho de
que una persona está separada de la otra o alejada de un determinado lugar o que, encontrán
dose físicamente presentes, no tengan posibilidad de diálogo por diferentes razones, como
podría ser el hecho de hablar idiomas distintos. Habrá ausencia, por lo tanto, en la medida de
que no exista entre oferente y destinatario una inmediata comunicación de voluntades. Para
solucionar el problema de contratación entre ausentes se ha creado cuatro sistemas o teorías
fundamentales: De la declaración, la expedición, la recepción y el conocimiento.
La teoría del conocimiento o cognición, señala que el contrato se perfecciona desde que el ofe
rente conoce la aceptación del recipiendario de la oferta. El contrato existe, por consiguiente,
sólo cuando ambas partes están informadas de que hay acuerdo entre ellas y se ha producido
la coincidencia de voluntades. Esta teoría es la asumida por nuestro Código Civil en el artí
culo 1374, adicionándose la presunción “jurís tantum " de que la aceptación es conocida en el
momento en que llegue a la dirección del oferente. La fórm ula recogida por el código es en
verdad una combinación entre los sistemas del conocim ientoy la recepción.
6. Formación del contrato
6.1. Las tratativas: La formación del contrato comprende actos o series de actos que preceden
o pueden preceder a la perfección de un contrato. Es frecuente en los contratos de importancia
económica o de cierta complejidad que antes de que se produzca el concurso entre oferta y
aceptación las partes entren en los tratos preliminares de contenido muy diverso, en los cuales
las partes noquedan obligadassino,simplementeanimadas porsuvoluntaddediscutircom o
querrían vincularse. Constituye la etapa precontractual, que se inicia cuando una de las partes
se pone en contacto con la otra o conjuntamente se dan tratos o averiguaciones sobre el nego
cio, y en la que debe estar presidida por una idea básica, la necesidad de actuar de buena fe.
Características de las tratativas:
No hay obligación de contratos.
Hay libertad para retirarse.
Hay interés en contratar.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 435 of 1506 --

Tema 2: Temas de derecho civil
Aunque las partes no asumen la obligación de llegar a un contrato asumen ciertos debe
res (buena fe objetiva: lealtad, honestidad, etc). Si la buena fe debe presidir el período
precontractual, es lógico suponer que la ruptura de las tratativas de mala fe es fuente de
responsabilidad por culpa in contrahendo o responsabilidad precontractual.
6.2. El precontrato: La formación de un contrato puede en ocasiones producirse mediante un
iter negocial complejo, de formación sucesiva, que se inicia con la celebración de un contrato
preliminar, al que se denomina también precontrato, compromiso de contrataro promesa de
contrato y al cual sucede en un momento posterior el contrato definitivo. Aunque la term i
nología puede resultar equívoca, el llamado precontrato es en sí mismo un contrato, puesto
que supone la existencia de una concorde voluntad de las partes. Lo único que sucede es que
esa concorde voluntad de las partes asigna al acuerdo entre ellas existente una pura función
preliminar o preparatoria del contrato que en definitiva entre ellas se establecerá o podrá es
tablecerse.
6.3. La oferta: La oferta o propuesta es la declaración de voluntad que requiere de otro extre
mo para crear el contrato (contrato es la integración de oferta y aceptación). En especial cons
tituye el acto de iniciativa, con el cual una de las partes, que recibe el nombre de oferente, pro
pone a la otra, que eventualmente deberá aceptar, una determinada regulación de intereses.
Naturaleza jurídica de la oferta: Existen dos posiciones muy definidas en torno a determinar
la naturaleza jurídica de la oferta para unos constituye un acto o negocio jurídico y para otros
no. Conforme al primer criterio la oferta es una declaración de voluntad que tiene el efecto
jurídico de obligar al proponente a no hacer acto alguno que haga imposible la ejecución de la
relación que surgirá cuando la otra parte la haya aceptado, por lo cual es un negocio jurídico.
Para quienes la oferta no reúne las calidades de acto o negocio jurídico, ella no consigue por
sí misma el fin inmediato relacionado con alguna adquisición, modificación o extinción de
derechos, lo cual es conseguido por el negocio jurídico denominado contrato.
Si bien la oferta contractual tiene una finalidad, que es la de hacer posible la celebración del
contrato, tal finalidad queda frustrada si la oferta no es aceptada. En tal eventualidad la oferta
es ineficaz, no es apta para producir efecto jurídico alguno, lo que determina que no pueda ser
considerada como un acto jurídico, sino como una declaración unilateral devoluntaden senti
do estricto. Consecuentemente, la oferta no tiene vida propia, sino que está destinada a cons
titu ir conjuntamente con otra u otras declaraciones unilaterales de voluntad, una declaración
bilateral o plurilateral de voluntad, que es la que produce efectos jurídicos como contrato.
Diferencias: La oferta es algo concluyente, por lo que supone em itir una proposición d efiniti
va, que encierra el ánimo de quedar obligado si la otra parte acepta. Diferente de la oferta es
la invitación a ofrecer o a contratar, que se dan cuando el que desea celebrar el contrato, en vez
de proponersu celebración en determinadas condiciones, anuncia simplemente que proyecta
celebrarlo y pide que le sean dadas a conocer las condiciones en que estarían dispuestos a
contratar a quienes interese. Habrá invitación a ofrecer, en términos generales, todas las veces
que en la declaración no se hallen contenidos los elementos esenciales del contrato.
La oferta al público es decir la destinada a persona incierta o a la generalidad, debe ser tenida
como una mera invitación a ofrecer, conforme lo establece el Art. 1388 del C.C. Sin embargo,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 436 of 1506 --

UBILEX
conforme al segundo párrafo de dicho artículo valdrá como oferta si el proponente indica que
su propuesta tiene carácter obligatorio.
Forma: La oferta no requiere una forma especial, salvo para aquellos contratos que se exija
una determinada formalidad adsolemnitatem, oque asilo hayan acordado las partes. La forma
de la propuesta debe ser idónea, según el caso, para una adecuada determinación del conteni
do contractual, y el mejor medio para esa finalidad es la declaración expresa, lo que no obsta
para que pueda resultar de una conducta concluyente y unívoca (llámese declaración tácita).
En todo caso, cualquiera que sea su forma, debe ser reconocible por su destinatario, pues de
otro modo no serviríaasufm .
Plazo: La oferta es temporal, está sujeta a un plazo el cual puede ser determinado, determ i
nadle o indeterminado.
Plazo determinado: Se señala el plazo de vigencia de la oferta.
Plazo determinable: El plazo puede ser destinado por las partes, recurriendo a un tipo de
cálculo, operaciones o informaciones.
Plazo indeterminado: El oferente no ha dicho hasta que momento vale su oferta.
Teorías sobre la vinculación del oferente: Conforme a la teoría de la libertad de revocación,
la oferta que no ha sido aceptada puede ser siempre revocada. Por otro lado, la teoría de la
obligatoriedad de la oferta, sostiene la eficacia vinculatoria de la misma. El destinatario de la
oferta tiene derecho de aceptarla o no, la oferta es obligatoria porque surte efectos, es decir,
vincula al oferente con el destinatario mediante nexo o lazo jurídico por el cual el oferente
queda sujeto al aceptante y éste con su sola aceptación puede cerrar el contrato. De acuerdo
con la posición tomada por el Código, la oferta, en principio, obliga al oferente. El artículo 1382
del C.C. sanciona la obligatoriedad de la oferta, salvo que lo contrario resulte de su propia for
mulación, desde la naturaleza de la obligación planteada o, por último, de las circunstancias
del caso, que pueden ser diversas.
El principal efecto de la obligatoriedad de la oferta es que ésta debe ser mantenida durante
todo el plazo de su vigencia, de tal manera que el destinatario está en la aptitud de aceptarla
dentro de dicho plazo, dando lugar con ello a que el contrato quede concluido.
Caducidad y revocación: La oferta caduca, es decir, deja de ser obligatoria, cuando transcurre
el plazo determinado o determinable establecido por el oferente para la aceptación sin que se
haya producido ésta. Si no se ha establecido ningún plazo, siendo así indeterminado, habrá de
entenderse vigente por todo el tiempo que la buena fe o los usos, atendiendo a la naturaleza
del contrato, impongan; fuera del cual, igualmente caduca. También caduca la oferta cuan
do el destinatario la rechaza, o cuando éste muere o deviene en incapaz. El artículo 1375 del
Código establece que la aceptación debe llegar a conocimiento del oferente dentro del plazo
establecido por él. El artículo 1385, por su parte, plantea en tres incisos diferentes hipótesis
que se traducen en la caducidad de la oferta, o sea, en el hecho de que ésta pierde fuerza vin
culante, siendo el plazo indeterminado. El primer inciso se refiere a la propuesta hecha a una
persona con la que se está en comunicación inmediata (contratación entre presentes) sin que
le haya concedido plazo, y el recipiendario no se manifiesta en el instante. El segundo inciso
se refiere a la contratación entre ausentes, también en caso de inexistencia de plazo, siendo el
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 437 of 1506 --

Tema 2 : Temas de derecho civil
razonamiento lógico el de considerar que deberá transcurrir un tiempo suficiente para que la
respuesta llegue a conocimiento del oferente, por el mismo modo de comunicación emplea
do por éste, fuera del cual la oferta igualmente habría caducado. El tercer inciso consagra el
principio de la libertad de revocación, cuando establece que caduca la oferta si antes de ser
recibida o simultáneamente con ella llega a conocimiento del destinatario la retractación del
oferente. La revocación de la oferta es, así, una declaración de voluntad de dejarla sin efecto
de carácter recepticio, pues debe ir dirigida necesariamente al destinatario de aquélla. Final
mente, el Art. 1387 establece que la muerte o incapacidad sobreviniente del destinatario de la
oferta determina la caducidad de ésta.
Clases de oferta
Ofertas alternativas.- Cuando el oferente formula varias ofertas al destinatario, en quien
sólo queda la posibilidad de elegir una de ellas, quedando automáticamente rechazadas
las demás (Artículo 1377, C.C.).
Ofertas cruzadas.- Cuando las dos partes efectúan recíprocamente y simultáneamente
ofertas y estas son coincidentes, se refieren a lo mismo, expresan una intención común.
En tal caso el contrato se perfecciona con la oferta que resulte aceptada en prim ertérm i-
no (artículo 1379, C.C.).
Ofertas al público.- Es una propuesta que tiene todos los requisitos exigidos a la oferta y
además esta oferta no va dirigida a persona particular, sino a una generalidad de terceros,
va dirigida al público en general, a todos los que puedan estar interesados en la oferta.
6.4. La contraoferta: El artículo 1376 dispone que la aceptación tardía y la aceptación opor
tuna que no sea conforme a la oferta equivalen a una contraoferta. Expresándolo, en otros
términos, el artículo quiere decir que la declaración tardía del destinatario de la oferta y la
declaración oportuna del mismo que modifica la oferta, reciben el tratam iento de una nueva
oferta. Así, si la aceptación es extemporánea o la oferta no es aceptada íntegramente, y aquel
a quien se dirigió le introduce modificaciones que somete a la consideración del primer ofe
rente, nos encontramos ante una segunda oferta, que sigue a la desestimación o rechazo de
la primera, en cuyo caso el oferente ha pasado a serlo a quien esa primera oferta iba dirigida.
Nada impide, sin embargo, que el oferente considere eficaz la aceptación tardía o la que se
haga con modificaciones, y así lo señala el segundo párrafo del artículo 1376, con el propósito
de alentar la celebración de los contratos y a condición que dé inmediato aviso en ese sentido
al aceptante. En este caso, el aviso no tiene el carácter de una nueva declaración contractual.
Su finalidad essimplemente informaral aceptante que el contratóse hacelebrado, noobstan-
te haber llegado la aceptación a conocimiento del oferente en forma tardía o aun cuando se
introdujeron modificaciones en la oferta. El aviso no es propiamente una aceptación.
6.5. La aceptación: La aceptación viene a ser una declaración de voluntad emitida por el des
tinatario de la oferta y dirigida al oferente mediante la cual aquél comunica a éste su confor
midad con los términos de la oferta. En efecto, es el medio a través del cual el destinatario
manifiesta su adhesión a la propuesta, tal como le ha sido formulada por la otra parte. Y, en
ese momento, el del encuentro y de la congruencia de los actos dispositivos de las partes inte
resadas, se celebra el acuerdo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 438 of 1506 --

UBILEX
Así como la oferta es la últim a proposición contractual, desde que contiene la propuesta defi
nitiva que el oferente hace al destinatario, la aceptación es la últim a declaración contractual,
pues con ella se forma el contrato, sin necesidad de ninguna declaración o intervención del
oferente. El aceptante, en principio, no propone nada al oferente, sólo le comunica que con su
aceptación ha quedado concluido el contrato.
Naturaleza jurídica: Su naturaleza jurídica es la misma que la de la oferta, es decir, constituye
una declaración de voluntad unilateral en sentido estricto. Tanto la oferta como la aceptación
son declaraciones de voluntad que, integrándose la una con la otra mediante la incorporación
de la primera a la segunda, dan ambas lugar a la formación del contrato.
La ofertay la aceptación constituyen las únicas declaraciones de voluntad aptas para concluir
el contrato. Cuando se unen, esta unión produce el acto o negocio bilateral. Empero, cada una
de ellas, separada de la otra, son meras declaraciones de voluntad en sentido estricto, cuya
existencia sólo tiene sentido si preparan el camino para celebrar el contrato, que de no verifi
carse, haría que aquellas desaparezcan del ámbito jurídico sin dejar huella alguna.
Características:
a) Coincidencia o congruencia con la oferta, para ello hay que analizar el contenido y no la
apariencia externa de la oferta.
b) Denota intención seriay definitiva de contratar.
c) Es oportuna, no es requisito de validez sino de eficacia,ya que debe darse dentro del pla
zo de vigencia de la oferta.
d) Va dirigida al oferente, de lo que se advierte su carácter recepticio.
e) Presenta forma o solemnidad cuando la oferta lo requiere.
f) Cierra la etapa contractual porque el aceptante tiene el poder inmenso con la aceptación
de reflejar el contenido del contrato.
Forma: Como el caso de la oferta, cuando se trata de contratos solemnes la aceptación debe
observar la formalidad requerida para el respectivo contrato. Rige entonces el principio de
libertad de forma en la declaración de aceptación, que puede incluso consistir en conductas
concluyentes (arrojar moneda al surtidor automático, o principiar la ejecución del contrato
propuesto). Sólo será preciso que la aceptación se haga bajo forma determinada cuando así lo
exige la ley para el contrato en formación, o la oferta o anteriores estipulaciones de las partes.
El artículo 1378 del Código Civil estipula que no tiene efecto la aceptación que se form ule sin
observarse la forma requerida por el oferente.
Situaciones: Oportunidad
Se pueden plantear dos hipótesis fundamentales en las cuales lafasede laaceptación adquie
re distinta relevancia prácticay el problema de la formación del contrato se ofrece en términos
diferentes.
Puede ocurrir que la aceptación se haya efectuado en presencia del proponente, quien por
ello tuvo inmediato conocimiento. En este caso el acto de adhesión no reviste de por sí mayor
alcance y la celebración del contrato, que se verificó instantáneamente, no da lugar a ningún
problema. Pero también puede suceder que transcurra un intervalo prolongado detiempo en-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 439 of 1506 --

Tema 2: Temas de derecho civil
tre la emisión de la aceptación y su conocimiento por parte del proponente, lo cual se presenta
en el caso de contrato entre ausentes. Aquí el acto de aceptación se distiende en el tiempo, con lo
cual surge el problema de determinar el momento en que deba considerarse el acuerdo.
Perfeccionamiento: La fase de perfeccionamiento de la aceptación viene a coincidir con la de
la celebración del contrato. La formación del contrato comienza y termina con el encuentro
de los dos actos constitutivos del acuerdo, que son la ofertay la aceptación. Con la aceptación
concluye el ciclo formativo del contrato, momento en el cual se celebra el acuerdo. Si bien la
aceptación existe desde el momento en que es declarada; empero, dado su carácter recepti-
cio, no produce el efecto que le es propio, o sea dar lugar a la conclusión o perfeccionamiento
del contrato, sino a partir del momento en que es conocida por el oferente. Resulta así que la
aceptación existe a partir del momento de su declaración, pero no es eficaz sino desde que es
conocida por el oferente. Conforme al artículo 1373 el contrato ha de considerarse formado o
perfeccionado en el momento y lugar en que el proponente tiene conocimiento de la acepta
ción. Evidentemente no existen problemas cuando la contratación se celebra entre presentes,
dado que en ella la oferta y la aceptación son coetáneas y no media un intervalo de tiempo
considerable entre las declaraciones de voluntad de las partes. En cambio, sí se suscitan pro
blemas tratándose de la formación de un contrato entre ausentes, pues entonces no existe
coincidencia en cuanto al momento en que se formula la aceptación y aquél en que esta es
conocida por el oferente. Por razón de la conjugación de los artículos 1373 y 1374 del Código
Civil el momento de la formación de los contratos con falta de comunicación inmediata puede
ser, bien cuando la declaración de aceptación es entregar personalmente al oferente y éste se
entera de su contenido o bien cuando llega a la dirección del oferente.
El Silencio: El silencio, en sí m ism oy por sí mismo, no tiene valor jurídico de consentimiento
tácito; sólo puede tener semejante valor si las circunstancias en las que se observa o que lo
acompañan permiten atribuirle el significado de comportamiento concluyente. Así, el silencio
circunstanciado o cualificado se produce cuando se haga una oferta frente a la cual se produz
ca un silencio que terminara teniendo valor de aceptación.
El silencio tiene, pues, valor neutral frente a la oferta, no es rechazo ni aceptación salvo en
ciertos casos (artículo 1381, CC):
Por costumbre se pueden dar supuestos en los que por razones prácticas no se quiere la
aceptación, sino que el simple silencio de aceptación puede ser particular o general.
En la invitación a ofrecer hay declaración o interés de contratary la otra parte hace la ofer
ta, si esta no es contestada este silencio será aceptación, se le ha puesto deber de diligen
cia al invitante al decir que no quiere contratar. Se forma contrato cuando ha pasado el
tiempo necesario en el cual se produce el rechazo.
Por el acuerdo previo entre las partes vía precontrato.
Renuncia y Revocación: Dentro de la línea de pensamiento fijada para los casos de la oferta
(artículo 1385, inciso 30, CC), se aplica la misma tesis respecto a la revocación de la aceptación, la
que es también susceptible de retractación por parte del destinatario de la ofertay aceptante a
la vez. De tal manera, la aceptación ya dada puede ser revocada, con tal de que la revocación
llegue a conocimiento del proponente antes de la aceptación. Debe tenerse presente que aun
