cuando la aceptación exista en tanto es declarada por el aceptante, no es eficaz sino a partir
del momento en que es conocida por el oferente, oportunidad en que da lugar a la conclusión
del contrato. De allí que no exista inconveniente conceptual para que el aceptante pueda re
tractarse de su aceptación antes que ésta llegue a conocerse por el oferente, por cuanto toda
vía no es una aceptación eficaz. Así lo ha previsto el Código Civil en el artículo 1386, al sancio
naren dicho supuesto como inexistente a la aceptación oportunamente revocada.
No cabe la retractación de la aceptación si es que la aceptación misma ha llegado antes a co
nocimiento del oferente, en virtud que por este hecho ha dejado de ser aceptación para dar
lugar a la conclusión del contrato. Portal motivo, para que pueda funcionar la retractación de
la aceptación es necesario que el aceptante utilice para em itirla un medio de comunicación
más rápido que el utilizado para comunicar su aceptación.
