7. Contratación entre ausentes
Se produce cuando no hay posibilidad de comunicación inmediata. Hay casos en los que no
hay comunicación inmediata pero sin presencia jurídica. Ejemplo en el caso de los negocian
tes que hablan distinto idioma al nuestro. Para solucionar el problema de contratación en
tre ausentes nuestro Código Civil ha adoptado en el artículo 1374 la teoría del conocimiento,
según la cual el contrato se perfecciona desde que el oferente conoce la aceptación del des
tinatario de la oferta. El contrato existe, por consiguiente, sólo cuando ambas partes están
informadas de que hay acuerdo entre ellas y se ha producido la coincidencia de voluntades;
adicionándose la presunción “juris tantum ” de que la aceptación es conocida en el momento en
que llegue a la dirección del oferente.
8. Contratación entre cónyuges
La contratación entre cónyuges es siempre posible si es que los esposos hayan establecido
un régimen de separación de bienes o tengan bienes propios. Se establece el impedimento
de los cónyuges de contratar respecto de los bienes que integran la sociedad de gananciales
en calidad de bienes sociales; lo cual significa que sí pueden contratar respecto de los bienes
propios, o en todo caso, como está dicho, siempre que hayan establecido un régimen de sepa
ración de bienes (Art. 312 CC).
Paradisponerde los bienes sociales, se requierequeen el acto de disposición intervengan am
bos cónyuges por mandato expreso del artículo 315o del Código Civil, como elemento constitu
tivo necesario para la validez del acto jurídico. Por ello, el acto de disposición de un bien social
realizado por uno solo de los cónyuges, sin la intervención del otro, es nulo por ser contrario
a una norma imperativa de orden público, según el inciso 8) del artículo 219o del Código Civil,
concordante con el artículo V del Título Preliminar del acotado Código. Precedente vinculan
te. VIII Pleno CasatorioCivil.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 441 of 1506 --

Tema 2: Temas de derecho civil
9. ■ Contratación en masa
La evolución económica y social experimentada en los últimos tiempos ha dado lugar a una
serie de mutaciones importantes en el régimen jurídico de los contratos. Un tráfico económi
co cada vez más acelerado ha ido dando origen a la aparición de una serie de modalidades
contractuales de muy difícil encasillamiento en el régimen jurídico tradicional, en el que el
contrato es un acuerdo de voluntades, un compromiso libremente convenido entre intereses
contrarios. Aparecen así los contratos en masa o contratos-tipo, impuestos a sus clientes por
grandes empresas mercantiles e industriales y referidos muchas veces a la utilización de bie
nes y servicios imprescindibles en la vida cotidiana (agua potable, gas, energía eléctrica, telé
fono, etc). Son contratos determinados por una producción masiva de bienes y servicios, que
hace imposible la discusión individualizada con cada usuario o consumidor, lo que origina
una situación de prepotencia de una de las partes. No obstante que esta modalidad contrac
tual ha sido reiteradamente criticada por cuanto adolecen de la denominada “capacidad de
negociación” de una de las partes del contrato, (el consumidor o parte débil) y por ende nos
encontramos ante contratos que son predispuestos unilateralmente, es innegable su gran im-
portanciay la función trascendental que cumplen en el derecho contractual y el tráfico comer
cial económico.
De estos nacen los contratos por adhesión y las cláusulas generales de contratación:
9.1. Contrato por adhesión: El contrato por adhesión, consideradoen sí mismo, es una mane
ra de contratar en la cual, sin perderse la autonomía privada manifestada por la libertad de
conclusión del contrato, la determinación de las condiciones del mismo es hecha unilateral
y exclusivamente por una de las partes y plasmada en su oferta, para que la otra parte, o sea
el destinatario, decida a su solo criterio contratar o no en tales condiciones. En el primer caso,
aceptará la oferta; en el segundo, la rechazará. El artículo 1390 del Código Civil establece que
el contrato es por adhesión cuando una de las partes, colocada en la alternativa de aceptar
o rechazar íntegramente las estipulaciones fijadas por la otra parte, declara su voluntad de
aceptar.
Características:
Todas las cláusulas han sido redactadas previa y unilateralmente por una de las partes,
quedando el destinatario en la sola alternativa de adherirse o no, es decir, de celebrar o
no el contrato.
El esquema planteado en forma unilateral consiste en un conjunto de cláusulas o esti
pulaciones que se predisponen para ser ofrecidas en bloque, sin que exista capacidad o
poder de negociación.
Tienen carácter técnico, se usa un lenguaje complicado (pueden conducirá un abuso de
la buena fe del consumidor).
Son redactados generalmente con letra pequeña.
El destinatario de la oferta o propuesta no es en términos generales un individuo deter
minado, sino un conjunto no precisado de personas, frente a las cuales la propuesta se
mantiene de modo duradero.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 442 of 1506 --

UBILEX
9.2. Cláusulas generales de contratación: Son aquellas redactadas previa y unilateralmente
para una persona o entidad en forma general y abstracta con el objeto de fijar el contenido
normativo de una serie indefinida de futuros contratos particulares con elementos propios
de ellos. Son cláusulas que se predisponen de una vez por todas para regular los problemas
principales que se pueden presentaren relación con la disciplina contractual de determinados
conflictos,y que constituyen, así, un reglamento agregado al contenido esencial del contrato,
destinado a tener aplicación en todo caso específico, independientemente del reenvío que a él
puedan hacer las partes. El artículo 1392 del C.C. estipula que las cláusulas generales de contra
tación son aquéllas redactadas previay unilateralmente por una persona o entidad, en forma
general y abstracta, con el objeto de fijar el contenido normativo de una serie indefinida de
futuros contratos particulares, con elementos propios de ellos.
Características:
Las cláusulas generales no son contratos, vienen incorporadas a la oferta. Son estipulacio
nes abstractas a las que el contratante se adhiere cuando suscribe el contrato individual.
Son generales y abstractas.
Se presentan en bloque pero no impide la discusión para que la oferta sea modificada. En
ellas cabe una cierta capacidad de negociación.
Permiten ahorrar tiempo en tanto dan rapidez a la contratación.
Tienen la virtud de ser completas, específicas y detalladas, constituyendo un factor de
seguridad para las partes.
10. Los contratos preparatorios
Concepto, formalidad y función que cumplen
El Código Civil de 1984, ha consagrado la institución de los contratos preparatorios, como el
común denominador de cualquier contrato que se desee celebraren el futuro, y se reduce, en
consecuencia, a preparar y asegurar situaciones jurídicas que comprometen a las partes a la
formalización o ejecución de un contrato posterior. Su función es de garantía para asegurar el
cumplim iento de un contrato a realizarse a futuro. Se utiliza normalmente un contrato prepa
ratorio cuando existen algunas dificultades de hecho o de derecho que impiden concluirlo en
el mismo acto, pero sí resulta recomendable que las partes aseguren su celebración futura. Los
contratos preparatorios pueden aplicarse a cualquier contrato, como puede ser a un mutuo,
compraventa, arrendamiento, o cualquier otro de cualquier naturaleza.
El Código Civil regula como contratos preparatorios al compromiso de contratary al contrato
de opción, y para ambos establece como causal de nulidad el supuesto de que no se celebren
en la misma forma que la ley prescribe para el contrato definitivo bajo sanción de nulidad
(artículo 1425 CC). El propósito del precepto no es otro que el de sancionar con nulidad la in
observancia de la forma solemne (adso/emnitatem) en el contrato preparatorio, cuando ésta se
exige al contrato definitivo. El contrato preparatorio de arbitraje o cláusula compromisoria lo
regula en el capítulo referido al arbitraje.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 443 of 1506 --

Tema 2: Temas de derecho civil
1. El compromiso de contratar
Por el compromiso de contratar, según el art. 1414o del C. C., las partes se obligan a celebraren
el futuro un contrato definitivo.
El compromiso de contratar debe contener minuciosamente los elementos esenciales del
contrato definitivo. Ejemplo: El contrato de compraventa tiene sujetos, objeto y forma. Tam
bién el compromiso de contratar, debe contener por lo menos, estos elementos, aparte de
otros, que las partes deseen, como una cláusula penal, la condición, el modo y plazo.
Plazo: El plazo del compromiso de contratar será no mayor de un año. En caso de que las par
tes hayan pactado un plazo mayor, se reducirá a un año, A falta de plazo convenido se conside
rara que es de un año. (Art. 1446o C.C.).
Renovación: El contrato de compromiso de contratar, puede ser renovado una vez vencido el
plazo determinado por las partes, porel plazo máximo de un añoy así sucesivamente.
Derecho de una de las partes en caso de injustificada negativa del obligado: De conformidad
al art. 1418o del Código Civil la injustificada negativa del obligado a celebrar el contrato defini
tivo, otorga a la otra parte, alternativamente, dos derechos: 1 - Exigir judicialmente la celebra
ción del contrato, o. 2.- Solicitarse deje sin efecto el compromiso de contratar. En cualquiera de
los casos, el perjudicado con el incumplimiento, tiene derecho a solicitar la indemnización por
los daños y perjuicios ocasionados.
2. El contrato de opción
Es un contrato en virtud del cual, una parte se compromete a conceder a la otra en forma ex-
clusivay temporal, el derecho a decidir a su solo arbitrio, la conclusión de un segundo contra
to, en determinadas condiciones pactadas en el primer contrato. Según el art. 1419o del Código
Civil. “Por el contrato de opción, una de las partes queda vinculada a la declaración de celebrar
en el futura un contrato definitivo y la otra tiene el derecho exclusivo de celebrarlo o no”. El
Dr. Manuel de la Puente y Lavalle, sugiere la siguiente definición del contrato de opción: es el
“Contrato por virtud del cual una de las partes se obliga irrevocablemente a mantener vigen
te por cierto tiempo y en determinadas condiciones que se precisan, una oferta exclusiva en
favor de la otra parte para que por decisión potestativa de ésta, se celebre un futuro contrato
definitivo en tales condiciones, el cual quedará perfeccionado por la sola aceptación oportuna
de la oferta.
Las características del Contrato de Opción son las siguientes: i. Sufinalidades que una de las
partes tenga el derecho, por su sola decisión de constituir otro contrato. 2. Su efecto es nece
sariamente futuro. 3. Es un contrato preparatorio. 4. Es un contrato principal. 5. Es un contrato
que deja al beneficiado en libertad absoluta para aceptar.
