Comparación de estas figuras con la opción mediatoria
Primero ¿Qué es la opción mediatoria?
La opción mediatoria ha sido recogida en el Código Civil con el propósito de facilitar la con
tratación, considerándose que no existe obstáculo para que se establezca la reserva a señalar
la persona con la que se entenderá el vínculo definitivo, en caso de que se ejercite la opción.
Señala el artículo 1421 que es igualmente válido el pacto conforme al cual el optante se reserva
el derecho de designar la persona con la que se establecerá el vínculo definitivo. La opción
mediatoria implica, que si bien el optante recibe exclusivamente el derecho, no lo recibe ne
cesariamente para sí, sino también puede transferirlo a un tercero. Sólo el optante tiene estas
facultades y es en estos términos que debe entenderse la exclusividad.
