BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 445 of 1506 --

Tema 2: Temas de derecho civil
12. El contrato a favor de tercero
La regla general es que el contrato produce efectos solamente entre las partes que lo otorgan
y sus herederos. No produce efectos respecto de estos últimos cuando se trata de derechos y
obligaciones no transmisibles. La eficacia del contrato se presenta respecto de terceros cuan
do estos últimos han sido ajenos a su celebración. Es este últim o supuesto cuando nos encon
tramos con el llamado contrato en favor de tercero. Terceros, respecto de un contrato dado,
son todos aquellos que no han sido autores del mismo. La ley autoriza que un tercero extraño
a la relación creada sea quien se beneficie con aquélla. Esto es lo que el Código Civil legisla
como “contrato en favor de tercero”. Al respecto el artículo 1457 nos da el concepto al señalar
que por el contrato en favor de tercero, el promitente se obliga frente al estipulante a cumplir
una prestación en beneficio de tercera persona. Agrega luego que el estipulante debe tener
interés propio en la celebración del contrato. De este dispositivo fluyen los elementos del con
trato en favor de tercero y, concretamente, quiénes son sus sujetos, esto es, el estipulante y el
promitente, y cómo el tercero que se beneficia de la prestación debe ser una persona extraña
a la relación contractual.
13. La promesa de la obligación o del hecho de un tercero
Normalmente, quien contrata se compromete a satisfacer directamente una prestación de
dar, hacer o no hacer. Puede suceder, empero, que ello no sea posible por consideraciones per
sonales o de otro orden o que haya interés en que alguien se obligue o ejecute un acto, pero
quien así lo requiere no pueda conseguirlo y exista en cambio quien tenga la posibilidad de
lograrlo. Se trata de situaciones que pueden presentarse bajo diversos matices y que legislati
vamente han sido resueltas a través de la denominada “promesa de la obligación o del hecho
de un tercero”. El artículo 1470 del Código Civil establece el concepto y alcances de la promesa,
señalando que se puede prometer la obligación o el hecho de un tercero, con cargo de que el
promitente quede obligado a indemnizar al otro contratante, si el tercero no asume la obliga
ción o no cumple el hecho prometido, respectivamente.
Se advierte que la obligación del promitente es una obligación de hacer, de realizar una acti
vidad propia dirigida a que el tercero se obligue o efectúe el hecho prometido. Se encuentran
dos matices de la promesa, o bien que el tercero asuma una obligación o que cumpla el hecho
prometido. Quien se obliga es el promitente en cualquiera de estos dos sentidos: obtener el
asentimiento del tercero para obligarse a realizar una prestación de dar, hacer o no hacer que
favorezca al promisario o a quien éste designe; o lograr que el tercero ejecute un hecho deter
minado que puede consistir en un dar, hacer o no hacer en favor del promisario o tercera per
sona. En cualquiera de estos casos, la no obtención por parte del promitente de la obligación
o del hecho del tercero dará lugar a que deba indemnizar al promisario.
14. Rescisión, resolución
Rescisión
La rescisión es el acto a través del cual se deja si n efecto el contrato por una razón q ue existía en
el momento en que se celebró. De lo expuesto aparece que si bien en la rescisión el contrato no
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 446 of 1506 --

UBILEX
se encuentra viciado en su origen de un modo que determine su nulidad o anulabilidad, tiene,
empero, un germen que puede conducirlo a su disolución el artículo 1370 del C.C. dispone que
la rescisión deja sin efecto (no lo invalida) un contrato por causal existente en el momento de
su celebración. Se considera que el contrato se celebró válidamente, pero que por razón de la
rescisión queda sin efecto, o sea es ineficaz. El contrato rescindido deja de dar lugar, por lo tan
to, a la creación, regulación, modificación o extinción de la relación jurídica patrimonial, pero
se reconoce su validez. Esto determina que el contrato rescindióle sea provisoriamente eficaz,
pero sujeto a la declaración judicial de ineficacia a causa de su irregularidad.
Resolución
La resolución presupone, a diferencia de la rescisión, un acto por el cual el contrato queda sin
efecto debido a la concurrencia de circunstancias sobrevinientes. La relación contractual nace
pura, y es sólo después que se presentan acontecimientos que determinan la pérdida de su
eficacia. El artículo 1371 del C.C. establece que la resolución deja sin efecto un contrato válido
por causal sobreviniente a su celebración.
Diferencias y efectos entre rescisión y resolución:
La diferencia entre rescisión y resolución radica entre en la primera se deja sin efecto un con
trato por causal existente en el momento de celebrarlo, lo que justifica la retroactividad de
sus efectos; mientras que la resolución deja sin efecto un contrato por causal sobreviniente
o posterior a su celebración, lo que explica que opere sólo a partir de que ocurre la causal y
sobre el elemento contractual que está vigente en ese momento, es decir la relación jurídica
patrimonial creada por el contrato.
Otra diferencia está en que la rescisión se declara judicialmente, pero los efectos de la sentencia
se retrotraen al momento de la celebración. En cambio, la resolución se invoca judicial o extra-
judicialmente, en ambos casos los efectos de la sentencia se retrotraen al momento en que se
produce la causal que la motiva. Así consta de lo establecido por el artículo 1372. del C.C.
Otro efecto de la rescisión es destruir las consecuencias del contrato, restituyendo las cosas al
sery estado que tenían cuando él se celebró. El efecto retroactivo obligacional de la rescisión
da lugar a que las partes deban restituirse las respectivas prestaciones si es que hubo principio
de ejecución, si ello no fuera posible se reembolsarán el valor que tenían dichas prestaciones
al momento de celebración del contrato.
Por razón de la resolución, las partes deben restituirse las prestaciones en el estado en que
se encontraba al momento en que se produce la causal que la motiva, y no desde la celebra
ción del contrato; si ello no fuera posible deben reembolsarse en dinero el valor que tenían en
aquel momento.
Cabe respecto de los efectos de la rescisión y de la resolución pacto en contrario, sin perjuicio
de los derechos adquiridos de buena fe (artículo 1372. del C.C.).
