BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 447 of 1506 --

Tema 2: Temas de derecho civil
La rescisión se declara por causal existente al momento
de la celebración dei contrato.
La declaración de la rescisión es siempre judicial.
En la rescisión ei contrato tiene un vicio de origen que no
determina la nulidad o anulabilidati, pero que puede con
ducirlo a su disolución.
Las causales de rescisión están fijadas por la ley.
La rescisión tiene efecto desde el momento de su celebra
ción, es decir, tiene efecto retroactivo obligacional,
La resolución se declara por causal sobrevimente al mo
mento de la celebración del contrato.
La declaración de la resolución puede ser judicial o ex
trajudicial.
En la resolución el contrato no adolece de ningún vicio en
su origen que pueda destruir su existencia.
Las causales de resolución pueden ser legales o conven
cionales.
La resolución tiene efecto irretroactivo (ex nunc), es decir,
el cese de los efectos se producen desde la causal sobre-
viniente y no hacia atrás.
T ip o s d e reso lució n: La resolución puede ser de origen legal, como ocurre en el caso de la re
solución por Incumplimiento contemplada en el artículo 1428 del C.C., o en el de resolución
por autoridad del acreedor a que se refiere el artículo 1429 del mismo código. Su origen puede
ser también, convencional, como es el caso del pacto comisorio regulado por el artículo 1430 del
C.C. o el del m utuo disenso.
15. Figuras jurídicas que permiten la revisión de los contratos
1. La lesión (Artículos 1447 a 1456 del Código Civil)
La lesión es una de las más importantes y controvertidas figuras jurídicas de la contratación.
El Art. 1447 del C.C. define a la lesión como una acción resclsorla que se utiliza cuando existe el
aprovechamiento de una de las partes, de la necesidad apremiante de la otra, "y ella se extiende
a todos los contratos típicos como atípleos siempre quesean a título oneroso o tengan carácter conmuta
tivo, con la salvedad del segundo párrafo del mencionado artículo.” Cas. N ° 3133- 9 7 -
La acción por lesión se aplica a los contratos con prestaciones recíprocas, a los contratos con
prestaciones autónomas (contratos Conmutativos) y a los contratos aleatorios. Se debe des
cartar total mente la aplicación de la lesión en los contratos unilaterales.
La lesión exige entonces tre s e le m e n to s para configurarse, un elemento llamado en la doc
trina o b je tiv o , referido a un desequilibrio entre las prestaciones que consiste en la diferencia
entre el valor de la prestación otorgada en favor del contratante lesionado y el supuesto valor
real u objetivo de la prestación ejecutada en favor del contratante lesionante; y otros dos de
carácter subjetivo, referidos al estado de necesidad de uno de los contratantes. Este estado
deberá ser conocido y aprovechado por la contraparte a fin de lograr el beneficio calificado
como injusto. Exp. N° 01126-2012-0-3101-JR-CI-02. Corte Superior de Justicia de Sultana. Juzgado
Especializado Civil Transitorio de Su/lana.
C aracterísticas: La lesión opera en los siguientes casos:
a. Cuando se ha causado desmedro económico en perjuicio del vendedor, por existir al mo
mento de la celebración del contrato, desequilibrio entre el valor del bien y el precio pa
gado.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 448 of 1506 --

b. Porque ha existido abuso del comprador por el estado de necesidad o inexperiencia del
lesionado.
c. Que la desproporción entre el precio pagado y el valor del bien sea mayor a las 2/5 partes
(40%).
d. Debe considerarse el valor del bien al tiempo de celebrarse el contrato.
La conjunción de estos elementos mueve el mecanismo de la lesióny puede lograrse judicial mente
la rescisión del contrato. En todo caso, le corresponde a la parte lesionada la carga de la prueba.
Lesión e x o rb ita n te : El artículo 1448 del Código Civil establece que puede darse un tipo de le
sión especial, que es la llamada lesión enorme. En este caso si la desproporción fuera igual
o superior a las dos terceras partes se presume el aprovechamiento por el lesionante de la
necesidad apremiante del lesionado. De esta manera el supuesto de lesión enorme prescinde
del elemento subjetivo, solicitando tan solo la existencia de la desproporción en 2/3 para con
figurare! supuesto lesivo.
C o n sign ació n d e la d ife re n c ia d e valor: Interpuesta la demanda de rescisión de contrato por
lesión, se concede al demandado el derecho de consignar la diferencia del valor reclamado
dentro del plazo de contestar la demanda, en cuyo caso y de hacerlo, fenece el proceso. Puede
también reconvenir para que el Juez reajuste el valor equitativamente. En la sentencia, el Juez
puede ordenar el pago de la diferencia del valor establecido, más sus intereses legales, dentro
del térm ino de 8 días, bajo apercibimiento de declararse rescindido el contrato.
N u lid a d d e la re n u n cia: El Art. 1453 del C.C. ha establecido que la cláusula que establece la
renuncia a la acción por lesión es nula de puro derecho; de esta forma se cierra el camino a las
cláusulas de estilo, impuestas por el contratante fuerte y conforme a las cuales la contraparte
estaría despojándose de un recurso de defensa tan valioso como la lesión.
C a d u c id a d d e la acción: La acción por lesión caduca a los 6 meses de cumplida la prestación,
pero en todo caso a los dos años de celebrado el contrato. Se trata de un plazo de caducidad
y no de prescripción, de modo que si se presenta, se extinguen el derecho y la acción, y no se
dan la interrupción ni la suspensión.
Im p ro c e d e n c ia d e la lesión: No procede la lesión en los siguientes casos:
a. Cuando proviene de transacción (cosa juzgada).
b. En las ventas hechas por remate público.
2. Excesiva onerosidad de la prestación: requisitos y efectos a favor de tercero
El Art. 1440 del C.C. establece que si la prestación llega a ser excesivamente onerosa por acon
tecimientos extraordinarios e imprevisibles, la parte perjudicada puede solicitar al Juez que la
reduzca o que aumente la contraprestación, a fin de que cese la excesiva onerosidad.
El Art. 1441 del Código Civil extiende el supuesto de aplicación a:
Los contratos conmutativos de ejecución inm ediatay
Los contratos aleatorios.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 449 of 1506 --

Tema 2: Temas de derecho civil
La excesiva onerosidad busca mantener vivo el contrato eliminando la desproporción, pero a
veces esto no puede darse por lo que en casos extremos se admita la resolución del contrato,
permite solicitar al juez la revisión del contrato para que éste reduzca o aumente la contra
prestación a fin de que cese la excesiva onerosidad.
Elementos condicionantes.- Los elementos condicionantes de la excesiva onerosidad son:
Que se presente en los contratos de ejecución continuada, periódicay diferida. En los con
tratos ya ejecutados no se da la excesiva onerosidad.
Que se dé la excesiva onerosidad por acontecimientos posteriores a la celebración del
contrato de carácter extraordinario e imprevisibles, como por ejemplo el alza de mate
riales, la suba de la mano de obra por un aumento no previsto de sueldos, un proceso
devaluatorio o inflacionario, entre otros casos.
El hecho extraordinario será aquel que está alejado de lo que frecuentemente suce
de como situación normal o corriente; en cambio lo imprevisible está vinculado con lo
que ordinariamente puede esperarse, esto es, lo que surge del razonamiento común y
corriente de los seres humanos. Ambos conceptos han sido, son y serán discutidos en la
doctrina y difícilmente se alcanzará consenso. En todo caso, ambos factores deberán ser
evaluados por el Juez.
La parte perjudicada, tiene el derecho de pedir al Juez la revisión del contrato, para que
reduzca la prestación o aumente la contraprestación, a fin de hacer cesar la excesiva one
rosidad.
De darse estas condiciones el Juez podrá revisar el contrato pero respecto a las prestaciones
por cumplirse, ya que las ya ejecutadas constituyen hechos consumados que no dan derecho
a revisión.
Efectos de la excesiva onerosidad:
a. - Que el Juez lo regule equitativamente.
b. - Si no fuera posible su regulación, el Juez ordenará en forma excepcional la resolución del
contrato.
c. - No es aplicable la Excesiva onerosidad a las prestaciones ejecutadas.
d. - No procede la acción por excesiva onerosidad de la prestación cuando su ejecución se ha
diferido por dolo o culpa de la parte perjudicada.
Nulidad de la cláusula sobre renuncia: Es nula la renuncia a la acción por excesiva onerosi
dad, protegiéndose de esta forma la posibilidad de evitar que por acción del contratante de
mayor poderío se imponga la renuncia, en perjuicio de la parte débil quien se vería perjudica
do al no poder ejercer un derecho tan importante.
Caducidad de la acción: La acción por excesiva onerosidad de la prestación caduca a los tres
meses de producidos los acontecimientos extraordinarios e imprevisibles.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 450 of 1506 --

UBILEX
16. Obligaciones de saneamiento: concepto» tipos y diferencias
Saneamiento
16.1. Concepto: El saneamiento se refiere a la reparación de los daños que se producen como
consecuencia de la celebración de los contratos relativos a la transferencia de la propiedad, la
posesión o el uso de un bien, mediando responsabilidad del transferente. Más que una garantía
el saneamiento es una responsabilidad objetiva es una obligación de reparación. No hay dolo o
culpa, solamente importa que el bien tiene un vicio.
En el Código Civil se observan tres casos: saneamiento por evicción, por vicios ocultos, por
hecho propio del transferente.
La institución del saneamiento por evicción, vicios ocultos y hecho propio del transferente se
fundamenta en la necesidad de reparar al adquirente por no poder destinar el bien a la finali
dad para la cual fue adquirido o cuando portales causas el bien disminuye su valor. La finali
dad de la adquisición es el factor determinante de la obligación de sanear, no contando para
nada la buena o mala fe con que haya actuado el transferente o si el contrato de transferencia
fue a título oneroso o gratuito.
Procede la obligación de sanear tanto en los contratos a título oneroso como en los a título gra
tuito por los que se transfiere la propiedad, uso o posesión de un bien.
El art. 1485 del Código Civil define al saneamiento en los siguientes términos:
"En virtud deí saneamiento el transferente está obligado a responder frente al adquirente por la evic
ción, por los vicios ocultos del bien o por sus hechos propios, que no permitan destinar el bien-trans
ferido a la finalidad para la cual fue adquirido o que disminuyan su valor".
Es decir, el saneamiento es la institución destinada exclusivamente a que el transferente com
pense (indemnice, resarza) al adquirente por la privación de su derecho a destinar el bien a la
finalidad para la cual fue adquirido o que disminuya su valor para ese efecto como consecuen
cia de la evicción, los vicios ocultos del bien o los hechos propios del transferente.
16.2. Saneamiento en ventas forzadas: Cuando se realiza una venta forzada, quien la sufre ca
rece de la libertad que es propia de las transferencias voluntarias y en vísta de ello, y con toda
justicia, se le impone sólo la obligación de restituir el precio. Así lo prevé el artículo 1490 del CC,
según el cual, en las ventas forzadas hechas por las autoridades y entidades autorizadas por ley,
el saneamiento queda limitado a la restitución del precio que produzca la transferencia.
La solución dada se justifica en el hecho que, si bien el vendedor rematando no transfiere por
su voluntad y no recibe el precio, también es cierto que se está utilizando ese precio para dis
m inuir sus obligaciones, satisfaciendo sus deudas.
La norma contenida en el artículo 1490 tiene carácter imperativoy no admite pacto en contra
rio. Además, es aplicable únicamente en los casos de ventas forzadas.
16.3. Saneamiento por evicción, por vicios ocultos, por hecho propio del transferente:
Saneamiento por evicción, es la obligación del transferente de compensar al adquirente la
privación del derecho que sufre por efecto de la evicción.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 451 of 1506 --

Tema 2: Temas de derecho civil
Saneamiento por vicio oculto, El transferente, independientemente de su buena o mala fe,
está obligado al saneamiento por vicios ocultos, llamados también redhibitorios (del la
tín redhibiré: retomar; el transferente debe retomar la cosa viciada).
En su sentido lato, los vicios redhibitorios son los defectos, imperfecciones, anomalías, de
terioros, averías, existentes en el bien al momento de la transferencia (art. 1503 del C.C.), no
susceptibles de ser apreciados a simple vista por el adquirente actuando con diligencia de
acuerdo con su aptitud personal y con las circunstancias (art. 1504 del C.C.), que disminuyan
su valoro que lo hagan inútil para la finalidad para la cual fue adquirido (art. 1485 del C.C.).
Como dice Spota, el vicio redhibitorio es un defecto oculto de la cosa, o sea, que se opone al
vicio aparente. El defecto de la cosa no es “oculto” si el adquirente lo conocía; o aun, si en razón
de “su profesión u oficio" debía conocerlo; esto últim o porque la ley exige una buena fe-diligente,
es decir, procediendo el contratante “con cuidado y previsión”.
Saneamiento por hecho propio del transferente, La obligación de saneamiento por hecho propio
del transferente se debe al adquirentey a todos los que adquieran de éste el bien, sea a título
universal o particular, oneroso o gratuito.
Constituyen actos violatorios del deber contractual de abstención del transferente, por ejem
plo, que no pague el débito por el cual ha grabado con hipoteca el predio que enajena, dando
lugar a que el acreedor hipotecario ejecute judicialmente la hipoteca, y como consecuencia
el adquirente sea despojado del bien; que el vendedor después de vender un bien registrado
al comprador, lo venda por segunda vez a otra persona, quien inscribe primero la transferen
cia, razón por la que es preferida en el derecho (art. 2016 del C.C.); que el del vendedor que
quedando colindante con el comprador, después de la venta corta la vía de agua que irriga el
predio vendido; que el que habiendo vendido un bien ajeno adquiere después la propiedad de
su verdadero propietario y en cuya virtud pretende reivindicar; que el vendedor en su terreno,
después de vender una casa que el comprador adquiere por la bonita vista que tiene hacia el
mar, levante un muro que impide al adquirente gozar de esa vista; la existencia de un contrato
de arrendamiento que el adquirente está obligado a respetar y que se había ocultado por el
transferente; que el transferente demande por evicción a su adquirente alegando un mejor
derecho que el que transmitió. Actos propios del transferente, como los de los ejemplos, que
no constituyen una simple amenaza, sino que efectivamente disminuyen el valor del bien, o
lo hacen inútil para la finalidad de la adquisición, o reducen sus cualidades para que pueda
servir para esa finalidad, generan la obligación de sanear al adquirente.
Esos actos propios del transferente pueden afectar a la naturaleza misma del bien como el
caso del vendedorque quedando colindante con el comprador, corta la corriente de agua que
irriga el predio vendido, por lo que éste deviene en terreno eriazo, o puede afectar el dere
cho que el adquirente tiene sobre el bien, así cuando el que vendió un bien ajeno, adquiere
a continuación la propiedad del mismo. Los actos propios del transferente que afectan a la
naturaleza del bien constituyen vicios de hechoy los que inciden sobre el derecho que tiene el
adquirente sobre el bien constituyen vicios de derecho.
El adquirente está protegido contra los hechos propios de su transferente, sean anteriores o
posteriores a la transferencia, siempre que los anteriores no hayan sido conocidos por el ad
quirente. El límite temporal señalado por el art. 1491 del C.C. cuando establece que se debe el
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 452 of 1506 --

UBILEX
saneamiento por razón de un derechoanterior a la transferencia, no es de aplicación a la obligación
de saneamiento por hecho propio del transferente, puesto que este dispositivo se refiere a la
obligación de saneamiento en caso de evicción por razón de un derecho de tercero.
El saneamiento por las perturbaciones de derecho de un tercero, opera cuando este ha obteni
do una sentencia o resolución administrativa firme con la cual despoja (evicciona) del bien al
adquirente; si no hay evicción no hay saneamiento; este procede sobre hechos consumados.
Contrariamente, el saneamiento por las perturbaciones de derecho del transferente, es de ca
rácter preventivo; tiene por fin evitar que el adquirente sea eviccionado del bien.
16.4. Efectos
Efectos del saneamiento por evicción.- En las relaciones contractuales normales, cuando el
adquirente de un derecho a la propiedad, el uso o la posesión de un bien ignora al celebrar
el contrato que el derecho que adquiere es litigioso o que el bien sobre el cual recae dicho
derecho es ajeno, considera que el título que adquiere es firm e y que no será privado de él.
Sin embargo, si un tercero obtiene una resolución firm e que priva al adquirente del derecho
que adquirió según el contrato, lo racional es que sea indemnizado por el transferente de los
perjuicios que sufre por razón de tal privación. El artículo 1495 del CC establece los alcances de
esa indemnización en el caso de una evicción total del adquirente, o sea cuando es privado de
todo su derecho a la propiedad, el uso o la posesión del bien por resolución firme. Se trata de
una responsabilidad objetiva que opera con prescindencia del dolo o culpa del transferente,
salvo el caso del inciso 70 Los conceptos que cubre la indemnización por evicción total son los
siguientes:
1) El valor del bien al momento de la evicción, teniendo en cuenta la finalidad para la que
fue adquirido.
z) Los intereses legales desde que se produce la evicción.
3) Los frutos devengados por el bien durante el tiempo que lo poseyó de buena fe o su valor,
si fue obligado a devolverlos con el mismo bien.
4) Las costas del juicio de evicción, en caso de haber sido obligado a pagarlas.
5) Los tributos y gastos del contrato que hayan sido de cargo del adquirente.
6) Todas las mejoras hechas de buena fe por el adquirente, no abonadas por el evicente.
7) La indemnización de dañosy perjuicios, cuando el transferente incurrió en dolo o culpa al
celebrar el contrato.
En caso de evicción parcial, señala el artículo 1501 del CC que el adquirente tiene derecho a
recibir el valor de la parte del bien cuyo derecho se pierde. Sin embargo, puede optar por la re
solución del contrato, si esa parte es de tal importancia con respecto al todo que la haga inútil
con la finalidad de la adquisición.
Efectos del saneamiento por vicios ocultos.- Conforme al artículo 1511 del CC, el adquirente
puede pedir, en razón del saneamiento a que está obligado el transferente, la resolución del
contrato (acción redhibitoria). Los efectos de esta resolución son similares a los contemplados
en los incisos i° al 40,y el 70 del artículo 1495 del CC, referente a los efectos del saneamiento por
