Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 453 of 1506 --

Tema 2: Temas de derecho civil
evicción,y están contemplados en el artículo 1512 de dicho Código, según el cual la resolución
impone al transferente la obligación de pagar al adquirente:
1) El valor que tendría el bien al momento de la resolución, si es que lo afecta, teniendo en
cuenta la finalidad de la adquisición.
2) Los intereses legales desde el momento de la citación con la demanda.
3) Los gastos o tributos del contrato pagados por el adquirente.
4) Los frutos del bien que estuviesen pendientes al momento de la resolución.
5) La indemnización de daños y perjuicios, cuando el transferente haya incurrido en dolo o
culpa respecto de la existencia de los vicios.
Conforme al Art. 1513 del CC, el adquirente puede optar por pedir que se le pague lo que el bien
vale de menos, por razón del vicio oculto (acción estimatoria o “quanti m''moris”), ello sin per
juicio de reclamar, asimismo, la indemnización de daños y perjuicios, cuando el transferente
haya incurrido en dolo o culpa.
Efectos del saneamiento por hecho propio del transferente.- El artículo 1525 del CC otorga al
saneamiento por hecho propio del transferente el mismo efecto que el saneamiento por vicios
ocultos, o sea la posibilidad de entablar las acciones redhibitoria o la estimatoria.
17. Las arras
Concepto, tipos, diferencias y utilidad de la figura
Es una figura jurídica netamente contractual. Las arras son un acto accesorio mediante el cual
las partes acuerdan entre entregar un bien o dinero. Desde el derecho romano hablar de arras
involucraba la entrega de un bien material o de dinero. Cuando la entrega de arras (o sea estos
bienes materiales o dinero) se hacía con miras al cumplim iento del contrato o sea de confir
marlo recibían el nombre de "arras confirmatorias’’. En cambio, cuando la entrega de las arras
se hacía con el objetivo de apartarse del contrato posteriormente, o sea de resolverlo, reci bían
el nombre de "arras penitenciales”.
Cabe aclarar que nuestro Código Civil peruano de 1984 regula a las arras en dos títulos. Título
XIII (Arras confirmatorias) y Título XIV (Arras de retractación) no existiendo propiamente un
título específico para las “Arras penales” pues estas en realidad están comprendidas dentro
de aquel títu lo y se manifiestan cuando quien da las arras (o quien las recibe) para concluir el
contrato lo incumple después.
Las arras pueden ser de tres tipos:
1) Arras confirmatorias: Tienen por función confirmar la existencia de un contrato ya cele
brado para probar la existencia del mismo. La entrega de las arras confirmatorias im p li
ca la conclusión del contrato. (Art. 1477 C.C.) Podemos definir a las arras confirmatorias
como aquellos bienes físicos o dinero que da una de las partes de la relación contractual
para la conclusión del mismo (constituyendo a su vez un medio de prueba de la celebra
ción del contrato). En caso de cumplimiento del contrato quien las recibió podrá o bien
devolverlas o imputarlas a su crédito. No obstante, cuando las arras tengan una naturale
za distinta al crédito de quien las recibió éste deberá devolverlas.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 454 of 1506 --

UBILEX
2) Arras Penitencíales: Señala Aníbal Torres “Las arras confirmatorias devienen en penales
por incumplimiento del contrato. Si se incumple el contrato, el efecto de las arras con
firmatorias es perderlas o devolverlas dobladas, según que el incumplimiento se deba a
causa imputable al que las entregó o al que las recibió. Es decir, las arras que en un prin
cipio fueron confirmatorias devienen en penales. La pérdida o la devolución doblada de
las arras es una sanción civil para el contratante que ha incumplido el contrato y evita a la
parte perjudicada con el incumplimiento el tener que recurrir necesariamente a jueces o
árbitros demandado el cumplim iento o la resolución del contrato, más la indemnización
de daños, con los consiguientes gastos y pérdida de tiempo.”
Es el Art. 1478 del C.C. el que los establece como penalidad correspondiente, ante el in
cumplim iento de la obligación.
3) Arras de Retractación: Tienen la función de otorgar derecho de retractación y este
es un derecho de e xtinguir el contrato, de no ejecutarlo, que es d istinto al incu m p li
miento. Cualquiera de las dos partes puede ejercer su derecho a partir de las arras y
retractarse. Si se retracta quien otorgó las arras las pierde, y si se retracta quien las
recibe tiene que devolverlas dobladas. Sólo se adm iten para los contratos preparato
rios. (Art. 1480 C.C.).
18. Contratos nominados
18.1. Compraventa
Concepto y elementos: El artículo 1529o del Código Civil define el contrato de compraventa
de la siguiente manera: “Por la compraventa, el vendedor se obliga a transferir la propiedad
de un bien al comprador y éste a pagar su precio en dinero”. Este artículo conserva el carácter
consensual de la compraventa en tanto que como contrato queda perfeccionado con el con
sentimiento sobre el bien vendido y el precio, generando una “obligación de transferir", que
debedeservaloradadeacuerdoaquesi el bien materia de la compraventa es un bien mueble
o inmueble, en donde serán necesarias, para consumar el efecto traslativo según corresponda,
la entrega o la simple exigibilidad de la obligación generada.
Según la jurisprudencia:
"La formalidad del otorgamiento de escritura pública no constituye, en nuestra norma sustantiva, ,
un requisito del contrato de compraventa, toda vez que en nuestro o r & ^ b j j e / ^
contrato es de carácter consensual; sin embargo, tal formalidad es una garantía de comprobación
de la realidad del acto y su inscripción en el Registro correspondiente permitirá al adquirente ejer
cer su derecho de propietario plenamente". Exp. N° 48-98, Primera Sala GivilGotpomíimSubespeeialí&mvi;
zatla en Procesos Sumarisimos y no Contenciosos de la Corte Superior de Lima. - - . ,
El solo consentimiento generará la obligación del vendedor de transferir la propiedad del bien
al comprador pudiéndose producir la entrega efectiva del bien en un momento posterior sin
generar problema alguno. No obstante, incluso en este caso, el comprador no tendría la plena
certeza de haber adquirido la propiedad del mencionado bien sino hasta que haga oponible
erga omnes tal derecho (título) inscribiendo la compraventa en los registros públicos.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 455 of 1506 --

Tema 2: Temas de derecho civil
Características:
1) Es un contrato obligatorio pero con una finalidad traslativa de dom inio pues el vendedor
se obliga a transferir la propiedad (tiene una finalidad más reducida con respecto a la
legislación comparada.
2) Es recíproco (sinalagmático) por que se generan obligaciones en ambas partes las que
se encuentran original y funcionalmente vinculadas. Esta coligación existente entre las
obligaciones a cargo de ambas partes recibe el nombre de “sinalagma”, concepto donde
descansa el fundamento de las acciones de resolución y excepción por incumplimiento
principalmente.
3) Es oneroso pues ambas partes asumen prestaciones con un valor objetivo o subjetivo
equivalente.
4) Es consensual pues para su conclusión la compraventa requiere solo de la confluencia de
las declaraciones de las partes.
5) Es conmutativa porque el vendedor sabe que está obligado a entregar un bien a cambio
de una determinada cantidad de dinero y el comprador igualmente se obliga a entregar
una cantidad de dinero a cambio de un bien, es decir existe certidumbre sobre la existen
cia de prestaciones correlativas.
6) Existe una sola excepción en que la compraventa no es conmutativa sino aleatoria y ésta
es la compraventa de bien futuro, es el caso de la emptio spei, llamada también compra
venta de la esperanza.
Elementos:
1. Los sujetos (vendedory comprador).
2. El objeto (el bien materia de la venta).
3. La transferencia de la propiedad del bien.
4. El precio.
Obligaciones del vendedor:
1. Perfeccionar la transferencia de la propiedad del bien materia del contrato (Art.1549 C.C.)
2. Entregar el bien en el estado en que se encuentre en el momento de la celebración del
contrato, incluyendo sus accesorios (Art. 1550o C.C.). Los bienes inmuebles se transfieren
con el consentimiento de las partes expresado en el contrato (La Escritura Pública es ga
rantía del comprador fren te a terceros). En los bienes muebles se requiere la entrega física
del bien, o tradición.
3. Garantizar por el buen estado y calidad del bien; de tal manera que éste no oculte vicio o
defecto alguno que lo invalide, o reduzca su verdadero valor; o sea inadecuado para los
fines que motivaron la decisión de compra.
Obligaciones del comprador: El comprador está obligado a pagar el precio en el momento, de
la maneray en el lugar pactado. Si no existe convenio, debe pagarlo al contado en el momento
y lugar de la entrega del bien. Si el pago no puede hacerlo en el momento de la entrega del
bien, lo hará en el dom icilio del comprador. El precio se puede pagar en dinero en efectivo; y
en especiey dinero; al contado o a plazos; porel comprador o un tercero, salvo pacto contrario.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 456 of 1506 --

UBILEX
O fosen materia devenía: Es toda entidad material o inmaterial susceptible de ser aprovecha
da económicamente. Para dicho aprovechamiento debe gozar de autonomía física y jurídica.
Existen tres condiciones que deben de reunir los bienes materia de la Compraventa:
1) Existencia o posibilidad de existencia. La existencia debe darse al momento de la cele
bración del contrato. Como posibilidad de existencia entendemos la no existencia en el
momento de la celebración, pero con una esperanza objetiva de que llegue a existir, por
ejemplo, los bienes futuros.
2) Que sean determinados o determinables. Por “determinado” entendemos al bien cierto so
bre el cual se ha alcanzado el máximo grado de identificación y especificación individualizada
o elegida. Por bien determinable entendemos a aquel bien susceptible de individualización
de determinación en la medida en que las partes han fijado cual es el criterio para ello.
3) Bienes cuya circulación no está prohibida por ley. La posibilidad del tráfico jurídico en
marcada en que no exista prohibición para que el bien pueda ser insertado como objeto
de la compraventa.
Estos tres requisitos han sido recogidos por nuestro Código Civil en el artículo 1532o
Determinación del precio
El Precio: viene a ser la contraprestación económica asumida por la atribución del bien. Su
concepto jurídico lo presenta como el equivalente dinerario que se da a cambio del bien.
Tiene tres requisitos.-
1) Debe consistir en dinero o en signo monetario que lo represente.
2) Debe ser cierto.
3) Debe ser real y equivalente (no contemplado en la legislación), esto significa que el pre
cio pactado por las partes debe ser realmente exigido y pagado, así como que este debe
guardar una equivalencia con el valor del bien.
El Art. 1531o del C.C. establece la problemática del precio mixto. El primer párrafo del citado
artículo establece que al fijarse el precio en parte en dineroy en parte en otro bien, la califica
ción del contrato, se efectuará de acuerdo a la intención manifiesta de las partes, sin impor
tar el nombre que se le haya otorgado, pudiendo ser compraventa o permuta de acuerdo a la
interpretación efectuada. El segundo párrafo de dicho artículo establece que si no consta la
intención de las partes, el contrato es de permuta cuando el valor del bien es igual o excede al
del dinero y de compraventa si es menor.
Transferencia del riesgo por pérdida del bien.- El riesgo por pérdida de bienes ciertos, no
imputables a los contratantes, pasa al comprador en el momento de su entrega (Art. 1567o del
C.C.).
Los elementos o requisitos para el desplazamiento del riesgo al comprador son:
1. Que sean los bienes ciertos o identificables, o debidamente certificados o identificados.
2. Que se produzca la pérdida total o parcial de los bienes.
3. Que la pérdida no sea imputable a las partes.
4. Que el vendedor haya efectuado la entrega del bien (Art. 9 0 i°y 902o del C.C.)
P56 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 457 of 1506 --

Tema 2: Temas de derecho civil
5. Si, encontrándose a su disposición, no lo recibe en e! momento señalado en el contrato
para su entrega (Art. 1567o C.C. concordante con el Art, 1569o C.C.).
6 . Cuando a pedido del comprador, el vendedor expide el bien a lugar distinto a aquel en
que debió ser entregado; el riesgo de la pérdida pasa al compradora partir del momento
de su expedición.
Pactos especiales que pueden integrar la compraventa.- Con excepción de los pactos de me
jor compradory de preferencia, que desestabilizan y obstaculizan la actividad contractual; la
compraventa puede ser integrada por toda clase de pactos válidos; siendo los más comunes:
1. - El Pacto de Reserva de Propiedad: Por el cual se puede pactar que el vendedor se reserva
la propiedad del bien, hasta que el comprador haya pagado la totalidad del precio, o una
parte determinada de él, aunque el bien haya sido entregado y venga siendo utilizado
por el comprador; el mismo que al pagar el importe del precio convenido, se convierte
automáticamente en propietario (Art. 1583o C.C.).
2. - Pacto de Retroventa: Por el cual la Ley faculta al vendedora recobrar el bien, devolviendo
el precio dentro de un plazo establecido en el contrato; vale decir que por la retroventa, el
vendedor adquiere el derecho de resolver el contrato, sin necesidad de decisión judicial
(Art. 1586o del CC.).
La retroventa resulta un pacto accesorio al contrato de compraventa que debe convenirse
expresamente la facultad del vendedor de recuperar el bien vendido, devolviendo el pre
cio, dentro del plazo y condiciones previstas, dentro de ellas la obligación del vendedor
de reembolsar las mejoras necesariasy útiles que haya efectuado el comprador.
El Art. 1587 del C.C. establece la nulidad de la estipulación que impone al vendedor la
obligación de devolver una suma mayor al precio pagado o el obtener una ventaja como
contrapartida por el ejercicio de la acción de resolución del contrato. El plazo máximo
fijado por el Art. 1588 del C.C. es de 02 años, tratándose de la venta de inmuebles, y de 01
año, en el caso de muebles. Si las partes hubieran fijado un plazo mayor, éste se reducirá
al plazo legal referido. Portratarsede una resolución del contratoy no de una rescisión, la
retroventa no opera retroactivamente, por lo tanto, sólo tiene efecto desde el momento
en que el vendedor ejercita su derecho de resolución.
Pactos prohibidos en la compraventa.-
El Art. 1582 del C.C. establece que son nulos los siguientes pactos:
1. - Pacto de mejor comprador.- Conocido como pacto de mejor oferta, y es aquel en virtud
del cual, se considera como tal, el acuerdo que tiende a rescindirse el contrato porencon- -
trarse un nuevo comprador que ofrezca mejores condiciones. En este caso el comprador
se obligaría a devolver el bien.
2. - Pacto de preferencia.- Cuando el vendedor queda obligado a ofrecer la venta del bien al
comprador preferente, en las condiciones que otro proponga, cuando pretenda enajenarlo.
Modalidades de compraventa.- Por su trascendencia practica se han regulado las m odali
dades de compraventa especiales más importantes, las que se califican como tales especí
ficamente por la singularidad de la forma de entrega del bien materia de trasferencia. Así
tenemos la compraventa a satisfacción del comprador, compraventa a prueba, compraventa
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 457

-- 458 of 1506 --

UBILEX
sobre medida y compraventa sobre documentos; formas de compraventa que contienen in
trínsecamente limitaciones a la eficacia del contrato vinculadas a las expectativas de las partes
con respecto al bien materia del contrato.
Derecho de retracto.- De acuerdo con el artículo 1592 del C.C. "el derecho de retracto es el que
la ley otorga a determinadas personas para subrogarse en el lugar del com pradory en todas
las estipulaciones del contrato de compraventa. El retrayente debe reembolsar al adquiriente
el precio, los tributos y gastos pagados por éste y, en su caso, los intereses pactados. Es impro
cedente el retracto en las ventas hechas por remate público.”
La definición contenida en este artículo es bastante completa pues destaca las siguientes caracte
rísticas del derecho de retracto: i - Es un derecho otorgado por la ley; no puede crearse convencio
nalmente. 2.-Sólo gozan del derecho determinadas personas, señaladas taxativamente por la ley.
3 - El derecho consiste en la subrogación de estas personas en el lugar del compradory en todas las
estipulaciones del contrato de compraventa. 4 - Quien ejerce el retracto debe reembolsar al com
prador el precio, los tributos y gastos pagados por éste y, en su caso, los intereses pactados.
Así, la ley crea el derecho de retracto y lo pone a disposición del retrayente, que es un tercero
calificado, correspondiendo a éste activar o no tal derecho en su favor cuando el propietario
del bien proceda a enajenarlo. Si el retrayente se decide a hacerlo se coloca en el lugar del
comprador en el previo contrato de compraventa, sin que se modifiquen las estipulaciones de
este contrato, salvo en lo relativo al cambio de personas.
Actos a los que se aplica: Según el artículo 1592 del C.C., el derecho de retracto procede en el
contrato de compraventa, el artículo 1593 del mismo Código agrega que también procede en
la dación en pago. Por otro lado, el artículo 1603 del C.C. señala que la permuta se rige por las
disposiciones sobre compraventa, en lo que sean aplicables, por tanto, se puede concluir que
se aplica también para la permuta en ciertos casos. Señala Arias Schreiber que “para la apli
cación de las reglas sobre el derecho de retracto a la permuta será preciso que la prestación
a cargo del permutante (seudocomprador) sea una de dar bienes fungibles, a fin de que el
retrayente esté en aptitud de entregar al permutante (seudocomprador) el equivalente de lo
que él a su vez entregó a su contraparte (seudovendedor).
18.2. Suministro
Concepto: Por el contrato de suministro (o de abastecimiento), el suministrante (o proveedor)
se obliga a ejecutar a favor del suministrado (o beneficiario o suministratario) prestaciones
periódicas o continuadas de bienes o servicios, a cambio de una contraprestación o a título de
liberalidad. A falta de pacto el suministro se presume oneroso19.
El art. 1604 del C.C. define el suministro como el contrato porel cual “el suministrante se obliga
a ejecutar a favor de otra persona prestaciones periódicas o continuadas de bienes".
19 Formas de suministro existieron desde tiempos remotos en el campo del derecho público con el fin de asegu
rar la provisión de víveres, armas y utensilios a los ejércitos o para la ejecución de obras públicas o la adquisi
ción de bienes para la satisfacción de las necesidades del Estado, así como para la satisfacción de los servicios
públicos prestados porel Estado a la colectividad. En el ámbito del derecho privado, el contrato de suministro
evoluciona paralelamente al crecimiento de la producción y el tráfico industrial y comercial que dieron lugar
al surgimiento de necesidades duraderas que satisfacer.
58 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 459 of 1506 --

Tema 2: Temas de derecho civil
C a ra cterís tic as d el c o n tra to d e s u m in is tro
1) Es co n sensual. Así se desprende del art. 1605 que dispone que "la exlstenciay el conteni
do del suministro puede probarse por cualquiera de los medios que permite la ley”. No
obstante, “si se hubiera celebrado por escrito, el mérito del instrumento respectivo preva
lecerá sobre todos los otros medios probatorios” (forma ad probationem ).
Si el contrato se celebra a título de liberalidad debe formalizarse por escrito, bajo sanción
de nulidad (art. 1605 C.C.). En este caso, la validez del contrato de suministro está subor
dinada a la redacción de un documento público o privado (forma adsolemnitatem). A falta
de documento el contrato es nulo.
2) Es un típ ic o c o n tra to d e d u ra c ió n , destinado a desarrollarse en un período durante el
cual las partes se someten a recíprocas obligaciones, salvo el suministro gratuito en el que
se obliga únicamente el suministrante. La duración no afecta solamente a la obligación,
sino también al cumplim iento que se prolonga por toda la vida del contrato y es satisfe
cha mediante la ejecución de prestaciones periódicas o continuadas, como única forma
por la que el suministrado pueda cubrir sus necesidades y que, como derecho habiente,
no podría aceptar que las prestaciones se agoten en un solo acto (por ello, también, el
contrato de suministro pertenece a la categoría de los detracto sucesivo).
El contrato no termina su eficacia en un solo acto de prestación y contraprestación, sino
que impone nuevos actos de cumplimiento en tanto perduren y se reproduzcan las ne
cesidades del suministrado por la vigencia del contrato. Existe proporcionalidad entre
utilidad y duración, entre duración y cuantía total de las prestaciones, a mayor duración
mayor cantidad de prestación total (proporcionalidad que no se da en la compraventa).
3) Es un c o n tra to único. Sea el suministro periódico o continuado, es único contractual y
obligatoriamente. Las prestaciones singulares gozan de autonomía propia y a su vez es
tán conectadas entre sí por provenir de un solo contrato, por ser todas del mismo conteni
do y, a veces, por tener todas el mismo precio.
Precisamente, la distinción entre el suministro periódico y la venta a cuotas “se traza en
términos inequívocos cuando se dice que el prorrateo atañe a la ejecución (cum plimien
to) de la prestación unitariamente negociada, mientras que en el suministro la distribu
ción de las entregas no es más que la consecuencia de la pluralidad de los objetos y de
las correspondientes prestaciones comprometidas”. En la compraventa la prestación es
única aunque su ejecución se puede fraccionar en el tiempo. En cambio, en el suministro
hay pluralidad de prestaciones autónomas; no importa tanto la suma de las prestaciones
(como en la compraventa) sino cada una de las prestaciones aisladas.
4) Es un c o n tra to d e p res tac io n es recíprocas. A la obligación del suministrante de entregar
los bienes que son objeto de su prestación corresponde la correlativa obligación del su
ministrado de pagar el precio. Por eso, es aplicable al suministrado de pagar el precio. Por
eso, es aplicable al suministro la exceptio non adim pleti contractus (art. 1426 C.C.), la excep-
Fue individualizado como contrato autónomo, en razón de la fundón económica que cumple, recién en la
legislación civil rusa de 1923, luego en el Código Civil Italiano de 1942, de donde pasó al Código de Comercio
Colombiano de 1971 y al Código Civil peruano de 1984.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 460 of 1506 --

UBILEX
ción de caducidad (art. 1427 C.C.), la resolución del contrato por incumplimiento (art. 1428
C.C.), la teoría del riesgo (arts. 1431 a 1433 del C.C.).
El contrato de suministro que se celebra a título de liberalidad es de prestaciones unilate
rales. Estas corren a cargo del suministrante sin que el beneficiario se obligue a nada.
5) Es o n ero so porque del suministro se derivan ventajas económicas para ambas partes con
tratantes. Empero, si se celebra a título de liberalidad es gratuito.
6) Es c o n m u ta tiv o , entendida la conmutatividad en su doble acepción: a) como equivalen
cia de valores que existe entre cada prestación singulary su correspondiente contrapres
tación. Por esta razón es de aplicación al suministro la rescisión del contrato por lesión
(art. 1447 C.C.). Por esta misma característica y además por ser un contrato de duración
procede la revisión o la resolución del contrato de suministro por sobrevenida excesiva
onerosidad de la prestación (art. 1440 C.C.).- y b) como que las partes, desde el momento
mismo del perfeccionamiento del contrato, saben de las ventajas y desventajas que les
puede reportar el suministro a cada una de ellas, salvo el cambio anormal de las circuns
tancias que haga imposible prever esa situación. No es un contrato aleatorio.
7) Es, a d e m á s , un c o n tra to típ ic o , p rin c ip a l, im p e rs o n a l. Aunque, en principio, es de libre
discusión, suele estipularse con frecuencia mediante formularios y condiciones estereo
tipadas (contratos por adhesión y contratos concluidos mediante cláusulas generales
de contratación). Es un contrato complejo debido a que de él surge una pluralidad de
prestaciones autónomas pero conexas entre sí (elimina la pluralidad de contratos con sus
siguientes molestias).
Forma:
El Suministro puede ser.-
a. P eriód ico: Cuando el precio se abona en el acto de las prestaciones singulares y en pro
porción a cada una de ellas (Art. 1608o del C.C.).
b. C o n tin u a d o : Cuando el precio se paga, a falta de pacto de acuerdo con los usos del mer
cado (Art. 1610° del C.C.)
Plazos: El Plazo establecido para las prestaciones singulares se presume Interés de ambas
partes (Art. 1611o del C.C.).
Cuando el beneficiario del suministro tiene la facultad de fijar el vencimiento de las presta
ciones singulares, debe comunicar su fecha al suministrante con un aviso previo no menor de
siete días (Art. 1612o del C.C.).
Si la duración del suministro no se encuentra establecida, cada una de las partes puede sepa
rarse el contrato dando aviso previo en el plazo pactado, o en su defecto, dentro de un plazo
no menor de treinta días (Art. 1613o del C.C.)
Pactos especiales que pueden integrar el suministro
1. Pacto de Preferencia: Cuando se pacta o establece una cláusula de preferencia en favor del
suministrante o del suministrado, la duración de la obligación no excederá de cinco años;
y se ha fijado un plazo mayor, este se reduce al mencionado límite. (Art. 1614° del C.C.)
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 461 of 1506 --

Tema 2: Temas de derecho civil
2. Pacto de exclusividad en favor del suministrante-. Cuando se ha pactado la cláusula de exclu
sividad en favor del suministrante, el beneficiario del suministro no puede recibir de ter
ceros prestaciones de la misma naturaleza, ni proveerlos con medios propios a la produc
ción de las cosas que constituyen el objeto de la prestación (Art. 1616o del C.C.)
3. Pacto de exclusividad en favor del suministrado-. Cuando se pacta en favor del beneficiario del
suministro, el suministrante no puede, directa ni indirectamente, efectuar prestaciones
de igual naturaleza que aquellas que son materia del contrato, en ningún otro lugar. (Art.
1617o del C.C.)
Tipos de incumplimiento del contrato de suministro y sus consecuencias
1. Incumplimiento en Promoción de Bienes Exclusivos-, El beneficiario del Suministro que asume
la obligación de promover la venta de los bienes que tienen en exclusividad, responde de
los daños y perjuicios si incumple esa obligación; aun cuando haya satisfecho el contrato
respecto de la cantidad mínima pactada. (Art. 1618o del C.C.)
2. Incumplimiento de Escasa Importancia-, Si el beneficiario del suministro no satisface la o bli
gación que le corresponde y este incumplimiento es de escasa importancia, el suminis
trante no puede suspender la ejecución del contrato, sin darle aviso previo (Art. 1619o del
C.C)
3. Incumplimiento de prestaciones singulares-. Cuando alguna de las partes incumple las presta
ciones singulares a que está obligada, la otra puede pedir la resolución del contrato si el
incum plim iento tiene una importancia tal que disminuya la confianza en la exactitud de
los sucesivos cumplimientos. (Art. 1620 del C.C.)
18.3. Donación
Concepto, características y forma.- El artículo 1621o del Código Civil lo define de la siguiente
manera: "Por la donación el donante se obliga a transferir gratuitamente al donatario la pro
piedad de un bien”.
La donación es un acto de liberalidad ya que una persona en forma voluntaria transfiere en
propiedad parte de su patrimonio a otra persona interviniente en la conclusión contrato. Por
ello, el contrato de donación es un contrato intervivos y no es un acto m ortis causa.
Sin embargo, los efectos del contrato de donación si pueden ser intervivos o mortis causa. Así
lo establece el artículo 1622 del C.C. al manifestar que la donación que hade producir sus efec
tos por muerte del donante, se rige por las reglas establecidas para la sucesión testamentaria.
En el contrato de donación no existe el denominado sujeto deudor de la prestación, es un con
trato con prestación unilateral, es decir, una sola parte está obligada a transferir la propiedad
a título gratuito (donante).
Característica del contrato de donación:
Es consensual, gratuito, conmutativo, individual, es un contrato principal, es unilateral,
tiene que producirse un empobrecimiento en el patrimonio del donante, es traslativo de
propiedad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 462 of 1506 --

UBILEX
derecho peruano, pluralidad de formas; estas dependen de la naturaleza del bien que se done,
de su valory hasta de las circunstancias en las que se celebra el contrato. De ahí que no pueda
hablarse de una formalidad para este contrato, sino de una pluralidad de formalidades.
a) B ienes m u eb les : el Art. 1623 del C.C. manifiesta que la donación de bienes muebles pue
de hacerse verbalmente cuando el valor del bien mueble no exceda el 25% de la UIT. El
Art. 1623 tiene una excepción contemplada en el Art. 1624 del C.C. al manifestar que si el
valor de los bienes muebles excede el límite del 25% de la UIT, el contrato de Donación se
deberá hacer por escrito de fecha cierta, bajo sanción de nulidad. Además, el instrumento
que contenga el contrato de Donación se debe especificar y valorizar los bienes que se
donan. Los bienes que pueden serobjeto de registro pueden ser joyas, cuadros valiosos.
b) B ienes In m u e b le s : Se contempla en el Art. 1625 del C.C. al manifestar que la donación de
bienes inmuebles debe hacerse por Escritura Pública, con indicación individual del in
mueble o inmuebles donados. Igualmente debe indicar el valor real y el de las cargas que
ha de satisfacer el donatario, bajo sanción de nulidad.
La legislación establece que la donación de bienes muebles con ocasión de matrimonios, bo
das o acontecimientos similares no está sujeto a las formalidades establecidas por los artícu
los i 6 2 4 °y 1625o del Código civil.
La donación de un bien donde ambas partes saben que es ajeno se rige por lo dispuesto en los
artículos 1470,1471 y H 72 del Código Civil.
El donante no puede donar más de lo que puede disponer por testamento, es decir, solamente
puede disponer de un tercio de sus bienes si tiene hijos descendientes o cónyuge, si solamen
te tiene cónyuge puede disponer solamente de la mitad de sus bienes ya que la otra m itad le
pertenecería a su cónyuge (sociedad de gananciales), la donación es invalida cuando el do
nante exceda esta medida, el valor se regula por el valor que tengan o debían tener los bienes
al momento de la muerte del donante.
Obligaciones del donante.- La obligación del donante es la de transferir gratuitamente la
propiedad del bien materia del contrato, esta obligación tiene como prestación, al igual que
la compraventa todo comportamiento destinado a lograr el efecto traslativo dirigido a la sa
tisfacción del interés primario del comprador, efectivizando la asunción de la titularidad por
parte del comprador. Implica, fuera de la obligación de entrega, la necesidad de que se pro
porcione toda la documentación vinculada a la propiedad y al uso del bien transferido; así
como la necesidad que se efectúen todos los actos necesarios para que el contrato cumpla la
función a que se encuentra dirigido, cual es la transferencia del derecho de propiedad de un
bien gratuitamente.
Modalidades de la donación. Clases de contrato de donación:
1) D o n a c ió n Pura: No tiene ningún cargo.
2) D o n a c ió n S im p le : Cuando se trata de un solo bien del donante.
3) D o n a c ió n U n iversa l: Cuando se trata de todo el patrimonio del donante, es decir, da todo
su patrimonio en donación.
