Tema 2: Tem as de derecho civil
4 ) D o n a c ió n R e m u n e ra tiv a : Por los servicios que prestó el donatario al donante éste le rega
la un bien. Igualmente se da el caso que el donatario ha salvado la vida del donante.
5) D o n a c ió n b a jo co n d ició n : Aquellos que entregan un bien a título gratuito condicionado
a que el donatario tenga que realizar una contraprestación de carácter moral.
6) D o n a c ió n b a jo cargo: Existe un gasto que debe realizar el donatario bajo ciertos impues
tos o tributos que tiene que pagar.
Pacto de reversión
Como se puede apreciar de la lectura del artículo 1631o C.C., la reversión no es otra cosa que
una cláusula o pacto que las partes pueden incluir en el contrato de donación que celebren. Es
una condición resolutoria20.
Ni la ley ni la doctrina establecen parámetros en relación a las características o contenido de
este pacto, loque equivale a decir que el mismo podría consistir en cualquier condición reso
lutoria.
Procederemos a citar ejemplos.
a) Un joven se va a radicar a Italia. Un tío, que tiene gran cariño por él, a la vez que mucho
dinero, le obsequia un departamento en una zona residencial de Roma. En el contrato
incluye una cláusula de reversión que establece que si su sobrino, antes de cinco años, se
dedica al tráfico ilícito de drogas y es condenado por el lo, la propiedad del departamento
se ha de revertir a favor del tío.
b) Un joven planea casarse dentro de tres añosy su padre le regala, con tal anticipación, una
casa, con la condición de que revierta a su propiedad si algún día se divorcia.
Derecho de revocación
La revocación en el contrato de donación no es otra cosa que la posibilidad de resolver unilate
ralmente el contrato por parte del donante, sin intervención del donatario.
Sin embargo, resulta necesario establecer que la posibilidad de revocar la donación se debe
ría realizar fundándola en una causa expresamente contemplada por la ley. Según el artículo
1637 del C.C. “el donante puede revocar la donación por las mismas causas de indignidad para
suceder y de desheredación.”
18.4. Mutuo
Concepto, características y forma.- Es igualmente conocido como préstamo, la defi nición del
contrato de mutuo lo encontramos en el artículo 1648odel nuestro CódigoCivil. El contrato de
mutuo puede darse sobre una determinada cantidad de dinero o sobre bienes consumibles.
20 Esta cláusula constituye una verdadera condición resolutoria: la reversión se produce si el donante sobrevive
al donatario o a éste y a sus herederos. Este hecho, la supervivencia del donante al donatario o a éste y sus
herederos o la muerte de estos antes que la de aquél, es de carácter enteramente eventual ya que no depen
de en lo más mínimo de la voluntad del donante. Cumplida la condición resolutoria, el dominio que fuera
transferido al donatario queda revocado-, sus efectos se producen de pleno derecho por el cumplimiento de
la condición, si bien en caso de negarse la restitución de la cosa por el donatario o los terceros poseedores de
ella, será preciso recurrirá las vías judiciales
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

