UBILEX
El objeto del contrato de mutuo es sobre bienes consumibles o fungibles (bienes que sufren
extinción o menoscabo con el uso) o sobre una determinada cantidad de dinero.
Al momento de darse el cambio se tiene que tener en cuenta: La especie, la calidady la cantidad.
C a ra c te rís tic a s d e l c o n tra to d e m u tu o
a. El objeto del contrato es el préstamo de bienes consumibles.
b. El mutuante al entregar el bien, transfiere su propiedad, quedando facultado el m utuata
rio para disponerde el.
c. Es un contrato necesariamente temporal, pues el mutuario deberá devolver el dinero o
los bienes dentro del plazo convenido. A falta de plazo se entiende que es de 30 días con
tados desde la fecha de entrega.
d. Cuando se prestan bienes consumibles, el mutuatario se obliga a devolver otros bienes
en la cantidad, especiey calidad que sean igual a los recibidos.
e. Es un contrato oneroso, pues se ha establecido que el m utuatario debe pagar los intereses
convenidos,y a falta de convenio se pagarán intereses legales. La exoneración del pago de
intereses debe ser pactada expresamente por escrito.
f. No está sujeto a una forma prevista por la Ley, pero es recomendable por efectos probato
rios, que consten por escrito.
Obligaciones del mutuante y del mutuatario
Obligaciones del m utuatario:
Devolver otro bien de igual cantidad, calidad o especie, esto lo diferencia del Comodato
en el que se devuelven la misma cosa, entonces ya no es mutuo sino comodato.
Responde por los vicios y efectos y por evicción de los bienes entregados.
Pagar intereses al mutuante, salvo pacto en contrario.
Obligaciones del mutuante:
Transmitir el dom inio de los bienes dados en mutuo.
Responder por los riesgos de los bienes.
Responder por la evicción o saneamiento.
Plazo.- En cuanto al plazo en el contrato de mutuo, funciona la regla de la voluntad contrac
tual, el “pacta sunt servanda” sí se celebra el contrato y se fija un plazo, éste debe respetarse.
Puede suceder que no se haya pactado plazo, y en estas circunstancias funciona en forma su
pletoria el art. 1656o, que otorga un plazo legal de 30 días, porque la tendencia de la legislación
contemporánea es el favorecer al deudor, tratándosele con menos rigor, para que no caiga en
las manos del acreedor. Por esa razón el art. 1656o C.C. señala: “Cuando no se ha fijado plazo para
la devolución ni éste resulta de las circunstancias se entiende que es de 30 días contados desde la entrega".
Modalidades del mutuo
Usura Encubierta: Si en el mutuo se declara recibida mayor cantidad, que la verdadera
mente entregada, el contrato se entiende celebrado por esta última, quedando sin efecto
en cuanto al exceso”. Art. 1664 del C.C.
