18.5. Arrendamiento
Concepto.- El Arrendamiento, fue conocido en Roma como ¡a ‘‘Locatio-Conductio"z\ y es el con
trato por el que una de las partes, el Arrendador, decide ceder temporalmente el uso de un
bien a la otra, el Arrendatario, quien, a su vez, se compromete a pagarle una renta convenida
porel usoy usufructo del bien. Está considerado en el Art. i 6 6 6 °del Código Civil el mismo que
señala: “Por el arrendamiento el arrendador se obliga a ceder temporalmente al arrendatario
el uso de un bien por cierta renta convenida”.
Características.- Es Típico; Nominado; Principal; Sinalagmático; Oneroso; Conmutativo; De
Tracto Sucesivo; Consensual; Temporal; De Goce.
Obligaciones del arrendador (Arts.1678 al 1680 C.C.)
1. Está obligado a entregar al Arrendatario el bien arrendado con todos sus accesorios, en el
plazo, lugary estado convenidos. Si no se indica en el contrato el tiempo ni el lugar de la
entrega, esta debe realizarse inmediatamente donde se celebró el contrato, salvo que por
costumbre se deba efectuar en otro lug ary/o época.
2. Debe entregar el bien en buen estado de serviry con todo lo necesario para su uso.
3. A mantener al Arrendatario en el uso del bien durante el plazo del contrato y conservarlo
en buen estado para el fin del Arrendamiento.
4. A realizar durante el Arrendamiento todas las reparaciones necesarias, salvo pacto distinto.
Obligaciones de arrendatario (Arts. 1681 C.C.)
1. Recibir el bien; cuidarlo diligentemente y usarlo para el destino que se le concedió en el
contrato o al que pueda presumirse de las circunstancias.
2. Pagar puntualmente la Renta en el plazo y lugar convenidos y, a falta de convenio, cada
mes, en su domicilio.
3. Pagar puntualmente los Servicios Públicos suministrados en beneficio del bien, con suje
ción a las normas que los regulan.21
21 La voz arrendamiento proviene de arrendar, que significa “ceder o adquirir mediante precio el aprovecha
miento temporal de cosas inmuebles, o de beneficio o rentas”.
En sus orígenes, el arrendamiento podía ser de cosas, obras o servicios. La idea de servicios tiene su origen en
la ¡dea romanista de la locatio conducho, y así, si bien como señala Diez-Picazo, el que promete pagar el pre
cio se llama “conductor”, en el denominado arrendamiento de obras se invierte la terminología y el que paga
el precio es llamado “locator”. Algunos autores, como Arias Ramos, analizan la idea de locare,y otros apuntan
que la terminología nació “probablemente en hipótesis referentes a obras del Estado y que de allí pasó al
derecho privado”.
La influencia del derecho inglés y del derecho germano sentaron sus bases para complementar al derecho
romano, al grado de no admitirse en la actualidad el arrendamiento perpetuo, pues a partir de la Revolución
francesa se modifica esta situación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 465

-- 466 of 1506 --

4. Dar aviso inmediato al Arrendador de cualquier usurpación, perturbación o imposición
de servidumbre que se intente contra el bien.
5. Permitir al Arrendador que inspeccione por causa justificada el bien, previo aviso de siete
días.
6 . No introducir cambio ni modificaciones en el bien sin consentimiento del Arrendador.
7. No subarrendare! bien total o parcialmente; ni cederel contrato, sin asentimiento escrito
del Arrendador.
8 . Devolver el bien al Arrendador al vencer el plazo del contrato en el estado en que lo reci
bió, sin más deterioro que el de su uso ordinario.
9. Cumplir las demás obligaciones que estable la Ley o el contrato.
Duración del arrendamiento.- El Arrendamiento puede ser de Duración Determinada o Du
ración Indeterminada (Art. 1687o del C.C.).
1.- El Arrendamiento de duración Determinada no puede exceder de diez años.
Cuando el bien pertenece a entidades públicas o incapaces, el plazo no puede ser ma
yor de seis años. Todo plazo o prórroga que exceda los términos antes mencionados, se
reducirá automáticamente a dichos plazos. A falta de acuerdo expreso, se presume que
el Arrendamiento es de Duración Determinada en los siguientes casos y por los periodos
que se indican:
a. Cuando el Arrendamiento tenga una finalidad específica, se entiende pactado por el
tiempo necesario para llevarla a cabo.
b. Si se trata de predios ubicados en lugares de temporada, el plazo de Arrendamiento
será el de una temporada.
“Artículo 1688 del Código Civil, se debe precisar que dicho numeral preceptúa el plazo máximo
del arrendamiento de duración determinada, disposición normativa que en el presente caso ha
servido de sustento a la Sala Superior para su aplicación en tanto que la renovación automática
del contrato de arrendamiento conforme pretende la demandante, significaría en el fondo que el
plazo del contrato exceda el plazo máximo de diez (10) años que permite la norma en comento,
lo que significaría igualmente una afectación a la libertad contractual configurada en el artículo
1354 del Código Civil". Cas. N° 636-2018, Lima.
2.- El Arrendamiento de Duración indeterminada se reputa por meses u otro periodo, según
se pague la Renta (Art. 1690o del C.C.)
D e Plazos o P eriod os fo rzo so s y v o lu n ta rio s : El Arrendamiento puede ser celebrados por
periodos forzosos y periodos voluntarios, pudiendo ser estos en favor de una o ambas
partes (Art. 1691o del C.C).
Subarrendamiento, cesión de! arrendamiento y cesión de posición contractual
1. S u b a rre n d a m ie n to : Es el Arrendamiento total o parcial del bien arrendado, que celebra
el Arrendatario a favor de un tercero, a cambio de una Renta, con asentimiento escrito del
Arrendador. (Art. 1692 del C.C.)
