Tanto el Arrendatario como el subarrendatario están obligados solidariamente ante el
Arrendador con las obligaciones asumidas por el Arrendatario.
Al térm ino o conclusión del Arrendamiento se extinguen los subarrendamientos cuyos
plazos no han vencido, dejándose a salvo el derecho del subarrendatario para exigir del
Arrendatario la Indemnización correspondiente.
2. Cesión d e l A r re n d a m ie n to : Constituye la transmisión de los derechos y obligaciones del
Arrendatario en favor de un tercero que lo sustituye y se rige por la regla de la Cesión de
Posición Contractual.
3. Cesión d e Posición C o n tra c tu a l: Se origina cuando, permaneciendo invariable en la obli
gación se sustituye al acreedor o al deudor de una relación obligacional singular. Es el
contrato por el que cualquiera de las partes involucradas en otro, cuyas prestaciones no
han sido aún ejecutadas, puede ceder a tercera persona su Posición Contractual, con el
consentimiento de la otra parte.
En este c o n tra to las p artes in te rvie n e n : El Cesionario, el Cedentey el Cedido, se ponen de acuer
do para expresar su voluntad común de que la Posición Contractual del Cedente sea aceptada
y/o asumida porel Cesionario quien se sustituye en los derechosy obligaciones del Cedente.
Resolución del contrato de arrendamiento
El Arrendamiento se resuelve (Art. 1697 C.C.):
1. - Si el Arrendatario no ha pagado dos meses más quince días de la merced conductiva. Si
a la renta pactada es por periodos mayores, basta el vencimiento de un solo periodo y
además quince días. Si el alquilerse conviene por periodos menores a un mes, basta que
venzan tres periodos.
2. Si el Arrendatario da al bien otro destino o uso señalado en el contrato; o permite algún
acto contrario al Orden Público y/o a las buenas costumbres.
3. - Por subarrendar o ceder el arrendamiento contra el pacto expreso contenido en el contra
to, o sin asentimiento del arrendador.
4. - Si el Arrendador o el Arrendatario no cumple cualquiera de las obligaciones contenidas
en el contrato.
Conclusión del arrendamiento
i . C o n clusió n d el A r r e n d a m ie n to d e d u ra c ió n D e te rm in a d a :
El Arrendamiento de duración determinada concluye al vencimiento del plazo estableci
do en el contrato, sin que sea necesario aviso previo alguno de las partes.
No existe tácita reconducción, en caso de que el arrendatario permanezca en el inmueble
después del vencimiento del plazo del contrato, si no la continuación del arrendamiento
bajo sus mismas estipulaciones, hasta que el arrendador solicite su devolución, la cual
puede pedir cualquier momento. (Art. 1700o del C.C.).
