Vencido el plazo del contrato o cursado el aviso de conclusión del Arrendamiento; si el
Arrendatario no restituye el bien, el Arrendador tiene derecho a exigir su devolución y a
cobrarla penalidad convenida, o en su defecto, una prestación igual a la renta del periodo
precedente, hasta su devolución efectiva. El cobro de cualquiera de ellas no importara la
