3. C o n clusió n p o r o tras causales: Además concluye el arrendamiento, sin necesidad de de
claración judicial, en los siguientes casos (Art. 1705 C.C.):
a. Cuando el Arrendador sea vencido en juicio sobre el derecho que tenía.
b. Si es necesario para la conservación del bien que el Arrendatario lo devuelva para ser
reparado.
c. Por la destrucción total o pérdida del bien Arrendado.
d. En caso de expropiación.
e. Si dentro de los 90 días de la muerte del arrendatario, sus herederos, que usan el
bien, comunican al arrendador que no continuaran el contrato.
Cláusula de allanamiento futuro - Ley N° 30201 (Pub. 28.08.2014).- El grado de i nformalidad
al momento de la celebración del arrendamiento constituía una gran debilidad para la protec
ción de los derechos del propietario del inmueble, quien ante el incumplimiento de pago del
inquilino, o el vencimiento del plazoy la falta de devolución del bien, se encontraba desprote
gido, generando que muchos propietarios tengan recelo a la hora de alquilar sus inmuebles.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 469 of 1506 --

Tema 2: Temas de derecho civil
En este contexto se publicó la Ley 30201, Ley que crea el Registro de Deudores Judiciales Moro
sos, reglamentada por el D. S. N° 011-2014-JUS.
Con respecto a la figura del “allanamiento anticipado” en el contrato de arrendamiento de in
muebles, se trata de un acuerdo expreso entre las partes, en virtud del cual el inquilino acepta
anteladamente la desocupación del predio, previo requerimiento judicial, por las causales de
conclusión del contrato y resolución del arrendamiento por falta de pago de las rentas conve
nidas.
Para que surte efecto la citada figura jurídica, debe reunir ciertas condiciones formales, como
son el de estar incluido por escrito a través de una cláusula en el contrato de arrendamiento
de un bien inmueble, por lo que no procederá en contratos verbales, el contrato de arrenda
miento deberá contar con firmas legalizadas ante notario público o juez de paz (en aquellos
lugares donde no haya notario).
Es importante resaltar que esta cláusula de allanamiento solamente permitirá la restitución
del inmueble solo cuando haya concluido el contrato de arrendamiento o, cuando el contrato
haya sido resuelto por falta de pago, siempre que el inquilino adeuda dos meses y medio de
renta,según el Art.1697 del Código Civil. Para el lo el arrendador deberá presentar la demanda
ante el juez de paz letrado competente, una vez recibida y admitida a trámite, el juez deberá
notificarla al arrendatario, el arrendatario solo podrá oponerse a la restitución del inmueble si
logra acreditar que el contrato de arrendamiento sigue vigente o que ha cancelado el alquiler
adeudado, para ello el arrendatario solo cuenta con 6 días de plazo desde que le es notificada
la demanda, vencido el plazo establecido sin que el arrendatario logre acreditar que el contra
to sigue vigente o que pagó la renta ha sido cancelado, el juez ordenará el lanzamiento en 15
días hábiles, de conformidad con el artículo 593 del C.PC.
Con respecto a este punto, dicha norma establece que consentida o ejecutoriada la sentencia
que declara fundada la demanda, el lanzamiento se ejecutará contra todos los que ocupen el
predio, aunque no hayan participado en el proceso o no aparezcan en el acta de notificación.
Es decir, para que proceda el lanzamiento, no basta con la resolución que expida el juez de paz
letrado, sino que esta decisión debe haber quedado confirmada por el superior jerárquico, si
es que es apelada por el arrendatario, o que éste no la haya impugnado. Por lo que la restitu
ción del inmueble no sería en tan breve plazo como podría esperarse.
Ahora, la figura se refiere a un “allanamiento anticipado”, en realidad éste no es tal,ya que una
aceptación anticipada real implicaría que ante la demanda de desalojo el inquilino no tendría
defensa alguna, por el contrario la citada norma señala que el juez notifica al inquilino para
que pruebe que el contrato de arrendamiento se ha prorrogado, o que ya había pagado la
deuda pendiente antes de la resolución del contrato de arrendamiento, si el demandado no
acredita estos hechos se ordena el lanzamiento, pero si el inquilino prueba que las pretensio
nes del demandante son falsas se quedará en el inmueble.
Leasing inmobiliario (D. LEC. N° 1177 Vigente a partir del 18-07-2015).- Para Alfredo Soria
Aguilar la Ley regula, entre otras cosas, tres modalidades de contratos:
(i) El c o n tra to d e a r r e n d a m ie n to d e in m u e b le d e s tin a d o a v iv ie n d a .- El contrato de arren
damiento, previsto por el D. Leg. N°H77,es la misma figura contractual de arrendamiento
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 470 of 1506 --

del Código Civil, sólo que ahora cuenta adicionalmente con una regulación especial para
el caso específico de inmuebles destinado a vivienda.
(¡i) El c o n tra to d e a r r e n d a m ie n to d e in m u e b le con o p ció n d e c o m p ra .- Es una figura que
permite al arrendatario contar con el uso temporal del bien por un plazo determinado a
cambio del pago de cierta renta convenida a favor del arrendador, con la posibilidad de
que el arrendatario pueda convertirse en propietario de dicho bien si es que ejerce la op
ción de compra al valor del precio que se hubiere estipulado de antemano. La diferencia
de un arrendamiento-venta con un contrato de arrendamiento con opción de compra es
que, en el caso de ésta última, el bien no se transmite automáticamente con el pago de
la últim a cuota pactada, sino que el bien se transfiere solamente si es que el arrendatario
ejerce la opción conferida a su favor. Antes de la dación del D. Leg. N ° ii77, el contrato de
arrendamiento con opción de compra, en virtud de la libertad contractual, era una figura
que podía pactarse sin inconveniente legal alguno, aunque no contara con una regulación
legal específica. Una de las novedades del D.Leg. N ° ii77, para el caso específico del arren
damiento con opción de compra de inmueble destinado a vivienda, es que se precisa que
los pagos de la renta convenida no constituyen pagos a cuenta para la adquisición del
inmueble lo cual es evidente desde la perspectiva contractual, pero que, desde la óptica
tributaria, podría interpretarse de manera distinta.
(iii) El c o n tra to d e a r re n d a m ie n to -fin a n c ie ro (le a s in g ) d e in m u e b le s .-S ig u e siendo la mis
ma operación de leasing que conocemos a la fecha. Es decir, una operación de fmancia-
miento realizada por una entidad autorizada por la Superintendencia de Banca, Seguros
y AFP (SBS), que cede temporalmente el uso de un bien a cambio del pago de cuotas
periódicas de arrendamiento financieroy que incluye una opción de compra que, en caso
sea ejercido, implica el pago de un valor residual. Lo particular del leasing de inmuebles
destinados a vivienda es la regulación especial que se adiciona a las normas de leasingya
existentes.
Conceptual mente hay que tener en cuenta que el leasing no es una modalidad del con
trato de arrendamiento porque el leasing cumple una función económica distinta. El lea
sing cumple una función definanciamiento mientras que los contratos de arrendamiento
común se encuentran dentro del género de los contratos que cumplen una función de
cesión de uso temporal de un bien. En el caso del arrendamiento con opción de compra
también existe una función distinta a la simple cesión en uso temporal del bien.
El D. Leg. N°1177 propone la suscripción de los contratos que regula, a través de form ula
rios específicos para cada una de ellas: El FUA es el form ulario único de arrendamiento de
inmueble destinado para vivienda, el FUAO es el form ulario único de arrendamiento con
opción de compra de inmueble destinado a vivienday finalmente, el FUALes el form ula
rio único de arrendamiento financiero (leasing) de inmueble destinado a vivienda. Sola
mente aquellos contratos relativos a inmuebles destinados a vivienda que se suscriban a
través de los formatos correspondientes y que cumplan las demás formalidades estable
cidas por la norma, contarán con el beneficio del Proceso Único de Ejecución de Desalojo,
el Régimen Tributario Especial, entre otros que otorga esta norma. No existe sanción de
nulidad para aquellos contratos que se suscriban sin respetar el uso de formularios o que
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 471 of 1506 --

Tema 2: Temas de derecho civil
carezcan de cualquiera de las formalidades previstas por dicha normativa. En consecuen
cia, celebrar alguno de los contratos referidos en el D. Leg. N ° n 77 sin utilizar el formato
correspondiente o sin respetar alguna otra formalidad contenida en dicha norma, im p li
cará un contrato válido pero dicho contrato no contará con los beneficios otorgados por
esta ley especial,
¿Qué beneficios presenta el leasing inmobiliario en comparación con una compraventa de
inmueble?
En una compraventa de inmueble, resuelto el contrato por incumplimiento de pago del com
prador, el vendedor debe iniciar un proceso judicial de desalojo el cual suele ser extenso y en
gorroso. Esto cambia con el D. Leg. N0Y177 pues, para los contratos que se suscriban conforme
con esta norma, se crea un Procedimiento Único de Ejecución de Desalojo contra quien se
encuentre ocupando el inmueble, con plazos muy expeditivos y estrictos. Por ejemplo, venci
do el plazo para contestar la demanda de desalojo, con la contestación o sin ésta, el Juez debe
sentenciaren un plazo máximo tres días hábiles bajo responsabilidad. La norma enfatiza que
la invocación de la carga procesal no exime al Juez de su responsabilidad por incumplimiento
del plazo previsto.
El desalojo en plazos muy cortos resulta un importante beneficio para las empresas de leasing
quienes podrán contar un proceso que les permita una más rápida recuperación del inmueble
en caso de resolución contractual y no restitución del inmueble.
Diferencias entre leasing inmobiliario y el crédito hipotecario: En el crédito hipotecario, el
banco facilita los recursos económicos necesarios para que el comprador adquiera la propie
dad del inmueble. El vendedor transfiere la propiedad del inmueble a favor del comprador,
pero al operar la transferencia se hipoteca el inmueble a favor del banco, para que éste últim o
tenga una garantía en respaldo de los recursos que facilitó al comprador en esta operación.
En el leasing inmobiliario, la propiedad del inmueble la detenta la empresa de leasing. El
arrendatario financiero solamente será propietario si es que cumple con el pago del monto
total financiado y ejerce la opción de compra establecida a su favor. Si el arrendatario finan
ciero no cumple con el pago de las cuotas de leasing, por dos o más meses consecutivos, la
empresa de leasing tendrá derecho a terminar anticipadamente el contrato y a solicitar el des
alojo según el procedimiento único creado por esta norma. Todo ello, sin perjuicio de las con
secuencias jurídicas de la resolución contractual como la aplicación de penalidades, el pago
de la totalidad de las cuotas pendientes de vencimiento, intereses y hasta la indemnización
que corresponda, de ser el caso.
En el leasing inmobiliario, como en cualquier arrendamiento financiero, el arrendatario fi
nanciero no se encuentra obligado a ejercer la opción de compra. La opción de compra es un
derecho potestativo que puede ser ejercido o no por el arrendatario financiero. En caso no
ejerza la opción de compra, el arrendatario financiero estará obligado a devolver el inmueble
al vencimiento del plazo del contrato de leasing.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 471

-- 472 of 1506 --

UBILEX
18.6. Comodato
Concepto: Es un contrato que supone que el comodante entregue un bien no consumible al
comodatario para que lo use por un tiempo o una finalidad determinada. Podría existir un
comodato sobre un bien consumible pero siemprey cuando no sea consumido.
Se diferencia con el mutuo, en que los bienes entregados en el “préstamo de consumo” lo son
a título oneroso y en propiedad. Y en el comodato o “préstamo de uso» en el cual los bienes se
entregan a título gratuito y en uso, es decir, se devuelven los mismos bienes entregados con el
desgaste natural que haya acarreado su cesión temporal.
Características:
C o n sen su al. El comodato es un contrato consensual porque se perfecciona con el simple
consentimiento de las partes contratantes.
C o n tra to A u tó n o m o . El comodato es un contrato autónomo porque tiene existencia pro-
pia, es principal y no depende de otro contrato.
C o n tra to G ra tu ito . El comodato es contrato gratuito porque se cede el uso del bien sin
cobrar nada. Si por el uso del bien se pagase una renta ya no sería comodato, sino arren
damiento.
B ila te ra l. El contrato de comodato es bilateral porque intervienen dos partes contratan
tes: el comodante y el comodatario.
C o n m u ta tiv o . El comodato es un contrato conmutativo porque existe presunciones re
cíprocas y correlativas. El comodante deberá entregar el bien al comodatario, por cierto
tiempo o para cierto fin ,y éste devolverlo.
F in a lis ta . El comodato es un contrato finalista porque es de uso y disfrute de un bien. El
mismo que se entrega por cierto tiempo o para cierta finalidad.
Obligaciones del comodante y del comodatario:
Las obligaciones típicas del comodante son las descritas en el Art. 1735° del C.C. e implican la
entrega oportuna del bien, comunicar al comodatario si éste adolece de algún vicio, asumir
los gastos extraordinarios de conservación y respetar el plazo pactado o el cumplim iento de la
finalidad para la cual se concluyó.
Las obligaciones del comodatario están enumeradas en el Art. 1738odel Código Civil, y se cen
tran en la custodiay conservación del bien, empleándolo para el uso que se le dio según pacto
o uso y/o costumbre, permitiendo la inspección del mismo por parte del comodante, pagar
los gastos ordinarios de conservación, y devolver el bien dentro del tiempo de duración del
contrato.
Responsabilidades:
Si el bien es empleado en forma distinta al que fluye del contenido del contrato, el comoda
tario asume el riesgo de su perdida y de los daños ocasionados aún cuando ellos se deban a
causa no imputable, salvo que pruebe que ésta afectaría al bien utilizado en forma normal o
devuelto en su oportunidad.
El comodatario asume la responsabilidad por el perecimiento del bien incluso por causa no
imputable a él, si es que pudo haberlo evitado sustituyéndolo con uno de su propiedad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 473 of 1506 --

Tema 2: Temas de derecho civil
Si el bien fue tasado en la conclusión, la pérdida o deterioro por causas no imputables son
asumidas por el comodatario.
Acciones legalesy caducidad.-Si la causa del deterioro o modificación del bien es imputable
al comodatario la acción concreta caduca a los seis meses de recuperado. El mismo plazo de
caducidad se tiene para la acción de pago de los gastos extraordinarios.
18.7. Locación de servicios
Concepto: Este contrato implica que el locador se obliga a prestarle sus servicios al comitente
por un cierto tiempo o trabajo determinado, sin estar subordinado al comitente, a cambio de
una retribución.
Características: Es consensual, bilateral, obligatorio, principal, oneroso y personal.
Objeto y plazo: Es materia de este contrato todo tipo de servicios materiales e intelectuales.
Si se trata de servicios profesionales el plazo máximo del contrato es de 06 años y si se trata
de otro tipo de servicios el plazo es de 03 años. Si se pacta un plazo mayor este sólo puede
invocarse por el locador.
18.8. Contrato de obra
Concepto: Por el cual el contratista se obliga a efectuar una obra determinada y el comitente a
pagarle una retribución.
Características: Es un contrato obligatorio, consensual, principal, etc. En el tipo contractual se
refleja un deseo de regular las obras de construcción de inmuebles.
Derechos y obligaciones del comitente y del contratista.- Son obligaciones del comitente
proporcionar todos los materiales necesarios para efectuar la obra y al pago de la retribución
convenida.
El contratista está obligado efectuar la obra en la forma y en el plazo convenido, a dar inm e
diato aviso sobre cualquier contratiempo que pueda afectar la ejecución de la obra, a pagar los
materiales dañados recibidos del comitente si ello ha ocurrido por su negligencia.
Modalidades
Contrato de Obra a satisfacción del comitente, en donde existe la necesidad de aceptación
expresa, pues caso contrario habrá de remitirse a la pericia, siendo nulo todo pacto en
contrario.
Contrato de Obra por pieza o medida, en donde se tiene derecho a la verificación por partes y
a que se le pague el precio según a la proporción de la obra realizada.
Responsabilidades y acciones.- El contratista responde por los vicios de la obra y por las di
versidades de la misma. La recepción sin reserva, sin embargo, descarga la responsabilidad
al contratista por las diversidades, es decir por características de la obra que difieran de las
pactadas, y por los vicios externos de la misma. Existe una garantía por 05 años en que si la
obra se destruye por defectos de construcción el contratista responde si se le notifica de tal
situación dentro de los 06 meses de acaecido tal hecho. No hay responsabilidad si el contratis
ta prueba que la obra fue realizada de acuerdo a las reglas del arte y de ser el caso en estricto
