el comitente.
18.9. Mandato
Concepto: Esta figura del mandato contractual, latenemos definidaen el art. 1790o del Código
Civil señala: “Por el mandato el m andatario se obliga a realizar uno o más actos jurídicos, por cuenta y
en interés del mandante”.
El mandato se diferencia de la representación, en que ésta, es el género y aquel, la especie.
Igualmente, la representación convencional se diferencia de la representación judicial, porque
la primera, tiene un contenido amplio, que conduce a la realización de todo acto lícito; mien
tras que la segunda, es específica, porque sólo sirve para representara una persona en el pro
ceso judicial, con las facultades estipuladas en los artículos 74°y 75° del nuevo Código Procesal
Civil, según sea general o especial. Asimismo, el mandato se diferencia del albaceazgo, que es
un mandato postumo. El albacea, es un mandatario, nombrado por el testador para que lo
represente después de fallecido, mientras que el mandatario normal, es el representante en
vida del mandante.
Características: Es un contrato individual, principal, se presume oneroso, conmutativo.
Es preparatorio, ésta es una característica saltante, porque es su ejercicio lo que determina la
fructificación del contrato. Puede ser muy prolijo al ejercitarse y muy estéril si no se ejercita.
Es personal, aunque no personalísimo. Ambos contratos se basan en la confianza de la perso
na, pero mientras que el contrato personalísimo sólo debe ser desempeñado por el titu lar y
no por otros, el personal, puede ser materia de transferencia, facultándose el mandato a otra
persona, con la autorización del mandante. Esta transferencia puede ser expresa o tácita y
anterior o posterior al contrato.
Es fundamentalmente consensual, ya que no se necesita documento, salvo que sea como medio
de prueba. No exige ninguna formalidad, a diferencia del mandato judicial, que requiere de
escrita pública o de acta que se suscribe ante el juez del proceso. Por excepción, el mandato
común es formalista o solemne, cuando se trata de actos que por su trascendencia pueden
poner en peligro los bienes del mandante.
Obligaciones del mandatario y del mandante (Arts. 1793° y 1794° C.C.)
Las obligaciones del mandante son suministrar los medios necesarios para la ejecución del man
dato, al pago de la retribución, al reembolso de los gastos en cumplimiento del mandato, y a
indemnizar los dañosy perjuicios eventualmente derivados del cumplimiento del mandato.
Las obligaciones del mandatario son practicar personalmente el servicio, salvo disposición
distinta los actos materia del mandato y a cumplir las instrucciones del mandato, a comunicar
la ejecución del mandato, a rendir cuentas de su actuación en la oportunidad fijada o cuando
lo exija el mandante.
Incumplimiento: Ante el incumplimiento del contrato de mandato surgen las responsabili
dades patrimoniales derivadas de los daños irrogados y del eventual daño moral ocasionado.
Modalidades: Tenemos las siguientes:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 475 of 1506 --

Tema 2: Temas de derecho civil
- M a n d a to irre v o c a b le .- No existe en nuestro Código, una disposición que sancione esta
figura. El mandato irrevocable, supone que no puede ser revocado unilateralmente por
el mandante. En la práctica, esta figura se puede establecer en virtud del principio de que
nadie está impedido de hacer lo que la ley no prohíbe.
- M a n d a to tá c ito .- Que se califica como mandato sin representación, está establecido en el
arto 1809o que dice: “El m andatario que actúa en nombre propio adquiere los derechos y asume
las obligaciones derivadas de los actos que celebra en interésy por cuenta del mandante, aún cuando
los terceros hayan tenido conocimiento del mandato”
En este caso, el mandatario está obligado directamente en favor de la persona con quien
ha contratado, puesto que si en el fondo está actuando para el mandante, en la forma está
actuando por sí.
En esta situación, los terceros no tienen acción sobre el mandante. La representación no
aparece,y el único que sabe es el mandatario. Niel mandante que no conoce, ni el tercero,
tienen acción entre sí, pero si ambos, frente al mandatario.
- M a n d a to C iv il.- Cuando los actos que va a ejecutar el mandatario, son civiles.
- M a n d a to M e r c a n til.- Cuando los actos a ejecutarse por el mandatario, son mercantiles.
- M a n d a to G e n e ra l.- Cuando se configura para q ue el mandatario celebre todos los contra
tos o actos jurídicos que se le pueden ofrecer al mandante.
- M a n d a to E sp ecial.- Cuando se otorga para la ejecución de algunas de las facultades del
mandato general o se otorgue para uno o varios asuntos determinados por la ley.
Extinción del mandato: Según el arto 1801o el mandato se extingue:
1. - Por ejecución total del mandato.
2 . - Por vencimiento del plazo del contrato, lo cual es obvio, razón por la cual señalar esta
causal era innecesaria.
Además, puede term inar por revocación del mandante, porque es un contrato de confian
za. No funciona este inciso, cuando el mandato es irrevocable. Asimismo, por renuncia del
mandatario.
De conformidad con el art. 1802, son válidos los actos que el mandatario realiza antes de
conocer la extinción del mandato.
3. - Por muerte, interdicción o inhabilitación del mandante o mandatario, ya que es un con
trato basado en la persona.
La muerte, interdicción o inhabilitación del mandante no extingue el mandato cuando éste ha
sido celebrado también en interés del mandatario o un tercero (Art. 1803 C.C.).
Por otro lado, cuando el mandato se extingue por muerte, interdicción o inhabilitación del
mandatario, sus herederos o quienes los representen, deben informar de inmediato al man-
dantey tomar, entre tanto, las providencias necesarias de acuerdo a las circunstancias.
Si por regla general el mandato cesa por la muerte del mandante, hay supuestos de excepción
a esta regla fija, que pueden ser aplicables
1.- Cuando las partes la hayan derogado por una convención expresa;
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 476 of 1506 --

2. - Cuando ello aparece ser la voluntad del mandante, lo cual puede inferirse del objeto del
mandato.
3. - Cuando el mandato ha sido dado por acto testamentario, para ser ejecutado después del
deceso del mandante;
4. - Cuando el mandato es la condición, la consecuencia o el modo de ejecución de un contra
to sinalagmático;
5. - Cuando el mandatario o un tercero, están interesados en el mandato.
6 . - Cuando el mandatario es una persona que el mandante, acreedor, ha indicado para reci
bir el pago;
7. - Cuando el mandato ha sido dado bajo una forma que hace imposible la revocación, como
en el caso de una donación disfrazada.
18.10. Depósito
Concepto; Es un contrato en el que una de las partes se obliga a custodiar el bien o bienes de
la otra parte y a devolverlo cuando lo solicite, a cambio de una remuneración (Art. 1814 C.C.).
Clases de depósito:
D e p ó s ito N ecesario : A este depósito también se le denomina: depósito forzoso. Se encuentra
definido por el Art. 1854 que expresa lo siguiente: “El depósito necesario es el que se hace en
cumplim iento de una obligación legal o bajo el apremio de un hecho o situación imprevistos”.
El apremio puede estar constituido por un terremoto, incendio, naufragio, saqueo, etc. Toda
persona está obligada a recibir el depósito necesario por eso se le llama también depósito for
zoso, a menos que tenga impedimento físico u otra justificación, así por ejemplo, ser persona
inválida o no tener dónde guardar el depósito (Art. 1854 a h 856 C.C.).
D e p ó s ito V o lu n ta rio ; Es cuando se lleva a cabo por convenio espontáneo entre el depositante
y el depositario.
Existe otro tipo de depósito llamado judicial el cual se efectúa por mandato de la ley o del juez
para cum plir con una obligación o para garantizar el pago de algo. En el primer caso, toma el
nombre de consignación, y en el segundo, de embargo. Este tipo de depósito se le conoce con
el nombre desecuestro.
Derechos y obligaciones del depositario:
Es el derecho del depositario mantener bajo su custodia el bien materia del depósito y en su
caso a cobrar la retribución pactada. Esta además obligado a custodiar el bien, a conservarlo
diligentem entey a devolverlo en el momento pactado.
18. 11. Secuestro
Concepto: Es el contrato por el cual una de las partes (secuestratario-depositario) se le confía
por otros sujetos (depositantes), una cosa respecto de la cual hay surgido alguna controversia
y tiene por objeto hacer posible la custodia y la posterior restitución de la cosa a quién co
rresponda una vez definida la controversia. Diferenciarlo de la medida cautelar denominada
secuestro conservativo, principalmente por su carácter contractual y porque no se crea una si-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 477 of 1506 --

Tema 2: Temas de derecho civil
tuación de indisponibilidad, sino que sólo crea a favor del secuestratario una obligación de
no devolver el bien a favor solamente de quién resulte con derecho luego de ser resuelta la
controversia.
Características: Es un contrato consensual, real (perfeccionamiento con la entrega), bilateral
y oneroso. El contrato debe constar por escrito bajo sanción de nulidad.
Responsabilidades y acciones: Los depositantes son solidariamente responsables por el cos
to que irrogue a partir del contrato, tales como los gastos de la retribución convenida al depo
sitario, gastos de conservación, así como cualquier otra erogación que derive del secuestro. El
depositario ejercer las acciones destinadas a recuperar el bien frente a un tercero y frente a los
propios depositantes que hayan tomado posesión del bien sin consentimiento de los demás
o sin mandato judicial.
18.12. Fianza
Concepto: La fianza es un contrato celebrado entre el acreedor de una obligación principal y
un tercero de ésta, que acepta ser posible responsable de la deuda contraída por el deudor en
caso de su insolvencia o incumplimiento.
El fiador asegura al acreedor el cumplimiento de la obligación del verdadero deudor. Es una
garantía personal. El fiador cubre la potencial falencia del deudor, para que el acreedor pueda
cobrar.
Características:
Es un contrato individual.- Vincula un sujeto con otro, que expresan su voluntad.
Es un contrato accesorio.- Porque no tiene vida autónoma y va unido a un contrato principal.
La accesoriedadde la fianza, es similar a laaccesoriedad de los contratos reales de garantía. La
hipoteca, en los bienes inmuebles depende del mutuo. No siempre la fianza, cubre los présta
mos, generalmente sirve para cubrir el cumplimiento de una obligación. Pueden garantizarse
con la fianza toda clase de obligaciones lícitas, ya sean principales o accesorias, de dar, hacer o
no hacer, líquidas o no líquidas, presentes o futuras, puras o con modalidades.
Es de prestación unilateral.-Es un contrato de prestación unilateral, porque el único obligado
frente al acreedor es el fiador, puesto que el deudor no interviene en este contrato. Se realiza
entre el acreedor y el fiador. El deudor es un elemento extraño al contrato. El acreedor debe
exigirle el cumplim iento del pago de ladeuday el fiador está obligado a pagar al requerimien
to del acreedor.
Es gratuito.- El único obligado es el fiador, si éste a su vez tiene derecho a cobrarle comisión al
deudor,ya no es fianza, sino un pacto adherido al contrato principal.
Es conmutativo.- Porque el fiador prevé las ventajas y desventajas del contrato.
Es literal.- La literalidad es ad-solemnitatem, porque se tiene que perfeccionar por escrito, se
gún el art. 1871 del C.C., que dice: "La fianza debe constar por escrito, bajo sanción de nulidad”
y sólo quedará obligado el fiador por aquello a que expresamente se hubiera comprometido,
sin que pueda obligársele por mayor cantidad, ni con más gravamen que el fijado (Art. 1873o
y 1874o del C.C.).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 478 of 1506 --

UBILEX
Esta formalidad se exige por razón de seguridad jurídica,ya que puede traer repercusiones en
el patrimonio del fiador.
En principio, es su b s id ia rio , porque en la fianza simple, como regla general, el fiador actúa
y cubre la deuda del deudor, sólo cuando éste es insolvente; en cambio, cuando la fianza es
solidaria, el fiador puede ser compelido al cumplim iento de la obligación, al mismo tiempo
que el deudor.
Formas:
La fianza es convencional cuando se constituye por medio de un negocio jurídico que celebran el
deudor, el acreedory el fiador.
La fianza legal es aquella que se da por disposición expresa de la ley. La obligación de prestar
fianza o de presentar fiador es una obligación que recae sobre el deudor. Sin embargo, el fia
dor asume la fianza voluntariamente.
La fianza judicial es aquella que se da por virtud de resolución judicial. Se trata de casos en que
la ley faculta a los jueces o tribunales para exigir del deudor la constitución de una fianza.
Extensión de la fianza: Si no hay límite en la fianza ésta se extiende a todos los accesorios de
la obligación principal, así como a las costas del juicio contra el fiador, devengada después de
habérsele requerido para el pago.
El beneficio de excusión: requisitos para oponerlo:
El beneficio de excusión es la facultad que otorga al fiador y que tiene por objeto enervar o
paralizar la pretensión ejecutiva del acreedor dirigida contra él. El fundamento de dicho be
neficio o facultad lo constituye el principio de subsidiariedad de la fianza. Conforme a lo esta
blecido en el artículo 1879 del C.C.: “el fiador no puede ser compelido a pagar al acreedor sin
hacerse antes excusión de los bienes del deudor.
En aplicación del artículo 1880 del C.C., el fiador deberá oponer el beneficio de excusión al
acreedor, luego que este lo requiera para el pago y acredite la existencia de bienes del deudor
realizables dentro de la República, quesean suficientes paracubrirel importe de la obligación.
El segundo párrafo del artículo 1882 de nuestro C.C., señala que si los bienes del deudor no
producen más que un pago parcial de la deuda, es decir, no extinguen toda la deuda, el acree
dor puede accionar contra el fiador por el saldo, incluyendo intereses y gastos.
Los casos en los que el beneficio de excusión no tiene lugar son: (i) cuando el fiador ha renun
ciado expresamente a ella; (ii) cuando se ha obligado solidariamente con el deudor; y, (iii) en
caso de quiebra del deudor. (Art. 1883 del C.C.)
No hay lugar a la excusión cuando el fiador ha renunciado expresamente a el la. La renuncia de
la excusión debe ser expresa. No se admite la renuncia tácita.
El beneficio de división
Es cuando se ha estipulado que cada cofiador que sea demandado para el pago de la deuda
pueda exigir al acreedor que reduzca la acción a la parte que le corresponde. Así lo estipula el
art. 1887o del C.C. pero la expresión “la parte que le corresponda” resulta muy vaga, es por eso
que para determinar dicha parte será menester acudir al negocio constitutivo de la fianza,
cuando en él haya sido fijadas expresamente las partes, cuotas o proporciones de la deuda de
