19. Enriquecimiento sin causa
El artículo 1954 del Código Civil señala que «aquél que se enriquece indebidamente a expensas
de otro está obligado a indemnizarlo». Este artículo tiene como antecedente al artículo 1149
Código Civil de 1936y, básicamente, el concepto es similar, es decir debe existir un menoscabo
en el patrimonio de una de las partes sin base alguna en beneficio de otra.
Delia Revoredo señala que «Como el enriquecimiento sin causa rompe el equilibrio patrim o
nial sin que medie justificación o razón jurídica válida, el Derecho busca reestablecer ese equi
librio concediendo al perjudicado la facultad de accionar. La acción restitutoria in rem verso di
fiere de la acción reivindicatoría y de la acción general indemnizatoria por daños y perjuicios.
Difiere de la primera en que la acción por enriquecimiento sin causa es personal [...] por eso
cabe reclamar por servicios prestados, [...] difiere de la acción indemnizatoria en que no cabe
dolo o culpa contractual ni extracontractual, pues falta necesariamente la causa jurídica en la
transmisión de valores».
La figura de enriquecimiento indebido requiere necesariamente un empobrecimiento de una
partey un beneficio de la otra, que sea consecuencia del menoscabo del primero.
20. Responsabilidad civil
20.1. Noción: Etimológicamente la palabra responsabilidad se remonta al término latino “res
ponderé” que es una forma latina del término responder, por eso decimos que la responsabili
dad es la habilidad de “responder”.
El Diccionario de la Lengua Española lo define como una deuda, obligación de reparary satis
facer, por sí o por otra persona, a consecuencia de un delito, de una culpa o de otra causa legal.
Partiendo del principio romano es deber genérico de causar daño a nadie, si este no es cum pli
do, su correlato es la obligación de reparar el perjuicio causado por su responsable. Conside
ramos que esta constituye la base de la responsabilidady desús distintos regímenes jurídicos
que derivan de él, sobre la naturaleza del hecho ilícito, entendido claro está como ¡lícito civil y
del daño ocasionado.
20.2. Clases:
La responsabilidad civil es una institución jurídica dentro del cual existe ¡a obligación de indem
nizar por daños causados en virtud a un incumplimiento de las obligaciones asumidas mediante una
relación contractual o por el acontecimiento de un hecho ilícito o riesgo creado (fuente extracon
tractual), en donde su reparación deberá consistir en el establecimiento de una situación anterior o
-cuando ello sea imposible- en un pago por concepto de indemnización. Para ello, en caso que una
conducta pueda ocasionar una lesión o menoscabo, el mismo se deberá analizar dentro de los
elementos constitutivos propios de la responsabilidad civil, esto es, la antijuridicidad, el daño,
el nexo causal y los factores de atribución.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 480 of 1506 --

UBILEX
Tanto la responsabilidad civil contractual como la extracontractual tienen como objetivo com
pensar el daño sufrido por la víctima, sin embargo, cada una tiene un tratam iento diferente y
específico en la legislación. La diferencia entre ambas se basa en si existe o no un contrato que
establezca las obligaciones de las partes involucradas.
20.3. La responsabilidad civil extracontractual: concepto: Los antecedentes sobre la respon
sabilidad civil extracontractual en nuestro derecho data del Código Civil de 1852, que adopta
el principio de culpa como base para la determinación de la responsabilidad, la culpa debe ser
demostrada por el demandante; en el Código Civil de 1936 mantuvo igual la teoría de la cul
pa y en nuestro actual Código Civil de 1984 la responsabilidad extracontractual se encuentra
regulada en el Libro Vil, Fuente de Obligaciones Sección Sexta, tanto como responsabilidad
objetiva como subjetiva.
La responsabilidad extracontractual se aplica en situaciones en las que ocurre un evento dañi
no y no existe un contrato que establezca obligaciones específicas.
Los criterios de información en materia de responsabilidad civil extracontractual se proyectan
bajo los siguientes criterios: a) La determinación de la culpa por acción u omisión, b) La deter
minación del dolo poracción uomisión.
20.4. Elementos de la responsabilidad civil extracontractual
a. La antijuridicidad.
b. El daño causado.
c. El nexo causal.
d. Los factores de atribución.
- LA A N T IJ U R ID IC ID A D Se refiere a una parte esencial del acto ilegal o ilícito, el cual
infringe las fuentes del derecho del ordenamiento jurídico, sobre todo las normas prescri
tas y la costumbre caracterizada por aquellas conductas socialmente aceptables, violan
do el deber genérico de no ejercer un daño contra un tercero. Además, la antijuridicidad
abarca tanto los comportamientos opuestos a los elementos externos como internos del
ordenamiento jurídico22.
En el ámbito de la responsabilidad extracontractual no rige el criterio de la tipicidad en
materia de conductas que pueden causar daños y dar lugar a la obligación legal de in
demnizar, sino que dichas conductas pueden ser típicas en cuanto se encuentren previs
tas en abstracto en supuestos legales, la producción de las mismas viole o contravenga
el ordenamiento jurídico. Este amplio concepto de antijuridicidad es reconocido por la
responsabilidad extracontractual, pues en ella no se encuentran predeterminadas las
conductas, por lo cual se entiende que cualquier conducta será susceptible de dar lugar
a una responsabilidad civil en la medida que se trate de una conducta ilícita que cause
daño. En cambio, en la responsabilidad contractual la antijuridicidad debe ser siempre
típica, ya que es consecuencia de un incumplimiento, cumplim iento tardío o defectuoso
de una obligación, por tanto, la conducta que puede dar lugar a una indemnización son
siempre conductas tipificadas legalmente.
