Tema 2: Temas de derecho civil
DAÑO.- Este alude a un menoscabo o detrimento del interés jurídicamente tutelado de
los particulares que se desenvuelven sobre la base de los principios orientadores de una
convivencia pacífica conteniendo éste además la siguiente tipología23:
El daño emergente, aquél que genera el egreso de un bien del patrimonio de la víctima; el
lucro cesante identificado como aquello que la víctima de percibir por efecto del daño en
determinado bien, es decir, que por efectos del daño no ha ingresado cierto bien a su pa
trim onio; el daño moral, constituido por la lesión a los sentimientos de lavíctim ay que le
produce un gran dolor, aflicción o sufrimiento afectando evidentemente en el daño moral
la esfera subjetiva e íntima de la persona inclusive su honory reputación; en cuanto a pro
yecciones de aquella hacia la sociedad si es que con tales aflicciones se la desprestigia pú
blicamente; el daño a la persona, conocido como daños a la libertad o al proyecto de vida es
aquél que recae sobre la persona del sujeto loque le impide real izar su actividad habitual,
que es la que efectuaba para proveerse de los bienes indispensables para su sustento así
como también en la que estaban plasmadas las metas que le permitirían su realización
personal comprendiéndose asimismo dentro de este daño la lesión a la integridad física y
psicológica del afectado.
Existen daños que, a pesar de haberse acreditado su existencia, no son materia de repa
ración, estos están previsto en el art. 1971 del C.C.: a) por haberse producido en el ejercicio
regular de un derecho, b) legítima defensa de la propia persona o estado de necesidad
(salvo algunas excepciones) c) daños producidos durante la ruptura de la relación de cau
salidad (daños producidos por caso fortuito o fuerza mayor), d) daños ocasionados por la
propia imprudencia de quien padece el daño, e) los daños en los que a pesar de haberse
acreditado la existencia del hecho dañoso, el daño y la relación de causalidad, no se pue
den atribuiral autor, por ausencia del factorde atribución.
NEXO CAUSAL O RELACIÓN DE CAUSALIDAD.- El cual significa que el daño causado
debe ser consecuencia de la conducta antijurídica del autor para que se configure el su
puesto de la responsabilidad civil extracontractual, es decir, que la conducta antijurídica
debe ser capaz o adecuada para producir el daño causado24.
Se afirma que en materia de responsabilidad civil extracontractual o aquiliana se acoge
la teoría de la causa adecuada (art. 1985 CC)y en inejecución de obligaciones se asume la
teoría de causa próxima (art. 1321 CC).
La relación de causalidad, además, presenta otras figurasy supuestos que se presentan en
torno a este aspecto fundamental de la responsabi Iidad civi I, tales como la fractura causal
o causa ajena, la de la concausa y la de pluralidad de causas:
1.- Fractura causal: Elimina la responsabilidad subjetiva si ha mediado caso fortuito o hecho de
terminante de tercero o hecho determinante de la víctima, nos encontramos ante una ausen
cia de culpa por parte del aparente causante. Por lo cual, si el presunto autor prueba que han
mediado las circunstancias antes mencionadas, no será obligado a la reparación del daño.
