UBILEX
La fractura causal se configura cada vez que un determinado supuesto presenta un conflicto
entre dos causas o conductas sobre la realización de un daño, el cual será resultado de una de
las conductas.
En todo supuesto de fractura causal una de las conductas o causas habrá producido el daño, y
la otra habrá llegado a causarlo justamente por haber sido consecuencia de la otra conducta.
Las conductas que no han llegado a causar daño se denominan causa inicial mientras que la
conducta que si llegó a causar el daño se denomina causa ajena. Todo supuesto de fractura
implica, un conflicto entre la causa ajenay la causa inicial, siendo el daño consecuencia de la
causa ajenay no existiendo ninguna relación de causalidad respecto de la causa inicial.
